INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-costa-rica', 'coffee', 'COFFEE', '哥斯达黎加咖啡', 'Costa Rican Coffee', 'gesidalijiakafei', 'gsdljkf', '哥斯达黎加咖啡是产自中美洲的阿拉比卡咖啡，以干净明亮的酸质与蜂蜜般的甜感著称，蜜处理与日晒处理法常见，适合浅中度烘焙。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。哥斯达黎加注重处理后风味与甜感，干净度在中美洲产区中较为突出。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 50, '[{"key": "ACIDITY", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["热饮", "黑咖啡", "手冲", "中等酒体", "甜感明显", "焦糖", "柑橘", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 16, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 16 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，先注至约 120 g，再补至总水量 16 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["哥斯达黎加", "Costa Rica"]', 'A', '2026-08-04', 1, '{"id": "coffee-costa-rica", "mode": "coffee", "category": "COFFEE", "nameZh": "哥斯达黎加咖啡", "nameEn": "Costa Rican Coffee", "intro": "哥斯达黎加咖啡是产自中美洲的阿拉比卡咖啡，以干净明亮的酸质与蜂蜜般的甜感著称，蜜处理与日晒处理法常见，适合浅中度烘焙。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "手冲", "中等酒体", "甜感明显", "焦糖", "柑橘", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-blue-mountain', 'coffee', 'COFFEE', '蓝山咖啡', 'Jamaica Blue Mountain Coffee', 'lanshankafei', 'lskf', '蓝山咖啡是产自牙买加蓝山山脉高海拔产区的阿拉比卡咖啡，以口感细腻、酸苦均衡和低刺激著称，多为中度烘焙，全球知名度极高。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。蓝山咖啡需经牙买加官方认证方可标注，产量有限、价格较高，口感以柔和见长。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Jamaica%20Blue%20Mountain%20Coffee%209494.JPG', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Jamaica%20Blue%20Mountain%20Coffee%209494.JPG', 93, 51, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "手冲过滤", "中等酒体", "顺滑", "均衡", "低苦", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 15 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，先注至约 120 g，再补至总水量 15 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["蓝山", "Blue Mountain"]', 'A', '2026-08-04', 1, '{"id": "coffee-blue-mountain", "mode": "coffee", "category": "COFFEE", "nameZh": "蓝山咖啡", "nameEn": "Jamaica Blue Mountain Coffee", "intro": "蓝山咖啡是产自牙买加蓝山山脉高海拔产区的阿拉比卡咖啡，以口感细腻、酸苦均衡和低刺激著称，多为中度烘焙，全球知名度极高。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Jamaica%20Blue%20Mountain%20Coffee%209494.JPG", "tags": ["热饮", "黑咖啡", "手冲过滤", "中等酒体", "顺滑", "均衡", "低苦", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-mandheling', 'coffee', 'COFFEE', '印尼曼特宁咖啡', 'Sumatra Mandheling', 'yinnimanteningkafei', 'ynmtnkf', '曼特宁咖啡是产自印尼苏门答腊的阿拉比卡咖啡，以深烘焙后的草本、泥土与香料风味和厚重醇度为特征，酸度低，适合重口味黑咖啡爱好者。', '本条目以 V6 编辑标准统一为深度烘焙法压壶冲煮，粉水比约一比十三。曼特宁多采用湿刨法处理，风味厚重浓郁，是亚洲产区中辨识度极高的代表。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 52, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 9.0}, {"key": "ROAST", "label": "烘焙感", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "黑咖啡", "法压", "醇厚/酒体饱满", "泥土", "草本", "苦味明显", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "深度烘焙咖啡豆", "nameEn": "Dark roast coffee beans", "amount": 18, "unit": "g", "role": "研磨度偏粗"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "90–94°C"}]', '["预热法压壶并用热水冲洗内壁。", "称取 18 g 咖啡豆，研磨至粗颗粒。", "将咖啡粉倒入壶中，注入 240 ml 热水。", "搅拌数下，盖上盖子静置浸泡 4 分钟。", "缓慢压下活塞，倒出咖啡液即可饮用。"]', '["曼特宁", "Mandheling", "苏门答腊曼特宁"]', 'A', '2026-08-04', 1, '{"id": "coffee-mandheling", "mode": "coffee", "category": "COFFEE", "nameZh": "印尼曼特宁咖啡", "nameEn": "Sumatra Mandheling", "intro": "曼特宁咖啡是产自印尼苏门答腊的阿拉比卡咖啡，以深烘焙后的草本、泥土与香料风味和厚重醇度为特征，酸度低，适合重口味黑咖啡爱好者。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "法压", "醇厚/酒体饱满", "泥土", "草本", "苦味明显", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-yemen', 'coffee', 'COFFEE', '也门咖啡', 'Yemeni Coffee', 'yemenkafei', 'ymkf', '也门咖啡是产自也门山地、以传统日晒自然干燥的阿拉比卡咖啡，风味复杂奔放，带果香与酒酿气息，是世界咖啡历史最悠久的产区之一。', '本条目以 V6 编辑标准统一为深度烘焙浸泡冲煮，粉水比约一比十二。也门咖啡沿用古法日晒，豆身与风味粗犷，常与摩卡港的历史名称相关联。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 53, '[{"key": "ACIDITY", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "黑咖啡", "浸泡", "醇厚/酒体饱满", "果香", "泥土", "香料", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "深度烘焙咖啡豆", "nameEn": "Dark roast coffee beans", "amount": 18, "unit": "g", "role": "研磨度中等偏粗"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 220, "unit": "ml", "role": "92–96°C"}]', '["将杯子用热水温热。", "称取 18 g 咖啡豆，研磨至中等偏粗。", "咖啡粉放入杯中，注入 220 ml 热水。", "搅拌后静置浸泡 4 分钟，让粉末自然沉淀。", "撇去表面浮沫，缓慢饮用杯中澄清液。"]', '["也门", "Yemen", "摩卡"]', 'A', '2026-08-04', 1, '{"id": "coffee-yemen", "mode": "coffee", "category": "COFFEE", "nameZh": "也门咖啡", "nameEn": "Yemeni Coffee", "intro": "也门咖啡是产自也门山地、以传统日晒自然干燥的阿拉比卡咖啡，风味复杂奔放，带果香与酒酿气息，是世界咖啡历史最悠久的产区之一。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "浸泡", "醇厚/酒体饱满", "果香", "泥土", "香料", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-jamaica', 'coffee', 'COFFEE', '牙买加咖啡', 'Jamaican Coffee', 'yamaijiakafei', 'ymjkf', '牙买加咖啡是产自牙买加的阿拉比卡咖啡，以柔和醇净、坚果与巧克力风味著称，口感顺滑、酸度温和，与蓝山同源产区一脉相承。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。牙买加以蓝山为最知名子产区，其余地块咖啡同样风味柔和，整体酸度偏低。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 54, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "手冲", "中等酒体", "顺滑", "坚果", "均衡", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 15 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，先注至约 120 g，再补至总水量 15 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["牙买加", "Jamaica"]', 'A', '2026-08-04', 1, '{"id": "coffee-jamaica", "mode": "coffee", "category": "COFFEE", "nameZh": "牙买加咖啡", "nameEn": "Jamaican Coffee", "intro": "牙买加咖啡是产自牙买加的阿拉比卡咖啡，以柔和醇净、坚果与巧克力风味著称，口感顺滑、酸度温和，与蓝山同源产区一脉相承。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "手冲", "中等酒体", "顺滑", "坚果", "均衡", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-peru', 'coffee', 'COFFEE', '秘鲁咖啡', 'Peruvian Coffee', 'bilukafei', 'blkf', '秘鲁咖啡是产自安第斯山脉高海拔的有机阿拉比卡咖啡，风味柔和均衡，带坚果与焦糖甜香，性价比高，是入门单品咖啡的热门选择。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。秘鲁咖啡以小农户种植、有机认证比例高著称，风味温和包容、对新手友好。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Freshly%20harvested%20coffee%20cherries.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Freshly%20harvested%20coffee%20cherries.jpg', 93, 55, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "手冲过滤", "中等酒体", "坚果", "均衡", "无乳配方", "日常"]', '["日常"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 15 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，先注至约 120 g，再补至总水量 15 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["秘鲁", "Peru"]', 'A', '2026-08-04', 1, '{"id": "coffee-peru", "mode": "coffee", "category": "COFFEE", "nameZh": "秘鲁咖啡", "nameEn": "Peruvian Coffee", "intro": "秘鲁咖啡是产自安第斯山脉高海拔的有机阿拉比卡咖啡，风味柔和均衡，带坚果与焦糖甜香，性价比高，是入门单品咖啡的热门选择。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Freshly%20harvested%20coffee%20cherries.jpg", "tags": ["热饮", "黑咖啡", "手冲过滤", "中等酒体", "坚果", "均衡", "无乳配方", "日常"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
