INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-el-salvador', 'coffee', 'COFFEE', '萨尔瓦多咖啡', 'Salvadoran Coffee', 'saerwaduokafei', 'sewdkf', '萨尔瓦多咖啡是产自中美洲火山地带的阿拉比卡咖啡，以柔滑的奶油口感与焦糖、坚果甜感著称，波旁与帕卡马拉品种尤为出名。', '本条目以 V6 编辑标准统一为中度烘焙法压壶冲煮，粉水比约一比十三。萨尔瓦多火山土壤肥沃，咖啡醇厚度高、甜感饱满，是中美洲的经典甜系产区。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 58, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "法压", "醇厚/酒体饱满", "焦糖", "坚果", "甜感明显", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 18, "unit": "g", "role": "研磨度偏粗"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "90–94°C"}]', '["预热法压壶并用热水冲洗内壁。", "称取 18 g 咖啡豆，研磨至粗颗粒。", "将咖啡粉倒入壶中，注入 240 ml 热水。", "搅拌数下，盖上盖子静置浸泡 4 分钟。", "缓慢压下活塞，倒出咖啡液即可饮用。"]', '["萨尔瓦多", "El Salvador"]', 'A', '2026-08-04', 1, '{"id": "coffee-el-salvador", "mode": "coffee", "category": "COFFEE", "nameZh": "萨尔瓦多咖啡", "nameEn": "Salvadoran Coffee", "intro": "萨尔瓦多咖啡是产自中美洲火山地带的阿拉比卡咖啡，以柔滑的奶油口感与焦糖、坚果甜感著称，波旁与帕卡马拉品种尤为出名。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "法压", "醇厚/酒体饱满", "焦糖", "坚果", "甜感明显", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-mexico', 'coffee', 'COFFEE', '墨西哥咖啡', 'Café de Olla', 'moxigekafei', 'mxgkf', '墨西哥传统陶罐咖啡，以瓦罐慢煮咖啡粉并加入肉桂与棕榈糖，带有明显的香料与焦糖甜味。', 'V6 采用墨西哥常见做法：浅度烘焙咖啡粉 15 g 加 240 ml 水与棕榈糖慢煮，并用肉桂棒增香。源自墨西哥民间家庭配方，非单一法定标准。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 59, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "香料", "甜感明显", "醇厚/酒体饱满", "经典", "无乳配方", "地域特色咖啡"]', '["经典"]', '{"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "浅度烘焙咖啡豆", "nameEn": "Light roast coffee beans", "amount": 15, "unit": "g", "role": "磨至粗中研磨度"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 240, "unit": "ml", "role": "常温水"}, {"nameZh": "棕榈糖", "nameEn": "Palm sugar", "amount": 20, "unit": "g", "role": "可依喜好调整"}, {"nameZh": "肉桂棒", "nameEn": "Cinnamon stick", "amount": 1, "unit": "g", "role": "约 5 cm 一段"}]', '["将粗研磨咖啡粉、棕榈糖与肉桂棒放入陶罐。", "加入常温水并置于中火加热至沸腾前。", "转小火保持微沸煮 5 分钟，期间轻搅两次。", "离火静置 2 分钟让粉渣沉淀。", "滤去粉渣后趁热倒入杯中饮用。"]', '["Café de olla", "墨西哥陶罐咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-mexico", "mode": "coffee", "category": "COFFEE", "nameZh": "墨西哥咖啡", "nameEn": "Café de Olla", "intro": "墨西哥传统陶罐咖啡，以瓦罐慢煮咖啡粉并加入肉桂与棕榈糖，带有明显的香料与焦糖甜味。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "香料", "甜感明显", "醇厚/酒体饱满", "经典", "无乳配方", "地域特色咖啡"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cuba', 'coffee', 'COFFEE', '古巴咖啡', 'Café Cubano', 'gubakafei', 'gbkf', '古巴浓缩咖啡，以深度烘焙细研磨咖啡粉萃取并趁热拌入糖粉，形成明显甜感与细密泡沫。', 'V6 标准化为 25 g 深度烘焙粉萃取 50 ml 浓缩，趁热加入 10 g 糖粉搅拌至绵密泡沫。源自古巴咖啡馆传统做法，不同家庭配糖比例略有差异。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 60, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 9.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["热饮", "苦味明显", "浓郁甜", "浓缩", "泡沫质地", "经典", "地域特色咖啡", "无乳配方"]', '["经典"]', '{"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "深度烘焙咖啡豆", "nameEn": "Dark roast coffee beans", "amount": 25, "unit": "g", "role": "意式细研磨"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 50, "unit": "ml", "role": "萃取用 92°C"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 10, "unit": "g", "role": "细砂糖"}]', '["将细研磨深度烘焙咖啡粉压入粉碗。", "萃取出约 50 ml 浓缩咖啡液。", "趁热将糖粉倒入浓缩液中快速搅拌。", "持续搅打至液体呈现细密浅色泡沫。", "倒入预热小杯后立即饮用。"]', '["Café cubano", "Cuban espresso"]', 'A', '2026-08-04', 1, '{"id": "coffee-cuba", "mode": "coffee", "category": "COFFEE", "nameZh": "古巴咖啡", "nameEn": "Café Cubano", "intro": "古巴浓缩咖啡，以深度烘焙细研磨咖啡粉萃取并趁热拌入糖粉，形成明显甜感与细密泡沫。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "苦味明显", "浓郁甜", "浓缩", "泡沫质地", "经典", "地域特色咖啡", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-puerto-rico', 'coffee', 'COFFEE', '波多黎各咖啡', 'Puerto Rican Coffee', 'boduoligekafei', 'bdlgkf', '波多黎各山地种植的阿拉比卡咖啡，以温和甜感与坚果焦糖风味为特点，常以手冲黑咖啡方式呈现。', 'V6 标准为中度烘焙波多黎各豆 15 g，以 1:16 水粉比手冲 240 ml。产区包括 Yauco 等山地，风味描述以杯测常用表述为编辑归纳。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 61, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["热饮", "黑咖啡", "坚果", "焦糖", "中等酒体", "日常", "地域特色咖啡", "无乳配方"]', '["日常"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "92°C"}]', '["预热滤杯并将滤纸润湿。", "倒入咖啡粉并轻拍平整。", "注入 40 ml 热水闷蒸 30 秒。", "分次注水至总量 240 ml。", "待滤完取下滤杯，倒入杯中饮用。"]', '["Puerto Rican coffee", "波多黎各咖啡豆"]', 'A', '2026-08-04', 1, '{"id": "coffee-puerto-rico", "mode": "coffee", "category": "COFFEE", "nameZh": "波多黎各咖啡", "nameEn": "Puerto Rican Coffee", "intro": "波多黎各山地种植的阿拉比卡咖啡，以温和甜感与坚果焦糖风味为特点，常以手冲黑咖啡方式呈现。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "坚果", "焦糖", "中等酒体", "日常", "地域特色咖啡", "无乳配方"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-kona', 'coffee', 'COFFEE', '夏威夷科纳咖啡', 'Kona Coffee', 'xiaweiyikenakafei', 'xwyknkf', '夏威夷大岛科纳地区种植的阿拉比卡咖啡，以柔和酸度、焦糖甜感与圆润顺滑的口感著称。', 'V6 标准为科纳豆 15 g 以 1:16 水粉比手冲 240 ml。科纳指夏威夷特定火山坡地种植并经认证的豆，真实咖啡因含量因烘焙与冲煮而异。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Kona%20Coffee%20beans.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Kona%20Coffee%20beans.jpg', 93, 62, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "焦糖", "坚果", "顺滑", "低苦", "地域特色咖啡", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "92°C"}]', '["预热滤杯并润湿滤纸。", "加入咖啡粉并轻拍平整。", "注入 40 ml 热水闷蒸 30 秒。", "分次注水至总量 240 ml。", "滤完移走滤杯，倒入杯中饮用。"]', '["Kona", "夏威夷科纳"]', 'A', '2026-08-04', 1, '{"id": "coffee-kona", "mode": "coffee", "category": "COFFEE", "nameZh": "夏威夷科纳咖啡", "nameEn": "Kona Coffee", "intro": "夏威夷大岛科纳地区种植的阿拉比卡咖啡，以柔和酸度、焦糖甜感与圆润顺滑的口感著称。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Kona%20Coffee%20beans.jpg", "tags": ["热饮", "黑咖啡", "焦糖", "坚果", "顺滑", "低苦", "地域特色咖啡", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-taiwan', 'coffee', 'COFFEE', '台湾咖啡', 'Taiwan Coffee', 'taiwankafei', 'twkf', '台湾低海拔产区种植的阿拉比卡咖啡，以细致花香、柔和酸度与轻盈清爽的口感为特色，苦味低。', 'V6 标准为中度烘焙台湾产豆 15 g 以 1:16 水粉比手冲 240 ml。台湾咖啡产量有限，风味随品种与海拔变化，此描述为常见杯测归纳。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Matsu%20Coffee%20%E6%9D%BE%E5%BA%AD%E5%92%96%E5%95%A1%E5%9C%92%20-%20panoramio.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Matsu%20Coffee%20%E6%9D%BE%E5%BA%AD%E5%92%96%E5%95%A1%E5%9C%92%20-%20panoramio.jpg', 93, 63, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 4.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["热饮", "黑咖啡", "花香", "柑橘", "轻盈", "含咖啡因", "地域特色咖啡", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "92°C"}]', '["预热滤杯并润湿滤纸。", "加入咖啡粉并轻拍平整。", "注入 40 ml 热水闷蒸 30 秒。", "分次注水至总量 240 ml。", "滤完移走滤杯，倒入杯中饮用。"]', '["Taiwan coffee", "台湾咖啡豆"]', 'A', '2026-08-04', 1, '{"id": "coffee-taiwan", "mode": "coffee", "category": "COFFEE", "nameZh": "台湾咖啡", "nameEn": "Taiwan Coffee", "intro": "台湾低海拔产区种植的阿拉比卡咖啡，以细致花香、柔和酸度与轻盈清爽的口感为特色，苦味低。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Matsu%20Coffee%20%E6%9D%BE%E5%BA%AD%E5%92%96%E5%95%A1%E5%9C%92%20-%20panoramio.jpg