INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-india', 'coffee', 'COFFEE', '印度咖啡', 'Indian Coffee', 'yindukafei', 'ydkf', '以印度阿拉比卡与罗布斯塔拼配或单品形式存在的咖啡，代表豆包括季风马拉巴，酸度柔和、口感厚重，是低酸亚洲风味的代表。', 'V6 编辑标准化为中度烘焙单品法压参数：以 16 克咖啡豆、250 克 92–94°C 热水浸泡 4 分钟。配方用于统一检索与对比，不代表特定庄园的唯一出品。', 'https://upload.wikimedia.org/wikipedia/commons/9/94/Coffee_Coconuts_Pepper_Estate_Coorg_Feb24_A7C_09365.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/94/Coffee_Coconuts_Pepper_Estate_Coorg_Feb24_A7C_09365.jpg', 93, 71, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "黑咖啡", "香料", "泥土", "醇厚/酒体饱满", "法压", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 16, "unit": "g", "role": "中粗研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "92–94°C"}]', '["将咖啡豆研磨至中粗研磨度。", "预热法压壶，倒入咖啡粉并注入 250 克热水，轻搅使咖啡粉完全浸没。", "盖上壶盖静置 4 分钟，期间轻搅一次以均匀萃取。", "缓慢下压滤网至壶底，立即倒出咖啡液以避免过萃。", "倒入杯中趁热饮用。"]', '["印度单品咖啡", "Indian Coffee"]', 'B', '2026-08-04', 1, '{"id": "coffee-india", "mode": "coffee", "category": "COFFEE", "nameZh": "印度咖啡", "nameEn": "Indian Coffee", "intro": "以印度阿拉比卡与罗布斯塔拼配或单品形式存在的咖啡，代表豆包括季风马拉巴，酸度柔和、口感厚重，是低酸亚洲风味的代表。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/94/Coffee_Coconuts_Pepper_Estate_Coorg_Feb24_A7C_09365.jpg", "tags": ["热饮", "黑咖啡", "香料", "泥土", "醇厚/酒体饱满", "法压", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-nepal', 'coffee', 'COFFEE', '尼泊尔咖啡', 'Nepal Coffee', 'nipoerkafei', 'npekf', '产自尼泊尔高海拔山区的精品阿拉比卡咖啡，种植环境清洁、采收精细，呈现花香与柑橘调的干净甜感风味。', 'V6 编辑标准化为浅度烘焙单品手冲参数：以 15 克咖啡豆、250 克 90°C 热水在约 2 分 30 秒内完成萃取。配方用于统一检索与对比，不代表特定庄园的唯一出品。', 'https://upload.wikimedia.org/wikipedia/commons/f/f4/Coffee_Himalayan_Java_Nepal.jpg', 'https://upload.wikimedia.org/wikipedia/commons/f/f4/Coffee_Himalayan_Java_Nepal.jpg', 93, 72, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["热饮", "黑咖啡", "花香", "柑橘", "轻盈", "手冲过滤", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "浅度烘焙咖啡豆", "nameEn": "Light roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90°C"}]', '["将咖啡豆研磨至中细研磨度，约细砂糖大小。", "用热水冲淋滤纸并预热滤杯与分享壶，倒掉滤下的水。", "倒入 15 克咖啡粉并轻拍平整，注入 30 克热水闷蒸 30 秒。", "以细水流从中心向外缓慢绕圈注水，分次加至 250 克，控制总时长约 2 分 30 秒。", "待滤水结束后移除滤纸，轻晃分享壶使浓度均匀，立即饮用。"]', '["尼泊尔精品咖啡", "Nepal Coffee"]', 'B', '2026-08-04', 1, '{"id": "coffee-nepal", "mode": "coffee", "category": "COFFEE", "nameZh": "尼泊尔咖啡", "nameEn": "Nepal Coffee", "intro": "产自尼泊尔高海拔山区的精品阿拉比卡咖啡，种植环境清洁、采收精细，呈现花香与柑橘调的干净甜感风味。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f4/Coffee_Himalayan_Java_Nepal.jpg", "tags": ["热饮", "黑咖啡", "花香", "柑橘", "轻盈", "手冲过滤", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-yunnan-natural', 'coffee', 'COFFEE', '中国云南日晒咖啡', 'Yunnan Natural Coffee', 'zhongguoyunnanrishaikafei', 'zgynrskf', '采用日晒自然干燥处理的云南单品咖啡，果肉在干燥过程中为咖啡豆带来莓果与发酵果香，甜感浓郁、口感饱满。', 'V6 编辑标准化为中度烘焙单品手冲参数：以 15 克咖啡豆、250 克 90°C 热水在约 2 分 30 秒内完成萃取。日晒法保留较多果肉参与发酵，风味强度高于同产区水洗处理。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 73, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "莓果", "果香", "中等酒体", "手冲过滤", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90°C"}]', '["将咖啡豆研磨至中细研磨度，约细砂糖大小。", "用热水冲淋滤纸并预热滤杯与分享壶，倒掉滤下的水。", "倒入 15 克咖啡粉并轻拍平整，注入 30 克热水闷蒸 30 秒。", "以细水流从中心向外缓慢绕圈注水，分次加至 250 克，控制总时长约 2 分 30 秒。", "待滤水结束后移除滤纸，轻晃分享壶使浓度均匀，立即饮用。"]', '["云南日晒", "日晒云南"]', 'B', '2026-08-04', 1, '{"id": "coffee-yunnan-natural", "mode": "coffee", "category": "COFFEE", "nameZh": "中国云南日晒咖啡", "nameEn": "Yunnan Natural Coffee", "intro": "采用日晒自然干燥处理的云南单品咖啡，果肉在干燥过程中为咖啡豆带来莓果与发酵果香，甜感浓郁、口感饱满。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "莓果", "果香", "中等酒体", "手冲过滤", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-yunnan-washed', 'coffee', 'COFFEE', '中国云南水洗咖啡', 'Yunnan Washed Coffee', 'zhongguoyunnanshuixikafei', 'zgynsxkf', '采用水洗处理的云南单品咖啡，去除果肉果胶后风味干净明亮，呈现绿茶、柑橘与清爽酸质，是云南咖啡的经典表达。', 'V6 编辑标准化为浅度烘焙单品手冲参数：以 15 克咖啡豆、250 克 90°C 热水在约 2 分 30 秒内完成萃取。水洗法充分去除果胶，口感比日晒与蜜处理更干净。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 74, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 4.0}, {"key": "ROAST", "label": "烘焙感", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["热饮", "黑咖啡", "柑橘", "草本", "轻盈", "手冲过滤", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "浅度烘焙咖啡豆", "nameEn": "Light roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90°C"}]', '["将咖啡豆研磨至中细研磨度，约细砂糖大小。", "用热水冲淋滤纸并预热滤杯与分享壶，倒掉滤下的水。", "倒入 15 克咖啡粉并轻拍平整，注入 30 克热水闷蒸 30 秒。", "以细水流从中心向外缓慢绕圈注水，分次加至 250 克，控制总时长约 2 分 30 秒。", "待滤水结束后移除滤纸，轻晃分享壶使浓度均匀，立即饮用。"]', '["云南水洗", "水洗云南"]', 'B', '2026-08-04', 1, '{"id": "coffee-yunnan-washed", "mode": "coffee", "category": "COFFEE", "nameZh": "中国云南水洗咖啡", "nameEn": "Yunnan Washed Coffee", "intro": "采用水洗处理的云南单品咖啡，去除果肉果胶后风味干净明亮，呈现绿茶、柑橘与清爽酸质，是云南咖啡的经典表达。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "柑橘", "草本", "轻盈", "手冲过滤", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
