INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-antigua', 'coffee', 'COFFEE', '危地马拉安提瓜', 'Antigua Guatemala Coffee', 'weidimalaantigua', 'wdmlatg', '危地马拉安提瓜产区的水洗单产地咖啡，以火山土壤与高地海拔著称，风味以巧克力与烤坚果为骨架，尾韵带柔和香料。', 'V6 标准为 15 g 中度烘焙咖啡豆配合 250 ml 90–93°C 热水手冲，粉水比约 1:16。安提瓜产自活火山坡地，以厚重醇体与平衡的苦甜著称。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Roasted_coffee_beans.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Roasted_coffee_beans.jpg', 93, 83, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["手冲", "热饮", "黑咖啡", "巧克力", "坚果", "无乳配方", "醇厚/酒体饱满", "地域特色咖啡"]', '["日常", "下午茶", "新手友好"]', '{"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶", "新手友好"]}', '[{"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–93°C"}, {"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度中度偏细"}]', '["将滤纸折叠放入滤杯，用 20 ml 热水冲湿滤纸并预热分享壶。", "倒入研磨好的咖啡粉并轻拍平，形成平整粉床。", "注入约 40 ml、90–93°C 热水闷蒸 30 秒。", "以画圈方式分次注水至 250 ml，控制总时长约 3 分钟。", "待滤液全部流下后轻晃分享壶使浓度均匀，趁热饮用。"]', '["危地马拉", "安提瓜咖啡", "Antigua"]', 'A', '2026-08-04', 1, '{"id": "coffee-antigua", "mode": "coffee", "category": "COFFEE", "nameZh": "危地马拉安提瓜", "nameEn": "Antigua Guatemala Coffee", "intro": "危地马拉安提瓜产区的水洗单产地咖啡，以火山土壤与高地海拔著称，风味以巧克力与烤坚果为骨架，尾韵带柔和香料。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Roasted_coffee_beans.jpg", "tags": ["手冲", "热饮", "黑咖啡", "巧克力", "坚果", "无乳配方", "醇厚/酒体饱满", "地域特色咖啡"], "scene": ["日常", "下午茶", "新手友好"], "recommendationScore": 93, "attributes": {"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cr-honey', 'coffee', 'COFFEE', '哥斯达黎加蜜处理', 'Costa Rica Honey Coffee', 'gesidalijiamichuli', 'gsdljmcl', '哥斯达黎加蜜处理的单产地黑咖啡，果肉部分保留于生豆外层干燥，带来焦糖与蜂蜜般的甜感，口感圆润顺滑。', 'V6 标准为 15 g 中度烘焙咖啡豆配合 250 ml 热水手冲，粉水比约 1:16。蜜处理因保留部分果胶，甜感与醇厚度介于水洗与日晒之间，果酸更圆润。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 84, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["手冲", "热饮", "黑咖啡", "甜感明显", "焦糖", "无乳配方", "中等酒体", "地域特色咖啡"]', '["日常", "下午茶", "新手友好"]', '{"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶", "新手友好"]}', '[{"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–93°C"}, {"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度中度偏细"}]', '["将滤纸折叠放入滤杯，用 20 ml 热水冲湿滤纸并预热分享壶。", "倒入研磨好的咖啡粉并轻拍平，形成平整粉床。", "注入约 40 ml、90–93°C 热水闷蒸 30 秒。", "以画圈方式分次注水至 250 ml，控制总时长约 3 分钟。", "待滤液全部流下后轻晃分享壶使浓度均匀，趁热饮用。"]', '["哥斯达黎加蜜", "CR Honey", "蜜处理咖啡"]', 'A', '2026-08-04', 1, '{"id": "coffee-cr-honey", "mode": "coffee", "category": "COFFEE", "nameZh": "哥斯达黎加蜜处理", "nameEn": "Costa Rica Honey Coffee", "intro": "哥斯达黎加蜜处理的单产地黑咖啡，果肉部分保留于生豆外层干燥，带来焦糖与蜂蜜般的甜感，口感圆润顺滑。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["手冲", "热饮", "黑咖啡", "甜感明显", "焦糖", "无乳配方", "中等酒体", "地域特色咖啡"], "scene": ["日常", "下午茶", "新手友好"], "recommendationScore": 93, "attributes": {"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cr-natural', 'coffee', 'COFFEE', '哥斯达黎加日晒', 'Costa Rica Natural Coffee', 'gesidalijiarishai', 'gsdljrs', '哥斯达黎加日晒处理的单产地黑咖啡，整颗咖啡果实带皮干燥，风味奔放，呈现莓果、葡萄干与热带水果的发酵甜香。', 'V6 标准为 15 g 浅度烘焙咖啡豆配合 250 ml 热水手冲，粉水比约 1:16。日晒保留整果干燥，发酵风味突出，较水洗处理酸质更奔放。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 85, '[{"key": "ACIDITY", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["手冲", "热饮", "黑咖啡", "果香", "莓果", "无乳配方", "醇厚/酒体饱满", "地域特色咖啡"]', '["日常", "下午茶", "新手友好"]', '{"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶", "新手友好"]}', '[{"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–93°C"}, {"nameZh": "浅度烘焙咖啡豆", "nameEn": "Light roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度中度偏细"}]', '["将滤纸折叠放入滤杯，用 20 ml 热水冲湿滤纸并预热分享壶。", "倒入研磨好的咖啡粉并轻拍平，形成平整粉床。", "注入约 40 ml、90–93°C 热水闷蒸 35 秒。", "以画圈方式分次注水至 250 ml，控制总时长约 3 分钟。", "待滤液全部流下后轻晃分享壶使浓度均匀，趁热饮用。"]', '["哥斯达黎加日晒", "CR Natural", "日晒咖啡"]', 'A', '2026-08-04', 1, '{"id": "coffee-cr-natural", "mode": "coffee", "category": "COFFEE", "nameZh": "哥斯达黎加日晒", "nameEn": "Costa Rica Natural Coffee", "intro": "哥斯达黎加日晒处理的单产地黑咖啡，整颗咖啡果实带皮干燥，风味奔放，呈现莓果、葡萄干与热带水果的发酵甜香。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["手冲", "热饮", "黑咖啡", "果香", "莓果", "无乳配方", "醇厚/酒体饱满", "地域特色咖啡"], "scene": ["日常", "下午茶", "新手友好"], "recommendationScore": 93, "attributes": {"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-brazil-natural', 'coffee', 'COFFEE', '巴西日晒', 'Brazil Natural Coffee', 'baxirishai', 'bxrs', '巴西日晒处理的单产地黑咖啡，以低酸度与饱满醇厚见长，带有花生、可可与焦糖的甜感，是适合日常大口饮用的黑咖啡。', 'V6 标准为 15 g 中度烘焙咖啡豆配合 250 ml 热水手冲，粉水比约 1:16。巴西普遍海拔较低，日晒处理酸度柔和，坚果与可可风味明显。', 'https://upload.wikimedia.org/wikipedia/commons/e/ef/A_coffee_plantation%2C_Sao_Paolo%2C_Brazil_LCCN2016821510.jpg', 'https://upload.wikimedia.org/wikipedia/commons/e/ef/A_coffee_plantation%2C_Sao_Paolo%2C_Brazil_LCCN2016821510.jpg', 93, 86, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["手冲", "热饮", "黑咖啡", "坚果", "巧克力", "无乳配方", "醇厚/酒体饱满", "地域特色咖啡"]', '["日常", "下午茶", "新手友好"]', '{"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶", "新手友好"]}', '[{"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–93°C"}, {"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度中度偏细"}]', '["将滤纸折叠放入滤杯，用 20 ml 热水冲湿滤纸并预热分享壶。", "倒入研磨好的咖啡粉并轻拍平，形成平整粉床。", "注入约 40 ml、90–93°C 热水闷蒸 30 秒。", "以画圈方式分次注水至 250 ml，控制总时长约 3 分钟。", "待滤液全部流下后轻晃分享壶使浓度均匀，趁热饮用。"]', '["巴西日晒", "Brazil Natural", "日晒巴西豆"]', 'A', '2026-08-04', 1, '{"id": "coffee-brazil-natural", "mode": "coffee", "category": "COFFEE", "nameZh": "巴西日晒", "nameEn": "Brazil Natural Coffee", "intro": "巴西日晒处理的单产地黑咖啡，以低酸度与饱满醇厚见长，带有花生、可可与焦糖的甜感，是适合日常大口饮用的黑咖啡。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/ef/A_coffee_plantation%2C_Sao_Paolo%2C_Brazil_LCCN2016821510.jpg", "tags": ["手冲", "热饮", "黑咖啡", "坚果", "巧克力", "无乳配方", "醇厚/酒体饱满", "地域特色咖啡"], "scene": ["日常", "下午茶", "新手友好"], "recommendationScore": 93, "attributes": {"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
