ans_unroosted.jpg", "tags": ["手冲", "热饮", "黑咖啡", "泥土", "香料", "无乳配方", "醇厚/酒体饱满", "地域特色咖啡"], "scene": ["日常", "下午茶", "新手友好"], "recommendationScore": 93, "attributes": {"coffeeType": "手冲", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
