INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-fushan', 'coffee', 'COFFEE', '海南福山咖啡', 'Fushan Hainan Coffee', 'hainanfushankafei', 'hnfskf', '产自海南澄迈福山镇的咖啡，依托火山岩土壤与湿润气候，形成醇厚甜感与坚果焦糖风味，是海南代表性咖啡产区。', 'V6 编辑标准以中度偏深烘焙为基准，突出福山产区火山土孕育的醇甜与焦糖特色。', 'https://upload.wikimedia.org/wikipedia/commons/0/0b/%E5%92%96%E5%95%A1%E6%A0%912_%E7%A6%8F%E5%B1%B1%E5%92%96%E5%95%A1%E5%AE%A3%E4%BC%A0_%E6%B5%B7%E5%8D%97%E7%9C%81%E6%BE%84%E8%BF%88%E5%8E%BF.jpg', 'https://upload.wikimedia.org/wikipedia/commons/0/0b/%E5%92%96%E5%95%A1%E6%A0%912_%E7%A6%8F%E5%B1%B1%E5%92%96%E5%95%A1%E5%AE%A3%E4%BC%A0_%E6%B5%B7%E5%8D%97%E7%9C%81%E6%BE%84%E8%BF%88%E5%8E%BF.jpg', 93, 106, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "黑咖啡", "焦糖", "坚果", "巧克力", "醇厚/酒体饱满", "无乳配方", "日常"]', '["日常"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 18, "unit": "g", "role": "中度偏深烘焙处理豆"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "92°C"}]', '["将 18 g 咖啡豆研磨至中细研磨度。", "用 92°C 热水润湿滤纸并倒入咖啡粉。", "注入 30 g 热水闷蒸 25 秒。", "缓慢注水至总量 240 ml。", "萃取完成后轻摇，温热时饮用。"]', '["福山咖啡", "Fushan Coffee", "海南福山小粒咖啡"]', 'A', '2026-08-04', 1, '{"id": "coffee-fushan", "mode": "coffee", "category": "COFFEE", "nameZh": "海南福山咖啡", "nameEn": "Fushan Hainan Coffee", "intro": "产自海南澄迈福山镇的咖啡，依托火山岩土壤与湿润气候，形成醇厚甜感与坚果焦糖风味，是海南代表性咖啡产区。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0b/%E5%92%96%E5%95%A1%E6%A0%912_%E7%A6%8F%E5%B1%B1%E5%92%96%E5%95%A1%E5%AE%A3%E4%BC%A0_%E6%B5%B7%E5%8D%97%E7%9C%81%E6%BE%84%E8%BF%88%E5%8E%BF.jpg", "tags": ["热饮", "黑咖啡", "焦糖", "坚果", "巧克力", "醇厚/酒体饱满", "无乳配方", "日常"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-xinglong', 'coffee', 'COFFEE', '海南兴隆咖啡', 'Xinglong Coffee', 'hainanxinglongkafei', 'hnxlkf', '海南兴隆咖啡是产自万宁兴隆地区的咖啡，常以阿拉比卡与罗布斯塔混合、中度烘焙呈现，带有坚果与柔和焦糖甜感，口感顺滑、酸度温和。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。兴隆是中国早期咖啡种植区之一，本地常混种中粒种（罗布斯塔），风味描述按常见杯测归纳。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 107, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "手冲", "坚果", "焦糖", "中等酒体", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 15 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，补至总注水量 250 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["兴隆咖啡", "海南万宁兴隆"]', 'A', '2026-08-04', 1, '{"id": "coffee-xinglong", "mode": "coffee", "category": "COFFEE", "nameZh": "海南兴隆咖啡", "nameEn": "Xinglong Coffee", "intro": "海南兴隆咖啡是产自万宁兴隆地区的咖啡，常以阿拉比卡与罗布斯塔混合、中度烘焙呈现，带有坚果与柔和焦糖甜感，口感顺滑、酸度温和。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "黑咖啡", "手冲", "坚果", "焦糖", "中等酒体", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-alishan', 'coffee', 'COFFEE', '台湾阿里山咖啡', 'Alishan Coffee', 'taiwanalishankafei', 'twalskf', '台湾阿里山咖啡是产自阿里山高海拔山区的阿拉比卡咖啡，以细致花香、柑橘酸质与清甜口感著称，多为浅中度烘焙，适合单品冲煮。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。阿里山海拔高、云雾多、日夜温差大，咖啡生长缓慢、风味细腻，与台湾低海拔产区形成对比。', 'https://upload.wikimedia.org/wikipedia/commons/e/e5/Matsu_Coffee_%E6%9D%BE%E5%BA%AD%E5%92%96%E5%95%A1%E5%9C%92_-_panoramio.jpg', 'https://upload.wikimedia.org/wikipedia/commons/e/e5/Matsu_Coffee_%E6%9D%BE%E5%BA%AD%E5%92%96%E5%95%A1%E5%9C%92_-_panoramio.jpg', 93, 108, '[{"key": "ACIDITY", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["热饮", "黑咖啡", "手冲过滤", "花香", "柑橘", "轻盈", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 15 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，补至总注水量 250 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["阿里山咖啡", "Alishan"]', 'A', '2026-08-04', 1, '{"id": "coffee-alishan", "mode": "coffee", "category": "COFFEE", "nameZh": "台湾阿里山咖啡", "nameEn": "Alishan Coffee", "intro": "台湾阿里山咖啡是产自阿里山高海拔山区的阿拉比卡咖啡，以细致花香、柑橘酸质与清甜口感著称，多为浅中度烘焙，适合单品冲煮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e5/Matsu_Coffee_%E6%9D%BE%E5%BA%AD%E5%92%96%E5%95%A1%E5%9C%92_-_panoramio.jpg", "tags": ["热饮", "黑咖啡", "手冲过滤", "花香", "柑橘", "轻盈", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-gukeng', 'coffee', 'COFFEE', '台湾古坑咖啡', 'Gukeng Coffee', 'taiwangukengkafei', 'twgkkf', '台湾古坑咖啡是产自云林古坑地区的阿拉比卡咖啡，以坚果与焦糖甜感、醇和口感和温和酸度为特点，是台湾较知名的传统产区。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。古坑为台湾较早种植咖啡的区域，海拔与气候温和，风味以均衡醇和见长。', 'https://upload.wikimedia.org/wikipedia/commons/8/80/HUANG%2CGENG-ZIH-2003GU%2CKENG.JPG', 'https://upload.wikimedia.org/wikipedia/commons/8/80/HUANG%2CGENG-ZIH-2003GU%2CKENG.JPG', 93, 109, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "手冲", "坚果", "焦糖", "中等酒体", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 15 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，补至总注水量 250 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["古坑咖啡", "云林古坑"]', 'A', '2026-08-04', 1, '{"id": "coffee-gukeng", "mode": "coffee", "category": "COFFEE", "nameZh": "台湾古坑咖啡", "nameEn": "Gukeng Coffee", "intro": "台湾古坑咖啡是产自云林古坑地区的阿拉比卡咖啡，以坚果与焦糖甜感、醇和口感和温和酸度为特点，是台湾较知名的传统产区。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/80/HUANG%2CGENG-ZIH-2003GU%2CKENG.JPG", "tags": ["热饮", "黑咖啡", "手冲", "坚果", "焦糖", "中等酒体", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-sun-moon-lake', 'coffee', 'COFFEE', '中国台湾日月潭咖啡', 'Sun Moon Lake Coffee', 'zhongguotaiwanriyuetankafei', 'zgtwrytkf', '台湾日月潭咖啡是产自南投日月潭周边山区的阿拉比卡咖啡，以柔和果酸、焦糖甜感与均衡顺滑的口感为特点，风味清透温和。', '本条目以 V6 编辑标准统一为中度烘焙手冲冲煮，粉水比约一比十六。日月潭周边海拔较高、云雾充沛，咖啡生长条件良好，与阿里山同属台湾高山产区。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sun%20Moon%20Lake.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sun%20Moon%20Lake.jpg', 93, 110, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["热饮", "黑咖啡", "手冲过滤", "均衡", "顺滑", "中等酒体", "无乳配方", "地域特色咖啡"]', '["日常", "下午茶"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}]', '["折好滤纸放入滤杯，用热水润湿滤纸并倒掉润杯水。", "称取 15 g 咖啡豆，研磨至中细度，倒粉并轻拍平整。", "将咖啡粉倒入滤杯，注入约 45 g 热水焖蒸 30 秒。", "分两次缓慢绕圈注入热水，补至总注水量 250 ml。", "待滤杯滴滤完成（约 3 分钟），取下滤杯即可饮用。"]', '["日月潭咖啡", "Sun Moon Lake"]', 'A', '2026-08-04', 1, '{"id": "coffee-sun-moon-lake", "mode": "coffee", "category": "COFFEE", "nameZh": "中国台湾日月潭咖啡", "nameEn": "Sun Moon Lake Coffee", "intro": "台湾日月潭咖啡是产自南投日月潭周边山区的阿拉比卡咖啡，以柔和果酸、焦糖甜感与均衡顺滑的口感为特点，风味清透温和。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Sun%20Moon%20Lake.jpg", "tags": ["热饮", "黑咖啡", "手冲过滤", "均衡", "顺滑", "中等酒体", "无乳配方", "地域特色咖啡"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-green-tea', 'coffee', 'COFFEE', '绿茶咖啡', 'Green Tea Coffee', 'lvchakafei', 'lckf', '绿茶咖啡是以冲调绿茶与浓缩咖啡结合而成的冰饮，绿茶清苦与咖啡焦香相互衬托，口感清爽、咖啡因适中。', '本条目以 V6 编辑标准统一为冰饮：4 g 抹茶粉（绿茶研磨粉）以冷水调开，加入双份浓缩与冰块。抹茶为绿茶的研磨形态，用以代表绿茶基底；与抹茶拿铁的区别在于不含奶且咖啡比重更高。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Green%20tea.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Green%20tea.jpg', 91, 111, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 3.0}, {"key": "BODY", "label": "醇厚度", "score": 4.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷饮", "草本", "清爽", "含咖啡因", "无乳配方", "日常", "茶咖"]', '["日常"]', '{"coffeeType": "茶咖", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "抹茶", "nameEn": "Matcha", "amount": 4, "unit": "g", "role": "绿茶研磨粉"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 80, "unit": "ml", "role": "调开茶粉"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 60, "unit": "g", "role": "双份浓缩"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 150, "unit": "g", "role": "约 6 块"}]', '["将 4 g 抹茶粉与 80 ml 冷水混合，用茶筅搅打至无结块。", "杯中放入冰块并倒入调好的绿茶液。", "将双份浓缩咖啡液缓缓倒入，形成分层。", "轻搅后饮用，搅匀后茶与咖啡风味更均衡。"]', '["绿茶咖", "Green Tea Espresso"]', 'B', '2026-08-04', 1, '{"id": "coffee-green-tea", "mode": "coffee", "category": "COFFEE", "nameZh": "绿茶咖啡", "nameEn": "Green Tea Coffee", "intro": "绿茶咖啡是以冲调绿茶与浓缩咖啡结合而成的冰饮，绿茶清苦与咖啡焦香相互衬托，口感清爽、咖啡因适中。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Green%20tea.jpg", "tags": ["冷饮", "草本", "清爽", "含咖啡因", "无乳配方", "日常", "茶咖"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"coffeeType": "茶咖", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-jasmine-tea', 'coffee', 'COFFEE', '茉莉花茶咖啡', 'Jasmine Tea Coffee', 'molihuachakafei', 'mlhckf', '茉莉花茶咖啡是以茉莉花茶与浓缩咖啡、牛奶结合的热饮，茉莉花香清雅、奶感顺滑，茶香与咖啡香层次分明。', '本条目以 V6 编辑标准统一为热饮：绿茶基底茉莉花茶以抹茶粉（绿茶研磨粉）代表茶底，与热牛奶、单份浓缩结合，顶部以可食用花点缀。咖啡用量较轻，突出花香。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Jasmine%20tea.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Jasmine%20tea.jpg', 93, 112, '[{"key": "ACIDITY", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "花香", "奶油感", "顺滑", "下午茶", "含咖啡因", "茶咖", "奶咖"]', '["下午茶"]', '{"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "抹茶", "nameEn": "Matcha", "amount": 3, "unit": "g", "role": "绿茶研磨粉，代表茉莉花茶茶底"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "加热至 60 至 65°C"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "单份浓缩"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "茉莉花装饰"}]', '["将 3 g 抹茶粉过筛，加入 30 ml 热水搅打成茶浆。", "将 180 ml 牛奶加热至 60 至 65°C。", "萃取 36 g 浓缩咖啡液。", "杯中依次倒入茶浆、热牛奶与浓缩，顶部放茉莉花装饰。", "轻搅后饮用。"]', '["茉莉花茶咖", "Jasmine Dirty"]', 'B', '2026-08-04', 1, '{"id": "coffee-jasmine-tea", "mode": "coffee", "category": "COFFEE", "nameZh": "茉莉花茶咖啡", "nameEn": "Jasmine Tea Coffee", "intro": "茉莉花茶咖啡是以茉莉花茶与浓缩咖啡、牛奶结合的热饮，茉莉花香清雅、奶感顺滑，茶香与咖啡香层次分明。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Jasmine%20tea.jpg", "tags": ["热饮", "花香", "奶油感", "顺滑", "下午茶", "含咖啡因", "茶咖", "奶咖"], "scene": ["下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-osmanthus-tea', 'coffee', 'COFFEE', '桂花茶咖', 'Osmanthus Tea Coffee', 'guihuachaka', 'ghck', '桂花茶咖是以桂花乌龙茶与浓缩咖啡、蜂蜜结合的热饮，桂花蜜香清甜、茶香温润，咖啡带来醇厚基底。', '本条目以 V6 编辑标准统一为热饮：120 ml 乌龙茶液与热牛奶、单份浓缩结合，加入蜂蜜提味并以可食用桂花点缀。乌龙茶为半发酵茶，此处以黑茶萃取液代表茶底。', 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Cheese_molecule_osmanthus_pear_latte.jpg', 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Cheese_molecule_osmanthus_pear_latte.jpg', 93, 113, '[{"key": "ACIDITY", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "花香", "蜂蜜", "奶油感", "甜感明显", "含咖啡因", "茶咖", "奶咖"]', '["日常", "下午茶"]', '{"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 120, "unit": "ml", "role": "乌龙茶液，浸泡 3 至 5 分钟"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 120, "unit": "ml", "role": "加热至 60 至 65°C"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "单份浓缩"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "g", "role": "桂花蜜更佳"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "桂花装饰"}]', '["将 120 ml 茶液与 10 g 蜂蜜混合搅匀。", "将 120 ml 牛奶加热至 60 至 65°C。", "萃取 36 g 浓缩咖啡液。", "杯中倒入茶蜜液与热牛奶，再注入浓缩。", "顶部放桂花点缀，轻搅后饮用。"]', '["桂花咖啡", "Osmanthus Latte"]', 'B', '2026-08-04', 1, '{"id": "coffee-osmanthus-tea", "mode": "coffee", "category": "COFFEE", "nameZh": "桂花茶咖", "nameEn": "Osmanthus Tea Coffee", "intro": "桂花茶咖是以桂花乌龙茶与浓缩咖啡、蜂蜜结合的热饮，桂花蜜香清甜、茶香温润，咖啡带来醇厚基底。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7d/Cheese_molecule_osmanthus_pear_latte.jpg", "tags": ["热饮", "花香", "蜂蜜", "奶油感", "甜感明显", "含咖啡因", "茶咖", "奶咖"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-oolong-tea', 'coffee', 'COFFEE', '乌龙茶咖', 'Oolong Tea Coffee', 'wulongchaka', 'wlck', '乌龙茶咖是以半发酵乌龙茶与浓缩咖啡、牛奶结合的热饮，茶韵醇厚、奶感顺滑，咖啡与茶香相互平衡。', '本条目以 V6 编辑标准统一为热饮：140 ml 乌龙茶液与热牛奶、单份浓缩结合。乌龙茶介于绿茶与红茶之间、带焙火与花果香，此处以黑茶萃取液代表茶底，突出醇厚茶韵。', 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Starbucks_Iced_Shaken_Peach_Oolong_Tea.jpg', 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Starbucks_Iced_Shaken_Peach_Oolong_Tea.jpg', 93, 114, '[{"key": "ACIDITY", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "草本", "奶油感", "醇厚/酒体饱满", "经典", "含咖啡因", "茶咖", "奶咖"]', '["经典"]', '{"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 140, "unit": "ml", "role": "乌龙茶液，浸泡 4 分钟"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 140, "unit": "ml", "role": "加热至 60 至 65°C"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "单份浓缩"}]', '["将 140 ml 乌龙茶液倒入杯中。", "将 140 ml 牛奶加热至 60 至 65°C。", "萃取 36 g 浓缩咖啡液。", "注入热牛奶，再缓缓倒入浓缩形成分层。", "轻搅后饮用，茶与咖啡风味更融合。"]', '["乌龙咖啡", "Oolong Dirty"]', 'B', '2026-08-04', 1, '{"id": "coffee-oolong-tea", "mode": "coffee", "category": "COFFEE", "nameZh": "乌龙茶咖", "nameEn": "Oolong Tea Coffee", "intro": "乌龙茶咖是以半发酵乌龙茶与浓缩咖啡、牛奶结合的热饮，茶韵醇厚、奶感顺滑，咖啡与茶香相互平衡。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7d/Starbucks_Iced_Shaken_Peach_Oolong_Tea.jpg", "tags": ["热饮", "草本", "奶油感", "醇厚/酒体饱满", "经典", "含咖啡因", "茶咖", "奶咖"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-white-tea', 'coffee', 'COFFEE', '白茶咖啡', 'White Tea Coffee', 'baichakafei', 'bckf', '白茶咖啡是以清淡白茶与浅烘焙咖啡结合的热饮，茶感清冽、咖啡柔和，口感轻盈，适合偏好低苦茶咖的人。', '本条目以 V6 编辑标准统一为热饮：2 g 抹茶粉（未发酵茶研磨粉，代表白茶茶底）以热水调开，兑入浅烘焙手冲咖啡。白茶口感清淡，咖啡以浅焙降低苦度，整体轻盈。', 'https://upload.wikimedia.org/wikipedia/commons/6/64/Black_Coffee_and_Tea_in_White_Cup_is_Hot.png', 'https://upload.wikimedia.org/wikipedia/commons/6/64/Black_Coffee_and_Tea_in_White_Cup_is_Hot.png', 91, 115, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 3.0}, {"key": "ROAST", "label": "烘焙感", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["热饮", "草本", "轻盈", "顺滑", "低苦", "无乳配方", "茶咖"]', '["日常", "下午茶"]', '{"coffeeType": "茶咖", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "浅度烘焙咖啡豆", "nameEn": "Light roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 150, "unit": "ml", "role": "92°C 冲煮咖啡"}, {"nameZh": "抹茶", "nameEn": "Matcha", "amount": 2, "unit": "g", "role": "未发酵茶研磨粉，代表白茶茶底"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 40, "unit": "ml", "role": "80°C 调开茶粉"}]', '["折好滤纸润湿滤杯，倒入 15 g 浅烘焙咖啡粉。", "分次注水 150 ml 冲煮，约 3 分钟滴滤完成。", "将 2 g 茶粉与 40 ml 80°C 热水搅打至无结块。", "杯中倒入茶浆，再注入手冲咖啡。", "轻搅后温热饮用。"]', '["白茶咖", "White Tea Blend"]', 'B', '2026-08-04', 1, '{"id": "coffee-white-tea", "mode": "coffee", "category": "COFFEE", "nameZh": "白茶咖啡", "nameEn": "White Tea Coffee", "intro": "白茶咖啡是以清淡白茶与浅烘焙咖啡结合的热饮，茶感清冽、咖啡柔和，口感轻盈，适合偏好低苦茶咖的人。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/64/Black_Coffee_and_Tea_in_White_Cup_is_Hot.png", "tags": ["热饮", "草本", "轻盈", "顺滑", "低苦", "无乳配方", "茶咖"], "scene": ["日常", "下午茶"], "recommendationScore": 91, "attributes": {"coffeeType": "茶咖", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-chenpi', 'coffee', 'COFFEE', '陈皮咖啡', 'Chenpi Coffee', 'chenpikafei', 'cpkf', '陈皮咖啡是以陈皮与中度烘焙黑咖啡结合的热饮，柑橘陈香与咖啡苦香交融，微甜顺口，口感温润。', '本条目以 V6 编辑标准统一为热饮：以 2 g 陈皮（此处以橙皮代表柑橘果皮）与咖啡一同冲煮，并加少量蜂蜜调和。陈皮为晒干的柑橘果皮、具陈香与回甘，实际风味随陈化年份变化。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Green%20tea.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Green%20tea.jpg', 91, 116, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "柑橘", "香料", "甜感明显", "经典", "无乳配方", "风味咖啡"]', '["经典"]', '{"coffeeType": "风味咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 2, "unit": "g", "role": "陈皮，以橙皮代表柑橘果皮"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "g", "role": "调和陈香"}]', '["将 15 g 中细研磨咖啡粉倒入润湿的滤杯。", "分次注水冲煮 250 ml 咖啡液。", "将 2 g 陈皮（橙皮）与 10 g 蜂蜜放入杯中。", "注入热咖啡，浸泡 1 分钟使陈香释放。", "过滤掉果皮后趁热饮用。"]', '["陈皮黑咖啡", "Tangerine Peel Coffee"]', 'B', '2026-08-04', 1, '{"id": "coffee-chenpi", "mode": "coffee", "category": "COFFEE", "nameZh": "陈皮咖啡", "nameEn": "Chenpi Coffee", "intro": "陈皮咖啡是以陈皮与中度烘焙黑咖啡结合的热饮，柑橘陈香与咖啡苦香交融，微甜顺口，口感温润。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Green%20tea.jpg", "tags": ["热饮", "柑橘", "香料", "甜感明显", "经典", "无乳配方", "风味咖啡"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"coffeeType": "风味咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "常温", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cinnamon', 'coffee', 'COFFEE', '肉桂咖啡', 'Cinnamon Coffee', 'rouguikafei', 'rgkf', '肉桂咖啡是以肉桂棒与中度烘焙黑咖啡结合的热饮，肉桂辛香温暖、咖啡苦香醇和，口感顺滑、甜度轻微。', '本条目以 V6 编辑标准统一为热饮：将 2 g 肉桂棒与 250 ml 手冲咖啡一同浸泡增香，不加奶与糖。肉桂为常见香料咖啡搭配，实际用量与浸泡时间影响香气强度。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 117, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "香料", "经典", "低糖", "无乳配方", "日常", "风味咖啡"]', '["经典", "日常"]', '{"coffeeType": "风味咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "研磨度接近细砂糖"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 250, "unit": "ml", "role": "90–94°C"}, {"nameZh": "肉桂棒", "nameEn": "Cinnamon stick", "amount": 2, "unit": "g", "role": "约 5 cm 一段，浸泡增香"}]', '["将 15 g 中细研磨咖啡粉倒入润湿的滤杯。", "分次注水冲煮 250 ml 咖啡液。", "将 2 g 肉桂棒放入杯中。", "注入热咖啡，浸泡 2 分钟使香气释放。", "取出肉桂棒后趁热饮用。"]', '["肉桂黑咖啡", "Cinnamon Brew"]', 'B', '2026-08-04', 1, '{"id": "coffee-cinnamon", "mode": "coffee", "category": "COFFEE", "nameZh": "肉桂咖啡", "nameEn": "Cinnamon Coffee", "intro": "肉桂咖啡是以肉桂棒与中度烘焙黑咖啡结合的热饮，肉桂辛香温暖、咖啡苦香醇和，口感顺滑、甜度轻微。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "香料", "经典", "低糖", "无乳配方", "日常", "风味咖啡"], "scene": ["经典", "日常"], "recommendationScore": 91, "attributes": {"coffeeType": "风味咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-ginger', 'coffee', 'COFFEE', '姜汁咖啡', 'Ginger Coffee', 'jiangzhikafei', 'jzkf', '姜汁咖啡是以新鲜姜汁与咖啡、牛奶结合的热饮，姜香微辛、奶感顺滑，红糖带来温润甜感，口感暖和。', '本条目以 V6 编辑标准统一为热饮：10 g 新鲜姜榨汁，与 160 ml 热牛奶、单份浓缩结合，加红糖调和。姜汁用量影响辛感强度，本配比为统一比较用的编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Ginger.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Ginger.jpg', 93, 118, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "姜味", "甜感明显", "奶油感", "早午餐", "含咖啡因", "风味咖啡", "奶咖"]', '["早午餐"]', '{"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}', '[{"nameZh": "生姜", "nameEn": "Fresh ginger", "amount": 10, "unit": "g", "role": "现磨取汁"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 160, "unit": "ml", "role": "加热至 60 至 65°C"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "单份浓缩"}, {"nameZh": "红糖", "nameEn": "Brown sugar", "amount": 8, "unit": "g", "role": "调和姜辛"}]', '["将 10 g 生姜去皮磨碎并挤出姜汁。", "将 160 ml 牛奶加热至 60 至 65°C。", "萃取 36 g 浓缩咖啡液。", "杯中放入姜汁与 8 g 红糖，注入热牛奶搅匀。", "倒入浓缩咖啡，轻搅后趁热饮用。"]', '["姜汁拿铁", "Ginger Latte"]', 'B', '2026-08-04', 1, '{"id": "coffee-ginger", "mode": "coffee", "category": "COFFEE", "nameZh": "姜汁咖啡", "nameEn": "Ginger Coffee", "intro": "姜汁咖啡是以新鲜姜汁与咖啡、牛奶结合的热饮，姜香微辛、奶感顺滑，红糖带来温润甜感，口感暖和。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Ginger.jpg", "tags": ["热饮", "姜味", "甜感明显", "奶油感", "早午餐", "含咖啡因", "风味咖啡", "奶咖"], "scene": ["早午餐"], "recommendationScore": 93, "attributes": {"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-honey', 'coffee', 'COFFEE', '蜂蜜咖啡', 'Honey Coffee', 'fengmikafei', 'fmkf', '以意式浓缩为基底、加入蜂蜜调味的热饮咖啡，蜂蜜的甜香与咖啡的烘焙感融合，口感圆润，适合偏好天然甜味的人。', 'V6 编辑标准化配比为双份浓缩 36 g 加 220 ml 蒸煮全脂牛奶，配 15 g 浅色蜂蜜。蜂蜜在牛奶与浓缩之间提供天然甜感，甜度强度低于糖浆类调味。', 'https://upload.wikimedia.org/wikipedia/commons/8/80/Chocolate_doughnut_and_coffee_at_Honey%27s.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/80/Chocolate_doughnut_and_coffee_at_Honey%27s.jpg', 91, 119, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "奶咖", "蜂蜜", "甜感明显", "奶油感", "日常", "风味咖啡"]', '["日常"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取的浓缩"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸汽加热至 60–65°C 并打出薄奶泡"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 15, "unit": "g", "role": "选用浅色蜂蜜以保留花香"}]', '["萃取双份浓缩 36 g。", "将 220 ml 全脂牛奶加热至 60–65°C 并打出薄奶泡。", "杯中先加入 15 g 蜂蜜。", "倒入浓缩，再倒入热牛奶并轻搅。", "立即饮用。"]', '["蜂蜜拿铁", "Honey Latte", "Café con Miel"]', 'B', '2026-08-04', 1, '{"id": "coffee-honey", "mode": "coffee", "category": "COFFEE", "nameZh": "蜂蜜咖啡", "nameEn": "Honey Coffee", "intro": "以意式浓缩为基底、加入蜂蜜调味的热饮咖啡，蜂蜜的甜香与咖啡的烘焙感融合，口感圆润，适合偏好天然甜味的人。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/80/Chocolate_doughnut_and_coffee_at_Honey%27s.jpg", "tags": ["热饮", "奶咖", "蜂蜜", "甜感明显", "奶油感", "日常", "风味咖啡"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-butter', 'coffee', 'COFFEE', '黄油咖啡', 'Butter Coffee', 'huangyoukafei', 'hykf', '以热咖啡为基础，加入黄油搅拌乳化而成的浓郁热饮，口感厚实顺滑，苦味柔和，常作为能量密度较高的早餐咖啡。', 'V6 编辑标准化配方为 240 ml 法压热咖啡配 15 g 无盐黄油与 1 g 海盐，高速搅打乳化。配方不使用牛奶，但黄油仍属乳制品，乳糖或乳蛋白敏感者需留意。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 120, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 9.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["热饮", "醇厚/酒体饱满", "奶油感", "低糖", "含咖啡因", "日常", "风味咖啡", "奶咖"]', '["日常"]', '{"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常"]}', '[{"nameZh": "法压咖啡液", "nameEn": "French press coffee", "amount": 240, "unit": "ml", "role": "深度烘焙豆按 1:12 粉水比法压萃取"}, {"nameZh": "黄油", "nameEn": "Butter", "amount": 15, "unit": "g", "role": "无盐黄油，室温软化"}, {"nameZh": "细海盐", "nameEn": "Fine sea salt", "amount": 1, "unit": "g", "role": "平衡风味"}]', '["用 1:12 粉水比法压萃取 240 ml 热咖啡。", "将咖啡、15 g 无盐黄油与 1 g 海盐放入搅拌杯。", "高速搅拌 20–30 秒至油脂完全乳化。", "倒入杯中，确认表面无油花分层。", "趁热饮用，避免久置后再次分层。"]', '["防弹咖啡", "Bulletproof Coffee"]', 'B', '2026-08-04', 1, '{"id": "coffee-butter", "mode": "coffee", "category": "COFFEE", "nameZh": "黄油咖啡", "nameEn": "Butter Coffee", "intro": "以热咖啡为基础，加入黄油搅拌乳化而成的浓郁热饮，口感厚实顺滑，苦味柔和，常作为能量密度较高的早餐咖啡。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "醇厚/酒体饱满", "奶油感", "低糖", "含咖啡因", "日常", "风味咖啡", "奶咖"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-vietnamese', 'coffee', 'COFFEE', '越南咖啡', 'Vietnamese Iced Coffee', 'yuenankafei', 'ynkf', '以深度烘焙咖啡经滴滤萃取后，与炼乳混合并加冰而成的经典越南冰饮，甜与苦并存，口感浓郁醇厚。', 'V6 编辑标准化按 phin 滤杯滴滤：20 g 中细研磨深烘焙咖啡粉用 88–92°C 热水萃取约 100 ml，兑 25 g 全脂炼乳后加冰至满杯。炼乳提供奶香与甜感，属于含乳饮品。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 89, 121, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 9.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["冷饮", "奶咖", "甜感明显", "醇厚/酒体饱满", "浓郁甜", "夏季"]', '["夏季"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": ["夏季"]}', '[{"nameZh": "手冲咖啡液", "nameEn": "Drip coffee liquid", "amount": 100, "unit": "ml", "role": "深度烘焙豆 phin 滴滤萃取"}, {"nameZh": "炼乳", "nameEn": "Condensed milk", "amount": 25, "unit": "g", "role": "全脂炼乳"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "满杯冰块"}]', '["将 20 g 中细研磨的深烘焙咖啡粉放入 phin 滤杯。", "注入 30 g 88–92°C 热水预浸润 30 秒。", "注入剩余热水，静置滴滤约 4–6 分钟得到约 100 ml 咖啡液。", "杯底先放 25 g 炼乳，倒入咖啡液并搅匀。", "加入 120 g 冰块，搅匀后饮用。"]', '["越式冰咖啡", "炼乳咖啡", "cà phê sữa đá"]', 'B', '2026-08-04', 1, '{"id": "coffee-vietnamese", "mode": "coffee", "category": "COFFEE", "nameZh": "越南咖啡", "nameEn": "Vietnamese Iced Coffee", "intro": "以深度烘焙咖啡经滴滤萃取后，与炼乳混合并加冰而成的经典越南冰饮，甜与苦并存，口感浓郁醇厚。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["冷饮", "奶咖", "甜感明显", "醇厚/酒体饱满", "浓郁甜", "夏季"], "scene": ["夏季"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cafe-au-lait', 'coffee', 'COFFEE', '法式牛奶咖啡', 'Café au Lait', 'fashiniunaikafei', 'fsnnkf', '以等比例的法压或滴滤咖啡与热牛奶调和而成的法式经典热饮，奶香与咖啡味均衡，口感温和顺滑。', 'V6 编辑标准化为 1:1 配比：150 ml 法压咖啡兑 150 ml 60–65°C 全脂牛奶。不使用浓缩，咖啡与奶的浓度比浓缩基奶咖更低更温和。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 89, 122, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "奶咖", "均衡", "顺滑", "经典", "日常"]', '["经典", "日常"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}', '[{"nameZh": "法压咖啡液", "nameEn": "French press coffee", "amount": 150, "unit": "ml", "role": "中度烘焙豆按 1:12 粉水比法压萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 150, "unit": "ml", "role": "加热至 60–65°C，不追求厚奶泡"}]', '["用 1:12 粉水比法压萃取 150 ml 咖啡。", "将 150 ml 全脂牛奶加热至 60–65°C。", "将咖啡与牛奶同时倒入杯中，保持约 1:1 比例。", "轻搅一次使奶咖融合。", "趁热饮用。"]', '["牛奶咖啡", "欧蕾咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-cafe-au-lait", "mode": "coffee", "category": "COFFEE", "nameZh": "法式牛奶咖啡", "nameEn": "Café au Lait", "intro": "以等比例的法压或滴滤咖啡与热牛奶调和而成的法式经典热饮，奶香与咖啡味均衡，口感温和顺滑。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "奶咖", "均衡", "顺滑", "经典", "日常"], "scene": ["经典", "日常"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-latte-macchiato', 'coffee', 'COFFEE', '拿铁玛奇朵', 'Latte Macchiato', 'natiemaqiduo', 'ntmqd', '以大量热牛奶和厚奶泡为基底、浓缩咖啡最后注入形成的分层奶咖，奶香突出，浓缩风味作为收尾。', 'V6 编辑标准化为 220 ml 蒸煮全脂牛奶加厚奶泡，再注入双份浓缩 36 g。与浓缩基的拿铁相比，奶的比例更高、分层更明显，浓缩以点缀方式叠加。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20macchiato.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20macchiato.jpg', 89, 123, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "奶咖", "奶油感", "泡沫质地", "甜感明显", "早午餐"]', '["早午餐"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}', '[{"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸煮至 60–65°C，上层留约 1 cm 厚奶泡"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}]', '["将 220 ml 全脂牛奶蒸煮至 60–65°C 并打出约 1 cm 厚奶泡。", "将牛奶与奶泡倒入透明杯中。", "缓慢注入双份浓缩 36 g，让浓缩浮于奶泡上形成分层。", "保持分层状态上桌，饮用前轻搅。"]', '["拉提玛琪朵", "牛奶玛奇朵"]', 'A', '2026-08-04', 1, '{"id": "coffee-latte-macchiato", "mode": "coffee", "category": "COFFEE", "nameZh": "拿铁玛奇朵", "nameEn": "Latte Macchiato", "intro": "以大量热牛奶和厚奶泡为基底、浓缩咖啡最后注入形成的分层奶咖，奶香突出，浓缩风味作为收尾。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20macchiato.jpg", "tags": ["热饮", "奶咖", "奶油感", "泡沫质地", "甜感明显", "早午餐"], "scene": ["早午餐"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-creme-brulee-latte', 'coffee', 'COFFEE', '焦糖布蕾拿铁', 'Crème Brûlée Latte', 'jiaotangbuleinatie', 'jtblnt', '在拿铁基础上加入焦糖与香草风味的奶咖，表层可撒糖炙烤出布蕾脆壳，甜感浓郁，口感绵密顺滑。', 'V6 编辑标准化以双份浓缩 36 g、220 ml 蒸煮牛奶、20 g 焦糖糖浆与 5 g 香草糖浆组合，杯顶糖壳为可选呈现，甜度高于普通拿铁。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 124, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 9.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "焦糖", "香草", "浓郁甜", "奶油感", "节日"]', '["节日"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["节日"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸煮至 60–65°C 并打出薄奶泡"}, {"nameZh": "焦糖糖浆", "nameEn": "Caramel syrup", "amount": 20, "unit": "g", "role": "焦糖糖浆"}, {"nameZh": "香草糖浆", "nameEn": "Vanilla syrup", "amount": 5, "unit": "g", "role": "香草糖浆"}]', '["杯中先加入 20 g 焦糖糖浆与 5 g 香草糖浆。", "萃取双份浓缩 36 g 倒入杯中搅匀。", "将 220 ml 牛奶蒸煮至 60–65°C 并打出薄奶泡。", "将牛奶倒入杯中，用奶泡覆盖表面。", "如需布蕾呈现，可在表面撒糖并短暂炙烤至焦色。"]', '["烤布蕾拿铁", "焦糖布蕾奶咖"]', 'B', '2026-08-04', 1, '{"id": "coffee-creme-brulee-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "焦糖布蕾拿铁", "nameEn": "Crème Brûlée Latte", "intro": "在拿铁基础上加入焦糖与香草风味的奶咖，表层可撒糖炙烤出布蕾脆壳，甜感浓郁，口感绵密顺滑。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "奶咖", "焦糖", "香草", "浓郁甜", "奶油感", "节日"], "scene": ["节日"], "recommendationScore": 91, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-salted-caramel-latte', 'coffee', 'COFFEE', '海盐焦糖拿铁', 'Salted Caramel Latte', 'haiyanjiaotangnatie', 'hyjtnt', '拿铁中加入焦糖糖浆并以海盐提味的奶咖，咸甜交织，焦糖的浓甜被盐粒平衡，苦味轻柔，口感层次丰富。', 'V6 编辑标准化为双份浓缩 36 g、220 ml 蒸煮牛奶与 18 g 焦糖糖浆，表层撒 0.5 g 海盐。盐的作用是平衡甜度而非咸味主导，整体甜感仍明显。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 89, 125, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "焦糖", "甜感明显", "奶油感", "餐后"]', '["餐后"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸煮至 60–65°C 并打出薄奶泡"}, {"nameZh": "焦糖糖浆", "nameEn": "Caramel syrup", "amount": 18, "unit": "g", "role": "焦糖糖浆"}, {"nameZh": "细海盐", "nameEn": "Fine sea salt", "amount": 0.5, "unit": "g", "role": "表面撒盐约一小撮"}]', '["萃取双份浓缩 36 g，加入 18 g 焦糖糖浆搅匀。", "将 220 ml 牛奶蒸煮至 60–65°C 并打出薄奶泡。", "牛奶倒入杯中，奶泡铺面。", "表面均匀撒 0.5 g 海盐。", "轻搅后趁热饮用。"]', '["盐焦糖拿铁", "海盐焦糖牛奶咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-salted-caramel-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "海盐焦糖拿铁", "nameEn": "Salted Caramel Latte", "intro": "拿铁中加入焦糖糖浆并以海盐提味的奶咖，咸甜交织，焦糖的浓甜被盐粒平衡，苦味轻柔，口感层次丰富。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "奶咖", "焦糖", "甜感明显", "奶油感", "餐后"], "scene": ["餐后"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-brown-sugar-latte', 'coffee', 'COFFEE', '黑糖拿铁', 'Brown Sugar Latte', 'heitangnatie', 'htnt', '以双份浓缩与蒸煮牛奶为基、加入黑糖调制的奶咖，黑糖带有焦香与甘蔗甜感，甜度适中，口感顺滑甜润。', 'V6 编辑标准化以 18 g 黑糖配合双份浓缩 36 g 与 220 ml 牛奶。黑糖风味较白砂糖更饱满，带轻微焦糖与红糖特有的醇香，甜度属中高。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 89, 126, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "甜感明显", "焦糖", "奶油感", "日常"]', '["日常"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸煮至 60–65°C 并打出奶泡"}, {"nameZh": "红糖", "nameEn": "Brown sugar", "amount": 18, "unit": "g", "role": "黑糖，提前用少量热水化开"}]', '["将 18 g 黑糖用 30 ml 热水化开。", "萃取双份浓缩 36 g，与黑糖液搅匀。", "将 220 ml 牛奶蒸煮至 60–65°C 并打出奶泡。", "牛奶倒入杯中，轻搅融合。", "趁热饮用。"]', '["黑糖牛奶咖啡", "红糖拿铁"]', 'B', '2026-08-04', 1, '{"id": "coffee-brown-sugar-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "黑糖拿铁", "nameEn": "Brown Sugar Latte", "intro": "以双份浓缩与蒸煮牛奶为基、加入黑糖调制的奶咖，黑糖带有焦香与甘蔗甜感，甜度适中，口感顺滑甜润。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg", "tags": ["热饮", "奶咖", "甜感明显", "焦糖", "奶油感", "日常"], "scene": ["日常"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-sesame-latte', 'coffee', 'COFFEE', '芝麻拿铁', 'Black Sesame Latte', 'zhimanatie', 'zmnt', '在拿铁基础上加入黑芝麻酱调制的奶咖，芝麻的烘烤坚果香与奶香咖啡融合，甜中带香，口感浓醇。', 'V6 编辑标准化为双份浓缩 36 g、220 ml 蒸煮牛奶与 20 g 无糖黑芝麻酱，芝麻酱以自磨或市售无添加糖酱为准。属含乳饮品，并含芝麻过敏原。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 89, 127, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "坚果", "奶油感", "甜感明显", "下午茶"]', '["下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "与 20 g 黑芝麻酱混合后蒸煮"}, {"nameZh": "红糖", "nameEn": "Brown sugar", "amount": 12, "unit": "g", "role": "调节甜度"}]', '["将 20 g 无糖黑芝麻酱与 220 ml 牛奶混合搅匀。", "混合液蒸煮至 60–65°C。", "萃取双份浓缩 36 g，加入 12 g 黑糖化开的糖液。", "倒入芝麻牛奶并轻搅均匀。", "表面可撒 2 g 熟芝麻增香，趁热饮用。"]', '["黑芝麻拿铁", "芝麻牛奶咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-sesame-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "芝麻拿铁", "nameEn": "Black Sesame Latte", "intro": "在拿铁基础上加入黑芝麻酱调制的奶咖，芝麻的烘烤坚果香与奶香咖啡融合，甜中带香，口感浓醇。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg", "tags": ["热饮", "奶咖", "坚果", "奶油感", "甜感明显", "下午茶"], "scene": ["下午茶"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-peanut-latte', 'coffee', 'COFFEE', '花生拿铁', 'Peanut Latte', 'huashengnatie', 'hsnt', '拿铁中加入顺滑花生酱调制的奶咖，花生的浓郁坚果香与奶咖融合，甜咸平衡，油脂感饱满，口感浓稠绵密。', 'V6 编辑标准化为双份浓缩 36 g、220 ml 蒸煮牛奶与 15 g 无糖花生酱，花生酱需提前搅打顺滑以防结块。属含乳与坚果类饮品。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 89, 128, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "坚果", "醇厚/酒体饱满", "甜感明显", "早午餐"]', '["早午餐"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "与 15 g 花生酱混合后蒸煮"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 8, "unit": "g", "role": "可选甜味调节"}]', '["将 15 g 顺滑无糖花生酱与 220 ml 牛奶混合搅匀。", "混合液蒸煮至 60–65°C。", "萃取双份浓缩 36 g 倒入杯中。", "倒入花生牛奶，加入 8 g 蜂蜜，轻搅均匀。", "趁热饮用。"]', '["花生牛奶咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-peanut-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "花生拿铁", "nameEn": "Peanut Latte", "intro": "拿铁中加入顺滑花生酱调制的奶咖，花生的浓郁坚果香与奶咖融合，甜咸平衡，油脂感饱满，口感浓稠绵密。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg", "tags": ["热饮", "奶咖", "坚果", "醇厚/酒体饱满", "甜感明显", "早午餐"], "scene": ["早午餐"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-pistachio-latte', 'coffee', 'COFFEE', '开心果拿铁', 'Pistachio Latte', 'kaixinguonatie', 'kxgnt', '拿铁中加入开心果酱调制的奶咖，开心果细腻清雅的坚果香与奶咖结合，甜感适度，尾韵干净，口感丝滑醇厚。', 'V6 编辑标准化为双份浓缩 36 g、220 ml 蒸煮牛奶与 15 g 无糖开心果酱，开心果酱需研磨细腻以保持口感顺滑。属含乳与坚果类饮品。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 91, 129, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "坚果", "香草", "奶油感", "甜感明显", "下午茶"]', '["下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "与 15 g 开心果酱混合后蒸煮"}, {"nameZh": "香草糖浆", "nameEn": "Vanilla syrup", "amount": 5, "unit": "g", "role": "提升甜香层次"}]', '["将 15 g 无糖开心果酱与 220 ml 牛奶混合搅匀。", "混合液蒸煮至 60–65°C 并打出薄奶泡。", "萃取双份浓缩 36 g 倒入杯中。", "倒入开心果牛奶，加入 5 g 香草糖浆。", "轻搅后趁热饮用。"]', '["开心果牛奶咖啡", "开心果奶咖"]', 'B', '2026-08-04', 1, '{"id": "coffee-pistachio-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "开心果拿铁", "nameEn": "Pistachio Latte", "intro": "拿铁中加入开心果酱调制的奶咖，开心果细腻清雅的坚果香与奶咖结合，甜感适度，尾韵干净，口感丝滑醇厚。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg", "tags": ["热饮", "奶咖", "坚果", "香草", "奶油感", "甜感明显", "下午茶"], "scene": ["下午茶"], "recommendationScore": 91, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-tiramisu-latte', 'coffee', 'COFFEE', '提拉米苏拿铁', 'Tiramisu Latte', 'tilamisunatie', 'tlmsnt', '以浓缩、蒸煮牛奶与表层可可粉复刻提拉米苏风味的奶咖，咖啡苦调与可可、奶香交织，甜感平衡，口感绵密顺滑。', 'V6 编辑标准化为双份浓缩 36 g、220 ml 蒸煮牛奶、表层 3 g 可可粉与可选的 20 g 打发奶油顶饰，甜度中等，突出可可与咖啡的复合感。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 91, 130, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "巧克力", "咖啡风味", "奶油感", "甜感明显", "餐后"]', '["餐后"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸煮至 60–65°C 并打出奶泡"}, {"nameZh": "打发奶油", "nameEn": "Whipped cream", "amount": 20, "unit": "g", "role": "可选马斯卡彭风味顶饰"}, {"nameZh": "可可粉", "nameEn": "Cocoa powder", "amount": 3, "unit": "g", "role": "表层筛撒"}]', '["萃取双份浓缩 36 g。", "将 220 ml 牛奶蒸煮至 60–65°C 并打出奶泡。", "杯中倒入浓缩与牛奶，轻搅。", "表面铺 20 g 打发奶油。", "均匀筛撒 3 g 可可粉，趁热饮用。"]', '["提拉米苏奶咖", "提拉米苏牛奶咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-tiramisu-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "提拉米苏拿铁", "nameEn": "Tiramisu Latte", "intro": "以浓缩、蒸煮牛奶与表层可可粉复刻提拉米苏风味的奶咖，咖啡苦调与可可、奶香交织，甜感平衡，口感绵密顺滑。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg", "tags": ["热饮", "奶咖", "巧克力", "咖啡风味", "奶油感", "甜感明显", "餐后"], "scene": ["餐后"], "recommendationScore": 91, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-martini', 'cocktail', 'COCKTAIL', '马天尼', 'Martini (Cocktail)', 'matianni', 'mtn', '以金酒与干味美思调制、直接搅拌并过滤的经典鸡尾酒，以干冽口感与草本气息著称，是烈酒主导型饮品的代表。', '本条目采用通用金酒马天尼配比：60 ml 金酒加 15 ml 干味美思，搅拌后滤入冰镇杯。风味与浓淡会随味美思比例和所用金酒风格明显变化，按 IBA 通用做法标准化。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 98, 1, '[{"key": "SWEETNESS", "label": "甜度", "score": 1.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["烈酒主导", "金酒基底", "偏干", "搅拌", "高强度", "经典", "开胃"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 60, "unit": "ml", "role": "IBA 通用配比"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 15, "unit": "ml", "role": "可选 6:1 金酒与味美思比例"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "搅拌用"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "在搅拌杯中加入足量冰块。", "倒入金酒与干味美思，搅拌约 20 秒至充分降温。", "滤入冰镇马天尼杯。", "挤柠檬皮油于杯面后投入或丢弃。"]', '["马天尼鸡尾酒", "Martini", "Gin Martini"]', 'A', '2026-08-04', 1, '{"id": "cocktail-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "马天尼", "nameEn": "Martini (Cocktail)", "intro": "以金酒与干味美思调制、直接搅拌并过滤的经典鸡尾酒，以干冽口感与草本气息著称，是烈酒主导型饮品的代表。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["烈酒主导", "金酒基底", "偏干", "搅拌", "高强度", "经典", "开胃"], "scene": ["经典", "开胃"], "recommendationScore": 98, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-dry-martini', 'cocktail', 'COCKTAIL', '干马天尼', 'Dry Martini', 'ganmatianni', 'gmtn', '以金酒为主、干味美思仅极少量辅助的极干型鸡尾酒，几乎纯烈的金酒风味与低甜度构成其标志性口感。', '本条目按 IBA 干马天尼配比标准化：60 ml 金酒兑 10 ml 干味美思，搅拌后滤杯。家庭版常以极少量味美思润杯即弃，风味更干。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 98, 2, '[{"key": "SWEETNESS", "label": "甜度", "score": 1.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["烈酒主导", "金酒基底", "偏干", "苦味明显", "搅拌", "高强度", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 60, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 10, "unit": "ml", "role": "极干比例，可再减少"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "搅拌用"}, {"nameZh": "青橄榄", "nameEn": "Green olive", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "搅拌杯加冰，倒入金酒与干味美思。", "搅拌约 20 秒至充分降温。", "滤入冰镇马天尼杯。", "以一颗青橄榄装饰。"]', '["Dry Martini", "干马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-dry-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "干马天尼", "nameEn": "Dry Martini", "intro": "以金酒为主、干味美思仅极少量辅助的极干型鸡尾酒，几乎纯烈的金酒风味与低甜度构成其标志性口感。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["烈酒主导", "金酒基底", "偏干", "苦味明显", "搅拌", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 98, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-dirty-martini', 'cocktail', 'COCKTAIL', '脏马天尼', 'Dirty Martini', 'zangmatianni', 'zmtn', '在干马天尼基础上加入橄榄盐水调制的鸡尾酒，呈现浑浊的咸鲜风味，是咸鲜与烈酒结合的经典变体。', '本条目按 IBA 脏马天尼配比标准化：60 ml 金酒、10 ml 干味美思，加一颗压碎的青橄榄连同腌制汁液，搅拌滤杯。咸度随橄榄与汁液用量变化，可依口味调整。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 96, 3, '[{"key": "SWEETNESS", "label": "甜度", "score": 1.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["烈酒主导", "金酒基底", "偏干", "咸鲜", "搅拌", "高强度"]', '["节日", "经典", "餐后"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干、咸鲜", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["节日", "经典", "餐后"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 60, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 10, "unit": "ml", "role": "可减至 5 ml"}, {"nameZh": "青橄榄", "nameEn": "Green olive", "amount": 15, "unit": "g", "role": "含腌制盐水，捣碎后连同汁液加入"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "搅拌用"}, {"nameZh": "青橄榄", "nameEn": "Green olive", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "将一颗青橄榄放入搅拌杯轻压，保留橄榄与汁液。", "加入冰块，倒入金酒、干味美思与橄榄汁液。", "搅拌约 20 秒至充分降温。", "滤入冰镇马天尼杯，可留一颗青橄榄入杯装饰。"]', '["Dirty Martini", "脏马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-dirty-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "脏马天尼", "nameEn": "Dirty Martini", "intro": "在干马天尼基础上加入橄榄盐水调制的鸡尾酒，呈现浑浊的咸鲜风味，是咸鲜与烈酒结合的经典变体。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["烈酒主导", "金酒基底", "偏干", "咸鲜", "搅拌", "高强度"], "scene": ["节日", "经典", "餐后"], "recommendationScore": 96, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干、咸鲜", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gibson', 'cocktail', 'COCKTAIL', '吉布森', 'Gibson', 'jibusen', 'jbs', '以金酒与干味美思调制的干型鸡尾酒，经典配以鸡尾酒洋葱装饰，是马天尼家族中带有咸鲜特色的经典变体。', '本条目按 IBA 吉布森配比标准化：60 ml 金酒兑 10 ml 干味美思，搅拌滤杯。传统以鸡尾酒洋葱装饰，本配方以青橄榄替代并保留腌制汁液风味。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gibson%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gibson%20cocktail.jpg', 98, 4, '[{"key": "SWEETNESS", "label": "甜度", "score": 1.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["烈酒主导", "金酒基底", "偏干", "咸鲜", "搅拌", "高强度", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干、咸鲜", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 60, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 10, "unit": "ml", "role": "极干比例"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "搅拌用"}, {"nameZh": "青橄榄", "nameEn": "Green olive", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "搅拌杯加冰，倒入金酒与干味美思。", "搅拌约 20 秒至充分降温。", "滤入冰镇马天尼杯。", "传统以鸡尾酒洋葱装饰，本条目以一颗青橄榄替代。"]', '["Gibson", "吉布森马天尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-gibson", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "吉布森", "nameEn": "Gibson", "intro": "以金酒与干味美思调制的干型鸡尾酒，经典配以鸡尾酒洋葱装饰，是马天尼家族中带有咸鲜特色的经典变体。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Gibson%20cocktail.jpg", "tags": ["烈酒主导", "金酒基底", "偏干", "咸鲜", "搅拌", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 98, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干、咸鲜", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vodka-martini', 'cocktail', 'COCKTAIL', '伏特加马天尼', 'Vodka Martini', 'futejiamatianni', 'ftjmtn', '以伏特加替代金酒与干味美思调制的干型鸡尾酒，口感更为纯净顺滑，是马天尼的伏特加基底变体。', '本条目采用 60 ml 伏特加兑 10 ml 干味美思的配比，搅拌滤杯。可用苦精增香或用橄榄盐水做成脏版，V6 按基础干型标准化。', 'https://upload.wikimedia.org/wikipedia/commons/0/00/VodkaMartini.jpg', 'https://upload.wikimedia.org/wikipedia/commons/0/00/VodkaMartini.jpg', 96, 5, '[{"key": "SWEETNESS", "label": "甜度", "score": 1.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["烈酒主导", "伏特加基底", "偏干", "搅拌", "高强度", "经典"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "烈酒主导", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 60, "unit": "ml", "role": "选用中性伏特加"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 10, "unit": "ml", "role": "极干比例"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "搅拌用"}, {"nameZh": "青橄榄", "nameEn": "Green olive", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "搅拌杯加冰，倒入伏特加与干味美思。", "搅拌约 20 秒至充分降温。", "滤入冰镇马天尼杯。", "以一颗青橄榄装饰。"]', '["Vodka Martini", "伏特加马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-vodka-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "伏特加马天尼", "nameEn": "Vodka Martini", "intro": "以伏特加替代金酒与干味美思调制的干型鸡尾酒，口感更为纯净顺滑，是马天尼的伏特加基底变体。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/00/VodkaMartini.jpg", "tags": ["烈酒主导", "伏特加基底", "偏干", "搅拌", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 96, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "烈酒主导", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-espresso-martini', 'cocktail', 'COCKTAIL', '咖啡马天尼', 'Espresso Martini', 'kafeimatianni', 'kfmtn', '以伏特加、浓缩咖啡与咖啡利口酒摇制的咖啡风味鸡尾酒，杯面浮着绵密泡沫，兼具咖啡香与酒感。', '本条目按 IBA 配比标准化：30 ml 伏特加、30 ml 咖啡利口酒加 30 ml 浓缩咖啡，摇和滤入马天尼杯，以咖啡豆装饰。使用新鲜浓缩咖啡可稳定获得泡沫层。', '/assets/images/posters/cocktail-espresso-martini-hero.webp', '/assets/images/posters/cocktail-espresso-martini-hero.webp', 100, 6, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["咖啡鸡尾酒", "伏特加基底", "咖啡风味", "泡沫质地", "摇和", "甜感明显", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["餐后"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 30, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "咖啡利口酒（通用）", "nameEn": "Coffee liqueur (generic)", "amount": 30, "unit": "ml", "role": "推荐咖啡利口酒"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 30, "unit": "ml", "role": "新鲜萃取浓缩"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "摇和用"}, {"nameZh": "咖啡豆装饰", "nameEn": "Espresso beans garnish", "amount": 3, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "摇酒壶加冰，倒入伏特加、咖啡利口酒与浓缩咖啡。", "用力摇和约 12 秒至充分降温。", "双重滤入冰镇马天尼杯。", "以三颗咖啡豆置于泡沫面上装饰。"]', '["Espresso Martini", "意式浓缩马天尼", "咖啡马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-espresso-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "咖啡马天尼", "nameEn": "Espresso Martini", "intro": "以伏特加、浓缩咖啡与咖啡利口酒摇制的咖啡风味鸡尾酒，杯面浮着绵密泡沫，兼具咖啡香与酒感。", "imageUrl": "/assets/images/posters/cocktail-espresso-martini-hero.webp", "tags": ["咖啡鸡尾酒", "伏特加基底", "咖啡风味", "泡沫质地", "摇和", "甜感明显", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 100, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-french-martini', 'cocktail', 'COCKTAIL', '法国马天尼', 'French Martini', 'faguomatianni', 'fgmtn', '以伏特加、树莓利口酒与菠萝汁摇制的果味鸡尾酒，酸甜果香与顺滑质地结合，外观呈粉红。', '本条目按 IBA 配比标准化：45 ml 伏特加、15 ml 树莓利口酒加 15 ml 菠萝汁，摇和滤入马天尼杯。水果比例与利口酒甜度决定整体酸甜平衡。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/French%20Martini.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/French%20Martini.jpg', 96, 7, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["伏特加基底", "莓果", "菠萝", "粉红色外观", "摇和", "酸甜"]', '["节日", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "莓果、菠萝", "abv": "较高＞20%～30%", "extra": ["菠萝汁"], "scene": ["节日", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "树莓利口酒", "nameEn": "Raspberry liqueur", "amount": 15, "unit": "ml", "role": "树莓利口酒"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 15, "unit": "ml", "role": "新鲜菠萝汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "摇和用"}]', '["将马天尼杯提前冰镇。", "摇酒壶加冰，倒入伏特加、树莓利口酒与菠萝汁。", "摇和约 10 秒至充分降温。", "滤入冰镇马天尼杯。"]', '["French Martini", "法式马天尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-french-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "法国马天尼", "nameEn": "French Martini", "intro": "以伏特加、树莓利口酒与菠萝汁摇制的果味鸡尾酒，酸甜果香与顺滑质地结合，外观呈粉红。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/French%20Martini.jpg", "tags": ["伏特加基底", "莓果", "菠萝", "粉红色外观", "摇和", "酸甜"], "scene": ["节日", "经典", "开胃"], "recommendationScore": 96, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "莓果、菠萝", "abv": "较高＞20%～30%", "extra": ["菠萝汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-apple-martini', 'cocktail', 'COCKTAIL', '苹果马天尼', 'Apple Martini', 'pingguomatianni', 'pgmtn', '以伏特加、苹果汁与苹果白兰地调制的现代鸡尾酒，苹果香气清脆，酸甜平衡，口感轻盈顺滑。', '本条目按 45 ml 伏特加、30 ml 苹果汁与 15 ml 苹果白兰地摇制标准化，可选糖边装饰。苹果汁的甜度与白兰地用量决定整体酸甜平衡。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 96, 8, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "苹果", "果香", "酸甜", "摇和", "中等强度"]', '["节日", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "苹果、果香", "abv": "较高＞20%～30%", "extra": ["苹果汁"], "scene": ["节日", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "选用中性伏特加"}, {"nameZh": "苹果汁", "nameEn": "Apple juice", "amount": 30, "unit": "ml", "role": "澄清苹果汁"}, {"nameZh": "苹果白兰地酒", "nameEn": "Apple brandy", "amount": 15, "unit": "ml", "role": "可选以利口酒增强苹果香"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "摇和用"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇，可选沾糖边。", "摇酒壶加冰，倒入伏特加、苹果汁与苹果白兰地。", "摇和约 10 秒至充分降温。", "滤入冰镇马天尼杯。", "以一片柠檬皮装饰。"]', '["Appletini", "苹果马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-apple-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "苹果马天尼", "nameEn": "Apple Martini", "intro": "以伏特加、苹果汁与苹果白兰地调制的现代鸡尾酒，苹果香气清脆，酸甜平衡，口感轻盈顺滑。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "苹果", "果香", "酸甜", "摇和", "中等强度"], "scene": ["节日", "经典", "开胃"], "recommendationScore": 96, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "苹果、果香", "abv": "较高＞20%～30%", "extra": ["苹果汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-blueberry-martini', 'cocktail', 'COCKTAIL', '蓝莓马天尼', 'Blueberry Martini', 'lanmeimatianni', 'lmmtn', '以伏特加、树莓利口酒与青柠汁调制的莓果风味鸡尾酒，突出浆果甜香与明快酸感，色泽呈紫红。', '本条目按 45 ml 伏特加、20 ml 树莓利口酒、15 ml 蔓越莓汁与 10 ml 青柠汁摇制标准化。蓝莓主题通过莓果利口酒与莓果汁呈现，比例决定色泽与果香浓度。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 96, 9, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "莓果", "果香", "酸甜", "摇和", "中等强度"]', '["节日", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "莓果、果香", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "蔓越莓汁"], "scene": ["节日", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "选用中性伏特加"}, {"nameZh": "树莓利口酒", "nameEn": "Raspberry liqueur", "amount": 20, "unit": "ml", "role": "莓果甜感来源"}, {"nameZh": "蔓越莓汁", "nameEn": "Cranberry juice", "amount": 15, "unit": "ml", "role": "提供莓果酸度与色泽"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "平衡甜度"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "摇和用"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "摇酒壶加冰，倒入伏特加、树莓利口酒、蔓越莓汁与青柠汁。", "摇和约 10 秒至充分降温。", "滤入冰镇马天尼杯。", "以一朵可食用花装饰。"]', '["Blueberry Martini", "蓝莓马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-blueberry-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蓝莓马天尼", "nameEn": "Blueberry Martini", "intro": "以伏特加、树莓利口酒与青柠汁调制的莓果风味鸡尾酒，突出浆果甜香与明快酸感，色泽呈紫红。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "莓果", "果香", "酸甜", "摇和", "中等强度"], "scene": ["节日", "经典", "开胃"], "recommendationScore": 96, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "莓果、果香", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "蔓越莓汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pineapple-martini', 'cocktail', 'COCKTAIL', '菠萝马天尼', 'Pineapple Martini', 'boluomatianni', 'blmtn', '以伏特加、菠萝汁与椰浆调制的金黄色鸡尾酒，突出菠萝的热带甜香与明亮口感，质地略带奶油感。', '本条目按 45 ml 伏特加、30 ml 菠萝汁与 15 ml 椰浆摇制标准化，可选柠檬皮装饰。菠萝汁成熟度决定甜香浓度，椰浆带来轻微奶油质地。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 96, 10, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "菠萝", "热带水果", "甜感明显", "摇和", "中等强度"]', '["节日", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "菠萝、热带水果", "abv": "较高＞20%～30%", "extra": ["椰奶", "菠萝汁"], "scene": ["节日", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "选用中性伏特加"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 30, "unit": "ml", "role": "成熟菠萝汁"}, {"nameZh": "椰奶", "nameEn": "Coconut milk", "amount": 15, "unit": "ml", "role": "可选椰浆增稠"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 1, "unit": "g", "role": "摇和用"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "摇酒壶加冰，倒入伏特加、菠萝汁与椰浆。", "摇和约 10 秒至充分降温。", "滤入冰镇马天尼杯。", "以一片柠檬皮装饰。"]', '["Pineapple Martini", "菠萝马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-pineapple-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "菠萝马天尼", "nameEn": "Pineapple Martini", "intro": "以伏特加、菠萝汁与椰浆调制的金黄色鸡尾酒，突出菠萝的热带甜香与明亮口感，质地略带奶油感。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "菠萝", "热带水果", "甜感明显", "摇和", "中等强度"], "scene": ["节日", "经典", "开胃"], "recommendationScore": 96, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "菠萝、热带水果", "abv": "较高＞20%～30%", "extra": ["椰奶", "菠萝汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cucumber-martini', 'cocktail', 'COCKTAIL', '黄瓜马天尼', 'Cucumber Martini', 'huangguamatianni', 'hgmtn', '以伦敦干金酒为基底，加入新鲜黄瓜与青柠汁摇和的马天尼变体，黄瓜清香与青柠酸度平衡，口感清爽。', '黄瓜马天尼是 2000 年代流行的现代鸡尾酒，常以杜松子味突出的金酒搭配黄瓜与青柠制成。本版本采用金酒 60 毫升、黄瓜 40 克捣汁、青柠汁 15 毫升与单糖浆 10 毫升的编辑标准化配比，与传统干马天尼不同，本款经充分摇和并双重过滤，突出黄瓜的植物清香。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Hendrick%27s%20Gin%201l%20with%20cup.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Hendrick%27s%20Gin%201l%20with%20cup.jpg', 93, 11, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "摇和", "草本", "柑橘", "清爽", "日常"]', '["日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "黄瓜"], "scene": ["日常"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 60, "unit": "ml", "role": "45% ABV 伦敦干金酒"}, {"nameZh": "黄瓜", "nameEn": "Cucumber", "amount": 40, "unit": "g", "role": "新鲜黄瓜切片捣碎"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜压榨"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}]', '["将黄瓜切片放入摇壶中捣碎出汁。", "加入伦敦干金酒、青柠汁与单糖浆。", "加满冰块，用力摇和约 12 秒。", "双重过滤倒入冰镇马天尼杯。", "以一片黄瓜片装饰后立即饮用。"]', '["黄瓜马提尼", "Cucumber Martini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cucumber-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黄瓜马天尼", "nameEn": "Cucumber Martini", "intro": "以伦敦干金酒为基底，加入新鲜黄瓜与青柠汁摇和的马天尼变体，黄瓜清香与青柠酸度平衡，口感清爽。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Hendrick%27s%20Gin%201l%20with%20cup.jpg", "tags": ["金酒基底", "摇和", "草本", "柑橘", "清爽", "日常"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "黄瓜"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-lychee-martini', 'cocktail', 'COCKTAIL', '荔枝马天尼', 'Lychee Martini', 'lizhimatianni', 'lzmtn', '以伏特加为基底，加入荔枝利口酒、荔枝糖浆与青柠汁摇和的果味马天尼，荔枝甜香突出，入口柔和。', '荔枝马天尼是流行的现代果味马天尼，以荔枝利口酒与荔枝糖浆提供甜香，青柠汁平衡甜度。本版本采用伏特加 45 毫升、荔枝利口酒 15 毫升、荔枝糖浆 10 毫升与青柠汁 15 毫升的编辑标准化配比，摇和过滤后装杯。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Lychee%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Lychee%20cocktail.jpg', 93, 12, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "摇和", "果香", "花香", "甜感明显", "日常"]', '["日常"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "果香、花香", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "荔枝糖浆"], "scene": ["日常"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "荔枝利口酒", "nameEn": "Lychee liqueur", "amount": 15, "unit": "ml", "role": "荔枝利口酒"}, {"nameZh": "荔枝糖浆", "nameEn": "Lychee syrup", "amount": 10, "unit": "ml", "role": "荔枝糖浆"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜压榨"}]', '["将伏特加、荔枝利口酒、荔枝糖浆与青柠汁加入摇壶。", "加冰摇和约 12 秒至充分冷却。", "双重过滤倒入冰镇马天尼杯。", "以一颗去皮荔枝装饰后立即饮用。"]', '["荔枝马提尼", "Lychee Martini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-lychee-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "荔枝马天尼", "nameEn": "Lychee Martini", "intro": "以伏特加为基底，加入荔枝利口酒、荔枝糖浆与青柠汁摇和的果味马天尼，荔枝甜香突出，入口柔和。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Lychee%20cocktail.jpg", "tags": ["伏特加基底", "摇和", "果香", "花香", "甜感明显", "日常"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "果香、花香", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "荔枝糖浆"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-peach-martini', 'cocktail', 'COCKTAIL', '桃马天尼', 'Peach Martini', 'taomatianni', 'tmtn', '以伏特加为基底，加入蜜桃利口酒与柠檬汁摇和的果味马天尼，蜜桃圆润甜香与柠檬酸度相平衡，口感柔和。', '桃马天尼是常见的果味马天尼变体，以蜜桃利口酒提供果香，柠檬汁平衡甜度。本版本采用伏特加 45 毫升、蜜桃利口酒 20 毫升、柠檬汁 15 毫升与单糖浆 5 毫升的编辑标准化配比，摇和过滤后装杯。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Peach%20Absinth%20Martini.png', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Peach%20Absinth%20Martini.png', 93, 13, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "摇和", "蜜桃", "果香", "甜感明显", "日常"]', '["日常"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "蜜桃、果香", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["日常"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "蜜桃利口酒", "nameEn": "Peach liqueur", "amount": 20, "unit": "ml", "role": "蜜桃利口酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜压榨"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "1:1 单糖浆"}]', '["将伏特加、蜜桃利口酒、柠檬汁与单糖浆加入摇壶。", "加冰充分摇和约 12 秒。", "双重过滤倒入冰镇马天尼杯。", "以一片蜜桃或柠檬皮装饰后立即饮用。"]', '["蜜桃马提尼", "Peach Martini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-peach-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "桃马天尼", "nameEn": "Peach Martini", "intro": "以伏特加为基底，加入蜜桃利口酒与柠檬汁摇和的果味马天尼，蜜桃圆润甜香与柠檬酸度相平衡，口感柔和。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Peach%20Absinth%20Martini.png", "tags": ["伏特加基底", "摇和", "蜜桃", "果香", "甜感明显", "日常"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "蜜桃、果香", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sour-martini', 'cocktail', 'COCKTAIL', '酸马天尼', 'Sour Martini', 'suanmatianni', 'smtn', '以伏特加为基底，加入柠檬汁、橙酒与糖摇和的酸型马天尼，可选糖边增添甜感，酸甜鲜明，口感清新明亮。', '酸马天尼以柠檬糖霜马天尼为蓝本，是柠檬酸型的伏特加马天尼。本版本采用伏特加 50 毫升、君度橙酒 15 毫升、柠檬汁 20 毫升与单糖浆 5 毫升的编辑标准化配比，可选糖边，摇和过滤后装杯。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Lemon%20Drop%20Martini.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Lemon%20Drop%20Martini.jpg', 93, 14, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["伏特加基底", "摇和", "柑橘", "酸甜", "糖边", "日常"]', '["日常"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "高度＞30%", "extra": ["新鲜柠檬汁"], "scene": ["日常"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "君度橙酒", "nameEn": "Cointreau", "amount": 15, "unit": "ml", "role": "君度橙酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜压榨"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "糖边", "nameEn": "Sugar rim", "amount": 5, "unit": "g", "role": "杯口糖边"}]', '["将马天尼杯杯口蘸湿，沾上一层细砂糖制成糖边。", "将伏特加、君度橙酒、柠檬汁与单糖浆加入摇壶。", "加冰充分摇和约 12 秒。", "双重过滤倒入带糖边的冰镇杯中。", "以一片柠檬片装饰后立即饮用。"]', '["酸马提尼", "柠檬糖霜马天尼", "Lemon Drop Martini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sour-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "酸马天尼", "nameEn": "Sour Martini", "intro": "以伏特加为基底，加入柠檬汁、橙酒与糖摇和的酸型马天尼，可选糖边增添甜感，酸甜鲜明，口感清新明亮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Lemon%20Drop%20Martini.jpg", "tags": ["伏特加基底", "摇和", "柑橘", "酸甜", "糖边", "日常"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "高度＞30%", "extra": ["新鲜柠檬汁"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vodkatini', 'cocktail', 'COCKTAIL', '维兹迪安', 'Vodkatini', 'weizidian', 'wzda', '以伏特加为基底，加入少量干白味美思搅拌冷却的干型马天尼，口感纯净顺滑，是伏特加马天尼的经典形态。', '维兹迪安即伏特加马天尼的昵称，是干型马天尼的伏特加版本。本版本采用伏特加 60 毫升、干白味美思 10 毫升与橙味苦精 1 滴的编辑标准化配比，在冰面搅拌后滤入冰镇杯。', 'https://upload.wikimedia.org/wikipedia/commons/a/a2/Classic_vodka_martini_lemon_twist.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a2/Classic_vodka_martini_lemon_twist.jpg', 93, 15, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["伏特加基底", "搅拌", "偏干", "高强度", "经典", "轻盈"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 60, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 10, "unit": "ml", "role": "干白味美思"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 1, "unit": "dash", "role": "橙味苦精"}]', '["在调酒杯中加入冰块并充分预冷。", "倒入伏特加、干白味美思与橙味苦精。", "搅拌约 20 秒至充分冷却与稀释。", "滤入冰镇马天尼杯。", "以拧过香气的柠檬皮装饰后立即饮用。"]', '["伏特加马天尼", "Vodka Martini", "Vodkatini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-vodkatini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "维兹迪安", "nameEn": "Vodkatini", "intro": "以伏特加为基底，加入少量干白味美思搅拌冷却的干型马天尼，口感纯净顺滑，是伏特加马天尼的经典形态。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a2/Classic_vodka_martini_lemon_twist.jpg", "tags": ["伏特加基底", "搅拌", "偏干", "高强度", "经典", "轻盈"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sazerac', 'cocktail', 'COCKTAIL', '萨泽拉克', 'Sazerac', 'sazelake', 'szlk', '以黑麦威士忌与干邑为基底，加入方糖、苦精并用苦艾酒冲洗杯壁的新奥尔良经典，茴香与苦味交织。', '萨泽拉克源于美国新奥尔良，被视为最早的鸡尾酒之一。本版本依据 IBA 配比精神，采用黑麦威士忌 45 毫升、干邑 15 毫升、方糖 1 颗、佩肖苦精与安格斯图拉苦精各数滴，杯壁以苦艾酒冲洗的编辑标准化版本。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg', 93, 16, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["黑麦基底", "搅拌", "苦感主导", "茴香", "经典", "高强度"]', '["经典"]', '{"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦感主导、茴香", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 45, "unit": "ml", "role": "40% ABV 黑麦威士忌"}, {"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 15, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 4, "unit": "g", "role": "方糖 1 颗"}, {"nameZh": "佩肖苦精", "nameEn": "Peychaud\'s bitters", "amount": 3, "unit": "dash", "role": "佩肖苦精"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 5, "unit": "ml", "role": "用于冲洗杯壁"}]', '["在调酒杯中放入方糖，加入佩肖苦精与安格斯图拉苦精，搅拌至溶解。", "倒入黑麦威士忌与干邑，加冰搅拌约 20 秒。", "在预冷的老式杯中倒入 5 ml 苦艾酒，旋转杯壁后倒出多余酒液。", "将调好的酒液滤入苦艾酒冲洗过的杯中。", "以柠檬皮拧出香气后装饰，立即饮用。"]', '["萨泽拉克鸡尾酒", "Sazerac"]', 'A', '2026-08-04', 1, '{"id": "cocktail-sazerac", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "萨泽拉克", "nameEn": "Sazerac", "intro": "以黑麦威士忌与干邑为基底，加入方糖、苦精并用苦艾酒冲洗杯壁的新奥尔良经典，茴香与苦味交织。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg", "tags": ["黑麦基底", "搅拌", "苦感主导", "茴香", "经典", "高强度"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦感主导、茴香", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-manhattan', 'cocktail', 'COCKTAIL', '曼哈顿', 'Manhattan', 'manhadun', 'mhd', '以威士忌为基底，加入甜红味美思与苦精搅拌而成的经典鸡尾酒，甜苦平衡，酒体圆润，以樱桃装饰。', '曼哈顿是经典的威士忌马天尼家族鸡尾酒，IBA 版本采用黑麦威士忌与甜红味美思。本版本采用波本威士忌 50 毫升、甜红味美思 20 毫升与安格斯图拉苦精 2 滴的编辑标准化配比，在冰面搅拌后滤杯，樱桃装饰。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20cocktail.jpg', 93, 17, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["威士忌基底", "搅拌", "经典", "草本", "中等酒体", "餐后"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 50, "unit": "ml", "role": "40% ABV 波本威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 20, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "piece", "role": "装饰用鸡尾酒樱桃"}]', '["在调酒杯中加入冰块并预冷。", "倒入波本威士忌、甜红味美思与苦精。", "搅拌约 20 秒至充分冷却。", "滤入冰镇马天尼杯或老式杯。", "以鸡尾酒樱桃装饰后立即饮用。"]', '["曼哈顿鸡尾酒", "Manhattan"]', 'A', '2026-08-04', 1, '{"id": "cocktail-manhattan", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "曼哈顿", "nameEn": "Manhattan", "intro": "以威士忌为基底，加入甜红味美思与苦精搅拌而成的经典鸡尾酒，甜苦平衡，酒体圆润，以樱桃装饰。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20cocktail.jpg", "tags": ["威士忌基底", "搅拌", "经典", "草本", "中等酒体", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-perfect-manhattan', 'cocktail', 'COCKTAIL', '完美曼哈顿', 'Perfect Manhattan', 'wanmeimanhadun', 'wmmhd', '以黑麦威士忌为基底，甜红味美思与干白味美思等量搭配的曼哈顿变体，酸甜苦均衡，草本层次清晰。', '完美曼哈顿是曼哈顿家族中使用甜味美思与干味美思各半的版本，口感介于经典曼哈顿与干型之间。本版本采用黑麦威士忌 45 毫升、甜红味美思 15 毫升、干白味美思 15 毫升与安格斯图拉苦精 2 滴的编辑标准化配比。', 'https://upload.wikimedia.org/wikipedia/commons/9/92/2_Manhattan_cocktails%2C_bird%27s_eye_view.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/92/2_Manhattan_cocktails%2C_bird%27s_eye_view.jpg', 93, 18, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["黑麦基底", "搅拌", "经典", "草本", "均衡", "餐后"]', '["经典", "餐后"]', '{"baseSpirit": "黑麦基底", "cocktailType": "曼哈顿", "flavor": "草本、均衡", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 45, "unit": "ml", "role": "40% ABV 黑麦威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 15, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 15, "unit": "ml", "role": "干白味美思"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "piece", "role": "装饰用鸡尾酒樱桃"}]', '["在调酒杯中加入冰块并预冷。", "倒入黑麦威士忌、两种味美思与苦精。", "搅拌约 20 秒至充分冷却。", "滤入冰镇马天尼杯。", "以鸡尾酒樱桃装饰后立即饮用。"]', '["完美曼哈顿鸡尾酒", "Perfect Manhattan"]', 'B', '2026-08-04', 1, '{"id": "cocktail-perfect-manhattan", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "完美曼哈顿", "nameEn": "Perfect Manhattan", "intro": "以黑麦威士忌为基底，甜红味美思与干白味美思等量搭配的曼哈顿变体，酸甜苦均衡，草本层次清晰。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/92/2_Manhattan_cocktails%2C_bird%27s_eye_view.jpg", "tags": ["黑麦基底", "搅拌", "经典", "草本", "均衡", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "曼哈顿", "flavor": "草本、均衡", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rye-manhattan', 'cocktail', 'COCKTAIL', '黑麦曼哈顿', 'Rye Manhattan', 'heimaimanhadun', 'hmmhd', '以黑麦威士忌为基底，加入甜红味美思与苦精搅拌的曼哈顿变体，黑麦香料感突出，口感干烈而圆润。', '黑麦曼哈顿以黑麦威士忌取代波本，是强调黑麦辛香与干燥感的曼哈顿版本。本版本采用黑麦威士忌 50 毫升、甜红味美思 20 毫升与安格斯图拉苦精 2 滴的编辑标准化配比，冰面搅拌后滤杯，樱桃装饰。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20cocktail.jpg', 93, 19, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["黑麦基底", "搅拌", "经典", "香料", "中等酒体", "餐后"]', '["经典", "餐后"]', '{"baseSpirit": "黑麦基底", "cocktailType": "曼哈顿", "flavor": "香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 50, "unit": "ml", "role": "40% ABV 黑麦威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 20, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "piece", "role": "装饰用鸡尾酒樱桃"}]', '["在调酒杯中加入冰块并预冷。", "倒入黑麦威士忌、甜红味美思与苦精。", "搅拌约 20 秒至充分冷却。", "滤入冰镇马天尼杯。", "以鸡尾酒樱桃装饰后立即饮用。"]', '["黑麦曼哈顿鸡尾酒", "Rye Manhattan"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rye-manhattan", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑麦曼哈顿", "nameEn": "Rye Manhattan", "intro": "以黑麦威士忌为基底，加入甜红味美思与苦精搅拌的曼哈顿变体，黑麦香料感突出，口感干烈而圆润。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20cocktail.jpg", "tags": ["黑麦基底", "搅拌", "经典", "香料", "中等酒体", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "曼哈顿", "flavor": "香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bronx', 'cocktail', 'COCKTAIL', '布朗克斯', 'Bronx', 'bulangkesi', 'blks', '以金酒为基底，加入甜红味美思、干白味美思与鲜橙汁摇和的鸡尾酒，果酸清新明亮，草本与苦味均衡。', '布朗克斯是金酒与味美思搭配鲜橙汁的经典鸡尾酒，被看作加了橙汁的完美马天尼。本版本依据 IBA 配比，采用伦敦干金酒 30 毫升、干白味美思 7.5 毫升、甜红味美思 7.5 毫升与鲜橙汁 10 毫升的编辑标准化配比。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 20, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "摇和", "柑橘", "草本", "均衡", "开胃"]', '["开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "柑橘、草本", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁"], "scene": ["开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "40% ABV 伦敦干金酒"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 7.5, "unit": "ml", "role": "干白味美思"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 7.5, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 10, "unit": "ml", "role": "鲜榨橙汁"}]', '["将伦敦干金酒、干白味美思、甜红味美思与鲜橙汁加入摇壶。", "加冰充分摇和约 12 秒。", "双重过滤倒入冰镇马天尼杯。", "以一片橙皮装饰后立即饮用。"]', '["布朗克斯鸡尾酒", "Bronx Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-bronx", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "布朗克斯", "nameEn": "Bronx", "intro": "以金酒为基底，加入甜红味美思、干白味美思与鲜橙汁摇和的鸡尾酒，果酸清新明亮，草本与苦味均衡。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["金酒基底", "摇和", "柑橘", "草本", "均衡", "开胃"], "scene": ["开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "柑橘、草本", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁"], "scene": ["开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-the-last-word', 'cocktail', 'COCKTAIL', '老友记', 'The Last Word', 'laoyouji', 'lyj', '以金酒、绿查特利口酒、马拉斯奇诺与青柠汁等量调配的酸型鸡尾酒，草本与果香并重，源于底特律并因西雅图酒吧而复兴。', 'V6 标准以四种原料等量各 22.5 毫升调配并充分摇和。相比酒吧常见的比例调整，等量版本更突出草本查特与樱桃利口酒的平衡。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20Last%20Word%20in%20Astoria,%20Queens%20New%20York.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20Last%20Word%20in%20Astoria,%20Queens%20New%20York.jpg', 93, 21, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["酸型鸡尾酒", "金酒基底", "草本", "酸甜", "经典", "冷饮"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本、酸甜", "abv": "高度＞30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 22.5, "unit": "ml", "role": "伦敦干金酒，等量配比"}, {"nameZh": "绿查特绿", "nameEn": "Green Chartreuse", "amount": 22.5, "unit": "ml", "role": "绿色查特利口酒"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino liqueur", "amount": 22.5, "unit": "ml", "role": "马拉斯奇诺利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 22.5, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰块"}]', '["向摇酒壶中加入 22.5 毫升金酒、绿查特利口酒与马拉斯奇诺利口酒。", "加入 22.5 毫升新鲜青柠汁与 90 克冰块。", "用力摇和 10 秒至酒壶表面结霜。", "用滤冰器滤入冰镇的蝶形杯。"]', '["老友记鸡尾酒", "Last Word", "绝句"]', 'B', '2026-08-04', 1, '{"id": "cocktail-the-last-word", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "老友记", "nameEn": "The Last Word", "intro": "以金酒、绿查特利口酒、马拉斯奇诺与青柠汁等量调配的酸型鸡尾酒，草本与果香并重，源于底特律并因西雅图酒吧而复兴。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20Last%20Word%20in%20Astoria,%20Queens%20New%20York.jpg", "tags": ["酸型鸡尾酒", "金酒基底", "草本", "酸甜", "经典", "冷饮"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本、酸甜", "abv": "高度＞30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-old-fashioned', 'cocktail', 'COCKTAIL', '古典鸡尾酒', 'Old Fashioned', 'gudianjiweijiu', 'gdjwj', '以波本威士忌加方糖与苦精直调而成的经典鸡尾酒，苦甜平衡、酒体扎实，用橙皮提香，被视为威士忌风格鸡尾酒的基石。', 'V6 标准以波本威士忌 45 毫升、一颗方糖与 3 滴安格斯图拉苦精直调。与老式鸡尾酒相比，本条目采用方糖而非糖浆，整体更偏经典原味。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 93, 22, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "苦味明显", "经典", "冷饮", "高强度", "无麸质"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌，IBA 风格基酒"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 1, "unit": "piece", "role": "方糖一颗"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 3, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 5, "unit": "ml", "role": "溶解方糖用"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮装饰"}]', '["在古典杯底放入一颗方糖，滴入 3 滴安格斯图拉苦精。", "加入 5 毫升过滤水，用捣棒轻压将方糖溶解。", "倒入 45 毫升波本威士忌，放入大冰球搅拌约 30 秒。", "用橙皮在杯口挤出橙油后投入杯中。"]', '["古典", "Old Fashioned", "老式"]', 'A', '2026-08-04', 1, '{"id": "cocktail-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "古典鸡尾酒", "nameEn": "Old Fashioned", "intro": "以波本威士忌加方糖与苦精直调而成的经典鸡尾酒，苦甜平衡、酒体扎实，用橙皮提香，被视为威士忌风格鸡尾酒的基石。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg", "tags": ["威士忌基底", "苦味明显", "经典", "冷饮", "高强度", "无麸质"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-old-fashioned-classic', 'cocktail', 'COCKTAIL', '老式鸡尾酒', 'Old Fashioned (Classic)', 'laoshijiweijiu', 'lsjwj', '以黑麦威士忌为基底、方糖与两种苦精调和的古典家族鸡尾酒，口感偏干、香料气息明显，配柠檬皮饮用。', 'V6 标准以黑麦威士忌为基，加入方糖与安格斯图拉、佩肖两种苦精。相比古典鸡尾酒，黑麦版本口感更干、香料感更强。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned%20Cocktail%20Hilton%20London%20Syon%20Park%20(55775610).jpeg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned%20Cocktail%20Hilton%20London%20Syon%20Park%20(55775610).jpeg', 93, 23, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["黑麦基底", "苦味明显", "经典", "冷饮", "高强度", "搅拌"]', '["经典"]', '{"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 45, "unit": "ml", "role": "黑麦威士忌"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 1, "unit": "piece", "role": "方糖一颗"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "佩肖苦精", "nameEn": "Peychaud\'s bitters", "amount": 1, "unit": "dash", "role": "佩肖苦精"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 5, "unit": "ml", "role": "溶解方糖用"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮装饰"}]', '["在古典杯底放一颗方糖，滴入安格斯图拉与佩肖苦精。", "加入 5 毫升过滤水，捣压方糖至完全溶解。", "倒入 45 毫升黑麦威士忌并放入大冰球搅拌 30 秒。", "用柠檬皮挤出精油后沿杯沿放入。"]', '["老式鸡尾酒", "Old Fashioned Classic", "黑麦古典"]', 'A', '2026-08-04', 1, '{"id": "cocktail-old-fashioned-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "老式鸡尾酒", "nameEn": "Old Fashioned (Classic)", "intro": "以黑麦威士忌为基底、方糖与两种苦精调和的古典家族鸡尾酒，口感偏干、香料气息明显，配柠檬皮饮用。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned%20Cocktail%20Hilton%20London%20Syon%20Park%20(55775610).jpeg", "tags": ["黑麦基底", "苦味明显", "经典", "冷饮", "高强度", "搅拌"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-whiskey-old-fashioned', 'cocktail', 'COCKTAIL', '威士忌古典', 'Whiskey Old Fashioned', 'weishijigudian', 'wsjgd', '以波本威士忌与枫糖浆代替方糖、加橙味苦精直调的古典变体，甜感更圆润，带有枫糖与焦糖般的余韵。', 'V6 标准以枫糖浆 5 毫升替代方糖，并改用橙味苦精，属古典家族的现代变体，甜感来自枫糖而非蔗糖。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned1.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned1.jpg', 93, 24, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "枫糖", "苦味明显", "冷饮", "高强度", "经典"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "枫糖、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "枫糖浆", "nameEn": "Maple syrup", "amount": 5, "unit": "ml", "role": "枫糖浆"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮装饰"}]', '["在古典杯中依次加入枫糖浆与橙味苦精。", "倒入 45 毫升波本威士忌，放入大冰球。", "用吧勺搅拌约 30 秒至充分冰镇。", "用橙皮在杯口挤出橙油后放入杯中。"]', '["威士忌古典鸡尾酒", "Whiskey Old Fashioned"]', 'B', '2026-08-04', 1, '{"id": "cocktail-whiskey-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "威士忌古典", "nameEn": "Whiskey Old Fashioned", "intro": "以波本威士忌与枫糖浆代替方糖、加橙味苦精直调的古典变体，甜感更圆润，带有枫糖与焦糖般的余韵。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned1.jpg", "tags": ["威士忌基底", "枫糖", "苦味明显", "冷饮", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "枫糖、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rum-old-fashioned', 'cocktail', 'COCKTAIL', '朗姆古典', 'Rum Old Fashioned', 'langmugudian', 'lmgd', '以陈年朗姆酒为基底、配红糖与苦精直调的古典变体，带有朗姆特有的糖蜜气息，比威士忌版本更温润。', 'V6 标准以陈年朗姆酒配红糖与安格斯图拉苦精直调。相比威士忌版本，朗姆带来的糖蜜与热带气息更明显，甜感更温润。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned%20(1).jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned%20(1).jpg', 93, 25, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["朗姆基底", "苦味明显", "经典", "冷饮", "高强度", "香料"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "古典家族", "flavor": "苦味明显、香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "陈年朗姆酒", "nameEn": "Aged rum", "amount": 45, "unit": "ml", "role": "陈年朗姆酒"}, {"nameZh": "红糖", "nameEn": "Brown sugar", "amount": 5, "unit": "g", "role": "红糖"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 3, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 5, "unit": "ml", "role": "溶解红糖用"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮装饰"}]', '["在古典杯中放入红糖，滴入 3 滴安格斯图拉苦精。", "加入 5 毫升过滤水，捣压至红糖溶解。", "倒入 45 毫升陈年朗姆酒并放入大冰球。", "搅拌约 30 秒后用橙皮提香并放入。"]', '["朗姆古典鸡尾酒", "Rum Old Fashioned"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rum-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朗姆古典", "nameEn": "Rum Old Fashioned", "intro": "以陈年朗姆酒为基底、配红糖与苦精直调的古典变体，带有朗姆特有的糖蜜气息，比威士忌版本更温润。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned%20(1).jpg", "tags": ["朗姆基底", "苦味明显", "经典", "冷饮", "高强度", "香料"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "古典家族", "flavor": "苦味明显、香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-old-fashioned', 'cocktail', 'COCKTAIL', '龙舌兰古典', 'Tequila Old Fashioned', 'longshelangudian', 'lslgd', '以陈年龙舌兰酒配龙舌兰糖浆与苦精直调的古典变体，突出龙舌兰的草本与矿物感，口感干爽利落。', 'V6 标准以陈年龙舌兰配龙舌兰糖浆与安格斯图拉、橙味两种苦精。突出龙舌兰草本与矿物感，苦甜平衡偏干。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned.jpg', 93, 26, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["龙舌兰基底", "苦味明显", "冷饮", "高强度", "经典", "无乳配方"]', '["经典"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "陈年龙舌兰酒", "nameEn": "Reposado tequila", "amount": 45, "unit": "ml", "role": "陈年龙舌兰酒"}, {"nameZh": "龙舌兰糖浆", "nameEn": "Agave syrup", "amount": 5, "unit": "ml", "role": "龙舌兰糖浆"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮装饰"}]', '["在古典杯中依次加入龙舌兰糖浆与两种苦精。", "倒入 45 毫升陈年龙舌兰酒，放入大冰球。", "用吧勺搅拌约 30 秒至充分冰镇。", "用橙皮在杯口挤出橙油后投入杯中。"]', '["龙舌兰古典鸡尾酒", "Tequila Old Fashioned"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tequila-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰古典", "nameEn": "Tequila Old Fashioned", "intro": "以陈年龙舌兰酒配龙舌兰糖浆与苦精直调的古典变体，突出龙舌兰的草本与矿物感，口感干爽利落。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned.jpg", "tags": ["龙舌兰基底", "苦味明显", "冷饮", "高强度", "经典", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-whiskey-sour', 'cocktail', 'COCKTAIL', '威士忌酸', 'Whiskey Sour', 'weishijisuan', 'wsjs', '以波本威士忌、柠檬汁与糖浆摇和而成的酸型鸡尾酒，酸甜平衡、泡沫绵密，是威士忌家族中最具代表性的酸酒。', 'V6 标准按 IBA 配比以波本威士忌 45 毫升、柠檬汁 25 毫升与糖浆 20 毫升，另加蛋清摇和出绵密泡沫。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg', 93, 27, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["酸型鸡尾酒", "威士忌基底", "酸甜", "柑橘", "冷饮", "泡沫质地"]', '["经典", "开胃"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典", "开胃"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "ml", "role": "蛋清用于绵密泡沫"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "柠檬片装饰"}]', '["将波本威士忌、柠檬汁、糖浆与蛋清一同加入摇酒壶。", "不加冰干摇 15 秒使蛋清充分起泡。", "加入 90 克冰块再摇和 10 秒至充分冰镇。", "双重过滤倒入加冰的古典杯，缀以柠檬片。"]', '["威士忌酸酒", "Whiskey Sour", "酸威士忌"]', 'A', '2026-08-04', 1, '{"id": "cocktail-whiskey-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "威士忌酸", "nameEn": "Whiskey Sour", "intro": "以波本威士忌、柠檬汁与糖浆摇和而成的酸型鸡尾酒，酸甜平衡、泡沫绵密，是威士忌家族中最具代表性的酸酒。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg", "tags": ["酸型鸡尾酒", "威士忌基底", "酸甜", "柑橘", "冷饮", "泡沫质地"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gin-sour', 'cocktail', 'COCKTAIL', '金酒酸', 'Gin Sour', 'jinjiusuan', 'jjs', '以伦敦干金酒、柠檬汁与糖浆摇和而成的酸型鸡尾酒，草本与柑橘香并现，口感清爽，可加蛋清增厚泡沫。', 'V6 标准以伦敦干金酒 45 毫升、柠檬汁 25 毫升与糖浆 20 毫升，可加蛋清摇和。相比威士忌酸，酒体更轻盈。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/White%20Lady%20-%20Beefeater%20gin,%20Cointreau,%20fresh%20lemon%20juice%20(12403540403).jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/White%20Lady%20-%20Beefeater%20gin,%20Cointreau,%20fresh%20lemon%20juice%20(12403540403).jpg', 93, 28, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "酸甜", "柑橘", "冷饮", "泡沫质地"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "ml", "role": "蛋清用于绵密泡沫"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮装饰"}]', '["将金酒、柠檬汁、糖浆与蛋清一起加入摇酒壶。", "不加冰干摇 15 秒至蛋清起泡。", "加入 90 克冰块摇和 10 秒至冰镇。", "双重过滤倒入冰镇蝶形杯，以柠檬皮点缀。"]', '["金酒酸酒", "Gin Sour", "杜松子酒酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-gin-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金酒酸", "nameEn": "Gin Sour", "intro": "以伦敦干金酒、柠檬汁与糖浆摇和而成的酸型鸡尾酒，草本与柑橘香并现，口感清爽，可加蛋清增厚泡沫。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/White%20Lady%20-%20Beefeater%20gin,%20Cointreau,%20fresh%20lemon%20juice%20(12403540403).jpg", "tags": ["酸型鸡尾酒", "金酒基底", "酸甜", "柑橘", "冷饮", "泡沫质地"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rum-sour', 'cocktail', 'COCKTAIL', '朗姆酸', 'Rum Sour', 'langmusuan', 'lms', '以白朗姆酒、青柠汁与糖浆摇和而成的酸型鸡尾酒，果香活泼、酸甜爽利，适合作为热带风味鸡尾酒的入门。', 'V6 标准以白朗姆酒 45 毫升、青柠汁 25 毫升与糖浆 20 毫升摇和。相比黛绮莉，糖量略高、酸甜更柔和。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/VTR%20-%20Ultimate%20Amaretto%20Sour%20-%2011371341036.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/VTR%20-%20Ultimate%20Amaretto%20Sour%20-%2011371341036.jpg', 93, 29, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["酸型鸡尾酒", "朗姆基底", "酸甜", "柑橘", "冷饮", "清爽"]', '["经典", "开胃"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["经典", "开胃"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 1, "unit": "piece", "role": "青柠片装饰"}]', '["将白朗姆酒、青柠汁与糖浆加入摇酒壶。", "加入 90 克冰块摇和 10 秒至充分冰镇。", "滤入冰镇的蝶形杯。", "在杯沿嵌一片青柠片作为装饰。"]', '["朗姆酸酒", "Rum Sour"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rum-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朗姆酸", "nameEn": "Rum Sour", "intro": "以白朗姆酒、青柠汁与糖浆摇和而成的酸型鸡尾酒，果香活泼、酸甜爽利，适合作为热带风味鸡尾酒的入门。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/VTR%20-%20Ultimate%20Amaretto%20Sour%20-%2011371341036.jpg", "tags": ["酸型鸡尾酒", "朗姆基底", "酸甜", "柑橘", "冷饮", "清爽"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-sour', 'cocktail', 'COCKTAIL', '龙舌兰酸', 'Tequila Sour', 'longshelansuan', 'lsls', '以银龙舌兰酒、青柠汁与糖浆摇和而成的酸型鸡尾酒，带有龙舌兰特有的植物气息，口感明亮清爽。', 'V6 标准以银龙舌兰酒 45 毫升、青柠汁 25 毫升与糖浆 20 毫升摇和。相比玛格丽特，省去橙味利口酒、口感更直接。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Tequila%20sour.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Tequila%20sour.jpg', 93, 30, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["酸型鸡尾酒", "龙舌兰基底", "酸甜", "柑橘", "冷饮", "夏季"]', '["夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["夏季"]}', '[{"nameZh": "银龙舌兰酒", "nameEn": "Blanco tequila", "amount": 45, "unit": "ml", "role": "银龙舌兰酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 1, "unit": "piece", "role": "青柠片装饰"}]', '["将银龙舌兰酒、青柠汁与糖浆加入摇酒壶。", "加入 90 克冰块摇和 10 秒至充分冰镇。", "滤入冰镇的蝶形杯。", "在杯沿嵌一片青柠片作为装饰。"]', '["龙舌兰酸酒", "Tequila Sour", "银龙舌兰酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tequila-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰酸", "nameEn": "Tequila Sour", "intro": "以银龙舌兰酒、青柠汁与糖浆摇和而成的酸型鸡尾酒，带有龙舌兰特有的植物气息，口感明亮清爽。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Tequila%20sour.jpg", "tags": ["酸型鸡尾酒", "龙舌兰基底", "酸甜", "柑橘", "冷饮", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vodka-sour', 'cocktail', 'COCKTAIL', '伏特加酸', 'Vodka Sour', 'futejiasuan', 'ftjs', '以伏特加为基底、加入柠檬汁与糖浆的酸型鸡尾酒，口感酸爽清亮，酒精结构被充分稀释，适合作为易饮的烈酒入门。', 'V6 编辑标准化配方采用伏特加、新鲜柠檬汁与 1:1 单糖浆 2:1:0.6 的配比，并可选加蛋清增加绵密泡沫；雷达与酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/a/a2/Blue_hawaii.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a2/Blue_hawaii.jpg', 93, 31, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["酸型鸡尾酒", "伏特加基底", "冷饮", "酸甜", "柑橘", "摇和", "轻盈", "经典"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "建议 40% ABV"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "g", "role": "约半个蛋清，可选"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇和用冰"}]', '["预冷摇壶与鸡尾酒杯。", "摇壶中加入伏特加、柠檬汁、单糖浆与蛋清。", "加入约 60 g 冰块，用力摇和 12 秒至充分混合。", "以滤网滤入预冷的鸡尾酒杯。", "以柠檬片或橙皮装饰后立即饮用。"]', '["Vodka Sour", "伏特加沙瓦", "莫斯科酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-vodka-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "伏特加酸", "nameEn": "Vodka Sour", "intro": "以伏特加为基底、加入柠檬汁与糖浆的酸型鸡尾酒，口感酸爽清亮，酒精结构被充分稀释，适合作为易饮的烈酒入门。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a2/Blue_hawaii.jpg", "tags": ["酸型鸡尾酒", "伏特加基底", "冷饮", "酸甜", "柑橘", "摇和", "轻盈", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-brandy-sour', 'cocktail', 'COCKTAIL', '白兰地酸', 'Brandy Sour', 'bailandisuan', 'blds', '以白兰地为基底、加入柠檬汁与糖浆的酸型鸡尾酒，果香与酸度平衡，既有烈酒的醇厚又有柑橘的明亮收尾。', 'V6 编辑标准化配方以白兰地、新鲜柠檬汁与 1:1 单糖浆为核心，可选加蛋清；酒精度按 40% ABV 白兰地估算，属于编辑数据。', 'https://upload.wikimedia.org/wikipedia/commons/9/96/Brandy_sour_%2822656571926%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/96/Brandy_sour_%2822656571926%29.jpg', 93, 32, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "白兰地基底", "冷饮", "酸甜", "果香", "摇和", "中等酒体", "经典"]', '["经典"]', '{"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、果香", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典"]}', '[{"nameZh": "白兰地", "nameEn": "Brandy", "amount": 45, "unit": "ml", "role": "建议 40% ABV"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "g", "role": "约半个蛋清，可选"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇和用冰"}]', '["预冷摇壶与鸡尾酒杯。", "摇壶中加入白兰地、柠檬汁、单糖浆与蛋清。", "加入约 60 g 冰块，摇和 12 秒。", "滤入预冷的鸡尾酒杯。", "以柠檬皮或酒渍樱桃装饰后饮用。"]', '["Brandy Sour", "白兰地沙瓦"]', 'B', '2026-08-04', 1, '{"id": "cocktail-brandy-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白兰地酸", "nameEn": "Brandy Sour", "intro": "以白兰地为基底、加入柠檬汁与糖浆的酸型鸡尾酒，果香与酸度平衡，既有烈酒的醇厚又有柑橘的明亮收尾。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/96/Brandy_sour_%2822656571926%29.jpg", "tags": ["酸型鸡尾酒", "白兰地基底", "冷饮", "酸甜", "果香", "摇和", "中等酒体", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、果香", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-boston-sour', 'cocktail', 'COCKTAIL', '波士顿酸', 'Boston Sour', 'boshidunsuan', 'bsds', '在威士忌酸基础上加入蛋清并覆以红葡萄酒浮层的酸型鸡尾酒，泡沫绵密、酸爽之中带一丝酒体与浆果气息。', 'V6 编辑标准化配方以黑麦威士忌、柠檬汁、单糖浆与蛋清摇和，最后轻浮一层红葡萄酒；比例与酒精度为编辑估算数据。', 'https://upload.wikimedia.org/wikipedia/commons/6/6e/100_years_exploring_life%2C_1888-1988_-_the_Marine_Biological_Laboratory_at_Woods_Hole_%281989%29_%2816640133106%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/6e/100_years_exploring_life%2C_1888-1988_-_the_Marine_Biological_Laboratory_at_Woods_Hole_%281989%29_%2816640133106%29.jpg', 93, 33, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "威士忌基底", "冷饮", "酸甜", "泡沫质地", "摇和", "经典", "无乳配方"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 45, "unit": "ml", "role": "黑麦威士忌，建议 40% ABV"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "g", "role": "约一个蛋清"}, {"nameZh": "红葡萄酒", "nameEn": "Red wine", "amount": 15, "unit": "ml", "role": "轻质干红葡萄酒，浮层用"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇和用冰"}]', '["预冷摇壶与鸡尾酒杯。", "干摇黑麦威士忌、柠檬汁、单糖浆与蛋清约 10 秒起泡。", "加入约 60 g 冰块，再次摇和 10 秒。", "滤入预冷的鸡尾酒杯，静置使泡沫稳定。", "沿杯壁缓缓倒入 15 ml 红葡萄酒形成浮层，立即饮用。"]', '["Boston Sour", "波士顿沙瓦"]', 'B', '2026-08-04', 1, '{"id": "cocktail-boston-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波士顿酸", "nameEn": "Boston Sour", "intro": "在威士忌酸基础上加入蛋清并覆以红葡萄酒浮层的酸型鸡尾酒，泡沫绵密、酸爽之中带一丝酒体与浆果气息。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6e/100_years_exploring_life%2C_1888-1988_-_the_Marine_Biological_Laboratory_at_Woods_Hole_%281989%29_%2816640133106%29.jpg", "tags": ["酸型鸡尾酒", "威士忌基底", "冷饮", "酸甜", "泡沫质地", "摇和", "经典", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-amaretto-sour', 'cocktail', 'COCKTAIL', '阿玛雷托酸', 'Amaretto Sour', 'amaleituosuan', 'amlts', '以杏仁利口酒阿玛雷托为基底、加入柠檬汁的酸型鸡尾酒，甜润杏仁香与明亮酸度互为衬托，是甜而不腻的经典酸饮。', 'V6 编辑标准化配方采用阿玛雷托、新鲜柠檬汁与单糖浆，并用橙皮提香；酒精度按利口酒约 28% ABV 估算，属编辑数据。', 'https://upload.wikimedia.org/wikipedia/commons/7/78/The_Russler_Cocktail.jpg', 'https://upload.wikimedia.org/wikipedia/commons/7/78/The_Russler_Cocktail.jpg', 93, 34, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["酸型鸡尾酒", "冷饮", "酸甜", "坚果", "焦糖", "摇和", "中等强度", "经典"]', '["经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、坚果", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "杏仁利口酒", "nameEn": "Amaretto", "amount": 50, "unit": "ml", "role": "杏仁利口酒，约 28% ABV"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇和用冰"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 5, "unit": "g", "role": "橙皮装饰"}]', '["预冷摇壶与古典杯。", "摇壶中加入阿玛雷托、柠檬汁与单糖浆。", "加入约 60 g 冰块，摇和 10 秒。", "滤入加有冰块的古典杯。", "以橙皮在杯口拧出香气后投入杯中。"]', '["Amaretto Sour", "阿玛雷托酸酒", "杏仁甜酒酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-amaretto-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "阿玛雷托酸", "nameEn": "Amaretto Sour", "intro": "以杏仁利口酒阿玛雷托为基底、加入柠檬汁的酸型鸡尾酒，甜润杏仁香与明亮酸度互为衬托，是甜而不腻的经典酸饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/78/The_Russler_Cocktail.jpg", "tags": ["酸型鸡尾酒", "冷饮", "酸甜", "坚果", "焦糖", "摇和", "中等强度", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、坚果", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-almond-sour', 'cocktail', 'COCKTAIL', '杏仁酸', 'Almond Sour', 'xingrensuan', 'xrs', '以白兰地为基底、用杏仁糖浆替代单糖浆的酸型鸡尾酒，坚果香与柑橘酸度交织，口感圆润且层次分明。', 'V6 编辑标准化配方以白兰地、新鲜柠檬汁、杏仁糖浆与蛋清摇和；杏仁糖浆为编辑选用，酒精度按烈酒配比估算。', 'https://upload.wikimedia.org/wikipedia/commons/3/37/%28S%29-Mandelate_Chemical_Structure.png', 'https://upload.wikimedia.org/wikipedia/commons/3/37/%28S%29-Mandelate_Chemical_Structure.png', 93, 35, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "白兰地基底", "冷饮", "酸甜", "坚果", "摇和", "泡沫质地", "无乳配方"]', '["经典", "开胃"]', '{"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、坚果", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "杏仁糖浆"], "scene": ["经典", "开胃"]}', '[{"nameZh": "白兰地", "nameEn": "Brandy", "amount": 45, "unit": "ml", "role": "建议 40% ABV"}, {"nameZh": "杏仁糖浆", "nameEn": "Almond syrup", "amount": 20, "unit": "ml", "role": "杏仁糖浆（orgeat）"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "g", "role": "约半个蛋清"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇和用冰"}]', '["预冷摇壶与鸡尾酒杯。", "干摇白兰地、杏仁糖浆、柠檬汁与蛋清约 10 秒。", "加入约 60 g 冰块，摇和 10 秒至充分起泡。", "滤入预冷的鸡尾酒杯。", "在泡沫表面磨入一层薄肉豆蔻粉或拧入柠檬皮提香，即可饮用。"]', '["Almond Sour", "杏仁沙瓦", "Orgeat Sour"]', 'B', '2026-08-04', 1, '{"id": "cocktail-almond-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "杏仁酸", "nameEn": "Almond Sour", "intro": "以白兰地为基底、用杏仁糖浆替代单糖浆的酸型鸡尾酒，坚果香与柑橘酸度交织，口感圆润且层次分明。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/37/%28S%29-Mandelate_Chemical_Structure.png", "tags": ["酸型鸡尾酒", "白兰地基底", "冷饮", "酸甜", "坚果", "摇和", "泡沫质地", "无乳配方"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、坚果", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "杏仁糖浆"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pisco-sour', 'cocktail', 'COCKTAIL', '皮斯科酸', 'Pisco Sour', 'pisikesuan', 'psks', '以秘鲁皮斯科为基底、加入青柠汁与蛋清的秘鲁国饮级酸型鸡尾酒，顶部苦精点睛，泡沫绵密、酸爽而富有果香。', '配方采用 IBA 官方比例：皮斯科、新鲜青柠汁、单糖浆与蛋清摇和，表面滴安格斯图拉苦精；酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/4/41/Pisco_Sour.JPG', 'https://upload.wikimedia.org/wikipedia/commons/4/41/Pisco_Sour.JPG', 93, 36, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "皮斯科基底", "冷饮", "柑橘", "泡沫质地", "摇和", "经典", "无乳配方"]', '["经典"]', '{"baseSpirit": "皮斯科基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "蛋清"], "scene": ["经典"]}', '[{"nameZh": "皮斯科", "nameEn": "Pisco", "amount": 60, "unit": "ml", "role": "秘鲁皮斯科，建议 40% ABV"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 30, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "g", "role": "约一个蛋清"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "表面装饰用"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇和用冰"}]', '["预冷摇壶与鸡尾酒杯。", "干摇皮斯科、青柠汁、单糖浆与蛋清约 10 秒起泡。", "加入约 60 g 冰块，摇和 10 秒。", "滤入预冷的鸡尾酒杯，静置至泡沫稳定。", "在泡沫表面滴 2 滴安格斯图拉苦精，立即饮用。"]', '["Pisco Sour", "皮斯科酸酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-pisco-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皮斯科酸", "nameEn": "Pisco Sour", "intro": "以秘鲁皮斯科为基底、加入青柠汁与蛋清的秘鲁国饮级酸型鸡尾酒，顶部苦精点睛，泡沫绵密、酸爽而富有果香。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/41/Pisco_Sour.JPG", "tags": ["酸型鸡尾酒", "皮斯科基底", "冷饮", "柑橘", "泡沫质地", "摇和", "经典", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "皮斯科基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "蛋清"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-singapore-sling', 'cocktail', 'COCKTAIL', '新加坡司令', 'Singapore Sling', 'xinjiaposiling', 'xjpsl', '源自新加坡莱佛士酒店的经典长饮，以金酒为基底叠加樱桃白兰地、菠萝汁与气泡水，果香奔放、清凉多汁。', '配方采用 IBA 官方框架：金酒、樱桃白兰地、班尼狄克汀与君度配菠萝汁和青柠，苏打水补足；酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg', 93, 37, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "果香", "热带水果", "气泡感", "摇和", "中等强度", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "樱桃白兰地利口酒", "nameEn": "Cherry brandy liqueur", "amount": 15, "unit": "ml", "role": "樱桃白兰地利口酒"}, {"nameZh": "班尼狄克汀", "nameEn": "Bénédictine", "amount": 7.5, "unit": "ml", "role": "班尼狄克汀"}, {"nameZh": "君度橙酒", "nameEn": "Cointreau", "amount": 7.5, "unit": "ml", "role": "君度橙酒"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 120, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 10, "unit": "ml", "role": "石榴糖浆调色"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 40, "unit": "ml", "role": "最后补足气泡"}]', '["高球杯中加满冰块。", "摇壶中加入金酒、樱桃白兰地、班尼狄克汀、君度、菠萝汁与青柠汁。", "加入冰块摇和 10 秒后滤入高球杯。", "沿杯壁补入苏打水并轻搅。", "滴入石榴糖浆调色，以菠萝块与樱桃装饰后饮用。"]', '["Singapore Sling", "新加坡司令酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-singapore-sling", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "新加坡司令", "nameEn": "Singapore Sling", "intro": "源自新加坡莱佛士酒店的经典长饮，以金酒为基底叠加樱桃白兰地、菠萝汁与气泡水，果香奔放、清凉多汁。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg", "tags": ["金酒基底", "冷饮", "果香", "热带水果", "气泡感", "摇和", "中等强度", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-daiquiri', 'cocktail', 'COCKTAIL', '黛绮莉', 'Daiquiri', 'daiqili', 'dql', '以白朗姆酒、青柠汁与糖浆构成的三元素经典酸型鸡尾酒，酸爽清爽、朗姆果香纯粹，是极简平衡的代表。', '配方采用 IBA 官方比例：白朗姆、新鲜青柠汁与糖浆摇和，不加装饰；酒精度按 40% ABV 朗姆估算，属编辑数据。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 38, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["酸型鸡尾酒", "朗姆基底", "冷饮", "柑橘", "酸甜", "摇和", "轻盈", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 60, "unit": "ml", "role": "白朗姆酒，建议 40% ABV"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰"}]', '["预冷摇壶与鸡尾酒杯。", "摇壶中加入白朗姆、青柠汁与单糖浆。", "加入约 90 g 冰块，摇和 12 秒至充分降温。", "双重滤入预冷的鸡尾酒杯。", "即刻饮用，不需任何装饰。"]', '["Daiquiri", "代基里", "得其利"]', 'A', '2026-08-04', 1, '{"id": "cocktail-daiquiri", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黛绮莉", "nameEn": "Daiquiri", "intro": "以白朗姆酒、青柠汁与糖浆构成的三元素经典酸型鸡尾酒，酸爽清爽、朗姆果香纯粹，是极简平衡的代表。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["酸型鸡尾酒", "朗姆基底", "冷饮", "柑橘", "酸甜", "摇和", "轻盈", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cuba-libre', 'cocktail', 'COCKTAIL', '自由古巴', 'Cuba Libre', 'ziyouguba', 'zygb', '以白朗姆酒与可乐为基干、以新鲜青柠汁提香的经典高球鸡尾酒，甜气与气泡明快，是上手度极高的日常长饮。', '配方遵循 IBA 官方框架：白朗姆、可乐配青柠汁现挤提香；酒精度与甜度随可乐品牌浮动，编辑取常见估算区间。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 39, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "焦糖", "气泡感", "直调", "日常", "低强度", "无麸质"]', '["日常"]', '{"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "焦糖", "abv": "中度＞10%～20%", "extra": ["可乐", "新鲜青柠汁"], "scene": ["日常"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 50, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 120, "unit": "ml", "role": "冰镇可乐"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "现挤青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}]', '["高球杯中加入约 100 g 冰块。", "加入 50 ml 白朗姆酒。", "挤入 10 ml 新鲜青柠汁。", "沿杯壁缓缓倒入冰镇可乐至杯口。", "轻搅两下，以青柠角装饰后饮用。"]', '["Cuba Libre", "古巴自由", "朗姆可乐"]', 'A', '2026-08-04', 1, '{"id": "cocktail-cuba-libre", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "自由古巴", "nameEn": "Cuba Libre", "intro": "以白朗姆酒与可乐为基干、以新鲜青柠汁提香的经典高球鸡尾酒，甜气与气泡明快，是上手度极高的日常长饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["朗姆基底", "冷饮", "焦糖", "气泡感", "直调", "日常", "低强度", "无麸质"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "焦糖", "abv": "中度＞10%～20%", "extra": ["可乐", "新鲜青柠汁"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mojito', 'cocktail', 'COCKTAIL', '莫吉托', 'Mojito', 'mojituo', 'mjt', '以白朗姆酒、青柠、薄荷与苏打水构成的古巴经典清凉长饮，薄荷辛香与青柠酸爽在气泡中格外清爽。', '配方采用 IBA 官方框架：白朗姆、薄荷叶、青柠汁与糖浆摇和后以苏打水补足；薄荷用量与甜度可依杯型微调。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 93, 40, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["酸型鸡尾酒", "朗姆基底", "冷饮", "薄荷", "柑橘", "清爽", "夏季", "新手友好"]', '["夏季", "新手友好"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季", "新手友好"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "约 8 片新鲜薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "最后补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}]', '["高球杯中加入薄荷叶、青柠汁与单糖浆。", "以捣棒轻压薄荷叶约 5 次释放香气。", "加入 45 ml 白朗姆酒并加满冰块。", "摇匀后补入苏打水至杯口。", "以薄荷枝与青柠角装饰，插入吸管饮用。"]', '["Mojito", "莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "莫吉托", "nameEn": "Mojito", "intro": "以白朗姆酒、青柠、薄荷与苏打水构成的古巴经典清凉长饮，薄荷辛香与青柠酸爽在气泡中格外清爽。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["酸型鸡尾酒", "朗姆基底", "冷饮", "薄荷", "柑橘", "清爽", "夏季", "新手友好"], "scene": ["夏季", "新手友好"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-caipirinha', 'cocktail', 'COCKTAIL', '凯皮利加', 'Caipirinha', 'kaipilijia', 'kplj', '以卡莎萨、新鲜青柠与细砂糖捣压而成的巴西经典鸡尾酒，酸爽清甜，甘蔗香气清晰，是巴西代表性国民饮品。', '本条目按 IBA 官方配比标准化：60 ml 卡莎萨、半个青柠切块加 2 茶匙细砂糖，捣压后加碎冰直调。青柠的用量与捣压强度决定酸度，砂糖量可按青柠成熟度微调。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 41, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 8.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["酸型鸡尾酒", "卡莎萨基底", "柑橘", "冷饮", "直调", "清爽", "经典", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "卡莎萨基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "夏季"]}', '[{"nameZh": "卡莎萨", "nameEn": "Cachaça", "amount": 60, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 2, "unit": "piece", "role": "切块入杯捣压"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 8, "unit": "g", "role": "约 2 茶匙"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 90, "unit": "ml", "role": "碎冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将半个青柠切成四块放入厚底杯。", "加入细砂糖，用捣棒轻压青柠以释放汁液。", "倒入卡莎萨并搅拌至糖溶解。", "加满碎冰，以吧勺稍作提拉混合。", "以一片青柠片装饰后立即饮用。"]', '["凯匹林纳", "卡皮利尼亚", "Caipirinha Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-caipirinha", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "凯皮利加", "nameEn": "Caipirinha", "intro": "以卡莎萨、新鲜青柠与细砂糖捣压而成的巴西经典鸡尾酒，酸爽清甜，甘蔗香气清晰，是巴西代表性国民饮品。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["酸型鸡尾酒", "卡莎萨基底", "柑橘", "冷饮", "直调", "清爽", "经典", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "卡莎萨基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-margarita', 'cocktail', 'COCKTAIL', '玛格丽特', 'Margarita', 'magelite', 'mglt', '以龙舌兰、橙味利口酒与新鲜青柠汁组成的经典酸型鸡尾酒，酸度明亮，可选半圈盐边，是墨西哥风味的代表。', '本条目按 IBA 官方配比标准化：50 ml 银龙舌兰、20 ml 橙味利口酒与 15 ml 新鲜青柠汁摇和滤冰。盐边是可选装饰，不进入液体配比；橙味利口酒用君度或库拉索会带来不同甜度与酒精度。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 93, 42, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 8.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["酸型鸡尾酒", "龙舌兰基底", "柑橘", "冷饮", "摇和", "可选盐边", "经典", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "细海盐"], "scene": ["经典", "夏季"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 50, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "橙味利口酒", "nameEn": "Triple sec", "amount": 20, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 30, "unit": "ml", "role": "摇和用"}, {"nameZh": "细海盐", "nameEn": "Fine sea salt", "amount": 1, "unit": "dash", "role": "盐边用"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["用青柠块润湿杯口后沾一层细盐作盐边。", "摇酒壶加冰，倒入龙舌兰、橙味利口酒与青柠汁。", "摇和约 10 秒至充分降温。", "滤入盐边杯，杯内不加冰。", "以一片青柠片装饰。"]', '["玛格丽塔", "Margarita Cocktail", "经典玛格丽特"]', 'A', '2026-08-04', 1, '{"id": "cocktail-margarita", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "玛格丽特", "nameEn": "Margarita", "intro": "以龙舌兰、橙味利口酒与新鲜青柠汁组成的经典酸型鸡尾酒，酸度明亮，可选半圈盐边，是墨西哥风味的代表。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg", "tags": ["酸型鸡尾酒", "龙舌兰基底", "柑橘", "冷饮", "摇和", "可选盐边", "经典", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "细海盐"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-sunrise', 'cocktail', 'COCKTAIL', '龙舌兰日出', 'Tequila Sunrise', 'longshelanrichu', 'lslrc', '以银龙舌兰、新鲜橙汁与石榴糖浆直调的长饮，石榴糖浆沉底形成落日般的红橙渐变，色彩与果味都很鲜明。', '本条目按 IBA 官方配比标准化：45 ml 银龙舌兰、90 ml 橙汁，石榴糖浆沉底后用吸管缓缓倒入形成渐变。石榴糖浆密度较高会自然下沉，倒入过快会破坏分层效果。', 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Tequila_Sunrise.jpg', 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Tequila_Sunrise.jpg', 91, 43, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["龙舌兰基底", "柑橘", "果香", "直调", "甜感明显", "粉红色外观", "夏季"]', '["夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘、果香", "abv": "中度＞10%～20%", "extra": ["新鲜橙汁"], "scene": ["夏季"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 45, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 90, "unit": "ml", "role": "新鲜橙汁"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 15, "unit": "ml", "role": "沉底形成渐变"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 30, "unit": "ml", "role": "杯内冰块"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 1, "unit": "piece", "role": "装饰用"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino cherry", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入冰块。", "倒入银龙舌兰与新鲜橙汁，轻搅混合。", "沿杯壁缓缓倒入石榴糖浆，使其沉底形成渐变。", "以橙片与一颗马拉斯奇诺樱桃装饰。"]', '["龙舌兰日出鸡尾酒", "Tequila Sunrise Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-tequila-sunrise", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰日出", "nameEn": "Tequila Sunrise", "intro": "以银龙舌兰、新鲜橙汁与石榴糖浆直调的长饮，石榴糖浆沉底形成落日般的红橙渐变，色彩与果味都很鲜明。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b7/Tequila_Sunrise.jpg", "tags": ["龙舌兰基底", "柑橘", "果香", "直调", "甜感明显", "粉红色外观", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘、果香", "abv": "中度＞10%～20%", "extra": ["新鲜橙汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-paloma', 'cocktail', 'COCKTAIL', '帕洛玛', 'Paloma', 'paluoma', 'plm', '以银龙舌兰、新鲜葡萄柚汁与气泡苏打直调的长饮，葡萄柚苦甜果香结合轻盈气泡，是墨西哥常见的龙舌兰高球。', '本条目采用银龙舌兰 45 ml、葡萄柚汁 60 ml 与苏打水 60 ml 的配比，青柠汁补足酸度。葡萄柚汁的品种与糖度会显著影响酸甜平衡，采集时需记录果汁规格。', 'https://upload.wikimedia.org/wikipedia/commons/6/69/Jessie_Christiansen_at_Palomar_Observatory.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/69/Jessie_Christiansen_at_Palomar_Observatory.jpg', 91, 44, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["龙舌兰基底", "柑橘", "气泡感", "直调", "清爽", "低糖", "夏季"]', '["夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "新鲜青柠汁"], "scene": ["夏季"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 45, "unit": "ml", "role": "银龙舌兰基底"}, {"nameZh": "新鲜葡萄柚汁", "nameEn": "Fresh grapefruit juice", "amount": 60, "unit": "ml", "role": "新鲜葡萄柚汁"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "补足酸度"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 30, "unit": "ml", "role": "杯内冰块"}, {"nameZh": "葡萄柚皮", "nameEn": "Grapefruit peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入冰块。", "倒入银龙舌兰、新鲜葡萄柚汁与青柠汁，轻搅混合。", "补入苏打水至满。", "轻搅一次后以一条葡萄柚皮装饰。"]', '["帕洛玛鸡尾酒", "Paloma Cocktail", "龙舌兰帕洛玛"]', 'B', '2026-08-04', 1, '{"id": "cocktail-paloma", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "帕洛玛", "nameEn": "Paloma", "intro": "以银龙舌兰、新鲜葡萄柚汁与气泡苏打直调的长饮，葡萄柚苦甜果香结合轻盈气泡，是墨西哥常见的龙舌兰高球。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/69/Jessie_Christiansen_at_Palomar_Observatory.jpg", "tags": ["龙舌兰基底", "柑橘", "气泡感", "直调", "清爽", "低糖", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "新鲜青柠汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-michelada', 'cocktail', 'COCKTAIL', '米歇尔达', 'Michelada', 'mixieerda', 'mxed', '以番茄汁、青柠汁与辣酱香料调配、兑入淡啤酒的墨西哥长饮，咸鲜酸辣带气泡，常作消暑解渴的啤酒鸡尾酒。', 'V6 编辑标准化：本配方以番茄汁、青柠汁、伍斯特酱、辣酱与盐胡椒调味，冰镇后兑入淡色拉格啤酒完成。当前原料词典未收录啤酒，故此条配方以调味基底为主，啤酒在采集时补充；风味描述与雷达按典型米歇尔达口径。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Michelada.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Michelada.jpg', 91, 45, '[{"key": "SWEETNESS", "label": "甜度", "score": 2.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["咸鲜", "辛辣", "柑橘", "直调", "冷饮", "可选盐边", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "低度≤10%", "extra": ["伍斯特酱", "新鲜青柠汁"], "scene": ["夏季"]}', '[{"nameZh": "番茄汁", "nameEn": "Tomato juice", "amount": 90, "unit": "ml", "role": "番茄汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "伍斯特酱", "nameEn": "Worcestershire sauce", "amount": 5, "unit": "ml", "role": "伍斯特酱"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 5, "unit": "ml", "role": "辣酱"}, {"nameZh": "粗盐", "nameEn": "Coarse salt", "amount": 2, "unit": "g", "role": "杯口盐边与调味"}, {"nameZh": "黑胡椒", "nameEn": "Black pepper", "amount": 1, "unit": "g", "role": "调味"}]', '["用青柠块润湿杯口后沾粗盐作盐边。", "杯中加入冰块，倒入番茄汁、青柠汁、伍斯特酱与辣酱。", "加入细海盐与黑胡椒并轻搅混合。", "补满冰镇苏打水与冰镇淡啤酒（采集时补充啤酒码）。", "以一片青柠角装饰。"]', '["米切拉达", "米歇尔拉达", "Michelada Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-michelada", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "米歇尔达", "nameEn": "Michelada", "intro": "以番茄汁、青柠汁与辣酱香料调配、兑入淡啤酒的墨西哥长饮，咸鲜酸辣带气泡，常作消暑解渴的啤酒鸡尾酒。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Michelada.jpg", "tags": ["咸鲜", "辛辣", "柑橘", "直调", "冷饮", "可选盐边", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "低度≤10%", "extra": ["伍斯特酱", "新鲜青柠汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bloody-mary', 'cocktail', 'COCKTAIL', '血腥玛丽', 'Bloody Mary', 'xuexingmali', 'xxml', '以伏特加与番茄汁为主、加入柠檬汁与辣酱调味的咸鲜长饮，酸辣鲜香与浓稠质地结合，是经典佐餐鸡尾酒。', '本条目按 IBA 官方配比标准化：45 ml 伏特加、90 ml 番茄汁、15 ml 柠檬汁与适量辣酱、伍斯特酱、盐和胡椒。番茄汁的稠度与调味料的用量决定整体咸鲜与辣度，可按口味调整。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 46, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "咸鲜", "辛辣", "直调", "冷饮", "早午餐", "经典"]', '["早午餐", "经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["早午餐", "经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "番茄汁", "nameEn": "Tomato juice", "amount": 90, "unit": "ml", "role": "番茄汁"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "伍斯特酱", "nameEn": "Worcestershire sauce", "amount": 5, "unit": "ml", "role": "伍斯特酱"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 5, "unit": "ml", "role": "辣酱"}, {"nameZh": "芹菜盐", "nameEn": "Celery salt", "amount": 1, "unit": "dash", "role": "调味用"}]', '["在高球杯中加冰。", "倒入伏特加、番茄汁、柠檬汁、伍斯特酱与辣酱。", "加入芹菜盐并以吧勺上下提拉混合。", "以一根芹菜梗与一片柠檬装饰。"]', '["Bloody Mary", "血腥玛丽鸡尾酒", "经典血腥玛丽"]', 'A', '2026-08-04', 1, '{"id": "cocktail-bloody-mary", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "血腥玛丽", "nameEn": "Bloody Mary", "intro": "以伏特加与番茄汁为主、加入柠檬汁与辣酱调味的咸鲜长饮，酸辣鲜香与浓稠质地结合，是经典佐餐鸡尾酒。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "咸鲜", "辛辣", "直调", "冷饮", "早午餐", "经典"], "scene": ["早午餐", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["早午餐", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bloody-maria', 'cocktail', 'COCKTAIL', '血腥玛丽亚', 'Bloody Maria', 'xuexingmaliya', 'xxmly', '以龙舌兰替代伏特加调制的番茄咸鲜长饮，在血腥玛丽基础上加入龙舌兰植物气息与辣椒辛香，是墨西哥风变体。', '本条目采用银龙舌兰 45 ml、番茄汁 90 ml、青柠汁 15 ml 加辣酱与伍斯特酱调味的配比，盐边可选。龙舌兰基底的植物味与辣椒风味组合是血腥玛丽亚的辨识特征。', 'https://upload.wikimedia.org/wikipedia/commons/2/26/Agalima_Organic_Bloody_Mary_Mix_01.jpg', 'https://upload.wikimedia.org/wikipedia/commons/2/26/Agalima_Organic_Bloody_Mary_Mix_01.jpg', 91, 47, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["龙舌兰基底", "咸鲜", "辛辣", "直调", "冷饮", "可选盐边", "香料"]', '["经典"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜青柠汁"], "scene": ["经典"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 45, "unit": "ml", "role": "银龙舌兰基底"}, {"nameZh": "番茄汁", "nameEn": "Tomato juice", "amount": 90, "unit": "ml", "role": "番茄汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "伍斯特酱", "nameEn": "Worcestershire sauce", "amount": 5, "unit": "ml", "role": "伍斯特酱"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 5, "unit": "ml", "role": "辣酱"}, {"nameZh": "芹菜盐", "nameEn": "Celery salt", "amount": 1, "unit": "dash", "role": "调味用"}]', '["在高球杯中加冰。", "倒入龙舌兰、番茄汁、青柠汁、伍斯特酱与辣酱。", "加入芹菜盐并以吧勺上下提拉混合。", "以一片青柠角与芹菜梗装饰。"]', '["Bloody Maria", "血腥玛利亚", "龙舌兰血腥玛丽"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bloody-maria", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "血腥玛丽亚", "nameEn": "Bloody Maria", "intro": "以龙舌兰替代伏特加调制的番茄咸鲜长饮，在血腥玛丽基础上加入龙舌兰植物气息与辣椒辛香，是墨西哥风变体。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/26/Agalima_Organic_Bloody_Mary_Mix_01.jpg", "tags": ["龙舌兰基底", "咸鲜", "辛辣", "直调", "冷饮", "可选盐边", "香料"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-red-snapper', 'cocktail', 'COCKTAIL', '红鲷鱼', 'Red Snapper', 'hongdiaoyu', 'hdy', '以金酒替代伏特加调制的番茄咸鲜长饮，被视为血腥玛丽的前身，杜松子的草本气息与番茄的咸鲜酸辣相互衬托。', '本条目按经典配比标准化：45 ml 伦敦干金酒、90 ml 番茄汁、15 ml 柠檬汁加辣酱与伍斯特酱调味。金酒的杜松子与草本风味是红鲷鱼区别于血腥玛丽的关键。', 'https://upload.wikimedia.org/wikipedia/commons/f/f0/FMIB_52019_Red_Tai_of_Japan%2C_Pagrus_major_Schlegel_Family_Sparidae.jpeg', 'https://upload.wikimedia.org/wikipedia/commons/f/f0/FMIB_52019_Red_Tai_of_Japan%2C_Pagrus_major_Schlegel_Family_Sparidae.jpeg', 91, 48, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "咸鲜", "草本", "辛辣", "直调", "冷饮", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、草本", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒基底"}, {"nameZh": "番茄汁", "nameEn": "Tomato juice", "amount": 90, "unit": "ml", "role": "番茄汁"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "伍斯特酱", "nameEn": "Worcestershire sauce", "amount": 5, "unit": "ml", "role": "伍斯特酱"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 5, "unit": "ml", "role": "辣酱"}, {"nameZh": "芹菜盐", "nameEn": "Celery salt", "amount": 1, "unit": "dash", "role": "调味用"}]', '["在高球杯中加冰。", "倒入金酒、番茄汁、柠檬汁、伍斯特酱与辣酱。", "加入芹菜盐并以吧勺上下提拉混合。", "以一片柠檬轮与芹菜梗装饰。"]', '["红鲷鱼鸡尾酒", "Red Snapper Cocktail", "金酒血腥玛丽"]', 'B', '2026-08-04', 1, '{"id": "cocktail-red-snapper", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "红鲷鱼", "nameEn": "Red Snapper", "intro": "以金酒替代伏特加调制的番茄咸鲜长饮，被视为血腥玛丽的前身，杜松子的草本气息与番茄的咸鲜酸辣相互衬托。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f0/FMIB_52019_Red_Tai_of_Japan%2C_Pagrus_major_Schlegel_Family_Sparidae.jpeg", "tags": ["金酒基底", "咸鲜", "草本", "辛辣", "直调", "冷饮", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、草本", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-american-lemonade', 'cocktail', 'COCKTAIL', '美国柠檬水', 'American Lemonade', 'meiguoningmengshui', 'mgnms', '以伏特加、新鲜柠檬汁与单糖浆兑入苏打水直调的长饮，酸甜清爽带气泡，是柠檬水与烈酒结合的日常易饮饮品。', '本条目按 V6 编辑标准化配比：40 ml 伏特加、30 ml 新鲜柠檬汁、20 ml 单糖浆与 60 ml 苏打水，直调于加冰高球杯。柠檬汁与糖浆的比例决定酸甜平衡，可按口味调整。', 'https://upload.wikimedia.org/wikipedia/commons/8/8a/Hotel_Radisson_Minneapolis_Drink_List_-_DPLA_-_2f0d3ac13419544b97c28612f2d9c751_%28page_1%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/8a/Hotel_Radisson_Minneapolis_Drink_List_-_DPLA_-_2f0d3ac13419544b97c28612f2d9c751_%28page_1%29.jpg', 91, 49, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["伏特加基底", "柑橘", "气泡感", "直调", "清爽", "低糖", "夏季"]', '["夏季"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "伏特加基底"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 30, "unit": "ml", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入冰块。", "倒入伏特加、新鲜柠檬汁与单糖浆，轻搅混合。", "补入苏打水至满。", "轻搅一次，以一片柠檬轮装饰。"]', '["美式柠檬水", "American Lemonade Cocktail", "烈酒柠檬水"]', 'B', '2026-08-04', 1, '{"id": "cocktail-american-lemonade", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "美国柠檬水", "nameEn": "American Lemonade", "intro": "以伏特加、新鲜柠檬汁与单糖浆兑入苏打水直调的长饮，酸甜清爽带气泡，是柠檬水与烈酒结合的日常易饮饮品。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8a/Hotel_Radisson_Minneapolis_Drink_List_-_DPLA_-_2f0d3ac13419544b97c28612f2d9c751_%28page_1%29.jpg", "tags": ["伏特加基底", "柑橘", "气泡感", "直调", "清爽", "低糖", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-collins', 'cocktail', 'COCKTAIL', '柯林斯', 'Collins', 'kelinsi', 'kls', '以基酒、新鲜柠檬汁、单糖浆与苏打水组成的长饮，酸甜清爽、气泡轻盈，是柯林斯家族的基础模板。', '本条目按通用柯林斯结构标准化：45 ml 基酒、25 ml 柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水。本条目以通用结构呈现，具体基酒由变体条目定义。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Tom%20Collins.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Tom%20Collins.jpg', 91, 50, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "柑橘", "气泡感", "摇和", "清爽", "夏季", "经典"]', '["夏季", "经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季", "经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "以金酒为代表基酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 75, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 30, "unit": "ml", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入基酒、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰。"]', '["柯林斯鸡尾酒", "Collins Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "柯林斯", "nameEn": "Collins", "intro": "以基酒、新鲜柠檬汁、单糖浆与苏打水组成的长饮，酸甜清爽、气泡轻盈，是柯林斯家族的基础模板。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Tom%20Collins.jpg", "tags": ["金酒基底", "柑橘", "气泡感", "摇和", "清爽", "夏季", "经典"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tom-collins', 'cocktail', 'COCKTAIL', '汤姆柯林斯', 'Tom Collins', 'tangmukelinsi', 'tmkls', '以老汤姆金酒配柠檬与糖浆、兑苏打水的经典长饮，酸甜清爽、气泡轻盈，是柯林斯家族的代表变体。', '本条目按 IBA 官方配比标准化：45 ml 老汤姆金酒、30 ml 新鲜柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水至满。老汤姆金酒较伦敦干金酒更甜润，是汤姆柯林斯区别于金酒柯林斯的关键。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Tom%20Collins.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Tom%20Collins.jpg', 91, 51, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "柑橘", "气泡感", "摇和", "酸甜", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}', '[{"nameZh": "老汤姆金酒", "nameEn": "Old Tom gin", "amount": 45, "unit": "ml", "role": "IBA 配比"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入老汤姆金酒、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰后饮用。"]', '["汤姆柯林斯鸡尾酒", "Tom Collins Cocktail", "汤姆柯林"]', 'A', '2026-08-04', 1, '{"id": "cocktail-tom-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "汤姆柯林斯", "nameEn": "Tom Collins", "intro": "以老汤姆金酒配柠檬与糖浆、兑苏打水的经典长饮，酸甜清爽、气泡轻盈，是柯林斯家族的代表变体。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Tom%20Collins.jpg", "tags": ["金酒基底", "冷饮", "柑橘", "气泡感", "摇和", "酸甜", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gin-collins', 'cocktail', 'COCKTAIL', '金酒柯林斯', 'Gin Collins', 'jinjiukelinsi', 'jjkls', '以伦敦干金酒配柠檬与糖浆、兑苏打水的清爽长饮，杜松子草本与酸甜果香在气泡中明快清爽。', '本条目按 V6 编辑标准化配比：45 ml 伦敦干金酒、30 ml 新鲜柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水至满。与汤姆柯林斯的不同在于采用更干的伦敦干金酒。', 'https://upload.wikimedia.org/wikipedia/commons/8/87/Gin_Blossoms_at_Taste_of_Fort_Collins_2009.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/87/Gin_Blossoms_at_Taste_of_Fort_Collins_2009.jpg', 91, 52, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "柑橘", "气泡感", "摇和", "酸甜", "清爽"]', '["夏季", "经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季", "经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "V6 编辑配比"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入伦敦干金酒、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰后饮用。"]', '["金酒柯林斯鸡尾酒", "Gin Collins Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-gin-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金酒柯林斯", "nameEn": "Gin Collins", "intro": "以伦敦干金酒配柠檬与糖浆、兑苏打水的清爽长饮，杜松子草本与酸甜果香在气泡中明快清爽。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/87/Gin_Blossoms_at_Taste_of_Fort_Collins_2009.jpg", "tags": ["金酒基底", "冷饮", "柑橘", "气泡感", "摇和", "酸甜", "清爽"], "scene": ["夏季", "经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-john-collins', 'cocktail', 'COCKTAIL', '约翰柯林斯', 'John Collins', 'yuehankelinsi', 'yhkls', '以波本威士忌配柠檬与糖浆、兑苏打水的长饮，谷物甜香与柑橘酸度平衡，是柯林斯家族中酒体更饱满的变体。', '本条目按 V6 编辑标准化配比：45 ml 波本威士忌、30 ml 新鲜柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水至满。约翰柯林斯传统以荷兰杜松子酒为底，现代酒吧常以威士忌替代并逐渐定型。', 'https://upload.wikimedia.org/wikipedia/commons/4/4e/IBA_Cocktail_John_Collins_%2829221732881%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/4e/IBA_Cocktail_John_Collins_%2829221732881%29.jpg', 91, 53, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["威士忌基底", "冷饮", "柑橘", "气泡感", "摇和", "酸甜", "经典"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "科林斯", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "V6 编辑配比"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入波本威士忌、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰后饮用。"]', '["约翰柯林斯鸡尾酒", "John Collins Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-john-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "约翰柯林斯", "nameEn": "John Collins", "intro": "以波本威士忌配柠檬与糖浆、兑苏打水的长饮，谷物甜香与柑橘酸度平衡，是柯林斯家族中酒体更饱满的变体。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4e/IBA_Cocktail_John_Collins_%2829221732881%29.jpg", "tags": ["威士忌基底", "冷饮", "柑橘", "气泡感", "摇和", "酸甜", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "科林斯", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-whiskey-collins', 'cocktail', 'COCKTAIL', '威士忌柯林斯', 'Whiskey Collins', 'weishijikelinsi', 'wsjkls', '以黑麦威士忌为基底、配柠檬汁与单糖浆并兑入苏打水的长饮，黑麦的辛香与柑橘酸度结合，气泡带来清爽收尾。', '本条目按 V6 编辑标准化配比：45 ml 黑麦威士忌、30 ml 新鲜柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水至满。黑麦威士忌的辛香与干爽是这一变体的辨识特征。', 'https://upload.wikimedia.org/wikipedia/commons/c/cd/Fun_Factory_Fun_House_-_panoramio.jpg', 'https://upload.wikimedia.org/wikipedia/commons/c/cd/Fun_Factory_Fun_House_-_panoramio.jpg', 91, 54, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["黑麦基底", "冷饮", "柑橘", "气泡感", "摇和", "香料", "中等强度"]', '["夏季", "经典", "开胃"]', '{"baseSpirit": "黑麦基底", "cocktailType": "科林斯", "flavor": "柑橘、香料", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季", "经典", "开胃"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 45, "unit": "ml", "role": "V6 编辑配比"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入黑麦威士忌、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰后饮用。"]', '["威士忌柯林斯鸡尾酒", "Whiskey Collins Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-whiskey-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "威士忌柯林斯", "nameEn": "Whiskey Collins", "intro": "以黑麦威士忌为基底、配柠檬汁与单糖浆并兑入苏打水的长饮，黑麦的辛香与柑橘酸度结合，气泡带来清爽收尾。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/cd/Fun_Factory_Fun_House_-_panoramio.jpg", "tags": ["黑麦基底", "冷饮", "柑橘", "气泡感", "摇和", "香料", "中等强度"], "scene": ["夏季", "经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "科林斯", "flavor": "柑橘、香料", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vodka-collins', 'cocktail', 'COCKTAIL', '伏特加柯林斯', 'Vodka Collins', 'futejiakelinsi', 'ftjkls', '以伏特加配柠檬与糖浆、兑苏打水的清爽长饮，纯净酒底让酸甜与气泡成为主角，易饮度高。', '本条目按 V6 编辑标准化配比：45 ml 伏特加、30 ml 新鲜柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水至满。中性伏特加不引入额外风味，适合作为最清淡的柯林斯版本。', 'https://upload.wikimedia.org/wikipedia/commons/f/fb/Vodka-1972.jpg', 'https://upload.wikimedia.org/wikipedia/commons/f/fb/Vodka-1972.jpg', 91, 55, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["伏特加基底", "冷饮", "柑橘", "气泡感", "摇和", "轻盈", "新手友好"]', '["新手友好"]', '{"baseSpirit": "伏特加基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["新手友好"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "选用中性伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入伏特加、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰后饮用。"]', '["伏特加柯林斯鸡尾酒", "Vodka Collins Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-vodka-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "伏特加柯林斯", "nameEn": "Vodka Collins", "intro": "以伏特加配柠檬与糖浆、兑苏打水的清爽长饮，纯净酒底让酸甜与气泡成为主角，易饮度高。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fb/Vodka-1972.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "气泡感", "摇和", "轻盈", "新手友好"], "scene": ["新手友好"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rum-collins', 'cocktail', 'COCKTAIL', '朗姆柯林斯', 'Rum Collins', 'langmukelinsi', 'lmkls', '以白朗姆为基底、配柠檬汁与单糖浆并兑入苏打水的清爽长饮，朗姆的甘蔗甜香与柑橘酸度在气泡中格外轻快。', '本条目按 V6 编辑标准化配比：45 ml 白朗姆、30 ml 新鲜柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水至满。选用白朗姆可保留甘蔗的干净香气而不额外加重酒体。', 'https://upload.wikimedia.org/wikipedia/commons/a/a5/Baroque_ceiling_frescoes_%28Ljubljana_Cathedral%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a5/Baroque_ceiling_frescoes_%28Ljubljana_Cathedral%29.jpg', 91, 56, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "柑橘", "气泡感", "摇和", "果香", "夏季"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "科林斯", "flavor": "柑橘、果香", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入白朗姆、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰后饮用。"]', '["朗姆柯林斯鸡尾酒", "Rum Collins Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rum-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朗姆柯林斯", "nameEn": "Rum Collins", "intro": "以白朗姆为基底、配柠檬汁与单糖浆并兑入苏打水的清爽长饮，朗姆的甘蔗甜香与柑橘酸度在气泡中格外轻快。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a5/Baroque_ceiling_frescoes_%28Ljubljana_Cathedral%29.jpg", "tags": ["朗姆基底", "冷饮", "柑橘", "气泡感", "摇和", "果香", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "科林斯", "flavor": "柑橘、果香", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-collins', 'cocktail', 'COCKTAIL', '龙舌兰柯林斯', 'Tequila Collins', 'longshelankelinsi', 'lslkls', '以银龙舌兰配柠檬与糖浆、兑苏打水的清爽长饮，龙舌兰的植物气息与柑橘酸度在气泡中明快爽朗。', '本条目按 V6 编辑标准化配比：45 ml 银龙舌兰、30 ml 新鲜柠檬汁与 15 ml 单糖浆摇和后滤入加冰柯林斯杯，补苏打水至满。银龙舌兰带来清新植物感，与柠檬苏打结构十分契合。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 57, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["龙舌兰基底", "冷饮", "柑橘", "气泡感", "摇和", "清爽", "夏季"]', '["夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 45, "unit": "ml", "role": "银龙舌兰"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在柯林斯杯中加满冰块。", "摇酒壶加冰，倒入银龙舌兰、柠檬汁与单糖浆，摇和约 8 秒。", "滤入柯林斯杯。", "补入苏打水至满并轻搅。", "以一片柠檬轮装饰后饮用。"]', '["龙舌兰柯林斯鸡尾酒", "Tequila Collins Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tequila-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰柯林斯", "nameEn": "Tequila Collins", "intro": "以银龙舌兰配柠檬与糖浆、兑苏打水的清爽长饮，龙舌兰的植物气息与柑橘酸度在气泡中明快爽朗。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["龙舌兰基底", "冷饮", "柑橘", "气泡感", "摇和", "清爽", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-negroni', 'cocktail', 'COCKTAIL', '内格罗尼', 'Negroni', 'neigeluoni', 'ngln', '金酒、金巴利与甜红味美思等量构成的开胃鸡尾酒，苦甜草本并重、酒体较强，是苦味鸡尾酒的代表。', '本条目按 IBA 官方等量结构标准化：各 30 ml 金酒、金巴利与甜红味美思，搅拌后滤入加冰古典杯，以橙皮装饰。三者等量是内格罗尼不变的骨架，基酒风格决定苦甜走向。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 93, 58, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 9.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["烈酒主导", "金酒基底", "苦感主导", "草本", "搅拌", "高强度", "经典", "开胃"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "IBA 等量配比"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 30, "unit": "ml", "role": "金巴利"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 30, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "搅拌用"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将古典杯预先冰镇或加入大块冰。", "搅拌杯加冰，倒入金酒、金巴利与甜红味美思。", "搅拌约 20 秒至充分降温。", "滤入加有冰块的古典杯。", "在杯面挤橙皮油后投入橙皮装饰。"]', '["内格罗尼鸡尾酒", "Negroni Cocktail", "尼格罗尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-negroni", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "内格罗尼", "nameEn": "Negroni", "intro": "金酒、金巴利与甜红味美思等量构成的开胃鸡尾酒，苦甜草本并重、酒体较强，是苦味鸡尾酒的代表。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["烈酒主导", "金酒基底", "苦感主导", "草本", "搅拌", "高强度", "经典", "开胃"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-aperol-spritz', 'cocktail', 'COCKTAIL', '阿佩罗开胃酒', 'Aperol Spritz', 'apeiluokaiweijiu', 'aplkwj', '以阿佩罗、普罗塞克与苏打水构成的开胃长饮，橙香与草本苦甜在细密气泡中明快，是意大利经典的餐前酒。', '本条目按 60 ml 阿佩罗、90 ml 普罗塞克与 30 ml 苏打水的常见配比标准化，直调于加冰酒杯并以橙片装饰。阿佩罗的苦甜较金巴利柔和，酒精度也显著更低。', 'https://upload.wikimedia.org/wikipedia/commons/5/51/Aperol_Aperitivo_Aperitif_03.tif', 'https://upload.wikimedia.org/wikipedia/commons/5/51/Aperol_Aperitivo_Aperitif_03.tif', 93, 59, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["开胃", "冷饮", "苦味明显", "草本", "气泡感", "直调", "低强度", "夏季"]', '["开胃", "夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "苦味明显、草本", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["开胃", "夏季"]}', '[{"nameZh": "阿佩罗", "nameEn": "Aperol", "amount": 60, "unit": "ml", "role": "阿佩罗"}, {"nameZh": "普罗塞克", "nameEn": "Prosecco", "amount": 90, "unit": "ml", "role": "普罗塞克起泡酒"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 30, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在酒杯中加入冰块。", "倒入 60 ml 阿佩罗。", "补入 90 ml 冰镇普罗塞克与 30 ml 苏打水。", "轻搅一次使混合。", "以一片橙片装饰后饮用。"]', '["阿佩罗气泡酒", "Aperol Spritz Cocktail", "阿佩罗斯普利兹"]', 'A', '2026-08-04', 1, '{"id": "cocktail-aperol-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "阿佩罗开胃酒", "nameEn": "Aperol Spritz", "intro": "以阿佩罗、普罗塞克与苏打水构成的开胃长饮，橙香与草本苦甜在细密气泡中明快，是意大利经典的餐前酒。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/51/Aperol_Aperitivo_Aperitif_03.tif", "tags": ["开胃", "冷饮", "苦味明显", "草本", "气泡感", "直调", "低强度", "夏季"], "scene": ["开胃", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "苦味明显、草本", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["开胃", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-campari-soda', 'cocktail', 'COCKTAIL', '金巴利苏打', 'Campari Soda', 'jinbalisuda', 'jblsd', '以金巴利兑苏打水的极简直调长饮，突出草本苦香与橙色果调，气泡让苦味轻盈，是意大利经典的开胃酒。', '本条目按 40 ml 金巴利与 120 ml 苏打水的经典配比标准化，直调于加冰高球杯并以橙片装饰。金巴利苏打几乎不含糖分，苦味与气泡是其全部性格，酒精度由金巴利用量决定。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 93, 60, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["苦感主导", "开胃", "冷饮", "草本", "气泡感", "直调", "日常", "低糖"]', '["开胃", "日常"]', '{"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "低度≤10%", "extra": ["苏打水"], "scene": ["开胃", "日常"]}', '[{"nameZh": "金巴利", "nameEn": "Campari", "amount": 40, "unit": "ml", "role": "金巴利"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 120, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯内冰块"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["高球杯中加入冰块。", "倒入 40 ml 金巴利。", "补入冰镇苏打水至满。", "轻搅一次使混合。", "以一片橙片装饰后饮用。"]', '["金巴利苏打水", "Campari Soda Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-campari-soda", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金巴利苏打", "nameEn": "Campari Soda", "intro": "以金巴利兑苏打水的极简直调长饮，突出草本苦香与橙色果调，气泡让苦味轻盈，是意大利经典的开胃酒。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg", "tags": ["苦感主导", "开胃", "冷饮", "草本", "气泡感", "直调", "日常", "低糖"], "scene": ["开胃", "日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "低度≤10%", "extra": ["苏打水"], "scene": ["开胃", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-americano', 'cocktail', 'COCKTAIL', '美国佬', 'Americano', 'meiguolao', 'mgl', '以金巴利与甜红味美思等量调配、再以苏打水冲调而成的开胃长饮，苦甜交织并带柑橘与草本气息，口感清爽，适合餐前饮用。', 'IBA 标准为金巴利与甜红味美思各 30 ml 加苏打水冲调，V6 采用此配比；相比内格罗尼去掉金酒、以苏打水拉长，苦度与酒精感均更低。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 89, 61, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["苦感主导", "草本", "开胃", "气泡感", "冷饮", "经典"]', '["开胃", "经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦感主导、草本", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["开胃", "经典"]}', '[{"nameZh": "金巴利", "nameEn": "Campari", "amount": 30, "unit": "ml", "role": "金巴利利口酒"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 30, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "冷藏苏打水"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 20, "unit": "g", "role": "装饰用橙片"}]', '["在高球杯中加入冰块并预冷。", "倒入金巴利 30 ml。", "倒入甜红味美思 30 ml。", "沿杯壁补入冷藏苏打水 60 ml。", "用吧勺轻搅一次，以橙片装饰。"]', '["Americano", "美式开胃酒", "金巴利味美思苏打"]', 'A', '2026-08-04', 1, '{"id": "cocktail-americano", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "美国佬", "nameEn": "Americano", "intro": "以金巴利与甜红味美思等量调配、再以苏打水冲调而成的开胃长饮，苦甜交织并带柑橘与草本气息，口感清爽，适合餐前饮用。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["苦感主导", "草本", "开胃", "气泡感", "冷饮", "经典"], "scene": ["开胃", "经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦感主导、草本", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bourbon-cocktail', 'cocktail', 'COCKTAIL', '波本鸡尾酒', 'Bourbon Cocktail', 'bobenjiweijiu', 'bbjwj', '以波本威士忌为基底、加入甜红味美思与安格斯图拉苦精搅拌而成的烈酒类鸡尾酒，焦糖与香草气息突出，酒体饱满，口感圆润。', '此款为曼哈顿家族的波本变体，V6 标准取波本威士忌 60 ml、甜红味美思 30 ml 与安格斯图拉苦精 2 滴搅拌而成；相比曼哈顿改用波本基酒，焦糖感更突出。', 'https://upload.wikimedia.org/wikipedia/commons/9/92/2_Manhattan_cocktails%2C_bird%27s_eye_view.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/92/2_Manhattan_cocktails%2C_bird%27s_eye_view.jpg', 91, 62, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["烈酒主导", "威士忌基底", "焦糖", "香草", "搅拌", "餐后", "经典"]', '["餐后", "经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "烈酒主导", "flavor": "焦糖、香草", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["餐后", "经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 30, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "ml", "role": "约 2 滴安格斯图拉苦精"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "g", "role": "装饰用鸡尾酒樱桃"}]', '["在混合杯中加入大量冰块。", "倒入波本威士忌 60 ml 与甜红味美思 30 ml。", "滴入安格斯图拉苦精 2 滴。", "搅拌约 20 秒至充分冷却。", "滤入老式杯中的大冰块上，以樱桃装饰。"]', '["Bourbon Cocktail", "波本曼哈顿变体", "波本甜味美思"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bourbon-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波本鸡尾酒", "nameEn": "Bourbon Cocktail", "intro": "以波本威士忌为基底、加入甜红味美思与安格斯图拉苦精搅拌而成的烈酒类鸡尾酒，焦糖与香草气息突出，酒体饱满，口感圆润。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/92/2_Manhattan_cocktails%2C_bird%27s_eye_view.jpg", "tags": ["烈酒主导", "威士忌基底", "焦糖", "香草", "搅拌", "餐后", "经典"], "scene": ["餐后", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "烈酒主导", "flavor": "焦糖、香草", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pimm-cup', 'cocktail', 'COCKTAIL', '皮姆杯', 'Pimm\'s Cup', 'pimubei', 'pmb', '以金酒为基底的编辑标准化长饮，加入柠檬苏打与黄瓜、薄荷调制，果香清爽、气泡充足，是夏季花园聚会的经典之选。', '原版以皮姆一号利口酒调制，该利口酒不在原料词典内，V6 以伦敦干金酒为基底做编辑标准化，配柠檬苏打、黄瓜与薄荷还原清爽结构。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Pimm%27s%20Cup.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Pimm%27s%20Cup.jpg', 91, 63, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["金酒基底", "冷饮", "果香", "草本", "清爽", "夏季", "新手友好"]', '["夏季", "新手友好"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "果香、草本", "abv": "中度＞10%～20%", "extra": ["柠檬苏打", "黄瓜"], "scene": ["夏季", "新手友好"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "柠檬苏打", "nameEn": "Lemon soda", "amount": 90, "unit": "ml", "role": "冷藏柠檬苏打"}, {"nameZh": "黄瓜", "nameEn": "Cucumber", "amount": 15, "unit": "g", "role": "黄瓜片"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 1, "unit": "g", "role": "薄荷叶"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 20, "unit": "g", "role": "装饰用橙片"}]', '["在高球杯中加入冰块。", "放入黄瓜片与薄荷叶并轻压出香。", "倒入伦敦干金酒 45 ml。", "补入冷藏柠檬苏打 90 ml。", "轻搅后以橙片与薄荷叶装饰。"]', '["Pimm\'s Cup", "皮姆杯汽水", "Pimm\'s No.1 Cup"]', 'B', '2026-08-04', 1, '{"id": "cocktail-pimm-cup", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皮姆杯", "nameEn": "Pimm\'s Cup", "intro": "以金酒为基底的编辑标准化长饮，加入柠檬苏打与黄瓜、薄荷调制，果香清爽、气泡充足，是夏季花园聚会的经典之选。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Pimm%27s%20Cup.jpg", "tags": ["金酒基底", "冷饮", "果香", "草本", "清爽", "夏季", "新手友好"], "scene": ["夏季", "新手友好"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "果香、草本", "abv": "中度＞10%～20%", "extra": ["柠檬苏打", "黄瓜"], "scene": ["夏季", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gin-tonic', 'cocktail', 'COCKTAIL', '金汤力', 'Gin and Tonic', 'jintangli', 'jtl', '以伦敦干金酒与汤力水直调而成的经典长饮，杜松子草本气息与汤力水的微苦气泡感平衡，配青柠角提鲜，清爽易饮。', 'IBA 标准以伦敦干金酒 50 ml 配汤力水约 100 ml 直调，V6 采用此配比并加入青柠角提香；相比老式金汤力，汤力水用量更高、苦度更柔和。', 'https://upload.wikimedia.org/wikipedia/commons/d/d4/Gin_and_Tonic_with_ingredients.jpg', 'https://upload.wikimedia.org/wikipedia/commons/d/d4/Gin_and_Tonic_with_ingredients.jpg', 91, 64, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["金酒基底", "冷饮", "柑橘", "清爽", "气泡感", "经典", "日常"]', '["经典", "日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["汤力水"], "scene": ["经典", "日常"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 100, "unit": "ml", "role": "冷藏汤力水"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 15, "unit": "g", "role": "青柠角"}]', '["在高球杯中加入大冰块至八分满。", "倒入伦敦干金酒 50 ml。", "沿杯壁缓慢补入冷藏汤力水 100 ml。", "轻搅两次避免气泡消散。", "挤入青柠角后投入杯中装饰。"]', '["Gin and Tonic", "G&T", "金汤力水"]', 'A', '2026-08-04', 1, '{"id": "cocktail-gin-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金汤力", "nameEn": "Gin and Tonic", "intro": "以伦敦干金酒与汤力水直调而成的经典长饮，杜松子草本气息与汤力水的微苦气泡感平衡，配青柠角提鲜，清爽易饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d4/Gin_and_Tonic_with_ingredients.jpg", "tags": ["金酒基底", "冷饮", "柑橘", "清爽", "气泡感", "经典", "日常"], "scene": ["经典", "日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["汤力水"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vodka-tonic', 'cocktail', 'COCKTAIL', '伏特加汤力', 'Vodka Tonic', 'futejiatangli', 'ftjtl', '以伏特加与汤力水直调而成的清爽长饮，酒体轻盈、气泡感强，汤力水的微苦与青柠的酸香相得益彰，适合日常放松。', 'IBA 未收录标准配比，V6 采用伏特加 50 ml 配汤力水 100 ml 的编辑标准化；与金汤力相比基底酒风味中性，整体更接近纯粹的清爽气泡感。', 'https://upload.wikimedia.org/wikipedia/commons/4/49/Gilbert_Scott%2C_St_Pancras%2C_NW1_%286504547823%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/49/Gilbert_Scott%2C_St_Pancras%2C_NW1_%286504547823%29.jpg', 91, 65, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["伏特加基底", "冷饮", "柑橘", "清爽", "气泡感", "经典", "无麸质"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["汤力水"], "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "伏特加"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 100, "unit": "ml", "role": "冷藏汤力水"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 15, "unit": "g", "role": "青柠角"}]', '["在高球杯中加入冰块至八分满。", "倒入伏特加 50 ml。", "沿杯壁缓慢补入冷藏汤力水 100 ml。", "轻搅两次。", "以青柠角挤汁后投入杯中。"]', '["Vodka Tonic", "V&T", "伏特加汤力水"]', 'B', '2026-08-04', 1, '{"id": "cocktail-vodka-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "伏特加汤力", "nameEn": "Vodka Tonic", "intro": "以伏特加与汤力水直调而成的清爽长饮，酒体轻盈、气泡感强，汤力水的微苦与青柠的酸香相得益彰，适合日常放松。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/49/Gilbert_Scott%2C_St_Pancras%2C_NW1_%286504547823%29.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "清爽", "气泡感", "经典", "无麸质"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["汤力水"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rum-coke', 'cocktail', 'COCKTAIL', '朗姆可乐', 'Rum and Coke', 'langmukele', 'lmkl', '以白朗姆酒与可乐直调而成的甜型长饮，焦糖与可乐香气浓郁，配青柠角平衡甜度，制作简单，适合休闲聚会。', '此款与自由古巴同源，V6 取白朗姆酒 50 ml 配可乐 120 ml，青柠角用量少于自由古巴，可乐焦糖甜感更主导。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 91, 66, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "甜感明显", "气泡感", "经典", "日常", "新手友好"]', '["经典", "日常", "新手友好"]', '{"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "甜感明显", "abv": "中度＞10%～20%", "extra": ["可乐"], "scene": ["经典", "日常", "新手友好"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 50, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 120, "unit": "ml", "role": "冷藏可乐"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 15, "unit": "g", "role": "青柠角"}]', '["在高球杯中加入冰块至八分满。", "倒入白朗姆酒 50 ml。", "补入冷藏可乐 120 ml。", "轻搅一次。", "挤入青柠角后投入杯中装饰。"]', '["Rum and Coke", "朗姆与可乐", "朗姆可乐直调"]', 'A', '2026-08-04', 1, '{"id": "cocktail-rum-coke", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朗姆可乐", "nameEn": "Rum and Coke", "intro": "以白朗姆酒与可乐直调而成的甜型长饮，焦糖与可乐香气浓郁，配青柠角平衡甜度，制作简单，适合休闲聚会。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["朗姆基底", "冷饮", "甜感明显", "气泡感", "经典", "日常", "新手友好"], "scene": ["经典", "日常", "新手友好"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "甜感明显", "abv": "中度＞10%～20%", "extra": ["可乐"], "scene": ["经典", "日常", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-whiskey-soda', 'cocktail', 'COCKTAIL', '威士忌苏打', 'Whiskey Soda', 'weishijisuda', 'wsjsd', '以波本威士忌与苏打水直调而成的轻盈高球，保留威士忌的焦糖与谷物香气，同时降低酒感，气泡清爽，适合长饮。', 'V6 编辑标准化取波本威士忌 60 ml 配苏打水 120 ml；与苏格兰高球相比，波本的焦糖与香草气息更明显，烟熏感弱。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 67, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["威士忌基底", "冷饮", "轻盈", "清爽", "气泡感", "日常", "无麸质"]', '["日常"]', '{"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "风味均衡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["日常"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 120, "unit": "ml", "role": "冷藏苏打水"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 3, "unit": "g", "role": "柠檬皮装饰"}]', '["在高球杯中加入冰块至八分满。", "倒入波本威士忌 60 ml。", "补入冷藏苏打水 120 ml。", "轻搅一次。", "以柠檬皮扭拧出香后入杯装饰。"]', '["Whiskey Soda", "威士忌苏打水", "威士忌高球"]', 'B', '2026-08-04', 1, '{"id": "cocktail-whiskey-soda", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "威士忌苏打", "nameEn": "Whiskey Soda", "intro": "以波本威士忌与苏打水直调而成的轻盈高球，保留威士忌的焦糖与谷物香气，同时降低酒感，气泡清爽，适合长饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["威士忌基底", "冷饮", "轻盈", "清爽", "气泡感", "日常", "无麸质"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "风味均衡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-soda', 'cocktail', 'COCKTAIL', '龙舌兰苏打', 'Tequila Soda', 'longshelansuda', 'lslsd', '以百分百龙舌兰银龙舌兰酒与苏打水直调而成的清爽高球，龙舌兰的植物清香与青柠酸香突出，气泡感强，低糖配方。', 'V6 编辑标准化取百分百龙舌兰银龙舌兰酒 60 ml 配苏打水 120 ml，类似牧场水的结构；不加糖浆，甜感仅来自食材本身。', 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Tequila_Sunrise.jpg', 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Tequila_Sunrise.jpg', 91, 68, '[{"key": "SWEETNESS", "label": "甜度", "score": 2.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["龙舌兰基底", "冷饮", "柑橘", "清爽", "气泡感", "低糖", "无麸质"]', '["夏季", "经典", "开胃"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["夏季", "经典", "开胃"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 60, "unit": "ml", "role": "百分百龙舌兰银龙舌兰酒"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 120, "unit": "ml", "role": "冷藏苏打水"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 15, "unit": "g", "role": "青柠角"}]', '["在高球杯中加入冰块至八分满。", "倒入百分百龙舌兰银龙舌兰酒 60 ml。", "补入冷藏苏打水 120 ml。", "轻搅一次。", "挤入青柠角后投入杯中。"]', '["Tequila Soda", "龙舌兰苏打水", "牧场水"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tequila-soda", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰苏打", "nameEn": "Tequila Soda", "intro": "以百分百龙舌兰银龙舌兰酒与苏打水直调而成的清爽高球，龙舌兰的植物清香与青柠酸香突出，气泡感强，低糖配方。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b7/Tequila_Sunrise.jpg", "tags": ["龙舌兰基底", "冷饮", "柑橘", "清爽", "气泡感", "低糖", "无麸质"], "scene": ["夏季", "经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-scotch-highball', 'cocktail', 'COCKTAIL', '苏格兰高球', 'Scotch Highball', 'sugelangaoqiu', 'sglgq', '以调和苏格兰威士忌与苏打水直调而成的经典高球，麦芽与轻微烟熏气息配合气泡感，酒感轻盈，适合搭配餐食。', '源自日式酒吧的经典高球，V6 取调和苏格兰威士忌 45 ml 配苏打水 120 ml；相比威士忌苏打，麦芽与烟熏层次更明显。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 69, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["威士忌基底", "冷饮", "烟熏", "轻盈", "气泡感", "经典", "日常"]', '["经典", "日常"]', '{"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "烟熏", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["经典", "日常"]}', '[{"nameZh": "混合苏格兰威士忌", "nameEn": "Blended Scotch whisky", "amount": 45, "unit": "ml", "role": "调和苏格兰威士忌"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 120, "unit": "ml", "role": "冷藏苏打水"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 3, "unit": "g", "role": "柠檬皮装饰"}]', '["在高球杯中加入冰块至八分满。", "倒入调和苏格兰威士忌 45 ml。", "补入冷藏苏打水 120 ml。", "轻搅一次。", "以柠檬皮扭拧出香后入杯装饰。"]', '["Scotch Highball", "苏格兰威士忌高球", "Scotch and Soda"]', 'B', '2026-08-04', 1, '{"id": "cocktail-scotch-highball", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "苏格兰高球", "nameEn": "Scotch Highball", "intro": "以调和苏格兰威士忌与苏打水直调而成的经典高球，麦芽与轻微烟熏气息配合气泡感，酒感轻盈，适合搭配餐食。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["威士忌基底", "冷饮", "烟熏", "轻盈", "气泡感", "经典", "日常"], "scene": ["经典", "日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "烟熏", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-moscow-mule', 'cocktail', 'COCKTAIL', '莫斯科骡子', 'Moscow Mule', 'mosikeluozi', 'msklz', '以伏特加、姜汁啤酒与新鲜青柠汁调制而成的经典骡子鸡尾酒，姜味辛辣与青柠酸香平衡，气泡充足，传统以铜杯盛装。', 'IBA 标准以伏特加、姜汁啤酒与青柠汁调配，V6 采用此配比；相比姜汁威士忌，基底换成伏特加，姜味更干净、无威士忌木质调。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Moscow%20Mule.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Moscow%20Mule.jpg', 91, 70, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["伏特加基底", "冷饮", "姜味", "柑橘", "清爽", "气泡感", "经典"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "伏特加"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger beer", "amount": 120, "unit": "ml", "role": "冷藏姜汁啤酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 15, "unit": "g", "role": "青柠角装饰"}]', '["铜杯中加入冰块至八分满。", "倒入伏特加 45 ml 与新鲜青柠汁 10 ml。", "补入冷藏姜汁啤酒 120 ml。", "轻搅一次。", "挤入青柠角后投入杯中装饰。"]', '["Moscow Mule", "莫斯科骡", "铜杯骡子"]', 'A', '2026-08-04', 1, '{"id": "cocktail-moscow-mule", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "莫斯科骡子", "nameEn": "Moscow Mule", "intro": "以伏特加、姜汁啤酒与新鲜青柠汁调制而成的经典骡子鸡尾酒，姜味辛辣与青柠酸香平衡，气泡充足，传统以铜杯盛装。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Moscow%20Mule.jpg", "tags": ["伏特加基底", "冷饮", "姜味", "柑橘", "清爽", "气泡感", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-london-mule', 'cocktail', 'COCKTAIL', '伦敦骡子', 'London Mule', 'lundunluozi', 'ldlz', '以伦敦干金酒为基底、加入姜汁啤酒与青柠汁的骡子类鸡尾酒，姜辛与金酒草本香气交织，气泡清爽，是轻盈易饮的长饮。', 'V6 编辑标准化配方以伦敦干金酒、姜汁啤酒与新鲜青柠汁按 4:10:1 直调；金酒与姜汁啤酒品牌差异会影响草本与姜辛强度，雷达与酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/4/41/Horses%2C_asses%2C_zebras%2C_mules_and_mule_breeding_BHL22987508.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/41/Horses%2C_asses%2C_zebras%2C_mules_and_mule_breeding_BHL22987508.jpg', 91, 71, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "姜味", "柑橘", "气泡感", "直调", "清爽"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 40, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger beer", "amount": 100, "unit": "ml", "role": "冰镇姜汁啤酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯或铜杯中加入约 100 g 冰块。", "加入 40 ml 伦敦干金酒。", "挤入 10 ml 新鲜青柠汁。", "沿杯壁倒入冰镇姜汁啤酒至杯口。", "轻搅两下，以青柠轮装饰后饮用。"]', '["London Mule", "金酒骡子", "London Buck"]', 'B', '2026-08-04', 1, '{"id": "cocktail-london-mule", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "伦敦骡子", "nameEn": "London Mule", "intro": "以伦敦干金酒为基底、加入姜汁啤酒与青柠汁的骡子类鸡尾酒，姜辛与金酒草本香气交织，气泡清爽，是轻盈易饮的长饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/41/Horses%2C_asses%2C_zebras%2C_mules_and_mule_breeding_BHL22987508.jpg", "tags": ["金酒基底", "冷饮", "姜味", "柑橘", "气泡感", "直调", "清爽"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-kentucky-mule', 'cocktail', 'COCKTAIL', '肯塔基骡子', 'Kentucky Mule', 'kentajiluozi', 'ktjlz', '以波本威士忌为基底、加入姜汁啤酒与青柠汁的骡子类鸡尾酒，香草与橡木甜香和姜辛结合，酒体比伏特加版更厚实。', 'V6 编辑标准化配方以波本威士忌、姜汁啤酒与新鲜青柠汁直调；波本陈年时间与姜汁啤酒的姜辣度会影响整体风味强度，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/3/37/87j099_Person%2C_Ole_Mule%2C_LD707_%287592023734%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/3/37/87j099_Person%2C_Ole_Mule%2C_LD707_%287592023734%29.jpg', 91, 72, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["威士忌基底", "冷饮", "姜味", "柑橘", "气泡感", "直调", "中等酒体"]', '["经典", "开胃"]', '{"baseSpirit": "威士忌基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["经典", "开胃"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger beer", "amount": 100, "unit": "ml", "role": "冰镇姜汁啤酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入约 100 g 冰块。", "加入 45 ml 波本威士忌。", "挤入 10 ml 新鲜青柠汁。", "沿杯壁倒入冰镇姜汁啤酒至杯口。", "轻搅两下，以青柠轮装饰后饮用。"]', '["Kentucky Mule", "波本骡子", "波本姜汁"]', 'B', '2026-08-04', 1, '{"id": "cocktail-kentucky-mule", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "肯塔基骡子", "nameEn": "Kentucky Mule", "intro": "以波本威士忌为基底、加入姜汁啤酒与青柠汁的骡子类鸡尾酒，香草与橡木甜香和姜辛结合，酒体比伏特加版更厚实。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/37/87j099_Person%2C_Ole_Mule%2C_LD707_%287592023734%29.jpg", "tags": ["威士忌基底", "冷饮", "姜味", "柑橘", "气泡感", "直调", "中等酒体"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mexican-mule', 'cocktail', 'COCKTAIL', '墨西哥骡子', 'Mexican Mule', 'moxigeluozi', 'mxglz', '以龙舌兰为基底、加入姜汁啤酒与青柠汁的骡子类鸡尾酒，龙舌兰的植物与柑橘香与姜辛相衬，清新利落且带一丝微辣。', 'V6 编辑标准化配方以 100% 龙舌兰银龙舌兰、姜汁啤酒与新鲜青柠汁直调；龙舌兰原料品种与姜汁啤酒甜度会影响风味表现，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Moscow%20Mule.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Moscow%20Mule.jpg', 91, 73, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["龙舌兰基底", "冷饮", "姜味", "柑橘", "气泡感", "直调", "清爽"]', '["经典", "开胃"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["经典", "开胃"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 40, "unit": "ml", "role": "100% 龙舌兰银龙舌兰"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger beer", "amount": 100, "unit": "ml", "role": "冰镇姜汁啤酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入约 100 g 冰块。", "加入 40 ml 银龙舌兰。", "挤入 10 ml 新鲜青柠汁。", "沿杯壁倒入冰镇姜汁啤酒至杯口。", "轻搅两下，以青柠轮装饰后饮用。"]', '["Mexican Mule", "龙舌兰骡子", "Tequila Mule"]', 'B', '2026-08-04', 1, '{"id": "cocktail-mexican-mule", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "墨西哥骡子", "nameEn": "Mexican Mule", "intro": "以龙舌兰为基底、加入姜汁啤酒与青柠汁的骡子类鸡尾酒，龙舌兰的植物与柑橘香与姜辛相衬，清新利落且带一丝微辣。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Moscow%20Mule.jpg", "tags": ["龙舌兰基底", "冷饮", "姜味", "柑橘", "气泡感", "直调", "清爽"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bloody-bloody-mary', 'cocktail', 'COCKTAIL', '血腥血腥玛丽', 'Bloody Bloody Mary', 'xuexingxuexingmali', 'xxxxml', '在经典血腥玛丽基础上加倍伏特加与辣酱风味的咸鲜型鸡尾酒，番茄浓汤感与辛辣层次突出，适合作为早午餐与开胃饮品。', 'V6 编辑标准化配方在经典血腥玛丽基础上提高伏特加与辣酱比例，加入伍斯特酱、芹菜盐与黑胡椒；配比与酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 74, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["伏特加基底", "冷饮", "咸鲜", "辛辣", "直调", "中等强度", "早午餐"]', '["早午餐"]', '{"baseSpirit": "伏特加基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["早午餐"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "伏特加，建议 40% ABV"}, {"nameZh": "番茄汁", "nameEn": "Tomato juice", "amount": 120, "unit": "ml", "role": "冰镇番茄汁"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "伍斯特酱", "nameEn": "Worcestershire sauce", "amount": 5, "unit": "ml", "role": "伍斯特酱"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 3, "unit": "ml", "role": "辣酱"}, {"nameZh": "芹菜盐", "nameEn": "Celery salt", "amount": 1, "unit": "g", "role": "芹菜盐"}, {"nameZh": "黑胡椒", "nameEn": "Black pepper", "amount": 1, "unit": "g", "role": "现磨黑胡椒"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "杯中冰"}]', '["高球杯中加入约 100 g 冰块。", "杯中加入伏特加、番茄汁与柠檬汁。", "加入伍斯特酱、辣酱、芹菜盐与黑胡椒。", "以吧勺上下提拉搅拌至混合均匀。", "以柠檬轮装饰后立即饮用。"]', '["Bloody Bloody Mary", "双重血腥玛丽", "烈版血腥玛丽"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bloody-bloody-mary", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "血腥血腥玛丽", "nameEn": "Bloody Bloody Mary", "intro": "在经典血腥玛丽基础上加倍伏特加与辣酱风味的咸鲜型鸡尾酒，番茄浓汤感与辛辣层次突出，适合作为早午餐与开胃饮品。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "冷饮", "咸鲜", "辛辣", "直调", "中等强度", "早午餐"], "scene": ["早午餐"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "中度＞10%～20%", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cuba-libre-classic', 'cocktail', 'COCKTAIL', '古巴自由', 'Cuba Libre', 'gubaziyou', 'gbzy', '以白朗姆酒与可乐为基干、以新鲜青柠角提香的经典高球鸡尾酒，焦糖甜感与气泡明快，是上手度极高的日常长饮。', 'V6 编辑标准化配方遵循 IBA 官方框架：白朗姆、可乐配青柠角现挤提香；可乐品牌与青柠用量会影响甜度与酸感，酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 75, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "焦糖", "气泡感", "直调", "日常", "低强度", "无麸质"]', '["日常"]', '{"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "焦糖", "abv": "中度＞10%～20%", "extra": ["可乐", "新鲜青柠汁"], "scene": ["日常"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 50, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 125, "unit": "ml", "role": "冰镇可乐"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "青柠角现挤汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 8, "unit": "g", "role": "青柠角装饰"}]', '["高球杯中加入约 100 g 冰块。", "加入 50 ml 白朗姆酒。", "挤入约 10 ml 青柠汁。", "沿杯壁缓缓倒入冰镇可乐至杯口。", "轻搅两下，以青柠角装饰后饮用。"]', '["Cuba Libre", "古巴自由经典", "经典朗姆可乐"]', 'A', '2026-08-04', 1, '{"id": "cocktail-cuba-libre-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "古巴自由", "nameEn": "Cuba Libre", "intro": "以白朗姆酒与可乐为基干、以新鲜青柠角提香的经典高球鸡尾酒，焦糖甜感与气泡明快，是上手度极高的日常长饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["朗姆基底", "冷饮", "焦糖", "气泡感", "直调", "日常", "低强度", "无麸质"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "焦糖", "abv": "中度＞10%～20%", "extra": ["可乐", "新鲜青柠汁"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sea-breeze', 'cocktail', 'COCKTAIL', '海风', 'Sea Breeze', 'haifeng', 'hf', '以伏特加为基底、混合蔓越莓汁与葡萄柚汁的粉红长饮，酸甜多汁、带葡萄柚的微苦回甘，清爽度很高。', 'V6 编辑标准化配方采用伏特加、蔓越莓汁与新鲜葡萄柚汁的等量结构摇和；果汁品牌与含糖量会影响酸甜平衡，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/4/49/Gilbert_Scott%2C_St_Pancras%2C_NW1_%286504547823%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/49/Gilbert_Scott%2C_St_Pancras%2C_NW1_%286504547823%29.jpg', 93, 76, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["伏特加基底", "冷饮", "蔓越莓", "柑橘", "果香", "摇和", "粉红色外观", "中等强度"]', '["夏季", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蔓越莓、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "蔓越莓汁"], "scene": ["夏季", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "伏特加"}, {"nameZh": "蔓越莓汁", "nameEn": "Cranberry juice", "amount": 60, "unit": "ml", "role": "蔓越莓汁"}, {"nameZh": "新鲜葡萄柚汁", "nameEn": "Fresh grapefruit juice", "amount": 30, "unit": "ml", "role": "新鲜葡萄柚汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}, {"nameZh": "葡萄柚皮", "nameEn": "Grapefruit peel", "amount": 5, "unit": "g", "role": "葡萄柚皮装饰"}]', '["高球杯中加入约 100 g 冰块。", "摇壶中加入伏特加、蔓越莓汁与葡萄柚汁。", "加入冰块摇和 10 秒。", "滤入加冰的高球杯。", "以葡萄柚皮提香后投入杯中，即可饮用。"]', '["Sea Breeze", "海风鸡尾酒", "海洋微风"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sea-breeze", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "海风", "nameEn": "Sea Breeze", "intro": "以伏特加为基底、混合蔓越莓汁与葡萄柚汁的粉红长饮，酸甜多汁、带葡萄柚的微苦回甘，清爽度很高。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/49/Gilbert_Scott%2C_St_Pancras%2C_NW1_%286504547823%29.jpg", "tags": ["伏特加基底", "冷饮", "蔓越莓", "柑橘", "果香", "摇和", "粉红色外观", "中等强度"], "scene": ["夏季", "经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蔓越莓、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "蔓越莓汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bahama-mama', 'cocktail', 'COCKTAIL', '海滩狂欢', 'Bahama Mama', 'haitankuanghuan', 'htkh', '以金朗姆与黑朗姆为基底、叠加椰子与咖啡利口酒的提基鸡尾酒，菠萝与蔓越莓果香浓郁，甜润而有热带气息。', 'V6 编辑标准化配方以金朗姆、黑朗姆配椰子与咖啡利口酒，加入菠萝汁与蔓越莓汁摇和；因含咖啡利口酒故标注含微量咖啡因，酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 77, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["朗姆基底", "冷饮", "热带水果", "椰子", "菠萝", "摇和", "甜感明显", "夏季"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "热带水果、椰子", "abv": "中度＞10%～20%", "extra": ["菠萝汁", "蔓越莓汁"], "scene": ["夏季"]}', '[{"nameZh": "金朗姆酒", "nameEn": "Golden rum", "amount": 30, "unit": "ml", "role": "金朗姆酒"}, {"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 15, "unit": "ml", "role": "黑朗姆酒"}, {"nameZh": "椰子利口酒", "nameEn": "Coconut liqueur", "amount": 15, "unit": "ml", "role": "椰子利口酒"}, {"nameZh": "咖啡利口酒（通用）", "nameEn": "Coffee liqueur (generic)", "amount": 10, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 70, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "蔓越莓汁", "nameEn": "Cranberry juice", "amount": 25, "unit": "ml", "role": "蔓越莓汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和与杯中冰"}]', '["摇壶中加入金朗姆、黑朗姆、椰子利口酒与咖啡利口酒。", "加入菠萝汁、蔓越莓汁与约 80 g 冰块。", "摇和 12 秒至充分混合。", "滤入加冰的飓风杯或高脚杯。", "以菠萝块与酒渍樱桃装饰后饮用。"]', '["Bahama Mama", "巴哈马妈妈", "巴哈马风情"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bahama-mama", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "海滩狂欢", "nameEn": "Bahama Mama", "intro": "以金朗姆与黑朗姆为基底、叠加椰子与咖啡利口酒的提基鸡尾酒，菠萝与蔓越莓果香浓郁，甜润而有热带气息。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["朗姆基底", "冷饮", "热带水果", "椰子", "菠萝", "摇和", "甜感明显", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "热带水果、椰子", "abv": "中度＞10%～20%", "extra": ["菠萝汁", "蔓越莓汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sex-on-the-beach', 'cocktail', 'COCKTAIL', '性爱沙滩', 'Sex on the Beach', 'xingaishatan', 'xast', '以伏特加与蜜桃杜松子利口酒为基底、混合橙汁与蔓越莓汁的果味长饮，蜜桃香甜与莓果酸爽平衡，适合夏季畅饮。', 'V6 编辑标准化配方采用伏特加、蜜桃杜松子利口酒、橙汁与蔓越莓汁摇和；蜜桃利口酒与果汁的含糖量影响甜度，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 93, 78, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["伏特加基底", "冷饮", "蜜桃", "蔓越莓", "果香", "摇和", "粉红色外观", "低强度"]', '["夏季", "经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蜜桃、蔓越莓", "abv": "中度＞10%～20%", "extra": ["新鲜橙汁", "蔓越莓汁"], "scene": ["夏季", "经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "伏特加"}, {"nameZh": "蜜桃杜松子利口酒", "nameEn": "Peach schnapps", "amount": 20, "unit": "ml", "role": "蜜桃杜松子利口酒"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 60, "unit": "ml", "role": "新鲜橙汁"}, {"nameZh": "蔓越莓汁", "nameEn": "Cranberry juice", "amount": 60, "unit": "ml", "role": "蔓越莓汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 10, "unit": "g", "role": "橙片装饰"}]', '["高球杯中加入约 100 g 冰块。", "摇壶中加入伏特加、蜜桃杜松子利口酒、橙汁与蔓越莓汁。", "加入冰块摇和 10 秒。", "滤入加冰的高球杯。", "以橙片与酒渍樱桃装饰后饮用。"]', '["Sex on the Beach", "沙滩风情", "蜜桃蔓越莓长饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sex-on-the-beach", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "性爱沙滩", "nameEn": "Sex on the Beach", "intro": "以伏特加与蜜桃杜松子利口酒为基底、混合橙汁与蔓越莓汁的果味长饮，蜜桃香甜与莓果酸爽平衡，适合夏季畅饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["伏特加基底", "冷饮", "蜜桃", "蔓越莓", "果香", "摇和", "粉红色外观", "低强度"], "scene": ["夏季", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蜜桃、蔓越莓", "abv": "中度＞10%～20%", "extra": ["新鲜橙汁", "蔓越莓汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-paloma', 'cocktail', 'COCKTAIL', '龙舌兰帕洛玛', 'Paloma', 'longshelanpaluoma', 'lslplm', '以龙舌兰为基底、混合葡萄柚汁与气泡苏打的清爽长饮，葡萄柚的酸甜微苦与龙舌兰植物香相得益彰，可选盐边。', 'V6 编辑标准化配方采用银龙舌兰、新鲜葡萄柚汁、青柠汁与葡萄柚苏打直调；盐边为可选装饰，甜酸随苏打品牌浮动，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/7/79/PALOMA_GAS_WATER_HEATER_JSW32-PH-163EW.jpg', 'https://upload.wikimedia.org/wikipedia/commons/7/79/PALOMA_GAS_WATER_HEATER_JSW32-PH-163EW.jpg', 93, 79, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["龙舌兰基底", "冷饮", "柑橘", "果香", "气泡感", "直调", "清爽", "可选盐边"]', '["夏季", "经典", "开胃"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘、果香", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "新鲜青柠汁"], "scene": ["夏季", "经典", "开胃"]}', '[{"nameZh": "银龙舌兰酒", "nameEn": "Blanco tequila", "amount": 45, "unit": "ml", "role": "银龙舌兰酒"}, {"nameZh": "新鲜葡萄柚汁", "nameEn": "Fresh grapefruit juice", "amount": 30, "unit": "ml", "role": "新鲜葡萄柚汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "葡萄柚苏打", "nameEn": "Grapefruit soda", "amount": 65, "unit": "ml", "role": "葡萄柚苏打"}, {"nameZh": "盐边", "nameEn": "Salt rim", "amount": 3, "unit": "g", "role": "可选盐边"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯满冰"}]', '["可选：以葡萄柚汁润湿杯口并沾取盐边。", "高球杯中加入约 100 g 冰块。", "加入银龙舌兰、葡萄柚汁与青柠汁。", "沿杯壁倒入葡萄柚苏打并轻搅。", "以葡萄柚皮提香后投入杯中即可饮用。"]', '["Paloma", "帕洛玛", "龙舌兰葡萄柚苏打"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tequila-paloma", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰帕洛玛", "nameEn": "Paloma", "intro": "以龙舌兰为基底、混合葡萄柚汁与气泡苏打的清爽长饮，葡萄柚的酸甜微苦与龙舌兰植物香相得益彰，可选盐边。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/79/PALOMA_GAS_WATER_HEATER_JSW32-PH-163EW.jpg", "tags": ["龙舌兰基底", "冷饮", "柑橘", "果香", "气泡感", "直调", "清爽", "可选盐边"], "scene": ["夏季", "经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘、果香", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mai-tai', 'cocktail', 'COCKTAIL', '迈泰', 'Mai Tai', 'maitai', 'mt', '以白朗姆与牙买加朗姆为基底、配橙味库拉索与杏仁糖浆的提基经典，青柠酸爽与坚果甜香平衡，热带气息浓郁。', '配方遵循 IBA 官方框架：白朗姆与牙买加朗姆搭配橙味库拉索、青柠汁与杏仁糖浆摇和；朗姆陈年与库拉索品牌影响风味，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/7/72/Cocktail_Zombie_nach_Printz.JPG', 'https://upload.wikimedia.org/wikipedia/commons/7/72/Cocktail_Zombie_nach_Printz.JPG', 93, 80, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "坚果", "柑橘", "热带水果", "摇和", "甜感明显", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "坚果、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "杏仁糖浆"], "scene": ["经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 40, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "牙买加朗姆酒", "nameEn": "Jamaican rum", "amount": 20, "unit": "ml", "role": "牙买加朗姆酒"}, {"nameZh": "橙味库拉索利口酒", "nameEn": "Orange curaçao liqueur", "amount": 15, "unit": "ml", "role": "橙味库拉索利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "杏仁糖浆", "nameEn": "Almond syrup", "amount": 10, "unit": "ml", "role": "杏仁糖浆（orgeat）"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "摇和用冰"}]', '["预冷双老式杯。", "摇壶中加入白朗姆、牙买加朗姆与橙味库拉索。", "加入青柠汁、杏仁糖浆与约 80 g 冰块。", "摇和 12 秒后滤入加碎冰的双老式杯。", "以青柠角与薄荷叶装饰后饮用。"]', '["Mai Tai", "麦泰", "迈泰鸡尾酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mai-tai", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "迈泰", "nameEn": "Mai Tai", "intro": "以白朗姆与牙买加朗姆为基底、配橙味库拉索与杏仁糖浆的提基经典，青柠酸爽与坚果甜香平衡，热带气息浓郁。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/72/Cocktail_Zombie_nach_Printz.JPG", "tags": ["朗姆基底", "冷饮", "坚果", "柑橘", "热带水果", "摇和", "甜感明显", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "坚果、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "杏仁糖浆"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-zombie', 'cocktail', 'COCKTAIL', '僵尸', 'Zombie', 'jiangshi', 'js', '以白朗姆、金朗姆与黑朗姆多种朗姆叠配的高酒精度提基鸡尾酒，菠萝与青柠果香浓烈，甜苦香料并重，源于 1934 年好莱坞提基酒吧。', 'V6 标准参考唐纳比奇（Donn Beach）框架，以三种朗姆搭配青柠汁、菠萝汁与石榴糖浆，加入安格斯图拉苦精平衡；多朗姆比例影响酒体，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/7/72/Cocktail_Zombie_nach_Printz.JPG', 'https://upload.wikimedia.org/wikipedia/commons/7/72/Cocktail_Zombie_nach_Printz.JPG', 91, 81, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["朗姆基底", "冷饮", "热带水果", "果香", "高强度", "摇和", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "热带水果、果香", "abv": "高度＞30%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": ["经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 30, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "金朗姆酒", "nameEn": "Golden rum", "amount": 30, "unit": "ml", "role": "金朗姆酒"}, {"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 30, "unit": "ml", "role": "黑朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 30, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 10, "unit": "ml", "role": "石榴糖浆"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 120, "unit": "g", "role": "摇和与杯内用碎冰"}]', '["向摇壶中加入白朗姆、金朗姆与黑朗姆。", "加入青柠汁、菠萝汁、石榴糖浆与 1 滴安格斯图拉苦精。", "加入约 60 g 碎冰，摇和 12 秒至充分混合。", "将混合液滤入加满碎冰的高脚提基杯。", "补满碎冰，以薄荷叶与橙片装饰后饮用。"]', '["Zombie", "僵尸鸡尾酒", "僵尸提基"]', 'B', '2026-08-04', 1, '{"id": "cocktail-zombie", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "僵尸", "nameEn": "Zombie", "intro": "以白朗姆、金朗姆与黑朗姆多种朗姆叠配的高酒精度提基鸡尾酒，菠萝与青柠果香浓烈，甜苦香料并重，源于 1934 年好莱坞提基酒吧。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/72/Cocktail_Zombie_nach_Printz.JPG", "tags": ["朗姆基底", "冷饮", "热带水果", "果香", "高强度", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "热带水果、果香", "abv": "高度＞30%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pina-colada', 'cocktail', 'COCKTAIL', '皮纳科拉达', 'Piña Colada', 'pinakelada', 'pnkld', '以白朗姆、椰浆与菠萝汁搅打而成的热带鸡尾酒，奶油质感绵密、菠萝椰香浓郁，波多黎各的国民饮品，也是 IBA 官方经典。', '配方遵循 IBA 官方框架，以白朗姆、椰浆与菠萝汁三份等量搅打，冷冻版使用碎冰；椰浆品牌与熟度影响甜度，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/d/d1/Pina_Colada_at_Aruba.jpg', 'https://upload.wikimedia.org/wikipedia/commons/d/d1/Pina_Colada_at_Aruba.jpg', 91, 82, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "椰子", "菠萝", "奶油感", "搅打", "甜感明显"]', '["夏季", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "椰子、菠萝", "abv": "较高＞20%～30%", "extra": ["椰浆", "菠萝汁"], "scene": ["夏季", "经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "建议 40% ABV"}, {"nameZh": "椰浆", "nameEn": "Coconut cream", "amount": 45, "unit": "ml", "role": "椰浆"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 60, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 120, "unit": "g", "role": "搅打用碎冰"}]', '["向搅拌机中加入白朗姆、椰浆与菠萝汁。", "加入约 120 g 碎冰。", "高速搅打 20 秒至质地均匀顺滑。", "倒入预冷的飓风杯或高球杯。", "以菠萝角与樱桃装饰后饮用。"]', '["Piña Colada", "椰林飘香", "皮娜可乐达"]', 'A', '2026-08-04', 1, '{"id": "cocktail-pina-colada", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皮纳科拉达", "nameEn": "Piña Colada", "intro": "以白朗姆、椰浆与菠萝汁搅打而成的热带鸡尾酒，奶油质感绵密、菠萝椰香浓郁，波多黎各的国民饮品，也是 IBA 官方经典。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d1/Pina_Colada_at_Aruba.jpg", "tags": ["朗姆基底", "冷饮", "椰子", "菠萝", "奶油感", "搅打", "甜感明显"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "椰子、菠萝", "abv": "较高＞20%～30%", "extra": ["椰浆", "菠萝汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-blue-hawaii', 'cocktail', 'COCKTAIL', '蓝色夏威夷', 'Blue Hawaii', 'lansexiaweiyi', 'lsxwy', '以朗姆、蓝橙利口酒配菠萝汁与青柠汁制成的蓝色热带鸡尾酒，外观清澈湛蓝，菠萝甜香与橙味酒甜感平衡，清凉感明显。', 'V6 编辑标准化配方以白朗姆为基底，蓝橙利口酒提供标志性蓝色与橙香，菠萝汁提供热带甜感；菠萝汁比例可调，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/0/0a/202408101026_IMG_0911.jpg', 'https://upload.wikimedia.org/wikipedia/commons/0/0a/202408101026_IMG_0911.jpg', 89, 83, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "热带水果", "菠萝", "甜感明显", "摇和"]', '["夏季", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "热带水果、菠萝", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": ["夏季", "经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 30, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "蓝橙利口酒", "nameEn": "Blue curaçao", "amount": 20, "unit": "ml", "role": "蓝橙利口酒"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 60, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰"}]', '["预冷飓风杯。", "摇壶中加入白朗姆与蓝橙利口酒。", "加入菠萝汁、青柠汁与约 90 g 冰块。", "摇和 12 秒后滤入加冰的飓风杯。", "以菠萝角与樱桃装饰后饮用。"]', '["Blue Hawaii", "蓝夏威夷", "蓝色夏威夷鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-blue-hawaii", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蓝色夏威夷", "nameEn": "Blue Hawaii", "intro": "以朗姆、蓝橙利口酒配菠萝汁与青柠汁制成的蓝色热带鸡尾酒，外观清澈湛蓝，菠萝甜香与橙味酒甜感平衡，清凉感明显。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0a/202408101026_IMG_0911.jpg", "tags": ["朗姆基底", "冷饮", "热带水果", "菠萝", "甜感明显", "摇和"], "scene": ["夏季", "经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "热带水果、菠萝", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-hurricane', 'cocktail', 'COCKTAIL', '飓风', 'Hurricane', 'jufeng', 'jf', '以朗姆配百香果与青柠汁而成的经典新奥尔良提基鸡尾酒，果香馥郁、酸甜平衡，因 1960 年代新奥尔良酒吧而声名远播。', 'V6 标准以两种朗姆搭配百香果糖浆、青柠汁与橙汁摇和；百香果风味来自糖浆浓缩物，用量可按甜酸偏好微调，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/2/20/Hurricane_at_Two_Friends_Bar_in_Key_West%2C_Florida.jpg', 'https://upload.wikimedia.org/wikipedia/commons/2/20/Hurricane_at_Two_Friends_Bar_in_Key_West%2C_Florida.jpg', 91, 84, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "百香果", "热带水果", "酸甜", "摇和", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "百香果、热带水果", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "百香果汁"], "scene": ["经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 30, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 30, "unit": "ml", "role": "黑朗姆酒"}, {"nameZh": "百香果汁", "nameEn": "Passion fruit juice", "amount": 60, "unit": "ml", "role": "百香果汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 30, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰"}]', '["预冷飓风杯。", "摇壶中加入白朗姆与黑朗姆。", "加入百香果汁、青柠汁、单糖浆与约 90 g 冰块。", "摇和 12 秒后连同碎冰倒入飓风杯。", "以橙片与樱桃装饰后饮用。"]', '["Hurricane", "飓风鸡尾酒", "新奥尔良飓风"]', 'A', '2026-08-04', 1, '{"id": "cocktail-hurricane", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "飓风", "nameEn": "Hurricane", "intro": "以朗姆配百香果与青柠汁而成的经典新奥尔良提基鸡尾酒，果香馥郁、酸甜平衡，因 1960 年代新奥尔良酒吧而声名远播。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/20/Hurricane_at_Two_Friends_Bar_in_Key_West%2C_Florida.jpg", "tags": ["朗姆基底", "冷饮", "百香果", "热带水果", "酸甜", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "百香果、热带水果", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "百香果汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-jungle-bird', 'cocktail', 'COCKTAIL', '丛林鸟', 'Jungle Bird', 'conglinniao', 'cln', '以黑朗姆、金巴利配菠萝汁与青柠汁的提基鸡尾酒，苦甜果香对比鲜明，浓烈的苦味与菠萝甜感在杯中碰撞出层次。', 'V6 标准以黑朗姆、金巴利、菠萝汁与青柠汁按 4:1.5:3:1 摇和；金巴利提供标志性苦橙气息，黑朗姆带来深色焦糖底味，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/1/17/Jungle_Bird%2C_Benares_Cucina_Indian%2C_Toronto%2C_Ontario%2C_2025-08-25_01.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/17/Jungle_Bird%2C_Benares_Cucina_Indian%2C_Toronto%2C_Ontario%2C_2025-08-25_01.jpg', 91, 85, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["朗姆基底", "冷饮", "苦感主导", "菠萝", "草本", "摇和", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "苦感主导、菠萝", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": ["经典"]}', '[{"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 40, "unit": "ml", "role": "黑朗姆酒"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 15, "unit": "ml", "role": "金巴利"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 30, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 10, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰"}]', '["预冷老式杯。", "摇壶中加入黑朗姆与金巴利。", "加入菠萝汁、青柠汁与约 90 g 冰块。", "摇和 12 秒后滤入加冰的老式杯。", "以菠萝角装饰后饮用。"]', '["Jungle Bird", "丛林鸟鸡尾酒", "雨林鸟"]', 'A', '2026-08-04', 1, '{"id": "cocktail-jungle-bird", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "丛林鸟", "nameEn": "Jungle Bird", "intro": "以黑朗姆、金巴利配菠萝汁与青柠汁的提基鸡尾酒，苦甜果香对比鲜明，浓烈的苦味与菠萝甜感在杯中碰撞出层次。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/17/Jungle_Bird%2C_Benares_Cucina_Indian%2C_Toronto%2C_Ontario%2C_2025-08-25_01.jpg", "tags": ["朗姆基底", "冷饮", "苦感主导", "菠萝", "草本", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "苦感主导、菠萝", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-saturn', 'cocktail', 'COCKTAIL', '萨图雅娜', 'Saturn', 'satuyana', 'styn', '以金酒为基底、配百香果汁与杏仁糖浆的提基风格鸡尾酒，果香与坚果甜香平衡，薄荷叶点缀带来清凉感，是金酒的热带演绎。', 'V6 标准参考当代提基版本，以伦敦干金酒搭配百香果汁、杏仁糖浆、柠檬汁与方糖摇和，薄荷叶提供点缀香；比例可按甜酸偏好调整，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/7/7e/Retrato_ilustrado_de_Yacun%C3%A3_Tux%C3%A1%2C_por_Julia_Gon%C3%A7alves.png', 'https://upload.wikimedia.org/wikipedia/commons/7/7e/Retrato_ilustrado_de_Yacun%C3%A3_Tux%C3%A1%2C_por_Julia_Gon%C3%A7alves.png', 91, 86, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["金酒基底", "冷饮", "百香果", "坚果", "热带水果", "酸甜", "摇和"]', '["夏季", "经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "百香果、坚果", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "杏仁糖浆"], "scene": ["夏季", "经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "百香果汁", "nameEn": "Passion fruit juice", "amount": 20, "unit": "ml", "role": "百香果汁"}, {"nameZh": "杏仁糖浆", "nameEn": "Almond syrup", "amount": 15, "unit": "ml", "role": "杏仁糖浆（orgeat）"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 5, "unit": "g", "role": "细砂糖"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 6, "unit": "piece", "role": "装饰用薄荷叶"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰"}]', '["预冷蝶形杯或老式杯。", "摇壶中加入金酒、百香果汁、杏仁糖浆与柠檬汁。", "加入细砂糖与约 90 g 冰块。", "摇和 12 秒后滤入预冷的杯子。", "以薄荷叶装饰后饮用。"]', '["Saturn", "萨图恩", "土星鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-saturn", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "萨图雅娜", "nameEn": "Saturn", "intro": "以金酒为基底、配百香果汁与杏仁糖浆的提基风格鸡尾酒，果香与坚果甜香平衡，薄荷叶点缀带来清凉感，是金酒的热带演绎。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7e/Retrato_ilustrado_de_Yacun%C3%A3_Tux%C3%A1%2C_por_Julia_Gon%C3%A7alves.png", "tags": ["金酒基底", "冷饮", "百香果", "坚果", "热带水果", "酸甜", "摇和"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "百香果、坚果", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "杏仁糖浆"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cuba-libre-bravo', 'cocktail', 'COCKTAIL', '库巴利布雷', 'Cuba Libre Bravo', 'kubalibulei', 'kblbl', '在自由古巴基础上叠加黑朗姆与香草糖浆的加强版高球鸡尾酒，可乐甜感与朗姆焦糖香更浓郁，青柠点睛，清爽易饮。', 'V6 编辑标准化配方在白朗姆加可乐的经典结构上，以黑朗姆提升焦糖层次、香草糖浆补足甜感；冰块与可乐气泡共同塑造爽口感，ABV 为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 87, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["朗姆基底", "冷饮", "甜感明显", "焦糖", "香草", "直调", "清爽"]', '["夏季", "经典", "餐后"]', '{"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "甜感明显、焦糖", "abv": "中度＞10%～20%", "extra": ["可乐", "新鲜青柠汁"], "scene": ["夏季", "经典", "餐后"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 30, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 20, "unit": "ml", "role": "黑朗姆酒"}, {"nameZh": "香草糖浆", "nameEn": "Vanilla syrup", "amount": 10, "unit": "ml", "role": "香草糖浆"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 125, "unit": "ml", "role": "可乐"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "满杯冰块"}]', '["向高球杯中加入白朗姆与黑朗姆。", "加入香草糖浆与青柠汁。", "填满冰块并轻轻搅拌混合。", "缓慢倒入可乐至杯满。", "以青柠角装饰后立即饮用。"]', '["Cuba Libre Bravo", "库巴利布雷特调", "勇士自由古巴"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cuba-libre-bravo", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "库巴利布雷", "nameEn": "Cuba Libre Bravo", "intro": "在自由古巴基础上叠加黑朗姆与香草糖浆的加强版高球鸡尾酒，可乐甜感与朗姆焦糖香更浓郁，青柠点睛，清爽易饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["朗姆基底", "冷饮", "甜感明显", "焦糖", "香草", "直调", "清爽"], "scene": ["夏季", "经典", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "甜感明显、焦糖", "abv": "中度＞10%～20%", "extra": ["可乐", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-flamethrower', 'cocktail', 'COCKTAIL', '喷火器', 'Flamethrower', 'penhuoqi', 'phq', '以香料朗姆配姜汁啤酒、酸橙与蜂蜜而成的辣感高球鸡尾酒，姜的辛香与朗姆的香料感叠合，气泡充足、体感热烈。', 'V6 编辑标准化配方以香料朗姆为基底，姜汁啤酒提供气泡与姜辣，蜂蜜补甜、青柠平衡酸度；辣度来自姜汁而非辣椒，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/7/7c/4th_Canadian_Armoured_Division_flamethrower_demonstration_across_canal_Balgerhoeke_Belgium_October_1944.jpg', 'https://upload.wikimedia.org/wikipedia/commons/7/7c/4th_Canadian_Armoured_Division_flamethrower_demonstration_across_canal_Balgerhoeke_Belgium_October_1944.jpg', 91, 88, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "辛辣", "姜味", "香料", "直调", "气泡感"]', '["夏季", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "辛辣、姜味", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["夏季", "经典"]}', '[{"nameZh": "香料朗姆酒", "nameEn": "Spiced rum", "amount": 45, "unit": "ml", "role": "香料朗姆酒"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger beer", "amount": 130, "unit": "ml", "role": "姜汁啤酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "ml", "role": "蜂蜜"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "满杯冰块"}]', '["向高球杯中加入蜂蜜与青柠汁。", "加入香料朗姆并搅拌至蜂蜜溶解。", "填满冰块。", "缓慢倒入姜汁啤酒并轻搅。", "以青柠角装饰后饮用。"]', '["Flamethrower", "火焰喷射器", "喷火鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-flamethrower", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "喷火器", "nameEn": "Flamethrower", "intro": "以香料朗姆配姜汁啤酒、酸橙与蜂蜜而成的辣感高球鸡尾酒，姜的辛香与朗姆的香料感叠合，气泡充足、体感热烈。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7c/4th_Canadian_Armoured_Division_flamethrower_demonstration_across_canal_Balgerhoeke_Belgium_October_1944.jpg", "tags": ["朗姆基底", "冷饮", "辛辣", "姜味", "香料", "直调", "气泡感"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "辛辣、姜味", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-suffering-bastard', 'cocktail', 'COCKTAIL', '眩晕', 'Suffering Bastard', 'xuanyun', 'xy', '以金酒与白兰地双烈酒为基底、配姜汁啤酒与青柠的高球式提基饮品，辛香果味交织，苦甜平衡，源于二战时期的开罗酒吧。', 'V6 标准以伦敦干金酒与白兰地对半调配，加青柠汁后以姜汁啤酒补足气泡；姜汁啤酒品牌决定辣度强度，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Suffering%20Bastard%20Cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Suffering%20Bastard%20Cocktail.jpg', 91, 89, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "辛辣", "姜味", "草本", "直调", "果香"]', '["夏季", "经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "辛辣、姜味", "abv": "较高＞20%～30%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["夏季", "经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "白兰地", "nameEn": "Brandy", "amount": 30, "unit": "ml", "role": "白兰地"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger beer", "amount": 100, "unit": "ml", "role": "姜汁啤酒"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 6, "unit": "piece", "role": "装饰用薄荷叶"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "满杯冰块"}]', '["向高球杯中加入金酒与白兰地。", "加入青柠汁并轻搅混合。", "填满冰块。", "缓慢倒入姜汁啤酒补足。", "以薄荷叶与青柠角装饰后饮用。"]', '["Suffering Bastard", "受苦混蛋", "受难者"]', 'B', '2026-08-04', 1, '{"id": "cocktail-suffering-bastard", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "眩晕", "nameEn": "Suffering Bastard", "intro": "以金酒与白兰地双烈酒为基底、配姜汁啤酒与青柠的高球式提基饮品，辛香果味交织，苦甜平衡，源于二战时期的开罗酒吧。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Suffering%20Bastard%20Cocktail.jpg", "tags": ["金酒基底", "冷饮", "辛辣", "姜味", "草本", "直调", "果香"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "辛辣、姜味", "abv": "较高＞20%～30%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tiki-cold-brew', 'cocktail', 'COCKTAIL', '提基冷萃', 'Tiki Cold Brew', 'tijilengcui', 'tjlc', '以冷萃浓缩液与香料朗姆为基底、配菠萝汁与椰浆的咖啡提基鸡尾酒，咖啡苦香与热带果甜融合，清凉顺滑。', 'V6 编辑标准化配方以冷萃浓缩液提供咖啡风味与咖啡因，香料朗姆带来辛香，菠萝与椰浆构成热带甜感；冷萃浓度影响咖啡苦度，ABV 为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/a/ae/Psychedelic_Haight_Street_Mural%3B_Joplin%2C_Hendrix%2C_Garcia.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/ae/Psychedelic_Haight_Street_Mural%3B_Joplin%2C_Hendrix%2C_Garcia.jpg', 91, 90, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["朗姆基底", "冷饮", "咖啡风味", "热带水果", "椰子", "含咖啡因", "摇和"]', '["夏季", "经典", "餐后"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "咖啡风味、热带水果", "abv": "中度＞10%～20%", "extra": ["冷萃浓缩液", "椰奶"], "scene": ["夏季", "经典", "餐后"]}', '[{"nameZh": "冷萃浓缩液", "nameEn": "Cold brew concentrate", "amount": 40, "unit": "ml", "role": "冷萃浓缩液"}, {"nameZh": "香料朗姆酒", "nameEn": "Spiced rum", "amount": 30, "unit": "ml", "role": "香料朗姆酒"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 50, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "椰奶", "nameEn": "Coconut milk", "amount": 20, "unit": "ml", "role": "椰奶"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇和用冰"}]', '["预冷老式杯。", "摇壶中加入冷萃浓缩液与香料朗姆。", "加入菠萝汁、椰奶、单糖浆与约 90 g 冰块。", "摇和 12 秒后滤入加冰的老式杯。", "以橙皮或菠萝角装饰后饮用。"]', '["Tiki Cold Brew", "提基冷萃咖啡", "热带冷萃"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tiki-cold-brew", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "提基冷萃", "nameEn": "Tiki Cold Brew", "intro": "以冷萃浓缩液与香料朗姆为基底、配菠萝汁与椰浆的咖啡提基鸡尾酒，咖啡苦香与热带果甜融合，清凉顺滑。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/ae/Psychedelic_Haight_Street_Mural%3B_Joplin%2C_Hendrix%2C_Garcia.jpg", "tags": ["朗姆基底", "冷饮", "咖啡风味", "热带水果", "椰子", "含咖啡因", "摇和"], "scene": ["夏季", "经典", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "咖啡风味、热带水果", "abv": "中度＞10%～20%", "extra": ["冷萃浓缩液", "椰奶"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-frozen-daiquiri', 'cocktail', 'COCKTAIL', '冰沙代基里', 'Frozen Daiquiri', 'bingshadaijili', 'bsdjl', '以白朗姆酒与新鲜青柠汁加糖和碎冰搅打成冰沙状的代基里变体，青柠酸爽与朗姆香甜交织，口感绵密，是热带风情的冰饮。', 'V6 编辑标准化配方在经典代基里基础上加入碎冰一同搅打，使其呈冰沙质地；冰块比例决定稠度，酒精度与甜度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/f/fd/Classic_Daiquiri_in_Cocktail_Glass.jpg', 'https://upload.wikimedia.org/wikipedia/commons/f/fd/Classic_Daiquiri_in_Cocktail_Glass.jpg', 91, 91, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "柑橘", "酸甜", "搅打", "夏季", "经典"]', '["夏季", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁"], "scene": ["夏季", "经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 170, "unit": "g", "role": "搅打用碎冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["准备一台可用的搅拌机。", "加入 45 ml 白朗姆酒、25 ml 新鲜青柠汁与 20 ml 单糖浆。", "加入约 170 g 碎冰，搅打至绵密冰沙状。", "倒入预冷的飓风杯或鸡尾酒杯。", "以青柠轮装饰后立即饮用。"]', '["冷冻代基里", "Frozen Daiquiri", "代基里冰沙"]', 'B', '2026-08-04', 1, '{"id": "cocktail-frozen-daiquiri", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冰沙代基里", "nameEn": "Frozen Daiquiri", "intro": "以白朗姆酒与新鲜青柠汁加糖和碎冰搅打成冰沙状的代基里变体，青柠酸爽与朗姆香甜交织，口感绵密，是热带风情的冰饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fd/Classic_Daiquiri_in_Cocktail_Glass.jpg", "tags": ["朗姆基底", "冷饮", "柑橘", "酸甜", "搅打", "夏季", "经典"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁"], "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-frozen-margarita', 'cocktail', 'COCKTAIL', '冰沙玛格丽特', 'Frozen Margarita', 'bingshamagelite', 'bsmglt', '以龙舌兰酒、橙味利口酒与青柠汁加碎冰搅打成冰沙状的玛格丽特变体，青柠酸爽与龙舌兰气息清爽，可选盐边，是经典冰冻鸡尾酒。', 'V6 编辑标准化配方在经典玛格丽特配比上加入碎冰搅打至绵密冰沙状；盐边可按偏好选择，酒精度与酸甜平衡为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/8/89/Caf%C3%A9_Bar_Revoluci%C3%B3n_3.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/89/Caf%C3%A9_Bar_Revoluci%C3%B3n_3.jpg', 91, 92, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["龙舌兰基底", "冷饮", "柑橘", "酸甜", "搅打", "可选盐边", "夏季"]', '["夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "冰沙", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁"], "scene": ["夏季"]}', '[{"nameZh": "银龙舌兰酒", "nameEn": "Blanco tequila", "amount": 50, "unit": "ml", "role": "银龙舌兰酒"}, {"nameZh": "橙味利口酒", "nameEn": "Triple sec", "amount": 25, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 30, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 165, "unit": "g", "role": "搅打用碎冰"}, {"nameZh": "盐边", "nameEn": "Salt rim", "amount": 2, "unit": "g", "role": "杯口盐边（可选）"}]', '["杯口先用青柠汁润湿并蘸盐边备用。", "搅拌机中加入 50 ml 银龙舌兰酒、25 ml 橙味利口酒。", "加入 30 ml 青柠汁、10 ml 单糖浆与约 165 g 碎冰。", "搅打至均匀的冰沙状。", "倒入预冷的玛格丽特杯，以青柠轮装饰后饮用。"]', '["冷冻玛格丽特", "Frozen Margarita", "玛格丽特冰沙"]', 'A', '2026-08-04', 1, '{"id": "cocktail-frozen-margarita", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冰沙玛格丽特", "nameEn": "Frozen Margarita", "intro": "以龙舌兰酒、橙味利口酒与青柠汁加碎冰搅打成冰沙状的玛格丽特变体，青柠酸爽与龙舌兰气息清爽，可选盐边，是经典冰冻鸡尾酒。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/89/Caf%C3%A9_Bar_Revoluci%C3%B3n_3.jpg", "tags": ["龙舌兰基底", "冷饮", "柑橘", "酸甜", "搅打", "可选盐边", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "冰沙", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-frozen-pina-colada', 'cocktail', 'COCKTAIL', '冰沙皮纳科拉达', 'Frozen Piña Colada', 'bingshapinakelada', 'bspnkld', '以白朗姆酒、椰浆与菠萝汁加碎冰搅打成冰沙状的经典热带鸡尾酒，椰香浓郁、菠萝果甜与朗姆甘蔗甜感交织，是标志性的海岛冰饮。', 'V6 编辑标准化配方以白朗姆、椰浆与菠萝汁按 1:1:1 比例加入碎冰搅打；椰浆品牌与菠萝汁甜度影响口感，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 93, 93, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "椰子", "菠萝", "热带水果", "搅打", "浓郁甜", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "椰子、菠萝", "abv": "中度＞10%～20%", "extra": ["椰浆", "菠萝汁"], "scene": ["经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "椰浆", "nameEn": "Coconut cream", "amount": 45, "unit": "ml", "role": "椰浆"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 45, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 165, "unit": "g", "role": "搅打用碎冰"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 30, "unit": "ml", "role": "装饰用菠萝块"}]', '["搅拌机中加入 45 ml 白朗姆酒。", "加入 45 ml 椰浆与 45 ml 菠萝汁。", "加入约 165 g 碎冰，搅打至细腻冰沙状。", "倒入预冷的飓风杯。", "以菠萝块与樱桃装饰后饮用。"]', '["冷冻皮纳科拉达", "Frozen Piña Colada", "椰林飘香冰沙"]', 'A', '2026-08-04', 1, '{"id": "cocktail-frozen-pina-colada", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冰沙皮纳科拉达", "nameEn": "Frozen Piña Colada", "intro": "以白朗姆酒、椰浆与菠萝汁加碎冰搅打成冰沙状的经典热带鸡尾酒，椰香浓郁、菠萝果甜与朗姆甘蔗甜感交织，是标志性的海岛冰饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["朗姆基底", "冷饮", "椰子", "菠萝", "热带水果", "搅打", "浓郁甜", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "椰子、菠萝", "abv": "中度＞10%～20%", "extra": ["椰浆", "菠萝汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-frozen-mai-tai', 'cocktail', 'COCKTAIL', '冰沙迈泰', 'Frozen Mai Tai', 'bingshamaitai', 'bsmt', '以白朗姆与牙买加朗姆为基底、配橙味利口酒与杏仁糖浆加碎冰搅打成冰沙状的迈泰变体，青柠酸香与坚果甜润交织，热带气息浓郁。', 'V6 编辑标准化配方在经典迈泰配比基础上加入碎冰一同搅打；朗姆陈年与杏仁糖浆品牌影响风味，酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 94, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "坚果", "柑橘", "热带水果", "搅打", "甜感明显", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "坚果、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "杏仁糖浆"], "scene": ["经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 40, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "牙买加朗姆酒", "nameEn": "Jamaican rum", "amount": 20, "unit": "ml", "role": "牙买加朗姆酒"}, {"nameZh": "橙味库拉索", "nameEn": "Orange curaçao", "amount": 15, "unit": "ml", "role": "橙味库拉索利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "杏仁糖浆", "nameEn": "Almond syrup", "amount": 15, "unit": "ml", "role": "杏仁糖浆（orgeat）"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 175, "unit": "g", "role": "搅打用碎冰"}]', '["搅拌机中加入 40 ml 白朗姆酒与 20 ml 牙买加朗姆酒。", "加入 15 ml 橙味库拉索与 25 ml 青柠汁。", "加入 15 ml 杏仁糖浆与约 175 g 碎冰。", "搅打至绵密冰沙状。", "倒入预冷的老式杯，以薄荷叶与青柠角装饰后饮用。"]', '["冷冻迈泰", "Frozen Mai Tai", "迈泰冰沙"]', 'A', '2026-08-04', 1, '{"id": "cocktail-frozen-mai-tai", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冰沙迈泰", "nameEn": "Frozen Mai Tai", "intro": "以白朗姆与牙买加朗姆为基底、配橙味利口酒与杏仁糖浆加碎冰搅打成冰沙状的迈泰变体，青柠酸香与坚果甜润交织，热带气息浓郁。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["朗姆基底", "冷饮", "坚果", "柑橘", "热带水果", "搅打", "甜感明显", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "坚果、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "杏仁糖浆"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-frozen-watermelon-daiquiri', 'cocktail', 'COCKTAIL', '冰沙西瓜代基里', 'Frozen Watermelon Daiquiri', 'bingshaxiguadaijili', 'bsxgdjl', '以白朗姆酒为基底、配西瓜风味糖浆与青柠汁加碎冰搅打成冰沙状的代基里变体，西瓜清甜与青柠酸爽交融，是果味清新的夏日冰饮。', 'V6 编辑标准化配方在经典代基里配比中以西瓜风味糖浆带入西瓜清甜，再以碎冰一同搅打；糖浆用量与青柠酸度决定甜酸平衡，酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 89, 95, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["朗姆基底", "冷饮", "果香", "酸甜", "搅打", "夏季"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "果香、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "草莓糖浆"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "草莓糖浆", "nameEn": "Strawberry syrup", "amount": 20, "unit": "ml", "role": "西瓜风味糖浆"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 205, "unit": "g", "role": "搅打用碎冰"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 6, "unit": "g", "role": "柠檬片装饰"}]', '["搅拌机中加入 45 ml 白朗姆酒。", "加入 20 ml 西瓜风味糖浆与 20 ml 新鲜青柠汁。", "加入 10 ml 单糖浆与约 205 g 碎冰。", "搅打至均匀绵密的冰沙状。", "倒入预冷的飓风杯，以一片柠檬装饰后立即饮用。"]', '["冷冻西瓜代基里", "西瓜代基里冰沙", "Frozen Watermelon Daiquiri"]', 'B', '2026-08-04', 1, '{"id": "cocktail-frozen-watermelon-daiquiri", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冰沙西瓜代基里", "nameEn": "Frozen Watermelon Daiquiri", "intro": "以白朗姆酒为基底、配西瓜风味糖浆与青柠汁加碎冰搅打成冰沙状的代基里变体，西瓜清甜与青柠酸爽交融，是果味清新的夏日冰饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["朗姆基底", "冷饮", "果香", "酸甜", "搅打", "夏季"], "scene": ["夏季"], "recommendationScore": 89, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "冰沙", "flavor": "果香、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "草莓糖浆"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bellini', 'cocktail', 'COCKTAIL', '贝利尼', 'Bellini', 'beilini', 'bln', '以普罗塞克与白桃风味利口酒调和而成的意大利开胃起泡鸡尾酒，蜜桃果香细腻清甜，气泡轻盈，是经典早午餐与开胃场合饮品。', 'IBA 官方配比为 3 份普罗塞克兑 1 份白桃果泥；V6 编辑标准化以白桃利口酒代替鲜果泥，按 3:1 比例直调，果味利口酒的甜度与品牌差异影响口感。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 91, 96, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["起泡酒基底", "冷饮", "蜜桃", "果香", "气泡感", "早午餐", "开胃"]', '["早午餐", "开胃"]', '{"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "蜜桃、果香", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["早午餐", "开胃"]}', '[{"nameZh": "普罗塞克", "nameEn": "Prosecco", "amount": 120, "unit": "ml", "role": "冰镇普罗塞克"}, {"nameZh": "蜜桃利口酒", "nameEn": "Peach liqueur", "amount": 40, "unit": "ml", "role": "白桃利口酒（IBA 以鲜白桃果泥调制）"}]', '["预冷香槟杯或郁金香杯。", "向杯中倒入 40 ml 白桃利口酒。", "沿杯壁缓缓倒入冰镇的 120 ml 普罗塞克。", "用吧勺轻轻搅动一次使桃味与酒液融合。", "立即饮用，保持气泡与分层美感。"]', '["贝里尼", "Bellini", "桃子贝利尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-bellini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "贝利尼", "nameEn": "Bellini", "intro": "以普罗塞克与白桃风味利口酒调和而成的意大利开胃起泡鸡尾酒，蜜桃果香细腻清甜，气泡轻盈，是经典早午餐与开胃场合饮品。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["起泡酒基底", "冷饮", "蜜桃", "果香", "气泡感", "早午餐", "开胃"], "scene": ["早午餐", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "蜜桃、果香", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["早午餐", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mimosa', 'cocktail', 'COCKTAIL', '含羞草', 'Mimosa', 'hanxiucao', 'hxc', '以香槟或起泡酒与橙汁等比例调和而成的开胃气泡鸡尾酒，柑橘香气明亮、气泡轻盈干爽，是经典早午餐与庆祝场合饮品。', 'IBA 官方配比为香槟与鲜榨橙汁各半；V6 编辑标准化以香槟与鲜榨橙汁按 1:1 直调，起泡酒与橙汁比例可按杯型调整。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 91, 97, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 2.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["起泡酒基底", "冷饮", "柑橘", "果香", "气泡感", "早午餐", "开胃"]', '["早午餐", "开胃"]', '{"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜橙汁"], "scene": ["早午餐", "开胃"]}', '[{"nameZh": "香槟", "nameEn": "Champagne", "amount": 80, "unit": "ml", "role": "冰镇香槟或起泡酒"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 80, "unit": "ml", "role": "鲜榨橙汁"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 10, "unit": "g", "role": "橙片装饰"}]', '["预冷香槟杯或笛型杯。", "先倒入 80 ml 冰镇香槟或起泡酒。", "再缓缓加入 80 ml 鲜榨橙汁。", "用吧勺轻搅一下使两层融合。", "以橙片装饰后立即饮用。"]', '["美美酒", "Mimosa", "香槟橙汁"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mimosa", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "含羞草", "nameEn": "Mimosa", "intro": "以香槟或起泡酒与橙汁等比例调和而成的开胃气泡鸡尾酒，柑橘香气明亮、气泡轻盈干爽，是经典早午餐与庆祝场合饮品。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["起泡酒基底", "冷饮", "柑橘", "果香", "气泡感", "早午餐", "开胃"], "scene": ["早午餐", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜橙汁"], "scene": ["早午餐", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-kir-royale', 'cocktail', 'COCKTAIL', '皇家基尔', 'Kir Royale', 'huangjiajier', 'hjje', '以香槟或起泡酒与黑加仑利口酒调制而成的开胃气泡鸡尾酒，莓果香酸甜、气泡轻盈，呈现淡紫红色，是优雅的法式餐前酒。', 'IBA 官方配比为 1 份黑加仑利口酒兑 9 份香槟；V6 编辑标准化以冰镇香槟按 1:9 比例直调，利口酒用量决定甜度与色泽。', 'https://upload.wikimedia.org/wikipedia/commons/1/13/Christmas_aperitif_Kir_Royale_%2831246794594%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/13/Christmas_aperitif_Kir_Royale_%2831246794594%29.jpg', 91, 98, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["起泡酒基底", "冷饮", "莓果", "果香", "气泡感", "开胃", "经典"]', '["开胃", "经典"]', '{"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "莓果、果香", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}', '[{"nameZh": "香槟", "nameEn": "Champagne", "amount": 135, "unit": "ml", "role": "冰镇香槟或起泡酒"}, {"nameZh": "黑加仑利口酒", "nameEn": "Crème de cassis", "amount": 15, "unit": "ml", "role": "黑加仑利口酒"}]', '["预冷笛型杯或香槟杯。", "向杯中倒入 15 ml 黑加仑利口酒。", "沿杯壁缓缓加入冰镇的 135 ml 香槟。", "轻搅一下使果酒与气泡酒融合。", "立即饮用，保持细腻气泡。"]', '["皇家基尔酒", "Kir Royale", "香槟黑加仑"]', 'A', '2026-08-04', 1, '{"id": "cocktail-kir-royale", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皇家基尔", "nameEn": "Kir Royale", "intro": "以香槟或起泡酒与黑加仑利口酒调制而成的开胃气泡鸡尾酒，莓果香酸甜、气泡轻盈，呈现淡紫红色，是优雅的法式餐前酒。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/13/Christmas_aperitif_Kir_Royale_%2831246794594%29.jpg", "tags": ["起泡酒基底", "冷饮", "莓果", "果香", "气泡感", "开胃", "经典"], "scene": ["开胃", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "莓果、果香", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-black-velvet', 'cocktail', 'COCKTAIL', '黑丝绒', 'Black Velvet', 'heisirong', 'hsr', '以黑啤风味姜汁啤酒与香槟等比例混合而成的淡爽气泡鸡尾酒，深色麦芽烤香与气泡酒干爽交织，口感顺滑，是独特而优雅的餐前饮。', 'V6 编辑标准化配方以冰镇香槟与深色姜汁啤酒按 1:1 直调，在 IBA 黑丝绒配比框架上以姜汁啤酒替代烈性黑啤；两者的干爽气泡与辛香共同构成标志性的黑金分层。', 'https://upload.wikimedia.org/wikipedia/commons/3/30/BLACK_VELVET_LUCY_%288544042889%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/3/30/BLACK_VELVET_LUCY_%288544042889%29.jpg', 91, 99, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["起泡酒基底", "冷饮", "苦味明显", "姜味", "气泡感", "偏干", "经典"]', '["经典"]', '{"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "苦味明显、姜味", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒"], "scene": ["经典"]}', '[{"nameZh": "香槟", "nameEn": "Champagne", "amount": 75, "unit": "ml", "role": "冰镇香槟或起泡酒"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger beer", "amount": 75, "unit": "ml", "role": "冰镇深色姜汁啤酒"}]', '["预冷笛型杯或香槟杯。", "缓缓倒入 75 ml 冰镇深色姜汁啤酒。", "沿杯壁再缓缓加入 75 ml 冰镇香槟。", "轻搅一下使两者融合。", "立即饮用，保留细腻气泡。"]', '["黑天鹅绒", "Black Velvet", "黑丝绒鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-black-velvet", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑丝绒", "nameEn": "Black Velvet", "intro": "以黑啤风味姜汁啤酒与香槟等比例混合而成的淡爽气泡鸡尾酒，深色麦芽烤香与气泡酒干爽交织，口感顺滑，是独特而优雅的餐前饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/30/BLACK_VELVET_LUCY_%288544042889%29.jpg", "tags": ["起泡酒基底", "冷饮", "苦味明显", "姜味", "气泡感", "偏干", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "苦味明显、姜味", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-french-75', 'cocktail', 'COCKTAIL', '法国75', 'French 75', 'faguo75', 'fg75', '以金酒、柠檬汁、糖浆与香槟调制而成的经典气泡鸡尾酒，金酒草本与柠檬酸香为底，香槟气泡轻盈，是优雅的餐前或庆祝饮品。', 'IBA 官方配比为金酒、柠檬汁、糖浆摇和后以香槟加满；V6 编辑标准化以伦敦干金酒按该比例制作，香槟用量决定气泡与酒体。', 'https://upload.wikimedia.org/wikipedia/commons/d/dd/2020-04-16_19.36.43_-_confinement_Covid-19_Noisy-le-Grand.jpg', 'https://upload.wikimedia.org/wikipedia/commons/d/dd/2020-04-16_19.36.43_-_confinement_Covid-19_Noisy-le-Grand.jpg', 91, 100, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "柑橘", "草本", "气泡感", "摇和", "开胃"]', '["开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "柑橘、草本", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁"], "scene": ["开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "香槟", "nameEn": "Champagne", "amount": 100, "unit": "ml", "role": "冰镇香槟"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 2, "unit": "g", "role": "柠檬皮装饰"}]', '["摇壶中加入 30 ml 伦敦干金酒。", "加入 15 ml 柠檬汁与 15 ml 单糖浆。", "加冰摇和 10 秒，滤入预冷的笛型杯。", "沿杯壁缓缓加入冰镇的 100 ml 香槟。", "以柠檬皮扭捏增香后装饰，立即饮用。"]', '["法国75号", "French 75", "French Seventy-Five"]', 'A', '2026-08-04', 1, '{"id": "cocktail-french-75", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "法国75", "nameEn": "French 75", "intro": "以金酒、柠檬汁、糖浆与香槟调制而成的经典气泡鸡尾酒，金酒草本与柠檬酸香为底，香槟气泡轻盈，是优雅的餐前或庆祝饮品。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/dd/2020-04-16_19.36.43_-_confinement_Covid-19_Noisy-le-Grand.jpg", "tags": ["金酒基底", "冷饮", "柑橘", "草本", "气泡感", "摇和", "开胃"], "scene": ["开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "柑橘、草本", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁"], "scene": ["开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-spritz', 'cocktail', 'COCKTAIL', '气泡鸡尾酒', 'Spritz (Generic)', 'qipaojiweijiu', 'qpjwj', '以起泡酒为基底、加少量苦味利口酒和气泡水兑制的开胃鸡尾酒，口感轻快且带气泡，适合餐前或夏日饮用。', '本条目采用通用气泡鸡尾酒配比：60 ml 起泡酒、40 ml 苦味利口酒加 30 ml 气泡水，直调于加冰的杯型。利口酒可选金巴利或阿佩罗，苦度与颜色随之变化。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 101, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["开胃", "冷饮", "苦味明显", "气泡感", "直调", "轻盈", "低强度", "夏季"]', '["开胃", "夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显", "abv": "中度＞10%～20%", "extra": ["气泡水"], "scene": ["开胃", "夏季"]}', '[{"nameZh": "普罗塞克", "nameEn": "Prosecco", "amount": 60, "unit": "ml", "role": "基酒"}, {"nameZh": "阿佩罗", "nameEn": "Aperol", "amount": 40, "unit": "ml", "role": "苦味利口酒"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 30, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在杯中加入三块冰块。", "倒入起泡酒与苦味利口酒。", "注入气泡水并轻轻搅拌。", "以橙皮挤油后投入杯面装饰。"]', '["Spritz", "气泡开胃酒", "Venetian Spritz"]', 'A', '2026-08-04', 1, '{"id": "cocktail-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "气泡鸡尾酒", "nameEn": "Spritz (Generic)", "intro": "以起泡酒为基底、加少量苦味利口酒和气泡水兑制的开胃鸡尾酒，口感轻快且带气泡，适合餐前或夏日饮用。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["开胃", "冷饮", "苦味明显", "气泡感", "直调", "轻盈", "低强度", "夏季"], "scene": ["开胃", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显", "abv": "中度＞10%～20%", "extra": ["气泡水"], "scene": ["开胃", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-italian-spritz', 'cocktail', 'COCKTAIL', '意大利气泡', 'Italian Spritz', 'yidaliqipao', 'ydlqp', '以阿佩罗、普罗塞克和少量气泡水直调的开胃鸡尾酒，橙香与草本气息突出，是意大利餐前饮品的代表。', '本条目按阿佩罗气泡的经典配比标准化：60 ml 普罗塞克、40 ml 阿佩罗加少量气泡水，直调于加冰的杯型，以橙片装饰。酒感轻、气泡柔和。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 102, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["开胃", "冷饮", "酸甜", "柑橘", "草本", "气泡感", "直调", "低强度"]', '["开胃"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "酸甜、柑橘", "abv": "中度＞10%～20%", "extra": ["气泡水"], "scene": ["开胃"]}', '[{"nameZh": "普罗塞克", "nameEn": "Prosecco", "amount": 60, "unit": "ml", "role": "基酒"}, {"nameZh": "阿佩罗", "nameEn": "Aperol", "amount": 40, "unit": "ml", "role": "阿佩罗利口酒"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 30, "unit": "ml", "role": "补齐容量"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在杯中加入三块冰块。", "倒入普罗塞克与阿佩罗。", "注入气泡水并轻轻搅拌。", "以一片橙片置于杯沿装饰。"]', '["Italian Spritz", "意大利开胃酒", "Spritz Italiano"]', 'A', '2026-08-04', 1, '{"id": "cocktail-italian-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "意大利气泡", "nameEn": "Italian Spritz", "intro": "以阿佩罗、普罗塞克和少量气泡水直调的开胃鸡尾酒，橙香与草本气息突出，是意大利餐前饮品的代表。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["开胃", "冷饮", "酸甜", "柑橘", "草本", "气泡感", "直调", "低强度"], "scene": ["开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "酸甜、柑橘", "abv": "中度＞10%～20%", "extra": ["气泡水"], "scene": ["开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-fruit-spritz', 'cocktail', 'COCKTAIL', '水果起泡酒', 'Fruit Spritz', 'shuiguoqipaojiu', 'sgqpj', '以起泡酒为基底、加入果汁或水果风味利口酒调制的起泡鸡尾酒，果香明亮、气泡轻盈，适合聚会与夏日场景。', '本条目采用通用水果气泡配比：60 ml 起泡酒、30 ml 水果利口酒加 30 ml 果汁，直调于加冰的杯型。水果可选择蜜桃、树莓或草莓，风味随水果变化。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Fros%C3%A9%20on%20Serving%20Tray.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Fros%C3%A9%20on%20Serving%20Tray.jpg', 93, 103, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["冷饮", "果香", "莓果", "甜感明显", "气泡感", "直调", "低强度", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "果香、莓果", "abv": "低度≤10%", "extra": ["气泡水", "草莓糖浆"], "scene": ["夏季"]}', '[{"nameZh": "普罗塞克", "nameEn": "Prosecco", "amount": 60, "unit": "ml", "role": "基酒"}, {"nameZh": "蜜桃利口酒", "nameEn": "Peach liqueur", "amount": 30, "unit": "ml", "role": "水果利口酒"}, {"nameZh": "草莓糖浆", "nameEn": "Strawberry syrup", "amount": 15, "unit": "ml", "role": "水果糖浆"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 30, "unit": "ml", "role": "气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}]', '["在杯中加入三块冰块。", "倒入起泡酒、蜜桃利口酒与草莓糖浆。", "注入气泡水并轻轻搅拌。", "以草莓或橙片置于杯沿装饰。"]', '["Fruit Spritz", "水果气泡酒", "Berry Spritz"]', 'B', '2026-08-04', 1, '{"id": "cocktail-fruit-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "水果起泡酒", "nameEn": "Fruit Spritz", "intro": "以起泡酒为基底、加入果汁或水果风味利口酒调制的起泡鸡尾酒，果香明亮、气泡轻盈，适合聚会与夏日场景。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Fros%C3%A9%20on%20Serving%20Tray.jpg", "tags": ["冷饮", "果香", "莓果", "甜感明显", "气泡感", "直调", "低强度", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "果香、莓果", "abv": "低度≤10%", "extra": ["气泡水", "草莓糖浆"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-champagne-cocktail', 'cocktail', 'COCKTAIL', '香槟鸡尾酒', 'Champagne Cocktail', 'xiangbinjiweijiu', 'xbjwj', '在方糖上滴苦精、注入香槟再补以白兰地的经典起泡鸡尾酒，气泡细腻，兼具干冽口感与微苦层次，是香槟调酒的代表做法。', '本条目按 IBA 配比标准化：方糖加安格斯图拉苦精，注入 90 ml 香槟，再以 10 ml 干邑补足酒感。直接在笛形杯中直调完成。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 104, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["开胃", "冷饮", "经典", "苦味明显", "气泡感", "直调", "轻盈", "低强度"]', '["开胃", "经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}', '[{"nameZh": "香槟", "nameEn": "Champagne", "amount": 90, "unit": "ml", "role": "基酒"}, {"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 10, "unit": "ml", "role": "补足酒感"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 1, "unit": "piece", "role": "盛放苦精"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "滴在方糖上"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将方糖放入笛形杯底。", "在方糖上滴一滴苦精。", "缓慢倒入香槟与干邑，避免过度冲击气泡。", "以柠檬皮挤油后置于杯沿装饰。"]', '["Champagne Cocktail", "香槟古典", "Classic Champagne Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-champagne-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "香槟鸡尾酒", "nameEn": "Champagne Cocktail", "intro": "在方糖上滴苦精、注入香槟再补以白兰地的经典起泡鸡尾酒，气泡细腻，兼具干冽口感与微苦层次，是香槟调酒的代表做法。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["开胃", "冷饮", "经典", "苦味明显", "气泡感", "直调", "轻盈", "低强度"], "scene": ["开胃", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mimosa-royal', 'cocktail', 'COCKTAIL', '莫罗托夫人', 'Mimosa Royal', 'moluotuofuren', 'mltfr', '香槟与橙汁以接近对半比例兑制的起泡鸡尾酒，橙香明亮、气泡轻盈，是早午餐与庆祝场合的经典选择。', '本条目按 1:1 对兑比例标准化：75 ml 香槟加 75 ml 鲜榨橙汁，直调于笛形杯。鲜榨橙汁可让甜酸更平衡，橙汁比例可按偏好微调。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mimosa%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mimosa%20cocktail.jpg', 93, 105, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷饮", "柑橘", "果香", "酸甜", "气泡感", "直调", "低强度", "早午餐"]', '["早午餐"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜橙汁"], "scene": ["早午餐"]}', '[{"nameZh": "香槟", "nameEn": "Champagne", "amount": 75, "unit": "ml", "role": "基酒"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 75, "unit": "ml", "role": "鲜榨橙汁"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将笛形杯冷藏。", "先倒入鲜榨橙汁至半杯。", "沿杯壁缓慢注入香槟，保持气泡。", "以橙片置于杯沿装饰。"]', '["Mimosa Royal", "皇家含羞草", "橙汁香槟"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mimosa-royal", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "莫罗托夫人", "nameEn": "Mimosa Royal", "intro": "香槟与橙汁以接近对半比例兑制的起泡鸡尾酒，橙香明亮、气泡轻盈，是早午餐与庆祝场合的经典选择。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mimosa%20cocktail.jpg", "tags": ["冷饮", "柑橘", "果香", "酸甜", "气泡感", "直调", "低强度", "早午餐"], "scene": ["早午餐"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜橙汁"], "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rossini', 'cocktail', 'COCKTAIL', '罗西尼', 'Rossini', 'luoxini', 'lxn', '草莓泥与香槟兑制的起泡鸡尾酒，莓果香明亮、气泡轻盈，甜酸平衡，是果味起泡饮品中的经典代表，适合早午餐与庆祝场合。', '本条目按经典配比标准化：60 ml 新鲜草莓泥加 90 ml 香槟，直调于笛形杯。草莓泥采用新鲜草莓压碎，可保留果肉感与自然甜酸。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Un%20Rossini%2C%20grazie%20(467053126).jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Un%20Rossini%2C%20grazie%20(467053126).jpg', 93, 106, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["冷饮", "莓果", "果香", "甜感明显", "气泡感", "直调", "低强度", "早午餐"]', '["早午餐"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "莓果、果香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "草莓糖浆"], "scene": ["早午餐"]}', '[{"nameZh": "香槟", "nameEn": "Champagne", "amount": 90, "unit": "ml", "role": "基酒"}, {"nameZh": "草莓糖浆", "nameEn": "Strawberry syrup", "amount": 60, "unit": "ml", "role": "草莓果泥糖浆"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 5, "unit": "ml", "role": "平衡甜度"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将笛形杯冷藏。", "在杯中加入草莓果泥糖浆与柠檬汁。", "缓慢注入香槟并轻轻搅拌一次。", "以草莓或柠檬皮装饰。"]', '["Rossini", "草莓香槟", "Rossini Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-rossini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "罗西尼", "nameEn": "Rossini", "intro": "草莓泥与香槟兑制的起泡鸡尾酒，莓果香明亮、气泡轻盈，甜酸平衡，是果味起泡饮品中的经典代表，适合早午餐与庆祝场合。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Un%20Rossini%2C%20grazie%20(467053126).jpg", "tags": ["冷饮", "莓果", "果香", "甜感明显", "气泡感", "直调", "低强度", "早午餐"], "scene": ["早午餐"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "莓果、果香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "草莓糖浆"], "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-irish-coffee', 'cocktail', 'COCKTAIL', '爱尔兰咖啡', 'Irish Coffee', 'aierlankafei', 'aelkf', '以爱尔兰威士忌、热咖啡与砂糖调制，覆以打发奶油的热饮鸡尾酒，兼具咖啡香、威士忌酒感与奶油顺滑。', '本条目按经典配比标准化：40 ml 爱尔兰威士忌、120 ml 热咖啡加一茶匙细砂糖，覆以未打发的淡奶油层。使用玻璃杯并先热杯可保持温度。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20glass.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20glass.jpg', 93, 107, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["热饮", "咖啡鸡尾酒", "威士忌基底", "咖啡风味", "奶油感", "甜感明显", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "中度＞10%～20%", "extra": ["打发奶油", "烘焙咖啡豆"], "scene": ["餐后"]}', '[{"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 150, "unit": "ml", "role": "冲煮热咖啡"}, {"nameZh": "烘焙咖啡豆", "nameEn": "Roasted coffee beans", "amount": 18, "unit": "g", "role": "咖啡粉"}, {"nameZh": "爱尔兰威士忌", "nameEn": "Irish whiskey", "amount": 40, "unit": "ml", "role": "爱尔兰威士忌"}, {"nameZh": "红糖", "nameEn": "Brown sugar", "amount": 8, "unit": "g", "role": "甜味剂"}, {"nameZh": "打发奶油", "nameEn": "Whipped cream", "amount": 20, "unit": "ml", "role": "奶油层"}]', '["用热水温热杯壁。", "用 18 g 咖啡粉冲煮 150 ml 热咖啡。", "将热咖啡倒入杯中，加入爱尔兰威士忌与红糖并搅拌。", "缓慢倒入打发奶油覆盖液面，不再搅拌。"]', '["Irish Coffee", "爱尔兰咖啡鸡尾酒", "热爱尔兰咖啡"]', 'A', '2026-08-04', 1, '{"id": "cocktail-irish-coffee", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "爱尔兰咖啡", "nameEn": "Irish Coffee", "intro": "以爱尔兰威士忌、热咖啡与砂糖调制，覆以打发奶油的热饮鸡尾酒，兼具咖啡香、威士忌酒感与奶油顺滑。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20glass.jpg", "tags": ["热饮", "咖啡鸡尾酒", "威士忌基底", "咖啡风味", "奶油感", "甜感明显", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "中度＞10%～20%", "extra": ["打发奶油", "烘焙咖啡豆"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mexican-coffee', 'cocktail', 'COCKTAIL', '墨西哥咖啡', 'Mexican Coffee', 'moxigekafei', 'mxgkf', '以咖啡利口酒、龙舌兰与热咖啡调制的热咖啡鸡尾酒，咖啡香与焦糖甜味平衡，酒感温和，适合作为餐后甜点式饮品。', '本条目采用常见配比：40 ml 咖啡利口酒、30 ml 银龙舌兰加 140 ml 热咖啡，搅匀后覆以打发奶油。利口酒比例可按甜度偏好微调。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 108, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["热饮", "咖啡鸡尾酒", "龙舌兰基底", "咖啡风味", "焦糖", "甜感明显", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、焦糖", "abv": "中度＞10%～20%", "extra": ["打发奶油", "烘焙咖啡豆"], "scene": ["餐后"]}', '[{"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 140, "unit": "ml", "role": "冲煮热咖啡"}, {"nameZh": "烘焙咖啡豆", "nameEn": "Roasted coffee beans", "amount": 16, "unit": "g", "role": "咖啡粉"}, {"nameZh": "咖啡利口酒（通用）", "nameEn": "Coffee liqueur (generic)", "amount": 40, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "银龙舌兰酒", "nameEn": "Blanco tequila", "amount": 30, "unit": "ml", "role": "银龙舌兰"}, {"nameZh": "打发奶油", "nameEn": "Whipped cream", "amount": 20, "unit": "ml", "role": "奶油层"}]', '["用 16 g 咖啡粉冲煮 140 ml 热咖啡。", "将热咖啡倒入预热杯中。", "加入咖啡利口酒与银龙舌兰并搅拌。", "缓慢倒入打发奶油覆盖液面。"]', '["Mexican Coffee", "墨西哥咖啡鸡尾酒", "Kahlúa Coffee"]', 'B', '2026-08-04', 1, '{"id": "cocktail-mexican-coffee", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "墨西哥咖啡", "nameEn": "Mexican Coffee", "intro": "以咖啡利口酒、龙舌兰与热咖啡调制的热咖啡鸡尾酒，咖啡香与焦糖甜味平衡，酒感温和，适合作为餐后甜点式饮品。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "咖啡鸡尾酒", "龙舌兰基底", "咖啡风味", "焦糖", "甜感明显", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、焦糖", "abv": "中度＞10%～20%", "extra": ["打发奶油", "烘焙咖啡豆"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
