laceholder.jpg", "tags": ["热饮", "咖啡鸡尾酒", "白兰地基底", "咖啡风味", "香料", "甜感明显", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、香料", "abv": "中度＞10%～20%", "extra": ["烘焙咖啡豆", "肉桂棒"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-italian-coffee', 'cocktail', 'COCKTAIL', '意大利咖啡', 'Italian Coffee', 'yidalikafei', 'ydlkf', '在浓缩咖啡中加入烈酒或利口酒的意大利传统咖啡饮品，咖啡香与酒香叠加，层次简单直接，适合餐后。', '本条目按咖啡科雷托风格配比：双份浓缩 40 g 加 25 ml 咖啡利口酒，也可用格拉巴酒或意大利白兰地替代。利口酒补甜、烈酒补酒感。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 110, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["热饮", "咖啡鸡尾酒", "咖啡风味", "浓缩", "甜感明显", "餐后", "经典", "含咖啡因"]', '["餐后", "经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "中度＞10%～20%", "extra": ["浓缩咖啡液"], "scene": ["餐后", "经典"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 40, "unit": "g", "role": "双份浓缩咖啡液"}, {"nameZh": "咖啡利口酒（通用）", "nameEn": "Coffee liqueur (generic)", "amount": 25, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 4, "unit": "g", "role": "可选甜味"}]', '["萃取 40 g 双份浓缩咖啡液。", "将浓缩倒入预热的小杯。", "加入咖啡利口酒并轻搅一次。", "可选加细砂糖调整甜度后饮用。"]', '["Italian Coffee", "咖啡科雷托", "Caffè Corretto"]', 'B', '2026-08-04', 1, '{"id": "cocktail-italian-coffee", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "意大利咖啡", "nameEn": "Italian Coffee", "intro": "在浓缩咖啡中加入烈酒或利口酒的意大利传统咖啡饮品，咖啡香与酒香叠加，层次简单直接，适合餐后。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["热饮", "咖啡鸡尾酒", "咖啡风味", "浓缩", "甜感明显", "餐后", "经典", "含咖啡因"], "scene": ["餐后", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "中度＞10%～20%", "extra": ["浓缩咖啡液"], "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-french-coffee', 'cocktail', 'COCKTAIL', '法国咖啡', 'French Coffee', 'faguokafei', 'fgkf', '以干邑、咖啡利口酒与热浓缩咖啡为基底的餐后热饮，顶部浮一层稀奶油，口感香甜浓郁并带明显咖啡与坚果气息。', 'V6 编辑标准化采用干邑与咖啡利口酒组合，参照法国餐后咖啡的传统做法；与爱尔兰咖啡相比以干邑替代威士忌，更突出利口酒的甜润与咖啡香气。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20layers.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20layers.jpg', 89, 111, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["咖啡鸡尾酒", "热饮", "咖啡风味", "奶油感", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "中度＞10%～20%", "extra": ["双份浓缩咖啡液", "稀奶油"], "scene": ["餐后"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 20, "unit": "ml", "role": "40% 酒精度的干邑"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 20, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 60, "unit": "ml", "role": "热双份浓缩，约 60 ml"}, {"nameZh": "稀奶油", "nameEn": "Heavy cream", "amount": 20, "unit": "ml", "role": "轻打至微稠，浮于表面"}]', '["预热容量不低于 200 ml 的耐热玻璃杯。", "向杯中注入干邑与咖啡利口酒。", "倒入热双份浓缩咖啡液并轻搅均匀。", "沿勺背缓缓倒入稀奶油，使其浮在咖啡液面上。", "立即饮用，不搅拌奶油层以保留分层口感。"]', '["法式咖啡", "Café Français"]', 'B', '2026-08-04', 1, '{"id": "cocktail-french-coffee", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "法国咖啡", "nameEn": "French Coffee", "intro": "以干邑、咖啡利口酒与热浓缩咖啡为基底的餐后热饮，顶部浮一层稀奶油，口感香甜浓郁并带明显咖啡与坚果气息。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20layers.jpg", "tags": ["咖啡鸡尾酒", "热饮", "咖啡风味", "奶油感", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 89, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "中度＞10%～20%", "extra": ["双份浓缩咖啡液", "稀奶油"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-coffee-liqueur-cream', 'cocktail', 'COCKTAIL', '咖啡利口酒加奶', 'Coffee Liqueur and Cream', 'kafeilikoujiujianai', 'kflkjjn', '以咖啡利口酒与冰牛奶简单混合而成的冷饮，口感顺滑甜润，咖啡香气与乳香充分融合，适合餐后或日常放松时饮用。', 'V6 编辑标准化的两原料直调饮品，以咖啡利口酒与全脂牛奶按 1:2 比例在冰上混合；较白俄罗斯省略烈酒基底，酒精感更低，甜感更直接。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Kahl%C3%BAa%20Mexican%20Coffee%20Liquor%2002.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Kahl%C3%BAa%20Mexican%20Coffee%20Liquor%2002.jpg', 91, 112, '[{"key": "SWEETNESS", "label": "甜度", "score": 9.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["咖啡鸡尾酒", "冷饮", "甜感明显", "咖啡风味", "奶油感", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "甜感明显、咖啡风味", "abv": "低度≤10%", "extra": ["全脂牛奶"], "scene": ["餐后"]}', '[{"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 45, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 90, "unit": "ml", "role": "冰镇全脂牛奶"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "约 4-5 块"}]', '["在古典杯中放入冰块。", "倒入咖啡利口酒。", "补入冰镇全脂牛奶。", "用吧勺轻搅一次后立即饮用。"]', '["咖啡利口酒兑奶", "Kahlúa and Milk"]', 'B', '2026-08-04', 1, '{"id": "cocktail-coffee-liqueur-cream", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "咖啡利口酒加奶", "nameEn": "Coffee Liqueur and Cream", "intro": "以咖啡利口酒与冰牛奶简单混合而成的冷饮，口感顺滑甜润，咖啡香气与乳香充分融合，适合餐后或日常放松时饮用。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Kahl%C3%BAa%20Mexican%20Coffee%20Liquor%2002.jpg", "tags": ["咖啡鸡尾酒", "冷饮", "甜感明显", "咖啡风味", "奶油感", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "甜感明显、咖啡风味", "abv": "低度≤10%", "extra": ["全脂牛奶"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-white-russian', 'cocktail', 'COCKTAIL', '白俄罗斯', 'White Russian', 'baieluosi', 'bels', '以伏特加与咖啡利口酒为基底、加入稀奶油调和的经典餐后鸡尾酒，口感顺滑，甜润的咖啡与焦糖风味突出，酒精感适中。', 'V6 采用 IBA 官方配比：伏特加 50 ml、咖啡利口酒 20 ml、新鲜稀奶油 30 ml，在冰上直调；奶油缓缓浮于表面形成分层，饮用时轻搅融合。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/White%20Russian%20Cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/White%20Russian%20Cocktail.jpg', 93, 113, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["伏特加基底", "咖啡鸡尾酒", "冷饮", "甜感明显", "咖啡风味", "奶油感", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "甜感明显、咖啡风味", "abv": "较高＞20%～30%", "extra": ["稀奶油"], "scene": ["餐后"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "40% 酒精度的伏特加"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 20, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "稀奶油", "nameEn": "Heavy cream", "amount": 30, "unit": "ml", "role": "新鲜稀奶油"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "约 4-5 块"}]', '["在古典杯中放入冰块。", "依次倒入伏特加与咖啡利口酒并轻搅。", "沿勺背缓慢倒入稀奶油，使其浮在酒液表面形成分层。", "饮用前轻搅一次使酒液与奶油融合。"]', '["白色俄罗斯", "White Russian Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-white-russian", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白俄罗斯", "nameEn": "White Russian", "intro": "以伏特加与咖啡利口酒为基底、加入稀奶油调和的经典餐后鸡尾酒，口感顺滑，甜润的咖啡与焦糖风味突出，酒精感适中。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/White%20Russian%20Cocktail.jpg", "tags": ["伏特加基底", "咖啡鸡尾酒", "冷饮", "甜感明显", "咖啡风味", "奶油感", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "甜感明显、咖啡风味", "abv": "较高＞20%～30%", "extra": ["稀奶油"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-black-russian', 'cocktail', 'COCKTAIL', '黑俄罗斯', 'Black Russian', 'heieluosi', 'hels', '伏特加与咖啡利口酒在冰上直调的经典鸡尾酒，口感甜润并带咖啡与焦糖风味，酒体中等偏烈，几乎无酸感。', 'V6 采用 IBA 官方配比：伏特加 50 ml 与咖啡利口酒 20 ml 于加冰古典杯中直调；相较白俄罗斯不含奶油，更纯粹地呈现咖啡利口酒的甜香与酒精感。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 114, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["伏特加基底", "咖啡鸡尾酒", "冷饮", "甜感明显", "咖啡风味", "中等强度", "含咖啡因"]', '["经典", "餐后"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "甜感明显、咖啡风味", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "40% 酒精度的伏特加"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 20, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "约 4-5 块"}]', '["在古典杯中放入冰块。", "倒入伏特加。", "倒入咖啡利口酒。", "用吧勺轻搅混合后饮用。"]', '["黑色俄罗斯", "Black Russian Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-black-russian", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑俄罗斯", "nameEn": "Black Russian", "intro": "伏特加与咖啡利口酒在冰上直调的经典鸡尾酒，口感甜润并带咖啡与焦糖风味，酒体中等偏烈，几乎无酸感。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "咖啡鸡尾酒", "冷饮", "甜感明显", "咖啡风味", "中等强度", "含咖啡因"], "scene": ["经典", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "甜感明显、咖啡风味", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-americano-digestivo', 'cocktail', 'COCKTAIL', '美国佬餐后版', 'Americano Digestivo', 'meiguolaocanhouban', 'mglchb', '金巴利、甜红味美思与苏打水组成的高球型鸡尾酒，苦甜交织并带浓郁草本气息，气泡感清爽，较开胃版更偏餐后收尾。', 'V6 编辑标准化基于 IBA 美国佬配比，将苏打水减量、提高金巴利占比，突出草本苦味以契合餐后消化场景；相较开胃版浓度略高、甜苦更均衡。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 89, 115, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["苦味明显", "草本", "清爽", "餐后", "经典", "中等强度"]', '["餐后", "经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显、草本", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["餐后", "经典"]}', '[{"nameZh": "金巴利", "nameEn": "Campari", "amount": 40, "unit": "ml", "role": "金巴利"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 30, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 50, "unit": "ml", "role": "冰镇苏打水"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "g", "role": "装饰用橙皮"}]', '["在高球杯中放入冰块。", "倒入金巴利与甜红味美思并轻搅。", "补入冰镇苏打水。", "挤压橙皮将皮油喷在液面，再将橙皮放入杯中。"]', '["餐后美国佬", "Americano da Digestivo"]', 'A', '2026-08-04', 1, '{"id": "cocktail-americano-digestivo", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "美国佬餐后版", "nameEn": "Americano Digestivo", "intro": "金巴利、甜红味美思与苏打水组成的高球型鸡尾酒，苦甜交织并带浓郁草本气息，气泡感清爽，较开胃版更偏餐后收尾。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["苦味明显", "草本", "清爽", "餐后", "经典", "中等强度"], "scene": ["餐后", "经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显、草本", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-espresso-rush', 'cocktail', 'COCKTAIL', '艾斯普雷索', 'Espresso Rush', 'aisipuleisuo', 'aspls', '伏特加、双份浓缩与冰镇能量饮料组成的提神型咖啡鸡尾酒，咖啡苦香与甜味平衡，气泡与咖啡因双重刺激，口感清爽。', 'V6 编辑标准化的自创咖啡饮品，将浓缩马提尼的甜感来源由利口酒替换为冰镇能量饮料；先摇和浓缩与伏特加再补入气泡饮品，保持气泡与层次。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 89, 116, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["伏特加基底", "咖啡鸡尾酒", "冷饮", "高咖啡因", "咖啡风味", "中等强度"]', '["经典", "餐后"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "中度＞10%～20%", "extra": ["双份浓缩咖啡液", "能量饮料"], "scene": ["经典", "餐后"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "40% 酒精度的伏特加"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 30, "unit": "ml", "role": "双份浓缩咖啡液"}, {"nameZh": "能量饮料", "nameEn": "Energy drink", "amount": 60, "unit": "ml", "role": "冰镇能量饮料"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "约 4-5 块"}]', '["在摇酒壶中加入冰块。", "倒入伏特加与双份浓缩咖啡液。", "用力摇和至充分降温。", "滤入加冰的玻璃杯中。", "补入冰镇能量饮料并轻搅后饮用。"]', '["浓缩冲击", "Espresso Rush Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-espresso-rush", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "艾斯普雷索", "nameEn": "Espresso Rush", "intro": "伏特加、双份浓缩与冰镇能量饮料组成的提神型咖啡鸡尾酒，咖啡苦香与甜味平衡，气泡与咖啡因双重刺激，口感清爽。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "咖啡鸡尾酒", "冷饮", "高咖啡因", "咖啡风味", "中等强度"], "scene": ["经典", "餐后"], "recommendationScore": 89, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "中度＞10%～20%", "extra": ["双份浓缩咖啡液", "能量饮料"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-coffee-martini', 'cocktail', 'COCKTAIL', '咖啡马提尼', 'Coffee Martini', 'kafeimatini', 'kfmtn', '伏特加、咖啡利口酒与浓缩咖啡摇和的经典咖啡鸡尾酒，液面带细密泡沫，兼具咖啡苦香与利口酒甜润，酒精感适中偏强。', 'V6 编辑标准化以浓缩马提尼结构为基础，强调咖啡利口酒与浓缩咖啡的均衡；相比艾斯普雷索不含气泡饮料，口感更集中、质地更绵密。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 117, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["伏特加基底", "咖啡鸡尾酒", "冷饮", "咖啡风味", "甜感明显", "高强度", "经典", "含咖啡因"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "40% 酒精度的伏特加"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 20, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 30, "unit": "ml", "role": "新鲜浓缩咖啡液"}]', '["在摇酒壶中加入冰块。", "依次倒入伏特加、咖啡利口酒与浓缩咖啡液。", "充分摇和 10-12 秒至液面起细密泡沫。", "滤入冰镇笛形杯。", "以两颗咖啡豆置于液面装饰后饮用。"]', '["浓缩马提尼变体", "Caffè Martini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-coffee-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "咖啡马提尼", "nameEn": "Coffee Martini", "intro": "伏特加、咖啡利口酒与浓缩咖啡摇和的经典咖啡鸡尾酒，液面带细密泡沫，兼具咖啡苦香与利口酒甜润，酒精感适中偏强。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "咖啡鸡尾酒", "冷饮", "咖啡风味", "甜感明显", "高强度", "经典", "含咖啡因"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mocha-martini', 'cocktail', 'COCKTAIL', '摩卡马提尼', 'Mocha Martini', 'mokamatini', 'mkmtn', '在咖啡马提尼基础上加入巧克力糖浆的甜型咖啡鸡尾酒，咖啡与巧克力香气交融，口感圆润甜润，泡沫细腻顺滑。', 'V6 编辑标准化的咖啡马提尼甜型变体，以巧克力糖浆引入可可风味、降低咖啡利口酒用量以控制甜度；适合偏好巧克力风味的餐后人群。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 118, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["伏特加基底", "咖啡鸡尾酒", "巧克力", "咖啡风味", "甜感明显", "奶油感", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "巧克力、咖啡风味", "abv": "较高＞20%～30%", "extra": ["巧克力糖浆", "浓缩咖啡液"], "scene": ["餐后"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "40% 酒精度的伏特加"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 15, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "巧克力糖浆", "nameEn": "Chocolate syrup", "amount": 15, "unit": "ml", "role": "巧克力糖浆"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 30, "unit": "ml", "role": "新鲜浓缩咖啡液"}]', '["在摇酒壶中加入冰块。", "倒入伏特加、咖啡利口酒、巧克力糖浆与浓缩咖啡液。", "充分摇和 10-12 秒。", "滤入冰镇笛形杯。", "撒上巧克力碎装饰后饮用。"]', '["巧克力咖啡马提尼", "Mocha Coffee Martini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-mocha-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "摩卡马提尼", "nameEn": "Mocha Martini", "intro": "在咖啡马提尼基础上加入巧克力糖浆的甜型咖啡鸡尾酒，咖啡与巧克力香气交融，口感圆润甜润，泡沫细腻顺滑。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "咖啡鸡尾酒", "巧克力", "咖啡风味", "甜感明显", "奶油感", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "巧克力、咖啡风味", "abv": "较高＞20%～30%", "extra": ["巧克力糖浆", "浓缩咖啡液"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
