ionScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "坚果、咖啡风味", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-salted-caramel-martini', 'cocktail', 'COCKTAIL', '咸焦糖马提尼', 'Salted Caramel Martini', 'xianjiaotangmatini', 'xjtmtn', '加入焦糖糖浆与少量海盐的甜型咖啡马提尼，焦糖的甜味与咸味相互衬托，浓缩咖啡提供香气骨架，口感圆润浓郁。', 'V6 编辑标准化的咖啡马提尼咸甜变体，以焦糖糖浆替代部分咖啡利口酒并加入极少量海盐提升味觉层次；杯沿撒盐边为可选呈现。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 120, '[{"key": "SWEETNESS", "label": "甜度", "score": 9.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["伏特加基底", "咖啡鸡尾酒", "焦糖", "甜感明显", "浓郁甜", "餐后", "可选盐边", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "焦糖、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液", "细海盐"], "scene": ["餐后"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "40% 酒精度的伏特加"}, {"nameZh": "焦糖糖浆", "nameEn": "Caramel syrup", "amount": 15, "unit": "ml", "role": "焦糖糖浆"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 15, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 30, "unit": "ml", "role": "新鲜浓缩咖啡液"}, {"nameZh": "细海盐", "nameEn": "Fine sea salt", "amount": 1, "unit": "g", "role": "细海盐约一小撮"}]', '["在摇酒壶中加入冰块。", "倒入伏特加、焦糖糖浆、咖啡利口酒、浓缩咖啡液与细海盐。", "充分摇和 10-12 秒至盐分溶解。", "滤入冰镇笛形杯。", "如偏好咸味可先在杯沿蘸盐边，饮用前轻搅。"]', '["海盐焦糖马提尼", "Salted Caramel Coffee Martini"]', 'B', '2026-08-04', 1, '{"id": "cocktail-salted-caramel-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "咸焦糖马提尼", "nameEn": "Salted Caramel Martini", "intro": "加入焦糖糖浆与少量海盐的甜型咖啡马提尼，焦糖的甜味与咸味相互衬托，浓缩咖啡提供香气骨架，口感圆润浓郁。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "咖啡鸡尾酒", "焦糖", "甜感明显", "浓郁甜", "餐后", "可选盐边", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "焦糖、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液", "细海盐"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-manhattan-classic', 'cocktail', 'COCKTAIL', '曼哈顿经典', 'Manhattan Classic', 'manhadunjingdian', 'mhdjd', '以黑麦威士忌、甜红味美思与安格斯图拉苦精搅拌而成的高酒精经典鸡尾酒，甜苦交织，带香料与药草气息，口感圆润饱满。', 'IBA 与通用经典配比为黑麦威士忌 50 ml、甜红味美思 20 ml、苦精 1 滴，V6 采用此配比；与标准曼哈顿的区别在于明确标注黑麦基底与樱桃装饰，标准化为不摇只搅。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20Cocktail2.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20Cocktail2.jpg', 89, 121, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["黑麦基底", "苦味明显", "偏干", "搅拌", "高强度", "经典"]', '["经典"]', '{"baseSpirit": "黑麦基底", "cocktailType": "曼哈顿", "flavor": "苦味明显、偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 50, "unit": "ml", "role": "黑麦威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 20, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "piece", "role": "装饰用鸡尾酒樱桃"}]', '["在搅拌杯中装入冰块并充分冷却。", "倒入黑麦威士忌 50 ml 与甜红味美思 20 ml。", "加入安格斯图拉苦精 1 滴。", "搅拌约 30 秒至充分稀释冷却。", "滤入冰镇后的鸡尾酒杯，以鸡尾酒樱桃装饰。"]', '["曼哈顿", "Manhattan Classic", "经典曼哈顿"]', 'A', '2026-08-04', 1, '{"id": "cocktail-manhattan-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "曼哈顿经典", "nameEn": "Manhattan Classic", "intro": "以黑麦威士忌、甜红味美思与安格斯图拉苦精搅拌而成的高酒精经典鸡尾酒，甜苦交织，带香料与药草气息，口感圆润饱满。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20Cocktail2.jpg", "tags": ["黑麦基底", "苦味明显", "偏干", "搅拌", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "曼哈顿", "flavor": "苦味明显、偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-arnold-palmer', 'cocktail', 'COCKTAIL', '阿诺德帕默', 'Arnold Palmer', 'anuodepamo', 'andpm', '以冰红茶与柠檬水各半调和的无酒精长饮，酸甜清新，茶香与柑橘香气平衡，冰凉解渴，适合日常与午后场景。', 'V6 编辑标准化配比为无糖冰红茶 120 ml 与柠檬水 120 ml 各半，加冰直调；冰红茶以红茶液稀释冷却而成，柠檬水含少量糖，实际甜度可按偏好调整。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 122, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷饮", "柑橘", "无乳配方", "清爽", "夏季", "低糖", "日常"]', '["夏季", "日常"]', '{"baseSpirit": "未标注基酒", "cocktailType": "酸基", "flavor": "柑橘", "abv": "酒精度未知", "extra": ["新鲜柠檬汁", "红茶液"], "scene": ["夏季", "日常"]}', '[{"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 120, "unit": "ml", "role": "冰红茶，茶液稀释冷却"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "调节酸甜"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 80, "unit": "ml", "role": "稀释用冷水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 160, "unit": "g", "role": "大冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用柠檬片"}]', '["在高球杯中加入大冰块并预冷。", "倒入冰红茶 120 ml。", "加入新鲜柠檬汁 30 ml 与单糖浆 10 ml。", "补入冷水 80 ml 至约八成满。", "轻搅混合，以柠檬片装饰后饮用。"]', '["阿诺帕默", "冰茶柠檬水", "Arnold Palmer"]', 'B', '2026-08-04', 1, '{"id": "cocktail-arnold-palmer", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "阿诺德帕默", "nameEn": "Arnold Palmer", "intro": "以冰红茶与柠檬水各半调和的无酒精长饮，酸甜清新，茶香与柑橘香气平衡，冰凉解渴，适合日常与午后场景。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["冷饮", "柑橘", "无乳配方", "清爽", "夏季", "低糖", "日常"], "scene": ["夏季", "日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "酸基", "flavor": "柑橘", "abv": "酒精度未知", "extra": ["新鲜柠檬汁", "红茶液"], "scene": ["夏季", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-corkscrew', 'cocktail', 'COCKTAIL', '高力士', 'Corkscrew', 'gaolishi', 'gls', '以白朗姆、干白味美思与蜜桃利口酒摇和滤冰的短饮，蜜桃果香与药草味交织，口感清透偏干，收尾带一丝利口酒甜润。', 'V6 采用通用配方：白朗姆 45 ml、干白味美思 20 ml、蜜桃利口酒 15 ml，摇和后滤入鸡尾酒杯；以蜜桃利口酒代替常见桃味糖浆，果香更清晰。', 'https://upload.wikimedia.org/wikipedia/commons/1/11/GuifeizuijiuWXM.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/11/GuifeizuijiuWXM.jpg', 89, 123, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["朗姆基底", "金酒基底", "偏干", "搅拌", "中等强度", "均衡"]', '["经典", "开胃"]', '{"baseSpirit": "朗姆基底", "cocktailType": "马天尼", "flavor": "偏干、均衡", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 20, "unit": "ml", "role": "干白味美思"}, {"nameZh": "蜜桃利口酒", "nameEn": "Peach liqueur", "amount": 15, "unit": "ml", "role": "蜜桃利口酒"}, {"nameZh": "青柠皮", "nameEn": "Lime peel", "amount": 1, "unit": "piece", "role": "装饰用青柠皮"}]', '["在摇酒壶中装入冰块。", "倒入白朗姆 45 ml、干白味美思 20 ml 与蜜桃利口酒 15 ml。", "充分摇和约 15 秒至冰透。", "滤入冰镇后的鸡尾酒杯。", "扭入青柠皮增香后饮用。"]', '["开瓶器", "Corkscrew", "高力士鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-corkscrew", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "高力士", "nameEn": "Corkscrew", "intro": "以白朗姆、干白味美思与蜜桃利口酒摇和滤冰的短饮，蜜桃果香与药草味交织，口感清透偏干，收尾带一丝利口酒甜润。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/11/GuifeizuijiuWXM.jpg", "tags": ["朗姆基底", "金酒基底", "偏干", "搅拌", "中等强度", "均衡"], "scene": ["经典", "开胃"], "recommendationScore": 89, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "马天尼", "flavor": "偏干、均衡", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-betty', 'cocktail', 'COCKTAIL', '贝丝', 'Betty', 'beisi', 'bs', '以金酒、白朗姆与君度橙酒等量搅拌而成的干型短饮，金酒草本与朗姆甘蔗香并立，橙香点睛，口感清冽偏干、酒精感鲜明。', '源自 1937 年美国组合，V6 采用君度官方配比：金酒、白朗姆、君度橙酒各 30 ml，搅拌后滤入冰镇库普杯；等量三角结构使三种基底互不掩盖。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20sour%20in%20coupe%20glass%20with%20garnishes.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20sour%20in%20coupe%20glass%20with%20garnishes.jpg', 89, 124, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["金酒基底", "朗姆基底", "偏干", "搅拌", "高强度", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 30, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "君度橙酒", "nameEn": "Cointreau", "amount": 30, "unit": "ml", "role": "君度橙酒"}]', '["在搅拌杯中装入冰块。", "倒入伦敦干金酒 30 ml、白朗姆 30 ml 与君度橙酒 30 ml。", "搅拌约 30 秒至充分冷却。", "滤入冰镇后的库普杯。", "可轻扭橙皮增香后直接饮用。"]', '["贝蒂", "Betty Cocktail", "贝丝鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-betty", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "贝丝", "nameEn": "Betty", "intro": "以金酒、白朗姆与君度橙酒等量搅拌而成的干型短饮，金酒草本与朗姆甘蔗香并立，橙香点睛，口感清冽偏干、酒精感鲜明。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20sour%20in%20coupe%20glass%20with%20garnishes.jpg", "tags": ["金酒基底", "朗姆基底", "偏干", "搅拌", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sling', 'cocktail', 'COCKTAIL', '司令', 'Gin Sling', 'siling', 'sl', '以金酒、柠檬汁与糖浆加冰调和的长饮，酸甜清新带气泡，杜松草本与柑橘香平衡，冰爽解渴，是短饮式古典司令的清凉延伸。', 'V6 采用经典配比：金酒 45 ml、新鲜柠檬汁 30 ml、单糖浆 15 ml，加冰以苏打水补足并轻搅，属直调长饮；与新加坡司令相比不含果汁与利口酒，结构更简洁。', 'https://upload.wikimedia.org/wikipedia/commons/f/ff/Los_Angeles_Chargers_at_Washington_Football_Team%2C_2021.jpg', 'https://upload.wikimedia.org/wikipedia/commons/f/ff/Los_Angeles_Chargers_at_Washington_Football_Team%2C_2021.jpg', 91, 125, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "气泡感", "柑橘", "清爽", "中等强度", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 100, "unit": "ml", "role": "冷藏苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 160, "unit": "g", "role": "大冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用柠檬片"}]', '["在柯林斯杯中加入大冰块。", "倒入金酒 45 ml、新鲜柠檬汁 30 ml 与单糖浆 15 ml。", "沿杯壁补入冷藏苏打水 100 ml。", "用吧勺轻搅一次使混合。", "以柠檬片装饰后饮用。"]', '["金酒司令", "Gin Sling", "经典司令"]', 'A', '2026-08-04', 1, '{"id": "cocktail-sling", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "司令", "nameEn": "Gin Sling", "intro": "以金酒、柠檬汁与糖浆加冰调和的长饮，酸甜清新带气泡，杜松草本与柑橘香平衡，冰爽解渴，是短饮式古典司令的清凉延伸。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/ff/Los_Angeles_Chargers_at_Washington_Football_Team%2C_2021.jpg", "tags": ["金酒基底", "冷饮", "气泡感", "柑橘", "清爽", "中等强度", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bourbon-mint-julep', 'cocktail', 'COCKTAIL', '波本薄荷朱利普', 'Bourbon Mint Julep', 'bobenbohezhulipu', 'bbbhzlp', '以波本威士忌、薄荷叶与单糖浆加碎冰调制的经典长饮，薄荷清凉与焦糖木质香交织，冰爽饱满，是肯塔基德比的标志性饮品。', 'V6 采用通用配比：波本 60 ml、薄荷叶 8 片、单糖浆 15 ml，捣压薄荷后加碎冰搅拌；与干性古典相比以薄荷与长饮形式呈现，甜度与清凉感更高。', 'https://upload.wikimedia.org/wikipedia/commons/c/cb/Kentucky_Derby_in_St._John%27s_-_2_mint_juleps.jpg', 'https://upload.wikimedia.org/wikipedia/commons/c/cb/Kentucky_Derby_in_St._John%27s_-_2_mint_juleps.jpg', 89, 126, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["波本基底", "薄荷", "冷饮", "草本", "经典", "高强度"]', '["经典"]', '{"baseSpirit": "波本基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "新鲜薄荷叶"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 180, "unit": "ml", "role": "碎冰"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 2, "unit": "piece", "role": "装饰用薄荷枝"}]', '["在朱利普杯或厚底杯中加入薄荷叶与单糖浆。", "轻压薄荷叶至释出香气但保持完整。", "倒入波本威士忌 60 ml。", "填满碎冰并用吧勺充分搅拌至杯壁起霜。", "补足碎冰至满，以薄荷枝装饰后饮用。"]', '["波本朱利普", "Bourbon Mint Julep", "肯塔基薄荷朱利普"]', 'A', '2026-08-04', 1, '{"id": "cocktail-bourbon-mint-julep", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波本薄荷朱利普", "nameEn": "Bourbon Mint Julep", "intro": "以波本威士忌、薄荷叶与单糖浆加碎冰调制的经典长饮，薄荷清凉与焦糖木质香交织，冰爽饱满，是肯塔基德比的标志性饮品。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/cb/Kentucky_Derby_in_St._John%27s_-_2_mint_juleps.jpg", "tags": ["波本基底", "薄荷", "冷饮", "草本", "经典", "高强度"], "scene": ["经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "波本基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-julep', 'cocktail', 'COCKTAIL', '朱利普', 'Julep', 'zhulipu', 'zlp', '以金酒、薄荷叶与单糖浆加碎冰调制的清凉长饮，杜松草本与薄荷清凉层层叠加，冰爽轻盈，酸甜含蓄，适合炎热季节畅饮。', 'V6 编辑标准化配比为金酒 50 ml、薄荷叶 8 片、单糖浆 15 ml，捣压薄荷后加碎冰搅拌；以金酒代替传统波本，酒精感更低、草本更清新。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20mint%20julep.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20mint%20julep.jpg', 89, 127, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["金酒基底", "薄荷", "冷饮", "草本", "清爽", "夏季"]', '["夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["夏季"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "新鲜薄荷叶"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 180, "unit": "ml", "role": "碎冰"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 2, "unit": "piece", "role": "装饰用薄荷枝"}]', '["在厚底杯中放入薄荷叶与单糖浆。", "轻压薄荷叶至香气释出。", "倒入伦敦干金酒 50 ml。", "填满碎冰并搅拌至杯壁结霜。", "补满碎冰，以薄荷枝装饰后饮用。"]', '["金酒朱利普", "Gin Julep", "经典朱利普"]', 'B', '2026-08-04', 1, '{"id": "cocktail-julep", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朱利普", "nameEn": "Julep", "intro": "以金酒、薄荷叶与单糖浆加碎冰调制的清凉长饮，杜松草本与薄荷清凉层层叠加，冰爽轻盈，酸甜含蓄，适合炎热季节畅饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20mint%20julep.jpg", "tags": ["金酒基底", "薄荷", "冷饮", "草本", "清爽", "夏季"], "scene": ["夏季"], "recommendationScore": 89, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mint-julep', 'cocktail', 'COCKTAIL', '薄荷朱利普', 'Mint Julep', 'bohezhulipu', 'bhzlp', '以波本威士忌、新鲜薄荷与糖浆加碎冰调制的经典长饮，薄荷清凉衬托波本的焦糖与橡木香，冰爽饱满，是美国南部的代表鸡尾酒。', 'IBA 标准为波本 60 ml、薄荷叶 8 片、单糖浆 15 ml，捣压薄荷后加碎冰搅拌，V6 采用此配比；本款是朱利普家族的标准波本版本。', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Mint_Julep2.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Mint_Julep2.jpg', 89, 128, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["波本基底", "薄荷", "冷饮", "草本", "经典", "高强度"]', '["经典"]', '{"baseSpirit": "波本基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "新鲜薄荷叶"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 180, "unit": "ml", "role": "碎冰"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 2, "unit": "piece", "role": "装饰用薄荷枝"}]', '["在朱利普杯中加入薄荷叶与单糖浆。", "轻压薄荷叶至香气释出而不捣碎。", "倒入波本威士忌 60 ml。", "填满碎冰并用吧勺搅拌至杯壁起霜。", "补足碎冰至满，以薄荷枝装饰后饮用。"]', '["Mint Julep", "肯塔基朱利普", "薄荷冰酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mint-julep", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "薄荷朱利普", "nameEn": "Mint Julep", "intro": "以波本威士忌、新鲜薄荷与糖浆加碎冰调制的经典长饮，薄荷清凉衬托波本的焦糖与橡木香，冰爽饱满，是美国南部的代表鸡尾酒。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/19/Mint_Julep2.jpg", "tags": ["波本基底", "薄荷", "冷饮", "草本", "经典", "高强度"], "scene": ["经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "波本基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-garden-julep', 'cocktail', 'COCKTAIL', '花园朱利普', 'Garden Julep', 'huayuanzhulipu', 'hyzlp', '以金酒、黄瓜、薄荷与罗勒加碎冰调制的清新长饮，黄瓜水润与双重草本香气叠加，冰爽轻盈，酸甜含蓄，适合炎热季节畅饮。', 'V6 编辑标准化配比为金酒 50 ml、黄瓜 3 片、薄荷叶 6 片、罗勒叶 2 片、单糖浆 10 ml，捣压后加碎冰搅拌；以蔬果草本代替传统糖浆主导的甜感。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mint%20Julep%20im%20Silberbecher.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mint%20Julep%20im%20Silberbecher.jpg', 89, 129, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["金酒基底", "草本", "冷饮", "清爽", "夏季", "轻盈"]', '["夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "草本", "abv": "较高＞20%～30%", "extra": ["罗勒叶", "黄瓜"], "scene": ["夏季"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "黄瓜", "nameEn": "Cucumber", "amount": 3, "unit": "piece", "role": "黄瓜片"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 6, "unit": "piece", "role": "新鲜薄荷叶"}, {"nameZh": "罗勒叶", "nameEn": "Basil leaves", "amount": 2, "unit": "piece", "role": "新鲜罗勒叶"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 190, "unit": "ml", "role": "碎冰"}]', '["在厚底杯中放入黄瓜片、薄荷叶、罗勒叶与单糖浆。", "轻压蔬果与香草至香气释出。", "倒入伦敦干金酒 50 ml。", "填满碎冰并搅拌至杯壁结霜。", "补满碎冰，以薄荷枝装饰后饮用。"]', '["花园薄荷朱利普", "Garden Julep", "草本朱利普"]', 'B', '2026-08-04', 1, '{"id": "cocktail-garden-julep", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "花园朱利普", "nameEn": "Garden Julep", "intro": "以金酒、黄瓜、薄荷与罗勒加碎冰调制的清新长饮，黄瓜水润与双重草本香气叠加，冰爽轻盈，酸甜含蓄，适合炎热季节畅饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mint%20Julep%20im%20Silberbecher.jpg", "tags": ["金酒基底", "草本", "冷饮", "清爽", "夏季", "轻盈"], "scene": ["夏季"], "recommendationScore": 89, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "草本", "abv": "较高＞20%～30%", "extra": ["罗勒叶", "黄瓜"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rob-roy', 'cocktail', 'COCKTAIL', '罗布罗伊', 'Rob Roy', 'luobuluoyi', 'lbly', '以混合苏格兰威士忌、甜红味美思与苦精搅拌而成的烈性经典鸡尾酒，烟熏麦芽与甜药草交织，口感圆润，带轻微泥煤气息。', 'IBA 标准为混合苏格兰威士忌 45 ml、甜红味美思 22.5 ml、安格斯图拉苦精 1 滴，搅拌后滤入鸡尾酒杯，V6 采用此配比；与曼哈顿的区别在于以苏格兰威士忌为基底。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rob%20Roy%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rob%20Roy%20cocktail.jpg', 89, 130, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["威士忌基底", "苦味明显", "草本", "搅拌", "高强度", "经典"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "苦味明显、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "混合苏格兰威士忌", "nameEn": "Blended Scotch whisky", "amount": 45, "unit": "ml", "role": "混合苏格兰威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 22.5, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "piece", "role": "装饰用鸡尾酒樱桃"}]', '["在搅拌杯中装入冰块。", "倒入混合苏格兰威士忌 45 ml 与甜红味美思 22.5 ml。", "加入安格斯图拉苦精 1 滴。", "搅拌约 30 秒至充分冷却。", "滤入冰镇后的鸡尾酒杯，以樱桃装饰。"]', '["苏格兰曼哈顿", "Rob Roy", "罗伯罗伊"]', 'A', '2026-08-04', 1, '{"id": "cocktail-rob-roy", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "罗布罗伊", "nameEn": "Rob Roy", "intro": "以混合苏格兰威士忌、甜红味美思与苦精搅拌而成的烈性经典鸡尾酒，烟熏麦芽与甜药草交织，口感圆润，带轻微泥煤气息。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Rob%20Roy%20cocktail.jpg", "tags": ["威士忌基底", "苦味明显", "草本", "搅拌", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "苦味明显、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bobby-burns', 'cocktail', 'COCKTAIL', '鲍比伯恩斯', 'Bobby Burns', 'baobiboensi', 'bbbes', '以苏格兰威士忌、甜味美思与班尼狄克汀调制的曼哈顿家族鸡尾酒，酒体饱满，草本与香料气息交织，是经典的餐后烈酒。', 'V6 编辑标准化配方以苏格兰混合威士忌、甜红味美思与班尼狄克汀按 8:5:1 搅拌调制；威士忌与味美思品牌会显著影响草本与麦芽表现，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/6/62/Bobby_Burns._Jr_MG_5140_%283377315553%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/62/Bobby_Burns._Jr_MG_5140_%283377315553%29.jpg', 93, 131, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "冷饮", "草本", "香料", "搅拌", "餐后", "经典", "高强度"]', '["餐后", "经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "草本、香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["餐后", "经典"]}', '[{"nameZh": "混合苏格兰威士忌", "nameEn": "Blended Scotch whisky", "amount": 40, "unit": "ml", "role": "混合苏格兰威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 25, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "班尼狄克汀", "nameEn": "Bénédictine", "amount": 5, "unit": "ml", "role": "班尼狄克汀"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "搅拌杯冰块"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮喷香装饰"}]', '["在搅拌杯中放入约 60 g 冰块，加入 40 ml 苏格兰混合威士忌。", "加入 25 ml 甜红味美思与 5 ml 班尼狄克汀。", "以吧勺搅拌约 15 秒至充分冰镇。", "滤入冰镇的鸡尾酒杯。", "以橙皮在杯口喷香后投入杯中。"]', '["Bobby Burns", "波比伯恩斯"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bobby-burns", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "鲍比伯恩斯", "nameEn": "Bobby Burns", "intro": "以苏格兰威士忌、甜味美思与班尼狄克汀调制的曼哈顿家族鸡尾酒，酒体饱满，草本与香料气息交织，是经典的餐后烈酒。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/62/Bobby_Burns._Jr_MG_5140_%283377315553%29.jpg", "tags": ["威士忌基底", "冷饮", "草本", "香料", "搅拌", "餐后", "经典", "高强度"], "scene": ["餐后", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "草本、香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cinderella', 'cocktail', 'COCKTAIL', '灰姑娘', 'Cinderella', 'huiguniang', 'hgn', '由菠萝汁、橙汁、柠檬汁与石榴糖浆兑制的无酒精果味饮料，酸甜清爽、果香浓郁，适合不饮酒的聚会与午后场合。', 'V6 编辑标准化配方以菠萝汁、橙汁、柠檬汁与石榴糖浆按 6:6:1.5:1 直调，苏打水补足；果汁甜酸比例会随品牌变化，属非 IBA 的编辑饮品。', 'https://upload.wikimedia.org/wikipedia/commons/9/9c/Cinderella%2C_or%2C_The_little_glass_slipper_%281908%29_%2814596694907%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/9c/Cinderella%2C_or%2C_The_little_glass_slipper_%281908%29_%2814596694907%29.jpg', 93, 132, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷饮", "果香", "柑橘", "酸甜", "清爽", "无乳配方", "纯素", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "潘趣", "flavor": "果香、柑橘", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "橙汁"], "scene": ["夏季"]}', '[{"nameZh": "橙汁", "nameEn": "Orange juice", "amount": 60, "unit": "ml", "role": "橙汁"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 60, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 10, "unit": "ml", "role": "石榴糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 30, "unit": "ml", "role": "补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 20, "unit": "g", "role": "橙片装饰"}]', '["高球杯中加入约 80 g 冰块。", "倒入 60 ml 菠萝汁、60 ml 橙汁与 15 ml 新鲜柠檬汁。", "加入 10 ml 石榴糖浆并轻搅。", "以苏打水补足至约 175 ml。", "以橙片装饰后插入吸管饮用。"]', '["Cinderella", "辛德瑞拉"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cinderella", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "灰姑娘", "nameEn": "Cinderella", "intro": "由菠萝汁、橙汁、柠檬汁与石榴糖浆兑制的无酒精果味饮料，酸甜清爽、果香浓郁，适合不饮酒的聚会与午后场合。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9c/Cinderella%2C_or%2C_The_little_glass_slipper_%281908%29_%2814596694907%29.jpg", "tags": ["冷饮", "果香", "柑橘", "酸甜", "清爽", "无乳配方", "纯素", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "潘趣", "flavor": "果香、柑橘", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "橙汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-harvey-wallbanger', 'cocktail', 'COCKTAIL', '哈维撞墙', 'Harvey Wallbanger', 'haweizhuangqiang', 'hwzq', '以伏特加、橙汁与草本利口酒浮层构成的高球类鸡尾酒，橙香明亮，草本利口酒漂浮收尾，是经典早午餐长饮。', 'V6 编辑标准化配方以伏特加与鲜榨橙汁直调，再以黄查特绿作为草本利口酒浮层（原料词典无 Galliano，编辑部以相近黄色草本利口酒替代）；酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Harvey%20Wallbanger.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Harvey%20Wallbanger.jpg', 93, 133, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "冷饮", "柑橘", "草本", "直调", "早午餐", "经典", "中等强度"]', '["早午餐", "经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "柑橘、草本", "abv": "中度＞10%～20%", "extra": ["橙汁"], "scene": ["早午餐", "经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 30, "unit": "ml", "role": "伏特加"}, {"nameZh": "橙汁", "nameEn": "Orange juice", "amount": 90, "unit": "ml", "role": "鲜榨橙汁"}, {"nameZh": "黄查特绿", "nameEn": "Yellow Chartreuse", "amount": 10, "unit": "ml", "role": "黄查特绿浮层（编辑替代 Galliano）"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "杯中冰"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 20, "unit": "g", "role": "橙片装饰"}]', '["高球杯中加入约 90 g 冰块。", "倒入 30 ml 伏特加与 90 ml 鲜榨橙汁，轻搅。", "沿吧勺背缓缓倒入 10 ml 黄查特绿，使其浮于顶层。", "以橙片装饰后插入吸管饮用。"]', '["Harvey Wallbanger", "哈维沃邦格"]', 'B', '2026-08-04', 1, '{"id": "cocktail-harvey-wallbanger", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "哈维撞墙", "nameEn": "Harvey Wallbanger", "intro": "以伏特加、橙汁与草本利口酒浮层构成的高球类鸡尾酒，橙香明亮，草本利口酒漂浮收尾，是经典早午餐长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Harvey%20Wallbanger.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "草本", "直调", "早午餐", "经典", "中等强度"], "scene": ["早午餐", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "柑橘、草本", "abv": "中度＞10%～20%", "extra": ["橙汁"], "scene": ["早午餐", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-campari-orange', 'cocktail', 'COCKTAIL', '金巴利橙汁', 'Campari Orange', 'jinbalichengzhi', 'jblcz', '以金巴利与橙汁简单直调的高球类饮品，橙汁柔化金巴利的苦味，酸甜与草本苦感平衡，开胃易饮。', 'V6 编辑标准化配方以金巴利与鲜榨橙汁按 1:2 直调；橙汁甜度与金巴利用量比例是风味关键，酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 134, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["苦味明显", "柑橘", "冷饮", "开胃", "直调", "低糖", "日常"]', '["开胃", "日常"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显、柑橘", "abv": "低度≤10%", "extra": ["橙汁"], "scene": ["开胃", "日常"]}', '[{"nameZh": "金巴利", "nameEn": "Campari", "amount": 45, "unit": "ml", "role": "金巴利"}, {"nameZh": "橙汁", "nameEn": "Orange juice", "amount": 90, "unit": "ml", "role": "鲜榨橙汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "杯中冰"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 20, "unit": "g", "role": "橙片装饰"}]', '["高球杯中加入约 90 g 冰块。", "倒入 45 ml 金巴利与 90 ml 鲜榨橙汁。", "轻搅两下让风味融合。", "以橙片装饰后饮用。"]', '["Campari Orange", "金巴利柳橙"]', 'B', '2026-08-04', 1, '{"id": "cocktail-campari-orange", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金巴利橙汁", "nameEn": "Campari Orange", "intro": "以金巴利与橙汁简单直调的高球类饮品，橙汁柔化金巴利的苦味，酸甜与草本苦感平衡，开胃易饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["苦味明显", "柑橘", "冷饮", "开胃", "直调", "低糖", "日常"], "scene": ["开胃", "日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "苦味明显、柑橘", "abv": "低度≤10%", "extra": ["橙汁"], "scene": ["开胃", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cucumber-mojito', 'cocktail', 'COCKTAIL', '黄瓜莫吉托', 'Cucumber Mojito', 'huangguamojituo', 'hgmjt', '在经典莫吉托中加入新鲜黄瓜的清新版本，白朗姆、青柠与薄荷的清爽之外更添瓜果清冽，适合夏季冰镇慢饮。', 'V6 编辑标准化配方以经典莫吉托为基底（白朗姆、青柠、薄荷、苏打水），加入压碎的黄瓜片增鲜；黄瓜用量影响清爽度，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/8/88/Mojito_with_mint_and_cucumber_in_Russia.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/88/Mojito_with_mint_and_cucumber_in_Russia.jpg', 93, 135, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["朗姆基底", "冷饮", "薄荷", "柑橘", "果香", "清爽", "夏季", "顺滑"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "约 8 片新鲜薄荷叶"}, {"nameZh": "黄瓜", "nameEn": "Cucumber", "amount": 40, "unit": "g", "role": "黄瓜片捣压"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入 40 g 黄瓜片与 8 片薄荷叶。", "以捣棒轻压约 5 次释放香气。", "加入 45 ml 白朗姆酒、25 ml 新鲜青柠汁与 15 ml 单糖浆。", "加满冰块后摇匀。", "补入 60 ml 苏打水，以黄瓜片与薄荷枝装饰。"]', '["Cucumber Mojito", "黄瓜莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-cucumber-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黄瓜莫吉托", "nameEn": "Cucumber Mojito", "intro": "在经典莫吉托中加入新鲜黄瓜的清新版本，白朗姆、青柠与薄荷的清爽之外更添瓜果清冽，适合夏季冰镇慢饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/88/Mojito_with_mint_and_cucumber_in_Russia.jpg", "tags": ["朗姆基底", "冷饮", "薄荷", "柑橘", "果香", "清爽", "夏季", "顺滑"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-strawberry-mojito', 'cocktail', 'COCKTAIL', '草莓莫吉托', 'Strawberry Mojito', 'caomeimojituo', 'cmmjt', '以草莓糖浆替代部分甜味的莫吉托变体，白朗姆、青柠与薄荷的基底上叠加莓果甜香，口感清爽果甜。', 'V6 编辑标准化配方以经典莫吉托为基底，用草莓糖浆提供莓果风味与甜感（原料词典无鲜草莓条目）；糖浆用量影响甜度，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/7/74/Dubbelfris_Pornstar_Martini_and_Strawberry_Mojito_-_2023.jpg', 'https://upload.wikimedia.org/wikipedia/commons/7/74/Dubbelfris_Pornstar_Martini_and_Strawberry_Mojito_-_2023.jpg', 93, 136, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "莓果", "薄荷", "酸甜", "清爽", "夏季", "果香"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "莓果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "草莓糖浆", "nameEn": "Strawberry syrup", "amount": 20, "unit": "ml", "role": "草莓糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "约 8 片新鲜薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入 8 片薄荷叶，以捣棒轻压约 5 次。", "加入 45 ml 白朗姆酒、25 ml 新鲜青柠汁与 20 ml 草莓糖浆。", "加满冰块后摇匀。", "补入 60 ml 苏打水。", "以草莓片与薄荷枝装饰后饮用。"]', '["Strawberry Mojito", "草莓莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-strawberry-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "草莓莫吉托", "nameEn": "Strawberry Mojito", "intro": "以草莓糖浆替代部分甜味的莫吉托变体，白朗姆、青柠与薄荷的基底上叠加莓果甜香，口感清爽果甜。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/74/Dubbelfris_Pornstar_Martini_and_Strawberry_Mojito_-_2023.jpg", "tags": ["朗姆基底", "冷饮", "莓果", "薄荷", "酸甜", "清爽", "夏季", "果香"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "莓果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-watermelon-mojito', 'cocktail', 'COCKTAIL', '西瓜莫吉托', 'Watermelon Mojito', 'xiguamojituo', 'xgmjt', '以蜜瓜利口酒呈现西瓜般清甜瓜果风味的莫吉托变体，搭配白朗姆、青柠与薄荷，甜润清爽，适合夏季冰饮。', 'V6 编辑标准化配方以经典莫吉托为基底，用蜜瓜利口酒提供瓜果清甜（原料词典无西瓜鲜果条目，编辑部以蜜瓜利口酒替代并降低朗姆用量）；酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/1/17/Sunday_Funday_Cocktails_Watermelon_Bellini%2C_Green_Tea_Mojito%2C_Strawberry-Lemon_Cocktail_%2815052466056%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/17/Sunday_Funday_Cocktails_Watermelon_Bellini%2C_Green_Tea_Mojito%2C_Strawberry-Lemon_Cocktail_%2815052466056%29.jpg', 93, 137, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "热带水果", "薄荷", "甜感明显", "清爽", "夏季", "果香"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "热带水果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 40, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "蜜瓜利口酒", "nameEn": "Melon liqueur", "amount": 20, "unit": "ml", "role": "蜜瓜利口酒（瓜果风味替代）"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "约 8 片新鲜薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入 8 片薄荷叶，以捣棒轻压约 5 次。", "加入 40 ml 白朗姆酒、25 ml 新鲜青柠汁与 20 ml 蜜瓜利口酒。", "加满冰块后摇匀。", "补入 60 ml 苏打水。", "以薄荷枝装饰后饮用。"]', '["Watermelon Mojito", "西瓜莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-watermelon-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "西瓜莫吉托", "nameEn": "Watermelon Mojito", "intro": "以蜜瓜利口酒呈现西瓜般清甜瓜果风味的莫吉托变体，搭配白朗姆、青柠与薄荷，甜润清爽，适合夏季冰饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/17/Sunday_Funday_Cocktails_Watermelon_Bellini%2C_Green_Tea_Mojito%2C_Strawberry-Lemon_Cocktail_%2815052466056%29.jpg", "tags": ["朗姆基底", "冷饮", "热带水果", "薄荷", "甜感明显", "清爽", "夏季", "果香"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "热带水果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pineapple-mojito', 'cocktail', 'COCKTAIL', '菠萝莫吉托', 'Pineapple Mojito', 'boluomojituo', 'blmjt', '以菠萝汁增添热带果香的莫吉托变体，白朗姆、青柠与薄荷的清凉基底叠加菠萝甜香，口感饱满爽口。', 'V6 编辑标准化配方以经典莫吉托为基底，加入菠萝汁并减少糖浆；菠萝汁甜度会影响整体甜感，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 93, 138, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "菠萝", "热带水果", "薄荷", "清爽", "夏季", "果香"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "菠萝、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 25, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "约 8 片新鲜薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入 8 片薄荷叶，以捣棒轻压约 5 次。", "加入 45 ml 白朗姆酒、25 ml 新鲜青柠汁、25 ml 菠萝汁与 10 ml 单糖浆。", "加满冰块后摇匀。", "补入 60 ml 苏打水。", "以菠萝角与薄荷枝装饰后饮用。"]', '["Pineapple Mojito", "菠萝莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-pineapple-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "菠萝莫吉托", "nameEn": "Pineapple Mojito", "intro": "以菠萝汁增添热带果香的莫吉托变体，白朗姆、青柠与薄荷的清凉基底叠加菠萝甜香，口感饱满爽口。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["朗姆基底", "冷饮", "菠萝", "热带水果", "薄荷", "清爽", "夏季", "果香"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "菠萝、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mango-mojito', 'cocktail', 'COCKTAIL', '芒果莫吉托', 'Mango Mojito', 'mangguomojituo', 'mgmjt', '以芒果汁带来厚实果甜的莫吉托变体，白朗姆、青柠与薄荷的清爽基底上，芒果甜感突出，口感圆润。', 'V6 编辑标准化配方以经典莫吉托为基底，加入芒果汁并减少糖浆；芒果品种与果汁浓度会影响甜感厚度，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/a/a1/Mango_Mojito_%E2%80%93_La_Casa_Restaurant_%E2%80%93_September_2023_-_Sarah_Stierch.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a1/Mango_Mojito_%E2%80%93_La_Casa_Restaurant_%E2%80%93_September_2023_-_Sarah_Stierch.jpg', 93, 139, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "芒果", "热带水果", "薄荷", "酸甜", "夏季", "清爽"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "芒果、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "芒果汁"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "芒果汁", "nameEn": "Mango juice", "amount": 25, "unit": "ml", "role": "芒果汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "约 8 片新鲜薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入 8 片薄荷叶，以捣棒轻压约 5 次。", "加入 45 ml 白朗姆酒、25 ml 新鲜青柠汁、25 ml 芒果汁与 10 ml 单糖浆。", "加满冰块后摇匀。", "补入 60 ml 苏打水。", "以芒果条与薄荷枝装饰后饮用。"]', '["Mango Mojito", "芒果莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mango-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "芒果莫吉托", "nameEn": "Mango Mojito", "intro": "以芒果汁带来厚实果甜的莫吉托变体，白朗姆、青柠与薄荷的清爽基底上，芒果甜感突出，口感圆润。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a1/Mango_Mojito_%E2%80%93_La_Casa_Restaurant_%E2%80%93_September_2023_-_Sarah_Stierch.jpg", "tags": ["朗姆基底", "冷饮", "芒果", "热带水果", "薄荷", "酸甜", "夏季", "清爽"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "芒果、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "芒果汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-passionfruit-mojito', 'cocktail', 'COCKTAIL', '百香果莫吉托', 'Passionfruit Mojito', 'baixiangguomojituo', 'bxgmjt', '以百香果汁带来强烈酸香与热带果味的莫吉托变体，搭配白朗姆、青柠与薄荷，酸甜奔放，非常清爽。', 'V6 编辑标准化配方以经典莫吉托为基底，加入百香果汁并省去额外糖浆；百香果汁的酸度与甜度比例是风味关键，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Passionfruit_mojito_at_Plaza_Khao_Gaeng%2C_Covent_Garden_2026-05-14.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Passionfruit_mojito_at_Plaza_Khao_Gaeng%2C_Covent_Garden_2026-05-14.jpg', 93, 140, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "冷饮", "百香果", "热带水果", "薄荷", "酸甜", "夏季", "清爽"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "百香果、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "百香果汁"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "百香果汁", "nameEn": "Passion fruit juice", "amount": 25, "unit": "ml", "role": "百香果汁"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "约 8 片新鲜薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "补足气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 6, "unit": "g", "role": "青柠轮装饰"}]', '["高球杯中加入 8 片薄荷叶，以捣棒轻压约 5 次。", "加入 45 ml 白朗姆酒、25 ml 新鲜青柠汁与 25 ml 百香果汁。", "加满冰块后摇匀。", "补入 60 ml 苏打水。", "以百香果壳与薄荷枝装饰后饮用。"]', '["Passionfruit Mojito", "百香果莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-passionfruit-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "百香果莫吉托", "nameEn": "Passionfruit Mojito", "intro": "以百香果汁带来强烈酸香与热带果味的莫吉托变体，搭配白朗姆、青柠与薄荷，酸甜奔放，非常清爽。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a9/Passionfruit_mojito_at_Plaza_Khao_Gaeng%2C_Covent_Garden_2026-05-14.jpg", "tags": ["朗姆基底", "冷饮", "百香果", "热带水果", "薄荷", "酸甜", "夏季", "清爽"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "百香果、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "百香果汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cucumber-gin-tonic', 'cocktail', 'COCKTAIL', '黄瓜金汤力', 'Cucumber Gin and Tonic', 'huangguajintangli', 'hgjtl', '以伦敦干金酒与汤力水为基底，加入黄瓜片的清爽长饮，杜松子草本与黄瓜清甜在气泡中轻盈明快。', 'V6 编辑标准化配比以 50 ml 伦敦干金酒配 120 ml 冷藏汤力水，加入黄瓜片增鲜；与经典金汤力的区别在于黄瓜的草本清新与更低苦度，汤力水品牌决定苦甜走向。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gin%20Tonic%205.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gin%20Tonic%205.jpg', 91, 141, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["金酒基底", "冷饮", "草本", "气泡感", "直调", "清爽", "夏季"]', '["夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "草本", "abv": "中度＞10%～20%", "extra": ["汤力水", "黄瓜"], "scene": ["夏季"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 120, "unit": "ml", "role": "冷藏汤力水"}, {"nameZh": "黄瓜", "nameEn": "Cucumber", "amount": 20, "unit": "g", "role": "黄瓜片"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "满杯冰块"}]', '["将高球杯加满冰块。", "加入 50 ml 伦敦干金酒。", "缓慢倒入冷藏汤力水并轻轻搅拌。", "加入 20 g 黄瓜片，让黄瓜清香融入。", "以黄瓜片装饰后立即饮用。"]', '["黄瓜金汤力", "Cucumber G&T", "黄瓜汤力"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cucumber-gin-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黄瓜金汤力", "nameEn": "Cucumber Gin and Tonic", "intro": "以伦敦干金酒与汤力水为基底，加入黄瓜片的清爽长饮，杜松子草本与黄瓜清甜在气泡中轻盈明快。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Gin%20Tonic%205.jpg", "tags": ["金酒基底", "冷饮", "草本", "气泡感", "直调", "清爽", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "草本", "abv": "中度＞10%～20%", "extra": ["汤力水", "黄瓜"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-grapefruit-tonic', 'cocktail', 'COCKTAIL', '葡萄柚汤力', 'Grapefruit Tonic', 'putaoyoutangli', 'ptytl', '以伦敦干金酒、汤力水与新鲜葡萄柚汁组成的清爽长饮，葡萄柚的酸甜苦香与气泡融合，明亮开胃。', 'V6 编辑标准化在经典金汤力结构上加入 30 ml 新鲜葡萄柚汁，以葡萄柚的酸甜苦香替代部分汤力水苦味；葡萄柚汁鲜度影响整体果香强度，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Self-made%20gin%20pink%20grapefruit%20long%20drink.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Self-made%20gin%20pink%20grapefruit%20long%20drink.jpg', 91, 142, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["金酒基底", "冷饮", "柑橘", "气泡感", "直调", "清爽", "夏季"]', '["夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "汤力水"], "scene": ["夏季"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜葡萄柚汁", "nameEn": "Fresh grapefruit juice", "amount": 30, "unit": "ml", "role": "新鲜葡萄柚汁"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 120, "unit": "ml", "role": "冷藏汤力水"}, {"nameZh": "葡萄柚皮", "nameEn": "Grapefruit peel", "amount": 1, "unit": "piece", "role": "装饰用葡萄柚皮"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "满杯冰块"}]', '["将高球杯加满冰块。", "加入 50 ml 伦敦干金酒与 30 ml 新鲜葡萄柚汁。", "缓慢倒入冷藏汤力水并轻搅混合。", "在杯口挤葡萄柚皮油后投入皮装饰。", "立即饮用。"]', '["葡萄柚金汤力", "Grapefruit G&T", "西柚汤力"]', 'B', '2026-08-04', 1, '{"id": "cocktail-grapefruit-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "葡萄柚汤力", "nameEn": "Grapefruit Tonic", "intro": "以伦敦干金酒、汤力水与新鲜葡萄柚汁组成的清爽长饮，葡萄柚的酸甜苦香与气泡融合，明亮开胃。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Self-made%20gin%20pink%20grapefruit%20long%20drink.jpg", "tags": ["金酒基底", "冷饮", "柑橘", "气泡感", "直调", "清爽", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜葡萄柚汁", "汤力水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-elderflower-tonic', 'cocktail', 'COCKTAIL', '接骨木汤力', 'Elderflower Tonic', 'jiegumutangli', 'jgmtl', '以伦敦干金酒与汤力水为底，加入接骨木花风味的清甜长饮，花香雅致、气泡轻盈，果香柔和不苦。', 'V6 编辑标准化以接骨木花利口酒为风味参照，用单糖浆代表其清甜基底并辅以可食用花装饰；汤力水提供苦甜与气泡，整体比经典金汤力更甜润、苦度更低。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 143, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "花香", "气泡感", "直调", "甜感明显", "清爽"]', '["夏季", "经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "花香、甜感明显", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "汤力水"], "scene": ["夏季", "经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "代表接骨木花利口酒的清甜基底"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 120, "unit": "ml", "role": "冷藏汤力水"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "接骨木花装饰"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "满杯冰块"}]', '["将高球杯加满冰块。", "加入 50 ml 伦敦干金酒、15 ml 单糖浆与 15 ml 柠檬汁。", "缓慢倒入冷藏汤力水并轻搅混合。", "以可食用花点缀后立即饮用。"]', '["接骨木花汤力", "Elderflower G&T", "圣日耳曼汤力"]', 'B', '2026-08-04', 1, '{"id": "cocktail-elderflower-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "接骨木汤力", "nameEn": "Elderflower Tonic", "intro": "以伦敦干金酒与汤力水为底，加入接骨木花风味的清甜长饮，花香雅致、气泡轻盈，果香柔和不苦。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["金酒基底", "冷饮", "花香", "气泡感", "直调", "甜感明显", "清爽"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "花香、甜感明显", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "汤力水"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rosemary-tonic', 'cocktail', 'COCKTAIL', '迷迭香汤力', 'Rosemary Tonic', 'midiexiangtangli', 'mdxtl', '以伦敦干金酒与汤力水为基底、缀以新鲜迷迭香的清爽长饮，草本辛香与汤力水的苦甜在气泡中平衡。', 'V6 编辑标准化在经典金汤力结构上加入新鲜迷迭香，以草本辛香平衡汤力水苦味；迷迭香用量影响辛香强度，浸泡时间长短可调整风味浓度，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gin%20and%20Tonic%20with%20ingredients.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gin%20and%20Tonic%20with%20ingredients.jpg', 91, 144, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["金酒基底", "冷饮", "草本", "气泡感", "直调", "清爽", "日常"]', '["日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "草本", "abv": "中度＞10%～20%", "extra": ["汤力水", "迷迭香"], "scene": ["日常"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 120, "unit": "ml", "role": "冷藏汤力水"}, {"nameZh": "迷迭香", "nameEn": "Rosemary", "amount": 5, "unit": "g", "role": "新鲜迷迭香"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用柠檬片"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "满杯冰块"}]', '["将高球杯加满冰块。", "加入 50 ml 伦敦干金酒。", "缓慢倒入冷藏汤力水并轻搅。", "加入 5 g 新鲜迷迭香，轻压释放香气。", "以柠檬片与迷迭香枝装饰后饮用。"]', '["迷迭香金汤力", "Rosemary G&T", "迷迭香汤力水"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rosemary-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "迷迭香汤力", "nameEn": "Rosemary Tonic", "intro": "以伦敦干金酒与汤力水为基底、缀以新鲜迷迭香的清爽长饮，草本辛香与汤力水的苦甜在气泡中平衡。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Gin%20and%20Tonic%20with%20ingredients.jpg", "tags": ["金酒基底", "冷饮", "草本", "气泡感", "直调", "清爽", "日常"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "草本", "abv": "中度＞10%～20%", "extra": ["汤力水", "迷迭香"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-lavender-martini', 'cocktail', 'COCKTAIL', '薰衣草马提尼', 'Lavender Martini', 'xunyicaomatini', 'xycmtn', '以伦敦干金酒、干味美思与薰衣草蜂蜜调制而成的花香马提尼，草本苦甜与花香融合，收尾干爽。', 'V6 编辑标准化以薰衣草蜜代表薰衣草利口酒的花香甜感，配合伦敦干金酒与干味美思的草本结构摇和；蜂蜜用量决定甜度，是一款偏干的花香马提尼。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Lavender%20cocktail,%20Rege.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Lavender%20cocktail,%20Rege.jpg', 91, 145, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["金酒基底", "冷饮", "花香", "草本", "摇和", "顺滑", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 15, "unit": "ml", "role": "干白味美思"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 5, "unit": "ml", "role": "薰衣草蜜，提供花香甜感"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用柠檬皮"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "摇和用冰"}]', '["预冷蝶形杯。", "摇酒壶加冰，倒入 45 ml 金酒、15 ml 干味美思与 5 ml 蜂蜜。", "摇和 12 秒至充分降温与混合。", "滤入预冷的蝶形杯。", "在杯口挤柠檬皮油后投入柠檬皮装饰。"]', '["薰衣草马提尼鸡尾酒", "Lavender Martini Cocktail", "薰衣草马天尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-lavender-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "薰衣草马提尼", "nameEn": "Lavender Martini", "intro": "以伦敦干金酒、干味美思与薰衣草蜂蜜调制而成的花香马提尼，草本苦甜与花香融合，收尾干爽。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Lavender%20cocktail,%20Rege.jpg", "tags": ["金酒基底", "冷饮", "花香", "草本", "摇和", "顺滑", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rose-martini', 'cocktail', 'COCKTAIL', '玫瑰马提尼', 'Rose Martini', 'meiguimatini', 'mgmtn', '以伦敦干金酒与柠檬汁、花蜜调成的粉嫩花香马提尼，玫瑰花瓣装饰，甜润顺滑、花香清雅。', 'V6 编辑标准化以花蜜与可食用玫瑰花瓣呈现玫瑰花香，配合金酒与柠檬汁构成酸甜骨架摇和；蜂蜜的甜度与花瓣用量决定花香强度，色泽来自食材本色。', 'https://upload.wikimedia.org/wikipedia/commons/e/e6/%28Treviso%29_Alberto_Martini_-_Signora_con_piume_rosa.jpg', 'https://upload.wikimedia.org/wikipedia/commons/e/e6/%28Treviso%29_Alberto_Martini_-_Signora_con_piume_rosa.jpg', 91, 146, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "冷饮", "花香", "甜感明显", "摇和", "顺滑", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、甜感明显", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "ml", "role": "花蜜，提供花香甜感"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "玫瑰花瓣装饰"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "摇和用冰"}]', '["预冷蝶形杯。", "摇酒壶加冰，倒入 45 ml 金酒、15 ml 柠檬汁与 10 ml 花蜜。", "摇和 12 秒后滤入预冷的蝶形杯。", "以可食用玫瑰花瓣装饰后饮用。"]', '["玫瑰马提尼鸡尾酒", "Rose Martini Cocktail", "玫瑰马天尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rose-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "玫瑰马提尼", "nameEn": "Rose Martini", "intro": "以伦敦干金酒与柠檬汁、花蜜调成的粉嫩花香马提尼，玫瑰花瓣装饰，甜润顺滑、花香清雅。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e6/%28Treviso%29_Alberto_Martini_-_Signora_con_piume_rosa.jpg", "tags": ["金酒基底", "冷饮", "花香", "甜感明显", "摇和", "顺滑", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、甜感明显", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-jasmine-martini', 'cocktail', 'COCKTAIL', '茉莉马提尼', 'Jasmine Martini', 'molimatini', 'mlmtn', '以伦敦干金酒与茉莉花茶基底调制而成的花香马提尼，茶香与花香交织，带适量咖啡因的现代演绎。', 'V6 编辑标准化以红茶液代表茉莉花茶基底，配伦敦干金酒与蜂蜜摇和；茶底带来适量咖啡因与茶香，与经典干马提尼相比更甜润、烈度更低。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 147, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["金酒基底", "冷饮", "花香", "含咖啡因", "摇和", "顺滑", "下午茶"]', '["下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香", "abv": "较高＞20%～30%", "extra": ["红茶液"], "scene": ["下午茶"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 40, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 30, "unit": "ml", "role": "红茶液，代表茉莉花茶基底"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "ml", "role": "蜂蜜"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用柠檬皮"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "摇和用冰"}]', '["预冷蝶形杯。", "摇酒壶加冰，倒入 40 ml 金酒、30 ml 茉莉花茶基底与 10 ml 蜂蜜。", "摇和 12 秒至充分混合。", "滤入预冷的蝶形杯。", "以柠檬皮装饰后饮用。"]', '["茉莉马提尼鸡尾酒", "Jasmine Martini Cocktail", "茉莉花马天尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-jasmine-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "茉莉马提尼", "nameEn": "Jasmine Martini", "intro": "以伦敦干金酒与茉莉花茶基底调制而成的花香马提尼，茶香与花香交织，带适量咖啡因的现代演绎。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["金酒基底", "冷饮", "花香", "含咖啡因", "摇和", "顺滑", "下午茶"], "scene": ["下午茶"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香", "abv": "较高＞20%～30%", "extra": ["红茶液"], "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-osmanthus-martini', 'cocktail', 'COCKTAIL', '桂花马提尼', 'Osmanthus Martini', 'guihuamatini', 'ghmtn', '以伦敦干金酒与桂花茶基底调制而成的花香马提尼，桂花蜜甜与茶香融合，口感顺滑、尾韵清甜。', 'V6 编辑标准化以红茶液代表桂花茶基底，配伦敦干金酒与蜂蜜摇和；桂花蜜甜与茶香为主调，比经典马提尼更甜、更柔和，含茶底带来的适量咖啡因。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Osmanthus%20wine%20for%20sale%20in%20Dali.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Osmanthus%20wine%20for%20sale%20in%20Dali.jpg', 91, 148, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["金酒基底", "冷饮", "花香", "含咖啡因", "摇和", "顺滑", "甜感明显"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、甜感明显", "abv": "较高＞20%～30%", "extra": ["红茶液"], "scene": ["经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 40, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 30, "unit": "ml", "role": "红茶液，代表桂花茶基底"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "ml", "role": "蜂蜜"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "可食用花点缀"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "摇和用冰"}]', '["预冷蝶形杯。", "摇酒壶加冰，倒入 40 ml 金酒、30 ml 桂花茶基底与 10 ml 蜂蜜。", "摇和 12 秒至充分混合。", "滤入预冷的蝶形杯。", "以可食用花点缀后饮用。"]', '["桂花马提尼鸡尾酒", "Osmanthus Martini Cocktail", "桂花马天尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-osmanthus-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "桂花马提尼", "nameEn": "Osmanthus Martini", "intro": "以伦敦干金酒与桂花茶基底调制而成的花香马提尼，桂花蜜甜与茶香融合，口感顺滑、尾韵清甜。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Osmanthus%20wine%20for%20sale%20in%20Dali.jpg", "tags": ["金酒基底", "冷饮", "花香", "含咖啡因", "摇和", "顺滑", "甜感明显"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、甜感明显", "abv": "较高＞20%～30%", "extra": ["红茶液"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-violet-martini', 'cocktail', 'COCKTAIL', '紫罗兰马提尼', 'Violet Martini', 'ziluolanmatini', 'zllmtn', '以伦敦干金酒与柠檬汁、紫罗兰糖浆调制而成的淡紫花香马提尼，甜润顺滑，以紫罗兰花点缀。', 'V6 编辑标准化以单糖浆代表紫罗兰利口酒的甜香、辅以石榴糖浆调出淡紫色泽，配合金酒与柠檬汁摇和；糖浆用量决定甜度与色泽深度，是偏甜的花香马提尼。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20doir%20(vodka,%20creme%20de%20violet,%20hint%20of%20orange%20bitters,%20lemon%20peel)%20(6267656531).jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20doir%20(vodka,%20creme%20de%20violet,%20hint%20of%20orange%20bitters,%20lemon%20peel)%20(6267656531).jpg', 91, 149, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "冷饮", "花香", "甜感明显", "摇和", "顺滑", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、甜感明显", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "单糖浆，代表紫罗兰糖浆甜感"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 5, "unit": "ml", "role": "石榴糖浆，调出淡紫色泽"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "可食用花点缀"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "摇和用冰"}]', '["预冷蝶形杯。", "摇酒壶加冰，倒入 45 ml 金酒、15 ml 柠檬汁、10 ml 单糖浆与 5 ml 石榴糖浆。", "摇和 12 秒后滤入预冷的蝶形杯。", "以可食用花点缀后饮用。"]', '["紫罗兰马提尼鸡尾酒", "Violet Martini Cocktail", "紫罗兰马天尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-violet-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "紫罗兰马提尼", "nameEn": "Violet Martini", "intro": "以伦敦干金酒与柠檬汁、紫罗兰糖浆调制而成的淡紫花香马提尼，甜润顺滑，以紫罗兰花点缀。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/The%20doir%20(vodka,%20creme%20de%20violet,%20hint%20of%20orange%20bitters,%20lemon%20peel)%20(6267656531).jpg", "tags": ["金酒基底", "冷饮", "花香", "甜感明显", "摇和", "顺滑", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、甜感明显", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-violet-fizz', 'cocktail', 'COCKTAIL', '紫罗兰菲兹', 'Violet Fizz', 'ziluolanfeizi', 'zllfz', '以伦敦干金酒与紫罗兰糖浆调制、兑入苏打水的淡紫菲兹，花香与气泡交织，酸甜清爽、色泽独特。', 'V6 编辑标准化以单糖浆代表紫罗兰利口酒的甜香、辅以石榴糖浆调出淡紫色泽，配合金酒、柠檬汁摇和后兑入苏打水；气泡让甜感轻盈，与干马提尼相比酒精感明显更低。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Violet%20fizz.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Violet%20fizz.jpg', 91, 150, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "花香", "气泡感", "摇和", "酸甜", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "花香、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "单糖浆，代表紫罗兰糖浆甜感"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 5, "unit": "ml", "role": "石榴糖浆，调出淡紫色泽"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "苏打水"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "可食用花点缀"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "满杯冰块"}]', '["将高球杯加满冰块。", "摇酒壶加冰，倒入 45 ml 金酒、20 ml 柠檬汁、15 ml 单糖浆与 5 ml 石榴糖浆。", "摇和 12 秒后滤入高球杯。", "缓慢兑入 60 ml 苏打水并轻搅。", "以可食用花点缀后饮用。"]', '["紫罗兰菲兹鸡尾酒", "Violet Fizz Cocktail", "紫罗兰菲斯"]', 'B', '2026-08-04', 1, '{"id": "cocktail-violet-fizz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "紫罗兰菲兹", "nameEn": "Violet Fizz", "intro": "以伦敦干金酒与紫罗兰糖浆调制、兑入苏打水的淡紫菲兹，花香与气泡交织，酸甜清爽、色泽独特。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Violet%20fizz.jpg", "tags": ["金酒基底", "冷饮", "花香", "气泡感", "摇和", "酸甜", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "花香、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-lemon-martini', 'cocktail', 'COCKTAIL', '柠檬马提尼', 'Lemon Martini', 'ningmengmatini', 'nmmtn', '以伏特加为基底、加入柠檬汁与甜味剂摇和滤冰的鸡尾酒，柠檬酸香明亮、口感顺滑偏甜，是清爽的餐前或餐后饮品。', 'V6 编辑标准化配方以伏特加为烈酒基底，搭配鲜柠檬汁与单糖浆平衡酸度，属于现代水果马提尼家族；含酒精，酸度与甜度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 151, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 8.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["伏特加基底", "冷饮", "柑橘", "酸甜", "摇和", "中等强度", "经典"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "柑橘、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "40% 伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 2, "unit": "g", "role": "柠檬皮装饰"}]', '["将摇壶与马提尼杯充分预冷。", "向摇壶加入 45 ml 伏特加、25 ml 新鲜柠檬汁与 20 ml 单糖浆。", "加入约 100 g 冰块，用力摇和约 12 秒。", "滤入冰镇的马提尼杯。", "以柠檬皮在杯沿拧出香气后轻放杯中点缀。"]', '["柠檬马天尼", "Lemon Martini", "柠檬伏特加马提尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-lemon-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "柠檬马提尼", "nameEn": "Lemon Martini", "intro": "以伏特加为基底、加入柠檬汁与甜味剂摇和滤冰的鸡尾酒，柠檬酸香明亮、口感顺滑偏甜，是清爽的餐前或餐后饮品。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "酸甜", "摇和", "中等强度", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "柑橘、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-strawberry-martini', 'cocktail', 'COCKTAIL', '草莓马提尼', 'Strawberry Martini', 'caomeimatini', 'cmmtn', '以伏特加为基底、加入草莓风味与柠檬汁摇和滤冰的鸡尾酒，草莓果香甜美、色泽粉红，口感顺滑，是果味马提尼的代表。', 'V6 编辑标准化配方以伏特加为烈酒基底，用草莓糖浆提供果味甜感并辅以鲜柠檬汁平衡；现代果味马提尼家族，甜度与酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 91, 152, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "莓果", "果香", "粉红色外观", "甜感明显", "摇和", "中等强度"]', '["经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "莓果、果香", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "草莓糖浆"], "scene": ["经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "40% 伏特加"}, {"nameZh": "草莓糖浆", "nameEn": "Strawberry syrup", "amount": 20, "unit": "ml", "role": "草莓糖浆"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 4, "unit": "g", "role": "柠檬片装饰"}]', '["将摇壶与马提尼杯充分预冷。", "向摇壶加入 45 ml 伏特加、20 ml 草莓糖浆与 15 ml 新鲜柠檬汁。", "加入约 100 g 冰块，用力摇和约 12 秒。", "滤入冰镇的马提尼杯。", "以柠檬片挂于杯沿装饰后立即饮用。"]', '["草莓马天尼", "Strawberry Martini", "草莓伏特加马提尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-strawberry-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "草莓马提尼", "nameEn": "Strawberry Martini", "intro": "以伏特加为基底、加入草莓风味与柠檬汁摇和滤冰的鸡尾酒，草莓果香甜美、色泽粉红，口感顺滑，是果味马提尼的代表。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg", "tags": ["伏特加基底", "莓果", "果香", "粉红色外观", "甜感明显", "摇和", "中等强度"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "马天尼", "flavor": "莓果、果香", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "草莓糖浆"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-blueberry-mojito', 'cocktail', 'COCKTAIL', '蓝莓莫吉托', 'Blueberry Mojito', 'lanmeimojituo', 'lmmjt', '以白朗姆酒、青柠汁、薄荷与莓果糖浆组成的莫吉托变体，呈现蓝莓般的浆果甜感，薄荷清凉交融，气泡轻盈，是热带感的清爽长饮。', 'V6 编辑标准化配方在经典莫吉托基础上加入莓果糖浆，营造蓝莓般的浆果甜感并以苏打水补足气泡；属于朗姆酸型长饮，含酒精。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 93, 153, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["朗姆基底", "莓果", "薄荷", "冷饮", "酸甜", "夏季", "直调", "清爽"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "莓果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "树莓糖浆"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "树莓糖浆", "nameEn": "Raspberry syrup", "amount": 20, "unit": "ml", "role": "莓果糖浆（呈现蓝莓般浆果甜感）"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 90, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "杯用冰块"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 8, "unit": "g", "role": "青柠角装饰"}]', '["在高球杯中加入薄荷叶与 20 ml 莓果糖浆，用捣棒轻压出香。", "加入 45 ml 白朗姆酒与 25 ml 新鲜青柠汁。", "填入约 120 g 冰块。", "补入约 90 ml 苏打水至满。", "用吧勺轻提一次使酒液混合，饰以薄荷枝与青柠角。"]', '["蓝莓薄荷莫吉托", "Blueberry Mojito", "蓝莓莫希托"]', 'B', '2026-08-04', 1, '{"id": "cocktail-blueberry-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蓝莓莫吉托", "nameEn": "Blueberry Mojito", "intro": "以白朗姆酒、青柠汁、薄荷与莓果糖浆组成的莫吉托变体，呈现蓝莓般的浆果甜感，薄荷清凉交融，气泡轻盈，是热带感的清爽长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["朗姆基底", "莓果", "薄荷", "冷饮", "酸甜", "夏季", "直调", "清爽"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "莓果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "树莓糖浆"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-blackberry-mojito', 'cocktail', 'COCKTAIL', '黑莓莫吉托', 'Blackberry Mojito', 'heimeimojituo', 'hmmjt', '以白朗姆酒、青柠汁、薄荷与黑加仑利口酒组成的莫吉托变体，带黑莓般深沉浆果香，薄荷清凉交融，口感清甜带微酸，气泡感轻盈。', 'V6 编辑标准化配方以经典莫吉托为骨架加入黑加仑利口酒，带出黑莓般深沉的浆果气息并以苏打水提供气泡；属于朗姆酸型长饮，含酒精。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 91, 154, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "莓果", "薄荷", "冷饮", "酸甜", "夏季", "直调"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "莓果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "黑加仑利口酒", "nameEn": "Crème de cassis", "amount": 15, "unit": "ml", "role": "黑加仑利口酒（带出黑莓般浆果香）"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 90, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "杯用冰块"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 8, "unit": "g", "role": "青柠角装饰"}]', '["在高球杯中加入薄荷叶，用捣棒轻压出香。", "加入 45 ml 白朗姆酒、25 ml 新鲜青柠汁与 15 ml 黑加仑利口酒。", "填入约 120 g 冰块。", "补入约 90 ml 苏打水至满。", "用吧勺轻提一次混合均匀，饰以薄荷枝与青柠角。"]', '["黑莓薄荷莫吉托", "Blackberry Mojito", "黑莓莫希托"]', 'B', '2026-08-04', 1, '{"id": "cocktail-blackberry-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑莓莫吉托", "nameEn": "Blackberry Mojito", "intro": "以白朗姆酒、青柠汁、薄荷与黑加仑利口酒组成的莫吉托变体，带黑莓般深沉浆果香，薄荷清凉交融，口感清甜带微酸，气泡感轻盈。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["朗姆基底", "莓果", "薄荷", "冷饮", "酸甜", "夏季", "直调"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "莓果、薄荷", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-mojito', 'cocktail', 'COCKTAIL', '无酒精莫吉托', 'Virgin Mojito', 'wujiujingmojituo', 'wjjmjt', '以青柠汁、薄荷、糖浆与苏打水组成的无酒精莫吉托，保留薄荷清凉与青柠酸爽，气泡轻盈，是不含酒精的清爽长饮。', 'V6 编辑标准化配方以经典莫吉托为骨架去除朗姆酒，将甜感与酸度微调至更平衡，青柠汁与薄荷为主要风味来源，不含酒精。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 93, 155, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["冷饮", "薄荷", "柑橘", "酸甜", "气泡感", "纯素", "夏季", "日常"]', '["夏季", "日常"]', '{"baseSpirit": "未标注基酒", "cocktailType": "酸基", "flavor": "薄荷、柑橘", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季", "日常"]}', '[{"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 30, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 25, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 10, "unit": "piece", "role": "薄荷叶"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 120, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "杯用冰块"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 8, "unit": "g", "role": "青柠角装饰"}]', '["在高球杯中加入薄荷叶与 25 ml 单糖浆，用捣棒轻压出香。", "加入 30 ml 新鲜青柠汁。", "填入约 120 g 冰块。", "补入约 120 ml 苏打水至满。", "用吧勺轻提一次混合均匀，饰以薄荷枝与青柠角。"]', '["莫吉托无酒精版", "Virgin Mojito", "无酒精薄荷青柠饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精莫吉托", "nameEn": "Virgin Mojito", "intro": "以青柠汁、薄荷、糖浆与苏打水组成的无酒精莫吉托，保留薄荷清凉与青柠酸爽，气泡轻盈，是不含酒精的清爽长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["冷饮", "薄荷", "柑橘", "酸甜", "气泡感", "纯素", "夏季", "日常"], "scene": ["夏季", "日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "酸基", "flavor": "薄荷、柑橘", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-margarita', 'cocktail', 'COCKTAIL', '无酒精玛格丽特', 'Virgin Margarita', 'wujiujingmagelite', 'wjjmglt', '以青柠汁、橙汁与糖浆组成的无酒精玛格丽特，酸甜结构清晰、柑橘风味明亮，可选盐边增添咸鲜，是清爽的无酒精酸型长饮。', 'V6 编辑标准化配方以经典玛格丽特为骨架去除龙舌兰，用橙汁与糖浆模拟橙味利口酒的甜橙层次，青柠酸爽为主轴，不含酒精。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 91, 156, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 8.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["柑橘", "酸甜", "可选盐边", "摇和", "冷饮", "纯素", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "橙汁"], "scene": ["夏季"]}', '[{"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 35, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "橙汁", "nameEn": "Orange juice", "amount": 60, "unit": "ml", "role": "橙汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 4, "unit": "g", "role": "青柠片装饰"}]', '["以青柠角润湿杯口，蘸取细海盐制成盐边。", "向摇壶加入 35 ml 新鲜青柠汁、60 ml 橙汁与 20 ml 单糖浆。", "加入约 100 g 冰块，摇和约 10 秒。", "滤入带盐边的鸡尾酒杯。", "以青柠片挂于杯沿装饰后立即饮用。"]', '["玛格丽特无酒精版", "Virgin Margarita", "无酒精龙舌兰酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-margarita", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精玛格丽特", "nameEn": "Virgin Margarita", "intro": "以青柠汁、橙汁与糖浆组成的无酒精玛格丽特，酸甜结构清晰、柑橘风味明亮，可选盐边增添咸鲜，是清爽的无酒精酸型长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg", "tags": ["柑橘", "酸甜", "可选盐边", "摇和", "冷饮", "纯素", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "橙汁"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-gin-tonic', 'cocktail', 'COCKTAIL', '无酒精金汤力', 'Virgin Gin & Tonic', 'wujiujingjintangli', 'wjjjtl', '以汤力水的草本苦甜与气泡为骨架、配青柠与黄瓜提升清新感的无酒精长饮，口感清冽，是清爽的开胃饮品。', 'V6 编辑标准化配方对应经典金汤力结构去除金酒，以汤力水的草本与苦甜为风味主体，加入青柠与黄瓜强化清新感，不含酒精。', 'https://upload.wikimedia.org/wikipedia/commons/d/d4/Gin_and_Tonic_with_ingredients.jpg', 'https://upload.wikimedia.org/wikipedia/commons/d/d4/Gin_and_Tonic_with_ingredients.jpg', 93, 157, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["冷饮", "草本", "柑橘", "气泡感", "直调", "低糖", "夏季", "开胃"]', '["夏季", "开胃"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "草本、柑橘", "abv": "酒精度未知", "extra": ["汤力水", "黄瓜"], "scene": ["夏季", "开胃"]}', '[{"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 160, "unit": "ml", "role": "汤力水"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 8, "unit": "g", "role": "青柠片"}, {"nameZh": "黄瓜", "nameEn": "Cucumber", "amount": 10, "unit": "g", "role": "黄瓜条"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "杯用冰块"}]', '["在高球杯中填入约 120 g 冰块。", "倒入约 160 ml 冰镇汤力水。", "挤入半片青柠汁后投入青柠片。", "以黄瓜条轻贴杯壁。", "轻拌一下使风味融合后立即饮用。"]', '["无酒精金酒汤力", "Virgin G&T", "无酒精杜松子汤力"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-gin-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精金汤力", "nameEn": "Virgin Gin & Tonic", "intro": "以汤力水的草本苦甜与气泡为骨架、配青柠与黄瓜提升清新感的无酒精长饮，口感清冽，是清爽的开胃饮品。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d4/Gin_and_Tonic_with_ingredients.jpg", "tags": ["冷饮", "草本", "柑橘", "气泡感", "直调", "低糖", "夏季", "开胃"], "scene": ["夏季", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "草本、柑橘", "abv": "酒精度未知", "extra": ["汤力水", "黄瓜"], "scene": ["夏季", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-pina-colada', 'cocktail', 'COCKTAIL', '无酒精皮纳科拉达', 'Virgin Piña Colada', 'wujiujingpinakelada', 'wjjpnkld', '以椰奶、菠萝汁与冰块搅打成的无酒精皮纳科拉达，椰香浓郁、菠萝清甜，口感绵密如冰沙，是热带风情的无酒精冰饮。', 'V6 编辑标准化配方以经典皮纳科拉达为骨架去除朗姆酒，以椰奶与菠萝汁为主味并加冰搅打，呈冰沙质地，不含酒精。', 'https://upload.wikimedia.org/wikipedia/commons/d/d1/Pina_Colada_at_Aruba.jpg', 'https://upload.wikimedia.org/wikipedia/commons/d/d1/Pina_Colada_at_Aruba.jpg', 93, 158, '[{"key": "SWEETNESS", "label": "甜度", "score": 9.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["椰子", "菠萝", "热带水果", "甜感明显", "搅打", "冷饮", "纯素", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "冰沙", "flavor": "椰子、菠萝", "abv": "酒精度未知", "extra": ["椰奶", "椰浆"], "scene": ["夏季"]}', '[{"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 90, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "椰奶", "nameEn": "Coconut milk", "amount": 60, "unit": "ml", "role": "椰奶"}, {"nameZh": "椰浆", "nameEn": "Coconut cream", "amount": 30, "unit": "ml", "role": "椰浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 150, "unit": "g", "role": "搅打用冰块"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "piece", "role": "樱桃装饰"}]', '["准备一台可用的搅拌机。", "加入 90 ml 菠萝汁、60 ml 椰奶与 30 ml 椰浆。", "加入约 150 g 冰块，搅打至绵密冰沙状。", "倒入预冷的飓风杯或高脚杯。", "以樱桃装饰后立即饮用。"]', '["无酒精椰林飘香", "Virgin Pina Colada", "无酒精椰香菠萝冰饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-pina-colada", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精皮纳科拉达", "nameEn": "Virgin Piña Colada", "intro": "以椰奶、菠萝汁与冰块搅打成的无酒精皮纳科拉达，椰香浓郁、菠萝清甜，口感绵密如冰沙，是热带风情的无酒精冰饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d1/Pina_Colada_at_Aruba.jpg", "tags": ["椰子", "菠萝", "热带水果", "甜感明显", "搅打", "冷饮", "纯素", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "冰沙", "flavor": "椰子、菠萝", "abv": "酒精度未知", "extra": ["椰奶", "椰浆"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-mai-tai', 'cocktail', 'COCKTAIL', '无酒精迈泰', 'Virgin Mai Tai', 'wujiujingmaitai', 'wjjmt', '以青柠汁、橙汁、杏仁糖浆与糖浆组成的无酒精迈泰，青柠酸爽、橙香与杏仁甜交织，热带果味饱满，是清爽的无酒精热带饮品。', 'V6 编辑标准化配方以经典迈泰为骨架去除朗姆，以橙汁与杏仁糖浆还原甜橙与杏仁的层次，青柠酸爽为主轴，不含酒精。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 159, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["柑橘", "热带水果", "酸甜", "果香", "摇和", "冷饮", "纯素", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "提基", "flavor": "柑橘、热带水果", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "杏仁糖浆"], "scene": ["夏季"]}', '[{"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "橙汁", "nameEn": "Orange juice", "amount": 60, "unit": "ml", "role": "橙汁"}, {"nameZh": "杏仁糖浆", "nameEn": "Almond syrup", "amount": 20, "unit": "ml", "role": "杏仁糖浆"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 8, "unit": "g", "role": "橙片装饰"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 3, "unit": "piece", "role": "薄荷枝装饰"}]', '["将摇壶预冷，向壶中加 25 ml 新鲜青柠汁与 60 ml 橙汁。", "加入 20 ml 杏仁糖浆与 15 ml 单糖浆。", "加入约 100 g 冰块，摇和约 10 秒。", "滤入冰镇的古典杯。", "以橙片与薄荷枝装饰后立即饮用。"]', '["迈泰无酒精版", "Virgin Mai Tai", "无酒精热带朗姆风味饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-mai-tai", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精迈泰", "nameEn": "Virgin Mai Tai", "intro": "以青柠汁、橙汁、杏仁糖浆与糖浆组成的无酒精迈泰，青柠酸爽、橙香与杏仁甜交织，热带果味饱满，是清爽的无酒精热带饮品。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["柑橘", "热带水果", "酸甜", "果香", "摇和", "冷饮", "纯素", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "提基", "flavor": "柑橘、热带水果", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "杏仁糖浆"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-bloody-mary', 'cocktail', 'COCKTAIL', '无酒精血玛', 'Virgin Bloody Mary', 'wujiujingxuema', 'wjjxm', '以番茄汁、柠檬汁与咸鲜香料组成的无酒精血腥玛丽，番茄浓醇、酸度与辛香平衡，口感饱满，是经典的咸鲜系开胃饮品。', 'V6 编辑标准化配方以经典血腥玛丽为骨架去除伏特加，以番茄汁为主味并用辣酱、伍斯特酱与芹菜盐调出咸鲜辛香，不含酒精。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 160, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["咸鲜", "辛辣", "早午餐", "直调", "冷饮", "低糖", "日常"]', '["早午餐", "日常"]', '{"baseSpirit": "未标注基酒", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "酒精度未知", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["早午餐", "日常"]}', '[{"nameZh": "番茄汁", "nameEn": "Tomato juice", "amount": 140, "unit": "ml", "role": "番茄汁"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "伍斯特酱", "nameEn": "Worcestershire sauce", "amount": 2, "unit": "dash", "role": "伍斯特酱"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 2, "unit": "dash", "role": "辣酱"}, {"nameZh": "芹菜盐", "nameEn": "Celery salt", "amount": 1, "unit": "g", "role": "芹菜盐"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯用冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 4, "unit": "g", "role": "柠檬片装饰"}]', '["在高球杯中填入约 80 g 冰块。", "倒入 140 ml 番茄汁与 15 ml 新鲜柠檬汁。", "加入 2 滴伍斯特酱与 2 滴辣酱。", "撒入约 1 g 芹菜盐。", "用吧勺轻提两次混合均匀，饰以柠檬片后立即饮用。"]', '["无酒精血腥玛丽", "Virgin Bloody Mary", "番茄咸鲜无酒精饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-bloody-mary", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精血玛", "nameEn": "Virgin Bloody Mary", "intro": "以番茄汁、柠檬汁与咸鲜香料组成的无酒精血腥玛丽，番茄浓醇、酸度与辛香平衡，口感饱满，是经典的咸鲜系开胃饮品。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["咸鲜", "辛辣", "早午餐", "直调", "冷饮", "低糖", "日常"], "scene": ["早午餐", "日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "酒精度未知", "extra": ["伍斯特酱", "新鲜柠檬汁"], "scene": ["早午餐", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-daiquiri', 'cocktail', 'COCKTAIL', '无酒精代基里', 'Virgin Daiquiri', 'wujiujingdaijili', 'wjjdjl', '以青柠汁与糖浆调制的无酒精代基里，清爽酸甜、冰凉宜人，保留经典代基里的柑橘骨架而不含酒精。', 'V6 编辑标准化配方以青柠汁和单糖浆为核心，用苏打水代替朗姆酒补足容量，属于无酒精酸型饮品；酸度与甜度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 161, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 8.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["酸型鸡尾酒", "柑橘", "冷饮", "酸甜", "摇和", "清爽", "纯素", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 40, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 30, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "补足容量用苏打水"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 50, "unit": "ml", "role": "稀释冰块化水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和与杯内用冰"}]', '["将摇壶与鸡尾酒杯充分预冷。", "向摇壶加入 40 ml 青柠汁与 30 ml 单糖浆。", "加入约 80 g 冰块，用力摇和约 12 秒。", "滤入冰镇鸡尾酒杯，加入 60 g 冰块。", "补入 60 ml 苏打水，轻轻搅拌后以青柠角点缀。"]', '["无酒精黛绮莉", "Virgin Daiquiri", "无酒精朗姆酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-daiquiri", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精代基里", "nameEn": "Virgin Daiquiri", "intro": "以青柠汁与糖浆调制的无酒精代基里，清爽酸甜、冰凉宜人，保留经典代基里的柑橘骨架而不含酒精。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["酸型鸡尾酒", "柑橘", "冷饮", "酸甜", "摇和", "清爽", "纯素", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "酒精度未知", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-virgin-whiskey-sour', 'cocktail', 'COCKTAIL', '无酒精威士忌酸', 'Virgin Whiskey Sour', 'wujiujingweishijisuan', 'wjjwsjs', '以柠檬汁、糖浆与蛋清打发的无酒精威士忌酸，泡沫绵密、酸甜平衡，复刻经典酸酒的层次而不含酒精。', 'V6 编辑标准化配方以柠檬汁与单糖浆支撑酸甜主体，蛋清提供绵密泡沫，以水补足烈酒容量；属于无酒精酸型饮品。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg', 91, 162, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["酸型鸡尾酒", "柑橘", "酸甜", "泡沫质地", "摇和", "冷饮", "日常"]', '["日常"]', '{"baseSpirit": "未标注基酒", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "酒精度未知", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["日常"]}', '[{"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 35, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 25, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "ml", "role": "提供泡沫"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 30, "unit": "ml", "role": "替代威士忌的容量"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰"}]', '["将摇壶与鸡尾酒杯充分预冷。", "向摇壶加入柠檬汁、单糖浆、蛋清与冷水。", "不加冰干摇约 10 秒使蛋清起泡。", "加入约 100 g 冰块，用力摇和约 12 秒。", "滤入冰镇鸡尾酒杯，以柠檬皮点缀。"]', '["无酒精威士忌酸酒", "Virgin Whiskey Sour", "无酒精酸酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-virgin-whiskey-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "无酒精威士忌酸", "nameEn": "Virgin Whiskey Sour", "intro": "以柠檬汁、糖浆与蛋清打发的无酒精威士忌酸，泡沫绵密、酸甜平衡，复刻经典酸酒的层次而不含酒精。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg", "tags": ["酸型鸡尾酒", "柑橘", "酸甜", "泡沫质地", "摇和", "冷饮", "日常"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "酒精度未知", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-espresso-negroni', 'cocktail', 'COCKTAIL', '浓缩咖啡尼格罗尼', 'Espresso Negroni', 'nongsuokafeinigeluoni', 'nskfngln', '在经典尼格罗尼基础上加入浓缩咖啡液，苦甜交织并叠加咖啡烘焙香，酒体饱满、收尾是干净的回味苦。', 'V6 编辑标准化配方以金巴利、甜红味美思与伦敦干金酒为主体，加入一份浓缩咖啡液丰富苦香层次；非 IBA 官方配方，配比为编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni%20Ambassador.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni%20Ambassador.jpg', 93, 163, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 9.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["咖啡鸡尾酒", "金酒基底", "苦感主导", "草本", "咖啡风味", "搅拌", "高强度", "含咖啡因"]', '["经典", "餐后"]', '{"baseSpirit": "金酒基底", "cocktailType": "咖啡鸡尾酒", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["经典", "餐后"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 25, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 20, "unit": "ml", "role": "金巴利"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 20, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 25, "unit": "ml", "role": "单份浓缩咖啡液"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "搅拌与杯内用冰"}]', '["将搅拌杯与老式酒杯充分预冷。", "向搅拌杯加入金酒、金巴利与甜红味美思。", "加入约 100 g 冰块，搅拌约 25 秒。", "滤入加有冰块的老式酒杯。", "沿杯缘缓缓加入 25 ml 浓缩咖啡液，轻拌两次后以橙皮点缀。"]', '["意式浓缩尼格罗尼", "Espresso Negroni", "咖啡内格罗尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-espresso-negroni", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "浓缩咖啡尼格罗尼", "nameEn": "Espresso Negroni", "intro": "在经典尼格罗尼基础上加入浓缩咖啡液，苦甜交织并叠加咖啡烘焙香，酒体饱满、收尾是干净的回味苦。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni%20Ambassador.jpg", "tags": ["咖啡鸡尾酒", "金酒基底", "苦感主导", "草本", "咖啡风味", "搅拌", "高强度", "含咖啡因"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "咖啡鸡尾酒", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-coffee-negroni', 'cocktail', 'COCKTAIL', '咖啡尼格罗尼', 'Coffee Negroni', 'kafeinigeluoni', 'kfngln', '以冷萃浓缩融入尼格罗尼的咖啡鸡尾酒，咖啡风味顺滑低酸，与金巴利的草本苦味相互映衬、层次丰富。', 'V6 编辑标准化配方以冷萃浓缩液替代部分甜味剂与酒液，降低咖啡酸度并让咖啡香更圆润；非 IBA 官方配方，配比为编辑标准。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 164, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 9.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["咖啡鸡尾酒", "金酒基底", "苦感主导", "咖啡风味", "草本", "搅拌", "高强度", "含咖啡因"]', '["经典", "餐后"]', '{"baseSpirit": "金酒基底", "cocktailType": "咖啡鸡尾酒", "flavor": "苦感主导、咖啡风味", "abv": "较高＞20%～30%", "extra": ["冷萃浓缩液"], "scene": ["经典", "餐后"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 25, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 20, "unit": "ml", "role": "金巴利"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 20, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "冷萃浓缩液", "nameEn": "Cold brew concentrate", "amount": 30, "unit": "ml", "role": "冷萃浓缩液"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "搅拌用冰，杯内另放整颗冰球"}]', '["将老式酒杯与整颗冰球一起预冷。", "向搅拌杯加入金酒、金巴利与甜红味美思。", "加入冰块搅拌约 25 秒。", "滤入放有冰球的老式酒杯。", "沿杯缘缓缓加入冷萃浓缩液，轻拌后以橙皮点缀。"]', '["冷萃尼格罗尼", "Coffee Negroni", "咖啡内格罗尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-coffee-negroni", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "咖啡尼格罗尼", "nameEn": "Coffee Negroni", "intro": "以冷萃浓缩融入尼格罗尼的咖啡鸡尾酒，咖啡风味顺滑低酸，与金巴利的草本苦味相互映衬、层次丰富。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["咖啡鸡尾酒", "金酒基底", "苦感主导", "咖啡风味", "草本", "搅拌", "高强度", "含咖啡因"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "咖啡鸡尾酒", "flavor": "苦感主导、咖啡风味", "abv": "较高＞20%～30%", "extra": ["冷萃浓缩液"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-espresso-sour', 'cocktail', 'COCKTAIL', '意式浓缩酸', 'Espresso Sour', 'yishinongsuosuan', 'ysnss', '以双份浓缩、柠檬汁与蛋清摇和的无酒精咖啡酸，绵密泡沫下是咖啡酸香与柑橘的清亮酸甜。', 'V6 编辑标准化配方以双份浓缩为基底，柠檬汁与单糖浆平衡酸度，蛋清提升泡沫质感；不含酒精，咖啡因与酸度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 165, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["咖啡鸡尾酒", "咖啡风味", "柑橘", "酸甜", "泡沫质地", "摇和", "含咖啡因"]', '["经典", "开胃", "餐后"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、柑橘", "abv": "酒精度未知", "extra": ["双份浓缩咖啡液", "新鲜柠檬汁"], "scene": ["经典", "开胃", "餐后"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 60, "unit": "ml", "role": "双份浓缩咖啡液"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 20, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "ml", "role": "提供泡沫"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰"}]', '["将摇壶与鸡尾酒杯充分预冷。", "向摇壶加入浓缩液、柠檬汁、单糖浆与蛋清。", "不加冰干摇约 10 秒使蛋清起泡。", "加入约 100 g 冰块，用力摇和约 12 秒。", "滤入冰镇鸡尾酒杯，以咖啡豆装饰点缀。"]', '["浓缩咖啡酸", "Espresso Sour", "咖啡酸酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-espresso-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "意式浓缩酸", "nameEn": "Espresso Sour", "intro": "以双份浓缩、柠檬汁与蛋清摇和的无酒精咖啡酸，绵密泡沫下是咖啡酸香与柑橘的清亮酸甜。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["咖啡鸡尾酒", "咖啡风味", "柑橘", "酸甜", "泡沫质地", "摇和", "含咖啡因"], "scene": ["经典", "开胃", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、柑橘", "abv": "酒精度未知", "extra": ["双份浓缩咖啡液", "新鲜柠檬汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-coffee-sour', 'cocktail', 'COCKTAIL', '咖啡酸', 'Coffee Sour', 'kafeisuan', 'kfs', '以波本、浓缩咖啡与柠檬汁调和的含酒精咖啡酸，咖啡苦香与威士忌酒体融合，酸甜苦三层平衡。', 'V6 编辑标准化配方以波本威士忌为烈酒基底，加入浓缩咖啡与柠檬汁，属于咖啡与酸酒结合的现代配方；非 IBA 官方配方，配比为编辑标准。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 166, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["咖啡鸡尾酒", "波本基底", "咖啡风味", "酸甜", "泡沫质地", "摇和", "含咖啡因"]', '["经典", "开胃", "餐后"]', '{"baseSpirit": "波本基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "浓缩咖啡液"], "scene": ["经典", "开胃", "餐后"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 40, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 30, "unit": "ml", "role": "单份浓缩咖啡液"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰"}]', '["将摇壶与鸡尾酒杯充分预冷。", "向摇壶加入波本、浓缩液、柠檬汁与单糖浆。", "加入约 100 g 冰块，用力摇和约 12 秒。", "滤入冰镇鸡尾酒杯。", "以一片橙皮挤出香气后轻放杯中点缀。"]', '["咖啡酸酒", "Coffee Sour", "威士忌咖啡酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-coffee-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "咖啡酸", "nameEn": "Coffee Sour", "intro": "以波本、浓缩咖啡与柠檬汁调和的含酒精咖啡酸，咖啡苦香与威士忌酒体融合，酸甜苦三层平衡。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["咖啡鸡尾酒", "波本基底", "咖啡风味", "酸甜", "泡沫质地", "摇和", "含咖啡因"], "scene": ["经典", "开胃", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "波本基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "浓缩咖啡液"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bourbon-maple-sour', 'cocktail', 'COCKTAIL', '波本枫糖酸', 'Bourbon Maple Sour', 'bobenfengtangsuan', 'bbfts', '以波本威士忌、柠檬汁与枫糖浆调制的经典酸酒，枫糖的焦甜裹着酒体，泡沫细腻、口感顺滑。', 'V6 编辑标准化配方以枫糖浆替代单糖浆作为甜味剂，配以波本与柠檬汁，蛋清提供泡沫；在经典威士忌酸基础上调整，配比为编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg', 91, 167, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["酸型鸡尾酒", "波本基底", "枫糖", "酸甜", "泡沫质地", "摇和", "冷饮"]', '["经典", "开胃"]', '{"baseSpirit": "波本基底", "cocktailType": "酸型鸡尾酒", "flavor": "枫糖、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典", "开胃"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 22, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "枫糖浆", "nameEn": "Maple syrup", "amount": 20, "unit": "ml", "role": "枫糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "ml", "role": "提供泡沫"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "ml", "role": "安格斯图拉苦精约 3 滴"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰"}]', '["将摇壶与老式酒杯充分预冷。", "向摇壶加入波本、柠檬汁、枫糖浆与蛋清。", "不加冰干摇约 10 秒使蛋清起泡。", "加入约 100 g 冰块与苦精，用力摇和约 12 秒。", "滤入冰镇老式酒杯，以柠檬皮点缀。"]', '["枫糖波本酸", "Bourbon Maple Sour", "枫糖威士忌酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bourbon-maple-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波本枫糖酸", "nameEn": "Bourbon Maple Sour", "intro": "以波本威士忌、柠檬汁与枫糖浆调制的经典酸酒，枫糖的焦甜裹着酒体，泡沫细腻、口感顺滑。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20Served%20Up.jpg", "tags": ["酸型鸡尾酒", "波本基底", "枫糖", "酸甜", "泡沫质地", "摇和", "冷饮"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "波本基底", "cocktailType": "酸型鸡尾酒", "flavor": "枫糖、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-honey-whiskey-sour', 'cocktail', 'COCKTAIL', '蜂蜜威士忌酸', 'Honey Whiskey Sour', 'fengmiweishijisuan', 'fmwsjs', '以威士忌、柠檬汁与蜂蜜调制的酸酒，蜂蜜的清甜柔和了烈酒棱角，入口顺滑、余韵带香。', 'V6 编辑标准化配方以蜂蜜替代单糖浆作为甜味剂，配以波本与柠檬汁，蛋清提升泡沫；在经典威士忌酸基础上调整，配比为编辑标准。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 168, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["酸型鸡尾酒", "威士忌基底", "蜂蜜", "酸甜", "泡沫质地", "摇和", "冷饮"]', '["经典", "开胃"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "蜂蜜、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典", "开胃"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 20, "unit": "ml", "role": "蜂蜜"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 15, "unit": "ml", "role": "提供泡沫"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰"}]', '["将摇壶与老式酒杯充分预冷。", "向摇壶加入波本、柠檬汁、蜂蜜与蛋清。", "不加冰干摇约 10 秒使蛋清起泡。", "加入约 100 g 冰块，用力摇和约 12 秒。", "滤入冰镇老式酒杯，以柠檬皮点缀。"]', '["蜂蜜酸酒", "Honey Whiskey Sour", "蜜糖威士忌酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-honey-whiskey-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蜂蜜威士忌酸", "nameEn": "Honey Whiskey Sour", "intro": "以威士忌、柠檬汁与蜂蜜调制的酸酒，蜂蜜的清甜柔和了烈酒棱角，入口顺滑、余韵带香。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["酸型鸡尾酒", "威士忌基底", "蜂蜜", "酸甜", "泡沫质地", "摇和", "冷饮"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "蜂蜜、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-ginger-whiskey', 'cocktail', 'COCKTAIL', '姜汁威士忌', 'Ginger Whiskey Highball', 'jiangzhiweishiji', 'jzwsj', '以波本威士忌与姜汁汽水直调的清凉高球，姜香微辛、气泡清爽，是轻松的日常畅饮之选。', 'V6 编辑标准化配方以波本为基底、姜汁汽水补足容量，属于直调高球家族；配比简单，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20im%20Collegium%20in%20T%C3%BCbingen.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20im%20Collegium%20in%20T%C3%BCbingen.jpg', 93, 169, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["威士忌基底", "姜味", "气泡感", "直调", "冷饮", "轻盈", "清爽", "日常"]', '["日常"]', '{"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "姜味", "abv": "中度＞10%～20%", "extra": ["姜汁汽水"], "scene": ["日常"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "姜汁汽水", "nameEn": "Ginger ale", "amount": 120, "unit": "ml", "role": "姜汁汽水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 150, "unit": "g", "role": "杯内冰块"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 10, "unit": "g", "role": "青柠角装饰"}]', '["在高球杯中加入约 150 g 冰块。", "倒入 45 ml 波本威士忌。", "沿杯壁缓慢补满 120 ml 姜汁汽水。", "用吧勺轻轻提拉一次混合。", "以青柠角夹于杯沿装饰后饮用。"]', '["威士忌姜汁", "Whiskey Ginger", "姜汁波本"]', 'B', '2026-08-04', 1, '{"id": "cocktail-ginger-whiskey", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "姜汁威士忌", "nameEn": "Ginger Whiskey Highball", "intro": "以波本威士忌与姜汁汽水直调的清凉高球，姜香微辛、气泡清爽，是轻松的日常畅饮之选。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Sour%20im%20Collegium%20in%20T%C3%BCbingen.jpg", "tags": ["威士忌基底", "姜味", "气泡感", "直调", "冷饮", "轻盈", "清爽", "日常"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "姜味", "abv": "中度＞10%～20%", "extra": ["姜汁汽水"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-spicy-margarita', 'cocktail', 'COCKTAIL', '辣椒玛格丽特', 'Spicy Margarita', 'lajiaomagelite', 'ljmglt', '以龙舌兰、橙味利口酒、青柠汁与辣酱调制的辛辣玛格丽特，酸辣明快、盐边提味，热感鲜明。', 'V6 编辑标准化配方在经典玛格丽特基础上加入辣酱并保留盐边，属于现代风味变体；非 IBA 官方配方，辣度与配比为编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Prickly%20Pear%20Spicy%20Margarita%20-%20January%202024%20-%20Sarah%20Stierch%2001.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Prickly%20Pear%20Spicy%20Margarita%20-%20January%202024%20-%20Sarah%20Stierch%2001.jpg', 93, 170, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 8.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["酸型鸡尾酒", "龙舌兰基底", "辛辣", "柑橘", "可选盐边", "摇和", "冷饮", "夏季"]', '["夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "辛辣、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "辣酱"], "scene": ["夏季"]}', '[{"nameZh": "100% 龙舌兰银龙舌兰酒", "nameEn": "100% agave blanco tequila", "amount": 45, "unit": "ml", "role": "100% 龙舌兰银龙舌兰酒"}, {"nameZh": "橙味利口酒", "nameEn": "Triple sec", "amount": 15, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 25, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 3, "unit": "ml", "role": "辣酱"}, {"nameZh": "盐边", "nameEn": "Salt rim", "amount": 5, "unit": "g", "role": "杯沿盐边"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "摇和用冰"}]', '["用青柠角润湿杯沿，将杯口在细海盐中滚一圈做盐边。", "将摇壶与玛格丽特杯充分预冷。", "向摇壶加入龙舌兰、橙味利口酒、青柠汁与辣酱。", "加入约 100 g 冰块，用力摇和约 12 秒。", "滤入盐边杯中，以青柠角点缀。"]', '["辣味玛格丽特", "Spicy Margarita", "墨西哥辣玛格丽特"]', 'A', '2026-08-04', 1, '{"id": "cocktail-spicy-margarita", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "辣椒玛格丽特", "nameEn": "Spicy Margarita", "intro": "以龙舌兰、橙味利口酒、青柠汁与辣酱调制的辛辣玛格丽特，酸辣明快、盐边提味，热感鲜明。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Prickly%20Pear%20Spicy%20Margarita%20-%20January%202024%20-%20Sarah%20Stierch%2001.jpg", "tags": ["酸型鸡尾酒", "龙舌兰基底", "辛辣", "柑橘", "可选盐边", "摇和", "冷饮", "夏季"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "辛辣、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "辣酱"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-smoked-old-fashioned', 'cocktail', 'COCKTAIL', '烟熏老式', 'Smoked Old Fashioned', 'yanxunlaoshi', 'yxls', '以波本威士忌、方糖与安格斯图拉苦精调制，杯口经烟熏处理的古典家族鸡尾酒，融合焦糖甜润、木质苦香与烟熏气息。', 'V6 编辑标准化配方以 60 ml 波本威士忌、1 颗方糖与 3 滴安格斯图拉苦精调制；烟熏采用苹果木在倒扣杯内燃烧挂香，不改变酒液配方，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 93, 171, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 0.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "苦味明显", "焦糖", "烟熏", "搅拌", "经典", "餐后", "烟熏呈现"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显、焦糖", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "40% ABV 波本威士忌"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 4, "unit": "g", "role": "方糖 1 颗"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 3, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮喷香装饰"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 60, "unit": "g", "role": "大冰球 1 颗"}]', '["将老式杯倒扣置于架子上，点燃一小片苹果木并让其冒烟后扣在杯口下方，静置约 1 分钟让烟雾附着杯壁。", "在杯中放入方糖并滴入安格斯图拉苦精，加 10 ml 水搅拌至方糖基本溶解。", "加入 60 ml 波本威士忌与一颗大冰球，轻搅约 10 秒至充分冰镇。", "以橙皮在杯口拧出香气并轻涂杯沿后投入杯中。", "盖上网盖维持烟雾短暂留香，随即取下并立即饮用。"]', '["Smoked Old Fashioned", "烟熏威士忌古典"]', 'A', '2026-08-04', 1, '{"id": "cocktail-smoked-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "烟熏老式", "nameEn": "Smoked Old Fashioned", "intro": "以波本威士忌、方糖与安格斯图拉苦精调制，杯口经烟熏处理的古典家族鸡尾酒，融合焦糖甜润、木质苦香与烟熏气息。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg", "tags": ["威士忌基底", "苦味明显", "焦糖", "烟熏", "搅拌", "经典", "餐后", "烟熏呈现"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显、焦糖", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sherry-manhattan', 'cocktail', 'COCKTAIL', '雪利酒曼哈顿', 'Sherry Manhattan', 'xuelijiumanhadun', 'xljmhd', '以波本威士忌、阿蒙蒂拉多雪利酒与安格斯图拉苦精调制的曼哈顿变奏，坚果氧化气息与深色烈酒交织，酒体饱满而收尾偏干。', 'V6 编辑标准化配方以 45 ml 波本威士忌与 25 ml 阿蒙蒂拉多雪利酒搅拌调制，替代传统甜味美思；雪利酒种类决定坚果与氧化表现，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20Cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20Cocktail.jpg', 93, 172, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "雪利酒基底", "偏干", "坚果", "搅拌", "经典", "餐后", "高强度"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "偏干、坚果", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "40% ABV 波本威士忌"}, {"nameZh": "阿蒙蒂拉多雪利酒", "nameEn": "Amontillado sherry", "amount": 25, "unit": "ml", "role": "阿蒙蒂拉多雪利酒"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "搅拌杯冰块"}, {"nameZh": "卢克索樱桃", "nameEn": "Luxardo cherry", "amount": 1, "unit": "piece", "role": "卢克索樱桃装饰"}]', '["在搅拌杯中放入约 60 g 冰块，加入 45 ml 波本威士忌。", "加入 25 ml 阿蒙蒂拉多雪利酒与 2 滴安格斯图拉苦精。", "以吧勺搅拌约 18 秒至充分冰镇。", "滤入冰镇的鸡尾酒杯。", "以一颗卢克索樱桃点缀后立即饮用。"]', '["Sherry Manhattan", "雪利曼哈顿"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sherry-manhattan", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "雪利酒曼哈顿", "nameEn": "Sherry Manhattan", "intro": "以波本威士忌、阿蒙蒂拉多雪利酒与安格斯图拉苦精调制的曼哈顿变奏，坚果氧化气息与深色烈酒交织，酒体饱满而收尾偏干。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Manhattan%20Cocktail.jpg", "tags": ["威士忌基底", "雪利酒基底", "偏干", "坚果", "搅拌", "经典", "餐后", "高强度"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "偏干、坚果", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sherry-old-fashioned', 'cocktail', 'COCKTAIL', '雪利酒古典', 'Sherry Old Fashioned', 'xuelijiugudian', 'xljgd', '以波本威士忌、阿蒙蒂拉多雪利酒、方糖与苦精调制的古典变奏，保留糖苦骨架，叠加雪利酒的坚果与氧化香气。', 'V6 编辑标准化配方在传统古典基础上以 10 ml 阿蒙蒂拉多雪利酒增强香气并微微收干甜度，主体仍是 50 ml 波本威士忌与方糖、安格斯图拉苦精，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 91, 173, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 0.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "雪利酒基底", "坚果", "焦糖", "搅拌", "经典", "餐后"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "坚果、焦糖", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 50, "unit": "ml", "role": "40% ABV 波本威士忌"}, {"nameZh": "阿蒙蒂拉多雪利酒", "nameEn": "Amontillado sherry", "amount": 10, "unit": "ml", "role": "阿蒙蒂拉多雪利酒"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 4, "unit": "g", "role": "方糖 1 颗"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 3, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮喷香装饰"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 60, "unit": "g", "role": "大冰球 1 颗"}]', '["在老式杯中放入方糖，滴入安格斯图拉苦精并加 10 ml 水，搅拌至方糖溶解。", "加入 50 ml 波本威士忌与 10 ml 阿蒙蒂拉多雪利酒。", "放入一颗大冰球，轻搅约 10 秒至充分冰镇。", "以橙皮在杯口拧出香气并投入杯中。", "立即饮用。"]', '["Sherry Old Fashioned", "雪利古典"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sherry-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "雪利酒古典", "nameEn": "Sherry Old Fashioned", "intro": "以波本威士忌、阿蒙蒂拉多雪利酒、方糖与苦精调制的古典变奏，保留糖苦骨架，叠加雪利酒的坚果与氧化香气。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg", "tags": ["威士忌基底", "雪利酒基底", "坚果", "焦糖", "搅拌", "经典", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "坚果、焦糖", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bourbon-sweet-tea', 'cocktail', 'COCKTAIL', '波本甜茶', 'Bourbon Sweet Tea', 'bobentiancha', 'bbtc', '以波本威士忌与甜味红茶加冰块直调的南方风格高球，红茶醇厚、柠檬清香与波本的焦糖甜润在冰爽中融合。', 'V6 编辑标准化配方以 45 ml 波本威士忌兑 150 ml 冷甜红茶直调，甜度来自约 10 g 细砂糖；红茶与波本品牌会明显改变风味，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Oxford%20glass%20of%20sweet%20tea%202.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Oxford%20glass%20of%20sweet%20tea%202.jpg', 93, 174, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["威士忌基底", "冷饮", "甜感明显", "果香", "直调", "夏季", "日常", "含咖啡因"]', '["夏季", "日常"]', '{"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "甜感明显、果香", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "红茶液"], "scene": ["夏季", "日常"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "40% ABV 波本威士忌"}, {"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 150, "unit": "ml", "role": "冷藏甜红茶"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 10, "unit": "g", "role": "细砂糖 2 小勺"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 5, "unit": "ml", "role": "新鲜柠檬汁提亮"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "高球杯冰块"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "柠檬片装饰"}]', '["将 2 小勺细砂糖用 20 ml 热红茶溶解后与冷藏红茶液混合成甜红茶。", "在高球杯中加满冰块，倒入 45 ml 波本威士忌。", "注入 150 ml 甜红茶与 5 ml 新鲜柠檬汁。", "轻搅约 8 秒至均匀冰镇。", "以柠檬片装饰后立即饮用。"]', '["Bourbon Sweet Tea", "波本冰茶"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bourbon-sweet-tea", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波本甜茶", "nameEn": "Bourbon Sweet Tea", "intro": "以波本威士忌与甜味红茶加冰块直调的南方风格高球，红茶醇厚、柠檬清香与波本的焦糖甜润在冰爽中融合。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Oxford%20glass%20of%20sweet%20tea%202.jpg", "tags": ["威士忌基底", "冷饮", "甜感明显", "果香", "直调", "夏季", "日常", "含咖啡因"], "scene": ["夏季", "日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "甜感明显、果香", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "红茶液"], "scene": ["夏季", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gimlet', 'cocktail', 'COCKTAIL', '吉姆雷特', 'Gimlet', 'jimuleite', 'jmlt', '以伦敦干金酒与新鲜青柠汁调制的清爽酸型鸡尾酒，金酒草本骨架配明亮柑橘酸度，口感干净利落。', 'V6 编辑标准化配方按金酒与青柠汁 3:1 摇和，并以 5 ml 1:1 单糖浆平衡酸度；采用新鲜青柠汁而非青柠利口酒，风味更清新，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gimlet%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gimlet%20cocktail.jpg', 93, 175, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "酸型鸡尾酒", "冷饮", "柑橘", "摇和", "经典", "无麸质", "低强度"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 60, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "摇和用冰块"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 1, "unit": "piece", "role": "青柠片装饰"}]', '["将鸡尾酒杯提前冰镇。", "摇酒壶中加冰，倒入 60 ml 伦敦干金酒与 20 ml 新鲜青柠汁。", "加入 5 ml 1:1 单糖浆，用力摇和约 10 秒至充分降温。", "滤入冰镇鸡尾酒杯。", "以青柠片置于杯沿装饰后立即饮用。"]', '["Gimlet", "金酒青柠"]', 'B', '2026-08-04', 1, '{"id": "cocktail-gimlet", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "吉姆雷特", "nameEn": "Gimlet", "intro": "以伦敦干金酒与新鲜青柠汁调制的清爽酸型鸡尾酒，金酒草本骨架配明亮柑橘酸度，口感干净利落。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Gimlet%20cocktail.jpg", "tags": ["金酒基底", "酸型鸡尾酒", "冷饮", "柑橘", "摇和", "经典", "无麸质", "低强度"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sazerac-classic', 'cocktail', 'COCKTAIL', '萨泽拉克经典', 'Sazerac', 'sazelakejingdian', 'szlkjd', '以黑麦威士忌、干邑、方糖、佩肖苦精调制，并以苦艾酒冲洗杯壁的经典烈酒鸡尾酒，茴香冷香与木质辛香层层展开。', 'V6 编辑标准化配方以 45 ml 黑麦威士忌与 15 ml 干邑为基，方糖与佩肖苦精增甜增香，苦艾酒仅冲洗杯壁；ABV 为编辑估算值，与经典新奥尔良做法一致。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg', 93, 176, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 0.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["黑麦基底", "干邑基底", "苦感主导", "茴香", "搅拌", "经典", "餐后", "高强度"]', '["经典", "餐后"]', '{"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦感主导、茴香", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 45, "unit": "ml", "role": "40% ABV 黑麦威士忌"}, {"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 15, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 4, "unit": "g", "role": "方糖 1 颗"}, {"nameZh": "佩肖苦精", "nameEn": "Peychaud\'s bitters", "amount": 3, "unit": "dash", "role": "佩肖苦精"}, {"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 5, "unit": "ml", "role": "用于冲洗杯壁"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮喷香装饰"}]', '["在搅拌杯中放入方糖，滴入佩肖苦精并加 10 ml 水，搅拌至方糖溶解。", "加入 45 ml 黑麦威士忌与 15 ml 干邑，加冰搅拌约 20 秒。", "在预冷的老式杯中倒入 5 ml 苦艾酒，旋转杯壁后倒出多余酒液。", "将调好的酒液滤入经苦艾酒冲洗的杯中。", "以柠檬皮拧出香气后投入杯中，立即饮用。"]', '["Sazerac", "经典萨泽拉克"]', 'A', '2026-08-04', 1, '{"id": "cocktail-sazerac-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "萨泽拉克经典", "nameEn": "Sazerac", "intro": "以黑麦威士忌、干邑、方糖、佩肖苦精调制，并以苦艾酒冲洗杯壁的经典烈酒鸡尾酒，茴香冷香与木质辛香层层展开。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg", "tags": ["黑麦基底", "干邑基底", "苦感主导", "茴香", "搅拌", "经典", "餐后", "高强度"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦感主导、茴香", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-singapore-sling-classic', 'cocktail', 'COCKTAIL', '新加坡司令经典', 'Singapore Sling', 'xinjiaposilingjingdian', 'xjpsljd', '以伦敦干金酒、樱桃白兰地与菠萝汁等调制的长饮鸡尾酒，果香浓郁、气泡轻盈，是新加坡莱佛士酒店风格的代表。', 'V6 编辑标准化配方按莱佛士风格以金酒为基，配樱桃白兰地、班尼狄克汀、君度、菠萝汁、青柠汁与苏打水，并以石榴糖浆调色；ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg', 93, 177, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "果香", "热带水果", "酸甜", "气泡感", "摇和", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "樱桃白兰地利口酒", "nameEn": "Cherry brandy liqueur", "amount": 15, "unit": "ml", "role": "樱桃白兰地利口酒"}, {"nameZh": "班尼狄克汀", "nameEn": "Bénédictine", "amount": 7.5, "unit": "ml", "role": "班尼狄克汀"}, {"nameZh": "君度橙酒", "nameEn": "Cointreau", "amount": 7.5, "unit": "ml", "role": "君度橙酒"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 120, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 10, "unit": "ml", "role": "石榴糖浆调色"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 40, "unit": "ml", "role": "最后补足气泡"}]', '["高球杯中加满冰块。", "摇壶中加入金酒、樱桃白兰地、班尼狄克汀、君度、菠萝汁与青柠汁。", "加入冰块摇和 10 秒后滤入高球杯。", "沿杯壁补入苏打水并轻搅。", "滴入石榴糖浆调色，以菠萝块与樱桃装饰后饮用。"]', '["Singapore Sling", "经典新加坡司令"]', 'A', '2026-08-04', 1, '{"id": "cocktail-singapore-sling-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "新加坡司令经典", "nameEn": "Singapore Sling", "intro": "以伦敦干金酒、樱桃白兰地与菠萝汁等调制的长饮鸡尾酒，果香浓郁、气泡轻盈，是新加坡莱佛士酒店风格的代表。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg", "tags": ["金酒基底", "冷饮", "果香", "热带水果", "酸甜", "气泡感", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-hurricane-classic', 'cocktail', 'COCKTAIL', '飓风经典', 'Hurricane', 'jufengjingdian', 'jfjd', '以黑白朗姆酒、百香果与青柠汁调制的提基长饮，浓郁果甜与酸度并存，盛于高脚飓风杯，是纽奥良风情的代表。', 'V6 编辑标准化配方以 30 ml 白朗姆与 60 ml 黑朗姆为基，配百香果汁、青柠汁与 1:1 单糖浆；果味与酸度平衡，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Hurricane%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Hurricane%20cocktail.jpg', 93, 178, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "百香果", "热带水果", "酸甜", "摇和", "经典", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "百香果、热带水果", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁", "新鲜青柠汁"], "scene": ["经典", "夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 30, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 60, "unit": "ml", "role": "黑朗姆酒"}, {"nameZh": "百香果汁", "nameEn": "Passion fruit juice", "amount": 30, "unit": "ml", "role": "百香果汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 30, "unit": "ml", "role": "新鲜橙汁"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 1, "unit": "piece", "role": "橙片装饰"}]', '["在摇壶中加入白朗姆、黑朗姆、百香果汁、青柠汁、橙汁与单糖浆。", "加入冰块用力摇和约 12 秒。", "滤入盛有碎冰的飓风杯中。", "补入碎冰至杯口。", "以橙片与樱桃装饰后立即饮用。"]', '["Hurricane", "经典飓风"]', 'A', '2026-08-04', 1, '{"id": "cocktail-hurricane-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "飓风经典", "nameEn": "Hurricane", "intro": "以黑白朗姆酒、百香果与青柠汁调制的提基长饮，浓郁果甜与酸度并存，盛于高脚飓风杯，是纽奥良风情的代表。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Hurricane%20cocktail.jpg", "tags": ["朗姆基底", "冷饮", "百香果", "热带水果", "酸甜", "摇和", "经典", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "百香果、热带水果", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁", "新鲜青柠汁"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-jungle-bird-classic', 'cocktail', 'COCKTAIL', '丛林鸟经典', 'Jungle Bird', 'conglinniaojingdian', 'clnjd', '以黑朗姆、菠萝汁、青柠汁与金巴利调制的提基鸡尾酒，热带果甜与草药苦味交织，是朗姆与金巴利的经典碰撞。', 'V6 编辑标准化配方以 45 ml 黑朗姆、45 ml 菠萝汁、15 ml 青柠汁、15 ml 金巴利与 5 ml 1:1 单糖浆摇和；苦甜平衡，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Jungle%20Bird.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Jungle%20Bird.jpg', 93, 179, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["朗姆基底", "冷饮", "苦感主导", "菠萝", "草本", "摇和", "经典", "热带水果"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "苦感主导、菠萝", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": ["经典"]}', '[{"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 45, "unit": "ml", "role": "黑朗姆酒"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 45, "unit": "ml", "role": "菠萝汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 15, "unit": "ml", "role": "金巴利"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 1, "unit": "piece", "role": "青柠片装饰"}]', '["在摇壶中加入黑朗姆、菠萝汁、青柠汁、金巴利与单糖浆。", "加入冰块摇和约 12 秒至充分降温。", "滤入盛满冰块的老式杯。", "以菠萝叶与青柠角装饰。", "立即饮用。"]', '["Jungle Bird", "经典丛林鸟"]', 'A', '2026-08-04', 1, '{"id": "cocktail-jungle-bird-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "丛林鸟经典", "nameEn": "Jungle Bird", "intro": "以黑朗姆、菠萝汁、青柠汁与金巴利调制的提基鸡尾酒，热带果甜与草药苦味交织，是朗姆与金巴利的经典碰撞。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Jungle%20Bird.jpg", "tags": ["朗姆基底", "冷饮", "苦感主导", "菠萝", "草本", "摇和", "经典", "热带水果"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "苦感主导、菠萝", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "菠萝汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-maroc', 'cocktail', 'COCKTAIL', '莫罗科', 'Maroc', 'moluoke', 'mlk', '以金酒与丽莱白葡萄酒调制的干型马天尼变奏，花香与柑橘气息轻盈，口感清冽，是丽莱风格的经典开胃鸡尾酒。', 'V6 编辑标准化配方按金酒与丽莱白葡萄酒约 2:1 搅拌，干型结构突出药草与花香；丽莱白葡萄酒品牌版本会影响甜度与香气，ABV 为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Vesper%20Cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Vesper%20Cocktail.jpg', 93, 180, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "花香", "柑橘", "偏干", "搅拌", "开胃", "经典", "轻盈"]', '["开胃", "经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、柑橘", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 50, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "丽莱白葡萄酒", "nameEn": "Lillet Blanc", "amount": 25, "unit": "ml", "role": "丽莱白葡萄酒"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 1, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "搅拌杯冰块"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮喷香装饰"}]', '["在搅拌杯中放入约 60 g 冰块，加入 50 ml 伦敦干金酒。", "加入 25 ml 丽莱白葡萄酒与 1 滴橙味苦精。", "以吧勺搅拌约 15 秒至充分冰镇。", "滤入冰镇的鸡尾酒杯。", "以柠檬皮拧出香气后投入杯中，立即饮用。"]', '["Maroc", "摩洛哥鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-maroc", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "莫罗科", "nameEn": "Maroc", "intro": "以金酒与丽莱白葡萄酒调制的干型马天尼变奏，花香与柑橘气息轻盈，口感清冽，是丽莱风格的经典开胃鸡尾酒。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Vesper%20Cocktail.jpg", "tags": ["金酒基底", "花香", "柑橘", "偏干", "搅拌", "开胃", "经典", "轻盈"], "scene": ["开胃", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "花香、柑橘", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-west-wind', 'cocktail', 'COCKTAIL', '西风', 'West Wind', 'xifeng', 'xf', '以干邑为基底、配橙味利口酒与苦精、保留浓烈酒感的古典系鸡尾酒，柑橘香气清亮、甜苦平衡，是偏烈型的干邑调制酒。', 'V6 编辑标准化配方以干邑为烈酒基底，加入橙味利口酒与橙味苦精平衡甜苦，采用古典杯直调；配方与数值为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 181, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["干邑基底", "搅拌", "苦味明显", "柑橘", "高强度", "经典", "偏干"]', '["经典"]', '{"baseSpirit": "干邑基底", "cocktailType": "古典家族", "flavor": "苦味明显、柑橘", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 45, "unit": "ml", "role": "40% 干邑白兰地"}, {"nameZh": "橙味库拉索", "nameEn": "Orange curaçao", "amount": 15, "unit": "ml", "role": "橙味库拉索"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 2, "unit": "g", "role": "橙皮装饰"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "搅拌用冰块"}]', '["将古典杯充分预冷。", "在搅拌杯中加入 45 ml 干邑、15 ml 橙味库拉索与 2 滴苦精。", "加入约 60 g 冰块，搅拌约 20 秒。", "滤入冰镇的古典杯。", "以橙皮拧出香气后轻放杯中点缀。"]', '["西风鸡尾酒", "West Wind Cocktail", "白兰地西风"]', 'B', '2026-08-04', 1, '{"id": "cocktail-west-wind", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "西风", "nameEn": "West Wind", "intro": "以干邑为基底、配橙味利口酒与苦精、保留浓烈酒感的古典系鸡尾酒，柑橘香气清亮、甜苦平衡，是偏烈型的干邑调制酒。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["干邑基底", "搅拌", "苦味明显", "柑橘", "高强度", "经典", "偏干"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "干邑基底", "cocktailType": "古典家族", "flavor": "苦味明显、柑橘", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cognac-highball', 'cocktail', 'COCKTAIL', '干邑高球', 'Cognac Highball', 'ganyigaoqiu', 'gygq', '以干邑为基底、加苏打水与柠檬皮组成的高球型长饮，气泡轻盈、干邑果香舒展，口感清冽易饮，是适合日常的低甜度长饮。', 'V6 编辑标准化配方参照苏格兰高球结构，以干邑替换威士忌并搭配苏打水，用柠檬皮增添清新，属高球家族；酒精与数值为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 182, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["干邑基底", "冷饮", "直调", "气泡感", "低糖", "日常", "清爽"]', '["日常"]', '{"baseSpirit": "干邑基底", "cocktailType": "高球", "flavor": "风味均衡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["日常"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 45, "unit": "ml", "role": "40% 干邑白兰地"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 90, "unit": "ml", "role": "冰镇苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "杯用冰块"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 2, "unit": "g", "role": "柠檬皮装饰"}]', '["在高球杯中填入约 100 g 冰块。", "倒入 45 ml 干邑。", "补入约 90 ml 冰镇苏打水。", "用吧勺轻提一次使酒液混合。", "以柠檬皮拧出香气后轻放杯中点缀。"]', '["干邑苏打", "Cognac Soda", "干邑高杯"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cognac-highball", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "干邑高球", "nameEn": "Cognac Highball", "intro": "以干邑为基底、加苏打水与柠檬皮组成的高球型长饮，气泡轻盈、干邑果香舒展，口感清冽易饮，是适合日常的低甜度长饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["干邑基底", "冷饮", "直调", "气泡感", "低糖", "日常", "清爽"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "干邑基底", "cocktailType": "高球", "flavor": "风味均衡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-brandy-highball', 'cocktail', 'COCKTAIL', '白兰地高球', 'Brandy Highball', 'bailandigaoqiu', 'bldgq', '以白兰地为基底、加苏打水与柠檬组成的高球型长饮，酒香圆润、气泡轻盈，口感顺滑清冽，是易饮的日常低甜度长饮。', 'V6 编辑标准化配方参照高球家族结构，以白兰地搭配苏打水并辅以柠檬，酒体较干邑柔和；酒精与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 91, 183, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["白兰地基底", "冷饮", "直调", "气泡感", "低糖", "日常", "清爽"]', '["日常"]', '{"baseSpirit": "白兰地基底", "cocktailType": "高球", "flavor": "风味均衡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["日常"]}', '[{"nameZh": "白兰地", "nameEn": "Brandy", "amount": 45, "unit": "ml", "role": "40% 白兰地"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 90, "unit": "ml", "role": "冰镇苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "杯用冰块"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 2, "unit": "g", "role": "柠檬皮装饰"}]', '["在高球杯中填入约 100 g 冰块。", "倒入 45 ml 白兰地。", "补入约 90 ml 冰镇苏打水。", "用吧勺轻提一次使酒液混合。", "以柠檬皮拧出香气后轻放杯中点缀。"]', '["白兰地苏打", "Brandy Soda", "白兰地高杯"]', 'B', '2026-08-04', 1, '{"id": "cocktail-brandy-highball", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白兰地高球", "nameEn": "Brandy Highball", "intro": "以白兰地为基底、加苏打水与柠檬组成的高球型长饮，酒香圆润、气泡轻盈，口感顺滑清冽，是易饮的日常低甜度长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["白兰地基底", "冷饮", "直调", "气泡感", "低糖", "日常", "清爽"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "高球", "flavor": "风味均衡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cognac-coke', 'cocktail', 'COCKTAIL', '干邑可乐', 'Cognac and Coke', 'ganyikele', 'gykl', '以干邑与可乐组成的高球型长饮，干邑果香与可乐焦糖甜碰撞，气泡密集、口感甜润清爽，是轻松易饮的日常调饮。', 'V6 编辑标准化配方参照自由古巴结构，以干邑替换朗姆并搭配可乐，可乐含咖啡因故标注含咖啡因；酒精与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 91, 184, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["干邑基底", "冷饮", "甜感明显", "气泡感", "直调", "含咖啡因", "日常"]', '["日常"]', '{"baseSpirit": "干邑基底", "cocktailType": "高球", "flavor": "甜感明显", "abv": "中度＞10%～20%", "extra": ["可乐"], "scene": ["日常"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 45, "unit": "ml", "role": "40% 干邑白兰地"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 120, "unit": "ml", "role": "冰镇可乐"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "杯用冰块"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 8, "unit": "g", "role": "青柠角装饰"}]', '["在高球杯中填入约 100 g 冰块。", "倒入 45 ml 干邑。", "补入约 120 ml 冰镇可乐。", "用吧勺轻提一次使酒液混合。", "饰以青柠角后立即饮用。"]', '["干邑可乐调饮", "Cognac Coke", "干邑可乐高杯"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cognac-coke", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "干邑可乐", "nameEn": "Cognac and Coke", "intro": "以干邑与可乐组成的高球型长饮，干邑果香与可乐焦糖甜碰撞，气泡密集、口感甜润清爽，是轻松易饮的日常调饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["干邑基底", "冷饮", "甜感明显", "气泡感", "直调", "含咖啡因", "日常"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "干邑基底", "cocktailType": "高球", "flavor": "甜感明显", "abv": "中度＞10%～20%", "extra": ["可乐"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cognac-tonic', 'cocktail', 'COCKTAIL', '干邑汤力', 'Cognac Tonic', 'ganyitangli', 'gytl', '以干邑与汤力水组成的高球型长饮，汤力水的草本苦甜托起干邑果香，气泡清冽、口感偏干带苦，是清爽的开胃系长饮。', 'V6 编辑标准化配方参照金汤力结构，以干邑替换金酒并搭配汤力水，用青柠角提亮；酒精与数值为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 185, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["干邑基底", "冷饮", "草本", "气泡感", "苦味明显", "直调", "低糖"]', '["夏季", "经典"]', '{"baseSpirit": "干邑基底", "cocktailType": "高球", "flavor": "草本、苦味明显", "abv": "中度＞10%～20%", "extra": ["汤力水"], "scene": ["夏季", "经典"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 45, "unit": "ml", "role": "40% 干邑白兰地"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 120, "unit": "ml", "role": "冰镇汤力水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "杯用冰块"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 8, "unit": "g", "role": "青柠角装饰"}]', '["在高球杯中填入约 100 g 冰块。", "倒入 45 ml 干邑。", "补入约 120 ml 冰镇汤力水。", "用吧勺轻提一次使酒液混合。", "挤入青柠角汁液后将青柠角投入杯中。"]', '["干邑汤力水调饮", "Cognac and Tonic", "干邑汤力高杯"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cognac-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "干邑汤力", "nameEn": "Cognac Tonic", "intro": "以干邑与汤力水组成的高球型长饮，汤力水的草本苦甜托起干邑果香，气泡清冽、口感偏干带苦，是清爽的开胃系长饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["干邑基底", "冷饮", "草本", "气泡感", "苦味明显", "直调", "低糖"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "干邑基底", "cocktailType": "高球", "flavor": "草本、苦味明显", "abv": "中度＞10%～20%", "extra": ["汤力水"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-campari-negroni', 'cocktail', 'COCKTAIL', '金巴利内格罗尼', 'Campari Negroni', 'jinbalineigeluoni', 'jblngln', '以金巴利加量为核心的内格罗尼变体，金酒、金巴利与甜味美思的等量结构强化苦甜与橘香，烈感扎实，是苦甜并重的开胃鸡尾酒。', 'V6 编辑标准化配方在经典内格罗尼基础上提高金巴利占比，突出橘皮苦香，仍采用古典杯搅拌；酒精与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 91, 186, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 9.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["金酒基底", "搅拌", "苦感主导", "开胃", "高强度", "草本", "经典"]', '["开胃", "经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 30, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 35, "unit": "ml", "role": "金巴利"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 25, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "搅拌用冰块"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 2, "unit": "g", "role": "橙皮装饰"}]', '["将古典杯充分预冷。", "在搅拌杯中加入 30 ml 金酒、35 ml 金巴利与 25 ml 甜红味美思。", "加入约 80 g 冰块，搅拌约 20 秒。", "滤入冰镇的古典杯。", "以橙皮拧出香气后轻放杯中点缀。"]', '["金巴利尼格罗尼", "Campari Negroni", "金巴利古典尼格罗尼"]', 'B', '2026-08-04', 1, '{"id": "cocktail-campari-negroni", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金巴利内格罗尼", "nameEn": "Campari Negroni", "intro": "以金巴利加量为核心的内格罗尼变体，金酒、金巴利与甜味美思的等量结构强化苦甜与橘香，烈感扎实，是苦甜并重的开胃鸡尾酒。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["金酒基底", "搅拌", "苦感主导", "开胃", "高强度", "草本", "经典"], "scene": ["开胃", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-absinthe-drip', 'cocktail', 'COCKTAIL', '苦艾酒', 'Absinthe Drip', 'kuaijiu', 'kaj', '以苦艾酒加冰水逐滴冲释的经典饮法，茴香与草本气息随乳浊效应舒展，甜感清淡、酒感集中，是专注体验草本烈酒的古典形式。', 'V6 编辑标准化配方采用传统滴水法，以冰水慢释苦艾酒并观察乳浊现象，糖与冰水用量为编辑建议；酒精与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg', 91, 187, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 10.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["茴香", "草本", "搅拌", "高强度", "偏干", "经典", "长时间制作"]', '["经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "茴香、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 30, "unit": "ml", "role": "苦艾酒"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 45, "unit": "ml", "role": "冰镇过滤水"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 1, "unit": "piece", "role": "方糖"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 50, "unit": "g", "role": "冷却用水"}]', '["将方糖置于滴杯槽中。", "向杯中倒入 30 ml 苦艾酒。", "用滴壶以约 1 滴每秒的速度滴入约 45 ml 冰镇过滤水，使其缓慢析出乳浊。", "待水全部滴完、乳浊充分后轻搅至糖溶。", "立即饮用并留意其高酒精度。"]', '["苦艾酒古典饮法", "Absinthe Drip", "苦艾水滴法"]', 'B', '2026-08-04', 1, '{"id": "cocktail-absinthe-drip", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "苦艾酒", "nameEn": "Absinthe Drip", "intro": "以苦艾酒加冰水逐滴冲释的经典饮法，茴香与草本气息随乳浊效应舒展，甜感清淡、酒感集中，是专注体验草本烈酒的古典形式。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Sazerac%20Cocktail.jpg", "tags": ["茴香", "草本", "搅拌", "高强度", "偏干", "经典", "长时间制作"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "茴香、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pastis', 'cocktail', 'COCKTAIL', '茴香酒', 'Pastis', 'huixiangjiu', 'hxj', '以茴香利口酒加水冲释的法国经典饮法，加水后呈现乳浊、茴香与甘草甜感柔和，冰爽易饮，是夏日常见的低度草本长饮。', 'V6 编辑标准化配方以山布卡茴香利口酒替代 Pastis 并加水冲释，呈乳浊效果；本条目为编辑近似，实际以法国 Pastis 品牌为准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Pastis.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Pastis.jpg', 91, 188, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["茴香", "草本", "直调", "冷饮", "甜感明显", "夏季", "清爽"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "茴香、草本", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["夏季"]}', '[{"nameZh": "山布卡茴香利口酒", "nameEn": "Sambuca", "amount": 30, "unit": "ml", "role": "山布卡茴香利口酒（近似 Pastis）"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 120, "unit": "ml", "role": "冰镇过滤水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "杯用冰块"}]', '["在高球杯中填入约 100 g 冰块。", "倒入 30 ml 山布卡茴香利口酒。", "缓慢加入约 120 ml 冰镇过滤水，观察乳浊现象。", "用吧勺轻搅一次使乳浊均匀。", "稍候片刻，待乳浊稳定后饮用。"]', '["法国茴香酒", "Pastis", "茴香高杯饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-pastis", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "茴香酒", "nameEn": "Pastis", "intro": "以茴香利口酒加水冲释的法国经典饮法，加水后呈现乳浊、茴香与甘草甜感柔和，冰爽易饮，是夏日常见的低度草本长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Pastis.jpg", "tags": ["茴香", "草本", "直调", "冷饮", "甜感明显", "夏季", "清爽"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "茴香、草本", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-ouzo', 'cocktail', 'COCKTAIL', '乌佐', 'Ouzo', 'wuzuo', 'wz', '以茴香烈酒加水或冰冲释的希腊经典饮法，加水即现乳浊，茴香与草本气息浓烈、口感带明显酒精感，是地中海风情的强草本长饮。', 'V6 编辑标准化配方以山布卡茴香利口酒替代乌佐并加水冲释，乳浊与草本走向相近；本条目为编辑近似，实际以希腊乌佐品牌为准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Ouzo.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Ouzo.jpg', 91, 189, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["茴香", "草本", "直调", "冷饮", "苦味明显", "中等强度", "夏季"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "茴香、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["夏季"]}', '[{"nameZh": "山布卡茴香利口酒", "nameEn": "Sambuca", "amount": 40, "unit": "ml", "role": "山布卡茴香利口酒（近似乌佐）"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "杯用冰块"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 45, "unit": "ml", "role": "冰镇过滤水"}]', '["在古典杯中放入约 60 g 冰块。", "倒入 40 ml 山布卡茴香利口酒。", "缓慢加入约 45 ml 冰镇过滤水，观察乳浊现象。", "轻搅一次使乳浊均匀。", "待乳浊稳定后饮用。"]', '["希腊茴香烈酒", "Ouzo", "乌佐冰水饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-ouzo", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "乌佐", "nameEn": "Ouzo", "intro": "以茴香烈酒加水或冰冲释的希腊经典饮法，加水即现乳浊，茴香与草本气息浓烈、口感带明显酒精感，是地中海风情的强草本长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Ouzo.jpg", "tags": ["茴香", "草本", "直调", "冷饮", "苦味明显", "中等强度", "夏季"], "scene": ["夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "茴香、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mint-julep-classic', 'cocktail', 'COCKTAIL', '薄荷朱利普经典', 'Mint Julep Classic', 'bohezhulipujingdian', 'bhzlpjd', '以波本威士忌、薄荷与糖浆组成的经典朱利普，薄荷清凉、波本温润、甜感克制，加碎冰呈霜杯呈现，是美式经典烈酒长饮。', 'V6 编辑标准化配方采用传统朱利普结构：波本配薄荷与单糖浆，以碎冰压实并形成杯壁结霜；配方与数值为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Mint_Julep2.jpg', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Mint_Julep2.jpg', 93, 190, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["威士忌基底", "薄荷", "冷饮", "直调", "草本", "夏季", "经典", "高强度"]', '["夏季", "经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["夏季", "经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 8, "unit": "piece", "role": "薄荷叶"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 150, "unit": "g", "role": "碎冰"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 3, "unit": "piece", "role": "薄荷枝装饰"}]', '["在朱利普杯中加入 8 片薄荷叶与 10 ml 单糖浆，用捣棒轻压出香。", "倒入 60 ml 波本威士忌。", "填满碎冰并以吧勺持续搅拌至杯壁结霜。", "再堆加碎冰至杯口呈圆顶状。", "饰以薄荷枝，插入吸管后立即饮用。"]', '["经典薄荷朱利普", "Classic Mint Julep", "传统薄荷朱利普"]', 'B', '2026-08-04', 1, '{"id": "cocktail-mint-julep-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "薄荷朱利普经典", "nameEn": "Mint Julep Classic", "intro": "以波本威士忌、薄荷与糖浆组成的经典朱利普，薄荷清凉、波本温润、甜感克制，加碎冰呈霜杯呈现，是美式经典烈酒长饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/19/Mint_Julep2.jpg", "tags": ["威士忌基底", "薄荷", "冷饮", "直调", "草本", "夏季", "经典", "高强度"], "scene": ["夏季", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-southern-cross', 'cocktail', 'COCKTAIL', '南十字', 'Southern Cross', 'nanshizi', 'nsz', '以伦敦干金酒与干味美思调制、缀以橙味苦精的烈酒风格鸡尾酒，柑橘与药草气息交织，口感干爽紧致，是追求经典马天尼精神的短饮。', 'V6 编辑标准化配方采用伦敦干金酒、干白味美思与橙味苦精按 45:20:2 搅拌调制；属经典马天尼风格的自由演绎，烈酒与味美思比例会影响苦度与草本表现，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/a/aa/Alan_Schaaf%2C_Imgur_Founder%2C_in_Wellington_for_TEDxWellington_%26_more_%2814935290219%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/a/aa/Alan_Schaaf%2C_Imgur_Founder%2C_in_Wellington_for_TEDxWellington_%26_more_%2814935290219%29.jpg', 91, 191, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["烈酒主导", "金酒基底", "搅拌", "冷饮", "偏干", "经典", "高强度"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 20, "unit": "ml", "role": "干白味美思"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "搅拌杯冰块"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮喷香装饰"}]', '["在搅拌杯中放入约 60 g 冰块，加入 45 ml 伦敦干金酒。", "加入 20 ml 干白味美思与 2 滴橙味苦精。", "以吧勺搅拌约 15 秒至充分冰镇。", "滤入冰镇的马天尼杯。", "以柠檬皮在杯口喷香后投入杯中。"]', '["Southern Cross", "南十字星"]', 'B', '2026-08-04', 1, '{"id": "cocktail-southern-cross", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "南十字", "nameEn": "Southern Cross", "intro": "以伦敦干金酒与干味美思调制、缀以橙味苦精的烈酒风格鸡尾酒，柑橘与药草气息交织，口感干爽紧致，是追求经典马天尼精神的短饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/aa/Alan_Schaaf%2C_Imgur_Founder%2C_in_Wellington_for_TEDxWellington_%26_more_%2814935290219%29.jpg", "tags": ["烈酒主导", "金酒基底", "搅拌", "冷饮", "偏干", "经典", "高强度"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-moonlight', 'cocktail', 'COCKTAIL', '月亮酒', 'Moonlight', 'yueliangjiu', 'ylj', '以伏特加、新鲜柠檬汁与蜂蜜兑入气泡水调制的高球鸡尾酒，酸甜柔润、带蜂蜜甜香与细密气泡，口感清爽顺喉，适合轻松的日常长饮。', 'V6 编辑标准化配方以伏特加 50 ml、柠檬汁 15 ml、蜂蜜 10 ml 与气泡水 60 ml 直调，气泡水补足；蜂蜜甜度随品种变化，酒精度为编辑估算值，属非 IBA 的编辑饮品。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 93, 192, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["伏特加基底", "冷饮", "蜂蜜", "柑橘", "清爽", "直调", "日常", "中等强度"]', '["日常"]', '{"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["日常"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "g", "role": "蜂蜜"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 60, "unit": "ml", "role": "气泡水补足"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "柠檬片装饰"}]', '["在高球杯中放入冰块，加入 50 ml 伏特加。", "加入 15 ml 新鲜柠檬汁与 10 g 蜂蜜，搅拌至蜂蜜完全化开。", "补入约 60 ml 冰镇气泡水。", "轻轻搅拌一次，以柠檬片装饰。"]', '["Moonlight", "月光"]', 'B', '2026-08-04', 1, '{"id": "cocktail-moonlight", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "月亮酒", "nameEn": "Moonlight", "intro": "以伏特加、新鲜柠檬汁与蜂蜜兑入气泡水调制的高球鸡尾酒，酸甜柔润、带蜂蜜甜香与细密气泡，口感清爽顺喉，适合轻松的日常长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["伏特加基底", "冷饮", "蜂蜜", "柑橘", "清爽", "直调", "日常", "中等强度"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-spirit-lemonade', 'cocktail', 'COCKTAIL', '烈酒柠檬水', 'Spirit Lemonade', 'liejiuningmengshui', 'ljnms', '以伏特加、新鲜柠檬汁与单糖浆兑入气泡水调制的气泡柠檬水长饮，酸甜明亮、气泡绵密，口感清爽解腻，是夏日聚会的爽口选择。', 'V6 编辑标准化配方以伏特加 50 ml、柠檬汁 25 ml、单糖浆 15 ml 与气泡水 90 ml 直调，柠檬与糖浆比例可按平衡调整，酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 193, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["伏特加基底", "冷饮", "柑橘", "清爽", "直调", "夏季", "气泡感", "中等强度"]', '["夏季"]', '{"baseSpirit": "伏特加基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["夏季"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 90, "unit": "ml", "role": "气泡水补足"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "柠檬片装饰"}]', '["在柯林杯中装满冰块，加入 50 ml 伏特加。", "加入 25 ml 新鲜柠檬汁与 15 ml 单糖浆。", "以吧勺搅拌均匀。", "补入约 90 ml 冰镇气泡水，轻搅一次。", "以柠檬片装饰后立即饮用。"]', '["Spirit Lemonade", "烈酒柠檬饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-spirit-lemonade", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "烈酒柠檬水", "nameEn": "Spirit Lemonade", "intro": "以伏特加、新鲜柠檬汁与单糖浆兑入气泡水调制的气泡柠檬水长饮，酸甜明亮、气泡绵密，口感清爽解腻，是夏日聚会的爽口选择。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "清爽", "直调", "夏季", "气泡感", "中等强度"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "科林斯", "flavor": "柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-brandy-sling', 'cocktail', 'COCKTAIL', '白兰地司令', 'Brandy Sling', 'bailandisiling', 'bldsl', '以白兰地、单糖浆与冷过滤水调制的高球鸡尾酒，干邑的果香与木质气息铺底，口感圆润顺喉，是经典司令家族中偏温和的长饮。', 'V6 编辑标准化配方以白兰地 50 ml、单糖浆 10 ml 与冷过滤水 40 ml 直调，柠檬皮增香；无气泡版本突出白兰地本身，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg', 91, 194, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["白兰地基底", "冷饮", "均衡", "直调", "经典", "中等酒体", "中等强度"]', '["经典"]', '{"baseSpirit": "白兰地基底", "cocktailType": "高球", "flavor": "均衡", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "白兰地", "nameEn": "Brandy", "amount": 50, "unit": "ml", "role": "白兰地"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 40, "unit": "ml", "role": "冷过滤水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 50, "unit": "g", "role": "杯内冰块"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮喷香装饰"}]', '["在高球杯中放入冰块，加入 50 ml 白兰地。", "加入 10 ml 单糖浆与 40 ml 冷过滤水。", "以吧勺搅拌约 10 秒至均匀冰镇。", "以柠檬皮在杯口喷香后投入杯中。"]', '["Brandy Sling", "干邑司令"]', 'B', '2026-08-04', 1, '{"id": "cocktail-brandy-sling", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白兰地司令", "nameEn": "Brandy Sling", "intro": "以白兰地、单糖浆与冷过滤水调制的高球鸡尾酒，干邑的果香与木质气息铺底，口感圆润顺喉，是经典司令家族中偏温和的长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Singapore%20Sling.jpg", "tags": ["白兰地基底", "冷饮", "均衡", "直调", "经典", "中等酒体", "中等强度"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "高球", "flavor": "均衡", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sloe-gin', 'cocktail', 'COCKTAIL', '黑刺李金酒', 'Sloe Gin', 'heicilijinjiu', 'hcljj', '以黑刺李金酒与干白味美思调制、缀以橙味苦精的利口酒短饮，浆果甜香与药草气息交织，口感甜润紧致，适合作为餐前或餐后慢饮。', 'V6 编辑标准化配方以黑刺李金酒 50 ml、干白味美思 20 ml 与橙味苦精 2 滴搅拌调制；黑刺李利口酒甜度与酒精度因品牌而异，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/4/4f/Hand_Made_Sloe_Gin.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/4f/Hand_Made_Sloe_Gin.jpg', 93, 195, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["烈酒主导", "金酒基底", "冷饮", "莓果", "甜感明显", "搅拌", "经典", "高强度"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "莓果、甜感明显", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "黑刺李金酒", "nameEn": "Sloe gin", "amount": 50, "unit": "ml", "role": "黑刺李金酒"}, {"nameZh": "干白味美思", "nameEn": "Dry vermouth", "amount": 20, "unit": "ml", "role": "干白味美思"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "搅拌杯冰块"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮喷香装饰"}]', '["在搅拌杯中放入约 60 g 冰块，加入 50 ml 黑刺李金酒。", "加入 20 ml 干白味美思与 2 滴橙味苦精。", "以吧勺搅拌约 15 秒至充分冰镇。", "滤入冰镇的鸡尾酒杯。", "以橙皮在杯口喷香后投入杯中。"]', '["Sloe Gin", "黑刺李鸡尾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sloe-gin", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑刺李金酒", "nameEn": "Sloe Gin", "intro": "以黑刺李金酒与干白味美思调制、缀以橙味苦精的利口酒短饮，浆果甜香与药草气息交织，口感甜润紧致，适合作为餐前或餐后慢饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4f/Hand_Made_Sloe_Gin.jpg", "tags": ["烈酒主导", "金酒基底", "冷饮", "莓果", "甜感明显", "搅拌", "经典", "高强度"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "莓果、甜感明显", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sloe-gin-fizz', 'cocktail', 'COCKTAIL', '斯洛金', 'Sloe Gin Fizz', 'siluojin', 'slj', '以黑刺李金酒、新鲜柠檬汁与单糖浆摇和后兑入气泡水的菲兹鸡尾酒，浆果甜香与柠檬酸爽相遇，气泡绵密，口感轻盈酸甜，适合午后长饮。', 'V6 编辑标准化配方以黑刺李金酒 45 ml、柠檬汁 20 ml、单糖浆 10 ml 摇匀滤入杯中，再补气泡水；甜酸比例可按黑刺李利口酒品牌调整，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg', 93, 196, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["金酒基底", "冷饮", "莓果", "果香", "气泡感", "摇和", "夏季", "中等强度"]', '["夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "莓果、果香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["夏季"]}', '[{"nameZh": "黑刺李金酒", "nameEn": "Sloe gin", "amount": 45, "unit": "ml", "role": "黑刺李金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 80, "unit": "ml", "role": "气泡水补足"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "柠檬片装饰"}]', '["在摇壶中加入 45 ml 黑刺李金酒、20 ml 新鲜柠檬汁与 10 ml 单糖浆。", "加入冰块，用力摇和约 12 秒。", "滤入装满冰块的柯林杯。", "补入约 80 ml 冰镇气泡水。", "轻搅一次，以柠檬片装饰后饮用。"]', '["Sloe Gin Fizz", "黑刺李菲兹"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sloe-gin-fizz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "斯洛金", "nameEn": "Sloe Gin Fizz", "intro": "以黑刺李金酒、新鲜柠檬汁与单糖浆摇和后兑入气泡水的菲兹鸡尾酒，浆果甜香与柠檬酸爽相遇，气泡绵密，口感轻盈酸甜，适合午后长饮。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Negroni.jpg", "tags": ["金酒基底", "冷饮", "莓果", "果香", "气泡感", "摇和", "夏季", "中等强度"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "莓果、果香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-saint-germain', 'cocktail', 'COCKTAIL', '圣日耳曼', 'Saint Germain', 'shengrierman', 'srem', '以金酒、丽莱白葡萄酒与柠檬汁摇和后兑入气泡酒的花香长饮，白花与葡萄果香交融，酸甜细腻、气泡优雅，适合开胃或聚会场合。', 'V6 编辑标准化配方以金酒 40 ml、丽莱白 30 ml、柠檬汁 15 ml 摇匀后补入普罗塞克 60 ml；丽莱白替代接骨木花利口酒提供花香，酒精度为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 93, 197, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "冷饮", "花香", "柑橘", "气泡感", "摇和", "开胃", "中等强度"]', '["开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "花香、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁"], "scene": ["开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 40, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "丽莱白葡萄酒", "nameEn": "Lillet Blanc", "amount": 30, "unit": "ml", "role": "丽莱白葡萄酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "普罗塞克", "nameEn": "Prosecco", "amount": 60, "unit": "ml", "role": "普罗塞克起泡酒补足"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮装饰"}]', '["在摇壶中加入 40 ml 金酒、30 ml 丽莱白与 15 ml 新鲜柠檬汁。", "加入冰块摇和约 10 秒。", "滤入冰镇的笛形杯。", "缓慢补入约 60 ml 冰镇普罗塞克。", "以柠檬皮扭拧入杯增香。"]', '["Saint Germain", "圣日耳曼花香"]', 'B', '2026-08-04', 1, '{"id": "cocktail-saint-germain", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "圣日耳曼", "nameEn": "Saint Germain", "intro": "以金酒、丽莱白葡萄酒与柠檬汁摇和后兑入气泡酒的花香长饮，白花与葡萄果香交融，酸甜细腻、气泡优雅，适合开胃或聚会场合。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg", "tags": ["金酒基底", "冷饮", "花香", "柑橘", "气泡感", "摇和", "开胃", "中等强度"], "scene": ["开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "花香、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁"], "scene": ["开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-elderflower-spritz', 'cocktail', 'COCKTAIL', '接骨木花', 'Elderflower Spritz', 'jiegumuhua', 'jgmh', '以丽莱白葡萄酒、蜂蜜与柠檬汁兑入气泡水的清爽气泡长饮，白花与蜂蜜的甜香柔和，酸度明亮、气泡绵密，适合午后与轻食场景。', 'V6 编辑标准化配方以丽莱白 60 ml、蜂蜜 5 ml、柠檬汁 10 ml 与气泡水 60 ml 直调；蜂蜜提供花香甜润替代接骨木花利口酒，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/c/c8/00_3769_Schwarzen_Holunder_%28Sambucus_nigra%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/c/c8/00_3769_Schwarzen_Holunder_%28Sambucus_nigra%29.jpg', 93, 198, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷饮", "花香", "气泡感", "轻盈", "直调", "夏季", "清爽", "中等强度"]', '["夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "花香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["夏季"]}', '[{"nameZh": "丽莱白葡萄酒", "nameEn": "Lillet Blanc", "amount": 60, "unit": "ml", "role": "丽莱白葡萄酒"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 5, "unit": "g", "role": "蜂蜜"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 10, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 60, "unit": "ml", "role": "气泡水补足"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "柠檬片装饰"}]', '["在酒杯中放入冰块，加入 60 ml 丽莱白。", "加入 5 g 蜂蜜与 10 ml 新鲜柠檬汁，搅拌至蜂蜜化开。", "补入约 60 ml 冰镇气泡水。", "轻搅一次，以柠檬片装饰后饮用。"]', '["Elderflower Spritz", "接骨木花起泡酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-elderflower-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "接骨木花", "nameEn": "Elderflower Spritz", "intro": "以丽莱白葡萄酒、蜂蜜与柠檬汁兑入气泡水的清爽气泡长饮，白花与蜂蜜的甜香柔和，酸度明亮、气泡绵密，适合午后与轻食场景。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c8/00_3769_Schwarzen_Holunder_%28Sambucus_nigra%29.jpg", "tags": ["冷饮", "花香", "气泡感", "轻盈", "直调", "夏季", "清爽", "中等强度"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "花香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-campari-absinthe', 'cocktail', 'COCKTAIL', '金巴利苦艾', 'Campari Absinthe', 'jinbalikuai', 'jblka', '以金巴利、苦艾酒、新鲜柠檬汁与单糖浆调制的酸型鸡尾酒，药草苦香与茴香气息强烈，酸度明亮、甜感克制，是风味鲜明的餐后短饮。', 'V6 编辑标准化配方以金巴利 40 ml、苦艾酒 10 ml、柠檬汁 20 ml 与单糖浆 5 ml 摇和；金巴利与苦艾的酒精度较高，实际值随品牌变化，酒精度为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 199, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["烈酒主导", "苦味明显", "草本", "茴香", "摇和", "冷饮", "餐后", "高强度"]', '["餐后"]', '{"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "苦味明显、草本", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["餐后"]}', '[{"nameZh": "金巴利", "nameEn": "Campari", "amount": 40, "unit": "ml", "role": "金巴利"}, {"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 10, "unit": "ml", "role": "苦艾酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇壶冰块"}]', '["在摇壶中加入 40 ml 金巴利、10 ml 苦艾酒与 20 ml 新鲜柠檬汁。", "加入 5 ml 单糖浆与冰块，用力摇和约 12 秒。", "滤入冰镇的鸡尾酒杯。", "以柠檬皮在杯口喷香后投入杯中。"]', '["Campari Absinthe", "金巴利苦艾酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-campari-absinthe", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金巴利苦艾", "nameEn": "Campari Absinthe", "intro": "以金巴利、苦艾酒、新鲜柠檬汁与单糖浆调制的酸型鸡尾酒，药草苦香与茴香气息强烈，酸度明亮、甜感克制，是风味鲜明的餐后短饮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["烈酒主导", "苦味明显", "草本", "茴香", "摇和", "冷饮", "餐后", "高强度"], "scene": ["餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "苦味明显、草本", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-americana', 'cocktail', 'COCKTAIL', '美国经典', 'Americana', 'meiguojingdian', 'mgjd', '以波本威士忌、甜红味美思、新鲜柠檬汁与单糖浆调制的酸型鸡尾酒，麦芽与葡萄甜香交融，酸甜均衡、酒体饱满，是经典的威士忌酸变体。', 'V6 编辑标准化配方以波本 60 ml、甜红味美思 30 ml、柠檬汁 20 ml 与单糖浆 10 ml 摇和；味美思品牌会显著影响甜度与药草表现，酒精度为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/f/ff/CES_2026_-_Billy_Magnussen_01.jpg', 'https://upload.wikimedia.org/wikipedia/commons/f/ff/CES_2026_-_Billy_Magnussen_01.jpg', 93, 200, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["威士忌基底", "酸型鸡尾酒", "冷饮", "柑橘", "草本", "摇和", "经典", "高强度"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、草本", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 30, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "摇壶冰块"}]', '["在摇壶中加入 60 ml 波本威士忌、30 ml 甜红味美思与 20 ml 新鲜柠檬汁。", "加入 10 ml 单糖浆与冰块，用力摇和约 12 秒。", "滤入装满冰块的古典杯。", "以柠檬皮在杯口喷香后投入杯中。"]', '["Americana", "美国之饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-americana", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "美国经典", "nameEn": "Americana", "intro": "以波本威士忌、甜红味美思、新鲜柠檬汁与单糖浆调制的酸型鸡尾酒，麦芽与葡萄甜香交融，酸甜均衡、酒体饱满，是经典的威士忌酸变体。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/ff/CES_2026_-_Billy_Magnussen_01.jpg", "tags": ["威士忌基底", "酸型鸡尾酒", "冷饮", "柑橘", "草本", "摇和", "经典", "高强度"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、草本", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-irish-coffee-classic', 'cocktail', 'COCKTAIL', '爱尔兰咖啡经典', 'Irish Coffee Classic', 'aierlankafeijingdian', 'aelkfjd', '以爱尔兰威士忌、热咖啡、砂糖与浮顶奶油的经典热饮，威士忌的谷物甜与咖啡烘焙香交融，奶油层顺滑，是餐后热鸡尾酒的代表。', 'V6 编辑标准化配方沿用经典结构：40 ml 爱尔兰威士忌配热咖啡与砂糖，顶部轻浮稀奶油且不搅拌，与爱尔兰咖啡条目同源，此处为强调分层的经典呈现；配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20glass.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20glass.jpg', 91, 201, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["咖啡鸡尾酒", "热饮", "咖啡风味", "奶油感", "餐后", "含咖啡因", "经典"]', '["餐后", "经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "低度≤10%", "extra": ["浓缩咖啡液", "稀奶油"], "scene": ["餐后", "经典"]}', '[{"nameZh": "爱尔兰威士忌", "nameEn": "Irish whiskey", "amount": 40, "unit": "ml", "role": "爱尔兰威士忌"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 60, "unit": "ml", "role": "热浓缩咖啡液"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 80, "unit": "ml", "role": "85–92°C 热水"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 5, "unit": "g", "role": "细砂糖"}, {"nameZh": "稀奶油", "nameEn": "Heavy cream", "amount": 30, "unit": "ml", "role": "轻打至微稠的稀奶油"}]', '["预热容量不低于 240 ml 的耐热玻璃杯。", "向杯中倒入 40 ml 爱尔兰威士忌与 5 g 细砂糖。", "注入 60 ml 热浓缩咖啡液与 80 ml 85–92°C 热水，轻搅至糖溶。", "沿勺背缓缓倒入 30 ml 稀奶油，使其浮于液面。", "立即饮用，不搅拌奶油层以保留分层口感。"]', '["经典爱尔兰咖啡", "Irish Coffee", "热爱尔兰咖啡"]', 'B', '2026-08-04', 1, '{"id": "cocktail-irish-coffee-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "爱尔兰咖啡经典", "nameEn": "Irish Coffee Classic", "intro": "以爱尔兰威士忌、热咖啡、砂糖与浮顶奶油的经典热饮，威士忌的谷物甜与咖啡烘焙香交融，奶油层顺滑，是餐后热鸡尾酒的代表。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Irish%20Coffee%20glass.jpg", "tags": ["咖啡鸡尾酒", "热饮", "咖啡风味", "奶油感", "餐后", "含咖啡因", "经典"], "scene": ["餐后", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "低度≤10%", "extra": ["浓缩咖啡液", "稀奶油"], "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mexican-coffee-classic', 'cocktail', 'COCKTAIL', '墨西哥咖啡经典', 'Mexican Coffee Classic', 'moxigekafeijingdian', 'mxgkfjd', '以龙舌兰、咖啡利口酒与热咖啡调成的墨西哥风味餐后热饮，龙舌兰的植物气息与咖啡烘焙香交融，甜感来自利口酒，温暖顺口。', 'V6 编辑标准化配方以银龙舌兰为烈酒基底、配咖啡利口酒并加肉桂棒提香，属咖啡鸡尾酒家族的热饮变体；配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg', 91, 202, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["咖啡鸡尾酒", "热饮", "咖啡风味", "香料", "甜感明显", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、香料", "abv": "低度≤10%", "extra": ["浓缩咖啡液", "肉桂棒"], "scene": ["餐后"]}', '[{"nameZh": "银龙舌兰酒", "nameEn": "Blanco tequila", "amount": 30, "unit": "ml", "role": "银龙舌兰酒"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 20, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 60, "unit": "ml", "role": "热浓缩咖啡液"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 90, "unit": "ml", "role": "85–92°C 热水"}, {"nameZh": "肉桂棒", "nameEn": "Cinnamon stick", "amount": 1, "unit": "piece", "role": "肉桂棒装饰"}]', '["预热容量不低于 240 ml 的耐热玻璃杯。", "向杯中倒入 30 ml 银龙舌兰酒与 20 ml 咖啡利口酒。", "注入 60 ml 热浓缩咖啡液与 90 ml 85–92°C 热水，轻搅均匀。", "以肉桂棒在杯中搅动两圈后留在杯内提香。", "趁热饮用，保持肉桂香气完整。"]', '["经典墨西哥咖啡", "Mexican Coffee", "墨西哥热咖啡"]', 'B', '2026-08-04', 1, '{"id": "cocktail-mexican-coffee-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "墨西哥咖啡经典", "nameEn": "Mexican Coffee Classic", "intro": "以龙舌兰、咖啡利口酒与热咖啡调成的墨西哥风味餐后热饮，龙舌兰的植物气息与咖啡烘焙香交融，甜感来自利口酒，温暖顺口。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mojito.jpg", "tags": ["咖啡鸡尾酒", "热饮", "咖啡风味", "香料", "甜感明显", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、香料", "abv": "低度≤10%", "extra": ["浓缩咖啡液", "肉桂棒"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-spanish-coffee-classic', 'cocktail', 'COCKTAIL', '西班牙咖啡经典', 'Spanish Coffee Classic', 'xibanyakafeijingdian', 'xbykfjd', '以白兰地、咖啡利口酒与热咖啡调成的西班牙风情餐后热饮，常用柑橘皮点燃增香，白兰地果香与咖啡苦甜交融，温热浓郁。', 'V6 编辑标准化配方以白兰地为烈酒基底、配咖啡利口酒，并以橙皮火焰提香还原传统西班牙咖啡的呈现；配方与数值为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 203, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["咖啡鸡尾酒", "热饮", "咖啡风味", "果香", "餐后", "含咖啡因", "经典"]', '["餐后", "经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、果香", "abv": "低度≤10%", "extra": ["浓缩咖啡液"], "scene": ["餐后", "经典"]}', '[{"nameZh": "白兰地", "nameEn": "Brandy", "amount": 30, "unit": "ml", "role": "白兰地"}, {"nameZh": "咖啡利口酒", "nameEn": "Coffee liqueur", "amount": 15, "unit": "ml", "role": "咖啡利口酒"}, {"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 60, "unit": "ml", "role": "热浓缩咖啡液"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 90, "unit": "ml", "role": "85–92°C 热水"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 2, "unit": "g", "role": "橙皮（点燃提香用）"}]', '["预热容量不低于 240 ml 的耐热玻璃杯。", "向杯中倒入 30 ml 白兰地与 15 ml 咖啡利口酒。", "注入 60 ml 热浓缩咖啡液与 90 ml 85–92°C 热水，轻搅均匀。", "持橙皮在杯口上方点燃片刻，将焦香与橙油挤入杯中。", "趁热饮用。"]', '["经典西班牙咖啡", "Spanish Coffee", "西班牙火咖啡"]', 'B', '2026-08-04', 1, '{"id": "cocktail-spanish-coffee-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "西班牙咖啡经典", "nameEn": "Spanish Coffee Classic", "intro": "以白兰地、咖啡利口酒与热咖啡调成的西班牙风情餐后热饮，常用柑橘皮点燃增香，白兰地果香与咖啡苦甜交融，温热浓郁。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["咖啡鸡尾酒", "热饮", "咖啡风味", "果香", "餐后", "含咖啡因", "经典"], "scene": ["餐后", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、果香", "abv": "低度≤10%", "extra": ["浓缩咖啡液"], "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-italian-coffee-classic', 'cocktail', 'COCKTAIL', '意大利咖啡经典', 'Italian Coffee Classic', 'yidalikafeijingdian', 'ydlkfjd', '以茴香利口酒配热浓缩咖啡调成的意式餐后热饮，接近咖啡扣雷托，茴香与甘草气息明亮，咖啡苦香打底，甜感含蓄而温暖。', 'V6 编辑标准化配方以山布卡茴香利口酒搭配热浓缩咖啡，还原意式餐后加料咖啡的常见形式；配方与数值为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 204, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["咖啡鸡尾酒", "热饮", "咖啡风味", "茴香", "草本", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、茴香", "abv": "中度＞10%～20%", "extra": ["双份浓缩咖啡液", "咖啡豆（意式配方）"], "scene": ["餐后"]}', '[{"nameZh": "山布卡茴香利口酒", "nameEn": "Sambuca", "amount": 30, "unit": "ml", "role": "山布卡茴香利口酒"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 60, "unit": "ml", "role": "热双份浓缩咖啡液"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 30, "unit": "ml", "role": "85–92°C 热水"}, {"nameZh": "咖啡豆（意式配方）", "nameEn": "Coffee beans for espresso", "amount": 3, "unit": "g", "role": "咖啡豆装饰"}]', '["预热容量不低于 160 ml 的耐热玻璃杯。", "向杯中倒入 30 ml 山布卡茴香利口酒。", "注入 60 ml 热双份浓缩咖啡液与 30 ml 85–92°C 热水，轻搅均匀。", "在液面放三颗咖啡豆作装饰。", "趁热饮用。"]', '["经典意大利咖啡", "Italian Coffee", "意式加料咖啡"]', 'B', '2026-08-04', 1, '{"id": "cocktail-italian-coffee-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "意大利咖啡经典", "nameEn": "Italian Coffee Classic", "intro": "以茴香利口酒配热浓缩咖啡调成的意式餐后热饮，接近咖啡扣雷托，茴香与甘草气息明亮，咖啡苦香打底，甜感含蓄而温暖。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["咖啡鸡尾酒", "热饮", "咖啡风味", "茴香", "草本", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、茴香", "abv": "中度＞10%～20%", "extra": ["双份浓缩咖啡液", "咖啡豆（意式配方）"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bourbon-old-fashioned', 'cocktail', 'COCKTAIL', '波本古典', 'Bourbon Old Fashioned', 'bobengudian', 'bbgd', '以波本威士忌、方糖与苦精直调的古典鸡尾酒，焦糖与橡木气息饱满，苦甜平衡，用橙皮提香，是威士忌古典家族中最直接的呈现。', 'V6 编辑标准化配方以波本威士忌为基底、配方糖与安格斯图拉苦精，大冰球直调；与黑麦古典相比谷物甜感更圆润，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 91, 205, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "苦味明显", "经典", "冷饮", "高强度", "无麸质", "偏干"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显、偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 45, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 1, "unit": "piece", "role": "方糖"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "室温过滤水", "nameEn": "Room-temperature filtered water", "amount": 5, "unit": "ml", "role": "室温过滤水（溶解方糖）"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮装饰"}]', '["在古典杯中放入方糖，滴入 2 滴安格斯图拉苦精。", "加入 5 ml 室温过滤水，用捣棒轻压至方糖溶解。", "倒入 45 ml 波本威士忌并放入大冰球。", "用吧勺搅拌约 30 秒至充分冰镇。", "以橙皮在杯口挤出橙油后投入杯中。"]', '["波本古典鸡尾酒", "Bourbon Old Fashioned", "波本老式"]', 'B', '2026-08-04', 1, '{"id": "cocktail-bourbon-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波本古典", "nameEn": "Bourbon Old Fashioned", "intro": "以波本威士忌、方糖与苦精直调的古典鸡尾酒，焦糖与橡木气息饱满，苦甜平衡，用橙皮提香，是威士忌古典家族中最直接的呈现。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg", "tags": ["威士忌基底", "苦味明显", "经典", "冷饮", "高强度", "无麸质", "偏干"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显、偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rye-old-fashioned', 'cocktail', 'COCKTAIL', '黑麦古典', 'Rye Old Fashioned', 'heimaigudian', 'hmgd', '以黑麦威士忌、方糖与苦精直调的古典鸡尾酒，黑麦的辛香与谷物感突出，苦甜利落，是比波本版本更干爽锐利的古典呈现。', 'V6 编辑标准化配方以黑麦威士忌为基底，配方糖与安格斯图拉苦精，大冰球直调；与波本古典相比辛香更锐利、甜感更收敛，配方与数值为编辑估算值。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 91, 206, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "苦味明显", "香料", "经典", "冷饮", "高强度", "偏干"]', '["经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显、香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 45, "unit": "ml", "role": "黑麦威士忌"}, {"nameZh": "方糖", "nameEn": "Sugar cube", "amount": 1, "unit": "piece", "role": "方糖"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "室温过滤水", "nameEn": "Room-temperature filtered water", "amount": 5, "unit": "ml", "role": "室温过滤水（溶解方糖）"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "柠檬皮装饰"}]', '["在古典杯中放入方糖，滴入 2 滴安格斯图拉苦精。", "加入 5 ml 室温过滤水，用捣棒轻压至方糖溶解。", "倒入 45 ml 黑麦威士忌并放入大冰球。", "用吧勺搅拌约 30 秒至充分冰镇。", "以柠檬皮在杯口挤出精油后投入杯中。"]', '["黑麦古典鸡尾酒", "Rye Old Fashioned", "黑麦老式"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rye-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑麦古典", "nameEn": "Rye Old Fashioned", "intro": "以黑麦威士忌、方糖与苦精直调的古典鸡尾酒，黑麦的辛香与谷物感突出，苦甜利落，是比波本版本更干爽锐利的古典呈现。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["威士忌基底", "苦味明显", "香料", "经典", "冷饮", "高强度", "偏干"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦味明显、香料", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rum-old-fashioned-special', 'cocktail', 'COCKTAIL', '朗姆古典特调', 'Rum Old Fashioned Special', 'langmugudiantediao', 'lmgdtd', '以陈年朗姆酒、红糖与苦精直调的古典特调，加肉桂提香，糖蜜与香料气息浓郁，比基础朗姆古典更温润丰盈，是冬季友好的烈酒。', 'V6 编辑标准化配方以陈年朗姆酒为基底、配红糖与安格斯图拉苦精，另加肉桂棒提香，属古典家族的特调变体；配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned%20(1).jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned%20(1).jpg', 91, 207, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["朗姆基底", "香料", "焦糖", "苦味明显", "高强度", "经典", "冷饮"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "古典家族", "flavor": "香料、焦糖", "abv": "高度＞30%", "extra": ["肉桂棒"], "scene": ["经典"]}', '[{"nameZh": "陈年朗姆酒", "nameEn": "Aged rum", "amount": 45, "unit": "ml", "role": "陈年朗姆酒"}, {"nameZh": "红糖", "nameEn": "Brown sugar", "amount": 5, "unit": "g", "role": "红糖"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 3, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "室温过滤水", "nameEn": "Room-temperature filtered water", "amount": 5, "unit": "ml", "role": "室温过滤水（溶解红糖）"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "肉桂棒", "nameEn": "Cinnamon stick", "amount": 1, "unit": "piece", "role": "肉桂棒装饰"}]', '["在古典杯中放入 5 g 红糖，滴入 3 滴安格斯图拉苦精。", "加入 5 ml 室温过滤水，用捣棒轻压至红糖溶解。", "倒入 45 ml 陈年朗姆酒并放入大冰球。", "用吧勺搅拌约 30 秒至充分冰镇。", "以肉桂棒轻搅一圈后留在杯中提香。"]', '["朗姆古典特调版", "Rum Old Fashioned Special", "香料朗姆古典"]', 'B', '2026-08-04', 1, '{"id": "cocktail-rum-old-fashioned-special", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朗姆古典特调", "nameEn": "Rum Old Fashioned Special", "intro": "以陈年朗姆酒、红糖与苦精直调的古典特调，加肉桂提香，糖蜜与香料气息浓郁，比基础朗姆古典更温润丰盈，是冬季友好的烈酒。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned%20(1).jpg", "tags": ["朗姆基底", "香料", "焦糖", "苦味明显", "高强度", "经典", "冷饮"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "古典家族", "flavor": "香料、焦糖", "abv": "高度＞30%", "extra": ["肉桂棒"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-old-fashioned-special', 'cocktail', 'COCKTAIL', '龙舌兰古典特调', 'Tequila Old Fashioned Special', 'longshelangudiantediao', 'lslgdtd', '以陈年龙舌兰酒、龙舌兰糖浆与苦精直调的古典特调，突出草本与矿物感，配烟熏呈现，口感干爽利落，是龙舌兰古典的进阶变体。', 'V6 编辑标准化配方以陈年龙舌兰为基底、配龙舌兰糖浆与橙味苦精，并以烟熏罩营造香气层次，属古典家族的特调变体；配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned.jpg', 91, 208, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["龙舌兰基底", "烟熏", "苦味明显", "草本", "高强度", "经典", "冷饮"]', '["经典"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "古典家族", "flavor": "烟熏、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "陈年龙舌兰酒", "nameEn": "Reposado tequila", "amount": 45, "unit": "ml", "role": "陈年龙舌兰酒"}, {"nameZh": "龙舌兰糖浆", "nameEn": "Agave syrup", "amount": 5, "unit": "ml", "role": "龙舌兰糖浆"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "大冰球"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮装饰"}]', '["在古典杯中依次加入 5 ml 龙舌兰糖浆与两种苦精。", "倒入 45 ml 陈年龙舌兰酒并放入大冰球。", "用吧勺搅拌约 30 秒至充分冰镇。", "以橙皮在杯口挤出橙油后投入杯中。", "加盖烟熏罩并注入一层薄薄烟熏香后立即饮用。"]', '["龙舌兰古典特调版", "Tequila Old Fashioned Special", "烟熏龙舌兰古典"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tequila-old-fashioned-special", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰古典特调", "nameEn": "Tequila Old Fashioned Special", "intro": "以陈年龙舌兰酒、龙舌兰糖浆与苦精直调的古典特调，突出草本与矿物感，配烟熏呈现，口感干爽利落，是龙舌兰古典的进阶变体。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Rum,%20Manhattan,%20Tequila%20Old%20Fashioned.jpg", "tags": ["龙舌兰基底", "烟熏", "苦味明显", "草本", "高强度", "经典", "冷饮"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "古典家族", "flavor": "烟熏、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gin-old-fashioned', 'cocktail', 'COCKTAIL', '金酒古典特调', 'Gin Old Fashioned', 'jinjiugudiantediao', 'jjgdtd', '以伦敦干金酒、糖浆与橙味苦精搅拌而成的古典变体，杜松子与草本气息清晰，苦甜均衡，口感清爽带烈度，是金酒少见的古典形态。', 'V6 编辑标准化配方以伦敦干金酒为基底、配单糖浆与橙味苦精，搅拌滤入古典杯；与威士忌古典相比草本更突出、甜感更克制，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 91, 209, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["金酒基底", "草本", "苦味明显", "高强度", "经典", "冷饮", "偏干"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "草本、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 3, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "搅拌用冰块"}, {"nameZh": "葡萄柚皮", "nameEn": "Grapefruit peel", "amount": 1, "unit": "piece", "role": "葡萄柚皮装饰"}]', '["在搅拌杯中加入 45 ml 伦敦干金酒、5 ml 单糖浆与 3 滴橙味苦精。", "加入约 80 g 冰块，搅拌约 20 秒。", "滤入冰镇的古典杯。", "以葡萄柚皮在杯口挤出精油后投入杯中。"]', '["金酒古典鸡尾酒", "Gin Old Fashioned", "杜松子古典"]', 'B', '2026-08-04', 1, '{"id": "cocktail-gin-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金酒古典特调", "nameEn": "Gin Old Fashioned", "intro": "以伦敦干金酒、糖浆与橙味苦精搅拌而成的古典变体，杜松子与草本气息清晰，苦甜均衡，口感清爽带烈度，是金酒少见的古典形态。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg", "tags": ["金酒基底", "草本", "苦味明显", "高强度", "经典", "冷饮", "偏干"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "草本、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vodka-old-fashioned', 'cocktail', 'COCKTAIL', '伏特加古典特调', 'Vodka Old Fashioned', 'futejiagudiantediao', 'ftjgdtd', '以伏特加、糖浆与橙味苦精搅拌而成的古典变体，伏特加中性顺滑，苦甜与柑橘香气成为主导，口感干净，是极简的现代古典呈现。', 'V6 编辑标准化配方以伏特加为基底、配单糖浆与橙味苦精，搅拌滤入古典杯；因伏特加风味中性，苦甜与橙香更突出，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg', 91, 210, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["伏特加基底", "苦味明显", "高强度", "经典", "冷饮", "偏干", "无乳配方"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "古典家族", "flavor": "苦味明显、偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "伏特加"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "1:1 单糖浆"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 3, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "搅拌用冰块"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "橙皮装饰"}]', '["在搅拌杯中加入 45 ml 伏特加、5 ml 单糖浆与 3 滴橙味苦精。", "加入约 80 g 冰块，搅拌约 20 秒。", "滤入冰镇的古典杯。", "以橙皮在杯口挤出橙油后投入杯中。"]', '["伏特加古典鸡尾酒", "Vodka Old Fashioned", "伏特加老式"]', 'B', '2026-08-04', 1, '{"id": "cocktail-vodka-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "伏特加古典特调", "nameEn": "Vodka Old Fashioned", "intro": "以伏特加、糖浆与橙味苦精搅拌而成的古典变体，伏特加中性顺滑，苦甜与柑橘香气成为主导，口感干净，是极简的现代古典呈现。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Whiskey%20Old%20Fashioned.jpg", "tags": ["伏特加基底", "苦味明显", "高强度", "经典", "冷饮", "偏干", "无乳配方"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "古典家族", "flavor": "苦味明显、偏干", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-brandy-old-fashioned', 'cocktail', 'COCKTAIL', '白兰地古典特调', 'Brandy Old Fashioned', 'bailandigudiantediao', 'bldgdtd', '以干邑白兰地为基底、加糖与苦精调制的古典鸡尾酒变体，葡萄果香圆润，微苦与甜感层次清晰，酒体饱满，适合烈酒爱好者。', '本条目按古典鸡尾酒框架标准化：45 ml 干邑、5 ml 1:1 单糖浆加两滴安格斯图拉苦精，以少量水稀释后加冰搅匀。以干邑替换传统威士忌，果香更圆润、谷物味更少。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned,%20Timeless%20Beauty.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned,%20Timeless%20Beauty.jpg', 91, 211, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["干邑基底", "苦味明显", "经典", "冷饮", "高强度", "直调", "无乳配方"]', '["经典"]', '{"baseSpirit": "干邑基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 45, "unit": "ml", "role": "干邑白兰地"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "单糖浆"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 10, "unit": "ml", "role": "稀释糖浆"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "搅拌用大冰球"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在古典杯中依次加入 5 ml 单糖浆与两滴安格斯图拉苦精。", "倒入 45 ml 干邑，加 10 ml 过滤水稀释。", "放入大冰球，用吧勺搅拌约 30 秒至充分冰镇。", "以橙皮在杯口挤出橙油后投入杯中装饰。"]', '["Brandy Old Fashioned", "白兰地古典", "干邑古典"]', 'B', '2026-08-04', 1, '{"id": "cocktail-brandy-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白兰地古典特调", "nameEn": "Brandy Old Fashioned", "intro": "以干邑白兰地为基底、加糖与苦精调制的古典鸡尾酒变体，葡萄果香圆润，微苦与甜感层次清晰，酒体饱满，适合烈酒爱好者。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned,%20Timeless%20Beauty.jpg", "tags": ["干邑基底", "苦味明显", "经典", "冷饮", "高强度", "直调", "无乳配方"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "干邑基底", "cocktailType": "古典家族", "flavor": "苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-apple-brandy-old-fashioned', 'cocktail', 'COCKTAIL', '苹果白兰地古典', 'Apple Brandy Old Fashioned', 'pingguobailandigudian', 'pgbldgd', '以苹果白兰地代替威士忌的古典鸡尾酒变体，苹果果香清新、甜感柔和，配以红糖与苦精平衡，是果味古典鸡尾酒的代表。', '本条目以卡尔瓦多斯替代传统威士忌：45 ml 苹果白兰地、5 g 红糖加两滴安格斯图拉苦精，加少量水溶解红糖后加冰搅匀。苹果风味来自白兰地本身而非额外糖浆。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned%20%2816401271862%29.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned%20%2816401271862%29.jpg', 93, 212, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["白兰地基底", "苹果", "苦味明显", "冷饮", "经典", "高强度", "直调", "无乳配方"]', '["经典"]', '{"baseSpirit": "白兰地基底", "cocktailType": "古典家族", "flavor": "苹果、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "苹果白兰地酒", "nameEn": "Apple brandy", "amount": 45, "unit": "ml", "role": "苹果白兰地"}, {"nameZh": "红糖", "nameEn": "Brown sugar", "amount": 5, "unit": "g", "role": "红糖"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 5, "unit": "ml", "role": "溶解红糖用"}, {"nameZh": "冰球", "nameEn": "Ice ball", "amount": 1, "unit": "piece", "role": "搅拌用大冰球"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在古典杯中放入 5 g 红糖，滴入两滴安格斯图拉苦精。", "加入 5 ml 过滤水，用捣棒轻压至红糖溶解。", "倒入 45 ml 苹果白兰地并放入大冰球。", "搅拌约 30 秒后，以柠檬皮提香并放入杯中装饰。"]', '["Apple Brandy Old Fashioned", "Calvados Old Fashioned", "苹果白兰地古典特调"]', 'B', '2026-08-04', 1, '{"id": "cocktail-apple-brandy-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "苹果白兰地古典", "nameEn": "Apple Brandy Old Fashioned", "intro": "以苹果白兰地代替威士忌的古典鸡尾酒变体，苹果果香清新、甜感柔和，配以红糖与苦精平衡，是果味古典鸡尾酒的代表。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Old%20Fashioned%20%2816401271862%29.jpg", "tags": ["白兰地基底", "苹果", "苦味明显", "冷饮", "经典", "高强度", "直调", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "古典家族", "flavor": "苹果、苦味明显", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sherry-old-fashioned-classic', 'cocktail', 'COCKTAIL', '雪利古典', 'Sherry Old Fashioned', 'xueligudian', 'xlgd', '以欧罗索雪利酒为基底、加糖与苦精调制的古典式鸡尾酒，坚果与氧化干香突出，甜苦平衡，酒精感低于传统威士忌古典。', '本条目采用欧罗索雪利酒 45 ml 加 5 ml 1:1 单糖浆与两滴橙味苦精，直调于加冰的古典杯。雪利酒本具坚果干甜，糖浆用量较低以保留酒体特征。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sherry-DSC01549.JPG', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Sherry-DSC01549.JPG', 93, 213, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["雪利酒基底", "坚果", "甜感明显", "苦味明显", "冷饮", "直调", "经典", "无乳配方"]', '["经典"]', '{"baseSpirit": "雪利酒基底", "cocktailType": "古典家族", "flavor": "坚果、甜感明显", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "欧罗索雪利酒", "nameEn": "Oloroso sherry", "amount": 45, "unit": "ml", "role": "欧罗索雪利酒"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 5, "unit": "ml", "role": "单糖浆"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "冰镇用"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在古典杯中依次加入 5 ml 单糖浆与两滴橙味苦精。", "倒入 45 ml 欧罗索雪利酒，放入两块冰块。", "用吧勺搅拌约 15 秒至充分冰镇。", "以橙皮在杯口挤出橙油后放入杯中装饰。"]', '["Sherry Old Fashioned", "雪利古典鸡尾酒", "雪利老式"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sherry-old-fashioned-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "雪利古典", "nameEn": "Sherry Old Fashioned", "intro": "以欧罗索雪利酒为基底、加糖与苦精调制的古典式鸡尾酒，坚果与氧化干香突出，甜苦平衡，酒精感低于传统威士忌古典。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Sherry-DSC01549.JPG", "tags": ["雪利酒基底", "坚果", "甜感明显", "苦味明显", "冷饮", "直调", "经典", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "雪利酒基底", "cocktailType": "古典家族", "flavor": "坚果、甜感明显", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-port-old-fashioned', 'cocktail', 'COCKTAIL', '波特古典', 'Port Old Fashioned', 'botegudian', 'btgd', '以茶色波特酒为基底、加苦精调制的古典式鸡尾酒，红果与坚果甜香饱满，甜度高、酒精感温和，是强化酒古典的代表做法。', '本条目以茶色波特酒 45 ml 加两滴安格斯图拉苦精直调，不再额外加糖以保留波特本身的甜度。以强化酒替换烈酒，酒感更温和、结构更圆润。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Port%20wine%20%285196302462%29.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Port%20wine%20%285196302462%29.jpg', 93, 214, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["甜感明显", "果香", "苦味明显", "冷饮", "直调", "经典", "无乳配方", "无麸质"]', '["经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "古典家族", "flavor": "甜感明显、果香", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "波特酒", "nameEn": "Port wine", "amount": 45, "unit": "ml", "role": "茶色波特酒"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "安格斯图拉苦精"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "冰镇用"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在古典杯中滴入两滴安格斯图拉苦精。", "倒入 45 ml 茶色波特酒，放入两块冰块。", "用吧勺轻搅约 15 秒至充分冰镇。", "以橙皮在杯口挤出橙油后放入杯中装饰。"]', '["Port Old Fashioned", "波特古典鸡尾酒", "波特老式"]', 'B', '2026-08-04', 1, '{"id": "cocktail-port-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波特古典", "nameEn": "Port Old Fashioned", "intro": "以茶色波特酒为基底、加苦精调制的古典式鸡尾酒，红果与坚果甜香饱满，甜度高、酒精感温和，是强化酒古典的代表做法。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Port%20wine%20%285196302462%29.jpg", "tags": ["甜感明显", "果香", "苦味明显", "冷饮", "直调", "经典", "无乳配方", "无麸质"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "古典家族", "flavor": "甜感明显、果香", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sour-highball', 'cocktail', 'COCKTAIL', '沙瓦', 'Sour Highball', 'shawa', 'sw', '以伏特加为基底、加柠檬汁与苏打水兑制的日式沙瓦风格长饮，酸甜清爽、气泡充盈，酒感低，适合佐餐与日常饮用。', '本条目按日式沙瓦框架标准化：40 ml 伏特加、15 ml 柠檬汁、10 ml 1:1 单糖浆兑 80 ml 苏打水，直调于高球杯。以伏特加提供中性基底，突出柑橘酸味。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Highball,%20bar,%20Golden%20Gai,%20Shinkjuku,%20Tokyo,%20Japan%20in%202024.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Highball,%20bar,%20Golden%20Gai,%20Shinkjuku,%20Tokyo,%20Japan%20in%202024.jpg', 93, 215, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["伏特加基底", "冷饮", "柑橘", "酸甜", "气泡感", "直调", "清爽", "无乳配方"]', '["日常", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["日常", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 80, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入三块冰块。", "倒入 40 ml 伏特加、15 ml 柠檬汁与 10 ml 单糖浆。", "注入 80 ml 苏打水，用吧勺轻搅一次。", "以柠檬片置于杯沿装饰。"]', '["Sour Highball", "沙瓦高球", "日式沙瓦"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sour-highball", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "沙瓦", "nameEn": "Sour Highball", "intro": "以伏特加为基底、加柠檬汁与苏打水兑制的日式沙瓦风格长饮，酸甜清爽、气泡充盈，酒感低，适合佐餐与日常饮用。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Highball,%20bar,%20Golden%20Gai,%20Shinkjuku,%20Tokyo,%20Japan%20in%202024.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "酸甜", "气泡感", "直调", "清爽", "无乳配方"], "scene": ["日常", "经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sour-highball-special', 'cocktail', 'COCKTAIL', '沙瓦特调', 'Special Sour Highball', 'shawatediao', 'swtd', '在基础沙瓦之上加入百香果糖浆的特调版本，果香更立体，酸甜与气泡并存，口感丰富，是沙瓦系列中偏果味的选择。', '本条目在基础沙瓦配比上加入 15 ml 百香果糖浆：40 ml 伏特加、15 ml 柠檬汁、15 ml 百香果糖浆兑 75 ml 苏打水，直调于高球杯。果香来自糖浆而非果汁。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Highball,%20bar,%20Golden%20Gai,%20Shinkjuku,%20Tokyo,%20Japan%20in%202024.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Highball,%20bar,%20Golden%20Gai,%20Shinkjuku,%20Tokyo,%20Japan%20in%202024.jpg', 93, 216, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["伏特加基底", "冷饮", "果香", "百香果", "酸甜", "气泡感", "直调", "无乳配方"]', '["日常", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "果香、百香果", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "百香果糖浆"], "scene": ["日常", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "百香果糖浆", "nameEn": "Passion fruit syrup", "amount": 15, "unit": "ml", "role": "百香果糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 75, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入三块冰块。", "倒入 40 ml 伏特加、15 ml 柠檬汁与 15 ml 百香果糖浆。", "注入 75 ml 苏打水，用吧勺轻搅一次。", "以橙皮挤油后投入杯面装饰。"]', '["Special Sour Highball", "水果沙瓦", "特调沙瓦"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sour-highball-special", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "沙瓦特调", "nameEn": "Special Sour Highball", "intro": "在基础沙瓦之上加入百香果糖浆的特调版本，果香更立体，酸甜与气泡并存，口感丰富，是沙瓦系列中偏果味的选择。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Highball,%20bar,%20Golden%20Gai,%20Shinkjuku,%20Tokyo,%20Japan%20in%202024.jpg", "tags": ["伏特加基底", "冷饮", "果香", "百香果", "酸甜", "气泡感", "直调", "无乳配方"], "scene": ["日常", "经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "果香、百香果", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "百香果糖浆"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-yuzu-sour', 'cocktail', 'COCKTAIL', '柚子沙瓦', 'Yuzu Sour', 'youzishawa', 'yzsw', '以柑橘风味伏特加、葡萄柚汁与柠檬汁调制的沙瓦长饮，以近似柚子的柑橘香气为特色，清爽微酸，气泡充盈。', '本条目以柑橘风味伏特加 40 ml、柠檬汁 15 ml 与葡萄柚汁 10 ml 近似柚子香气，加 10 ml 单糖浆与 75 ml 苏打水直调，适合没有鲜柚子汁时复现柑橘酸甜。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Yuzu.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Yuzu.jpg', 93, 217, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["伏特加基底", "冷饮", "柑橘", "果香", "酸甜", "气泡感", "直调", "无乳配方"]', '["日常", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "新鲜葡萄柚汁"], "scene": ["日常", "经典", "开胃"]}', '[{"nameZh": "柑橘伏特加", "nameEn": "Citron vodka", "amount": 40, "unit": "ml", "role": "柑橘风味伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "新鲜葡萄柚汁", "nameEn": "Fresh grapefruit juice", "amount": 10, "unit": "ml", "role": "以葡萄柚汁近似柚子香"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 75, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "葡萄柚皮", "nameEn": "Grapefruit peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入三块冰块。", "倒入 40 ml 柑橘风味伏特加、15 ml 柠檬汁与 10 ml 葡萄柚汁。", "加入 10 ml 单糖浆，注入 75 ml 苏打水并轻搅一次。", "以葡萄柚皮挤油后置于杯沿装饰。"]', '["Yuzu Sour", "柚子沙瓦鸡尾酒", "柚子酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-yuzu-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "柚子沙瓦", "nameEn": "Yuzu Sour", "intro": "以柑橘风味伏特加、葡萄柚汁与柠檬汁调制的沙瓦长饮，以近似柚子的柑橘香气为特色，清爽微酸，气泡充盈。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Yuzu.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "果香", "酸甜", "气泡感", "直调", "无乳配方"], "scene": ["日常", "经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "新鲜葡萄柚汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-lemon-sour', 'cocktail', 'COCKTAIL', '柠檬沙瓦', 'Lemon Sour', 'ningmengshawa', 'nmsw', '以伏特加、柠檬汁与苏打水兑制的柠檬沙瓦长饮，柠檬酸感集中、甜度克制，气泡清爽，适合喜欢鲜明柠檬酸味的人。', '本条目将柠檬汁提高到 20 ml 以突出酸感，配 40 ml 伏特加、10 ml 1:1 单糖浆与 80 ml 苏打水直调于高球杯，甜度克制、突出柠檬本味。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gimlet%20cocktail.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gimlet%20cocktail.jpg', 93, 218, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["伏特加基底", "冷饮", "柑橘", "酸甜", "气泡感", "直调", "低糖", "无乳配方"]', '["日常", "经典", "开胃"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["日常", "经典", "开胃"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 80, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入三块冰块。", "倒入 40 ml 伏特加与 20 ml 柠檬汁。", "加入 10 ml 单糖浆，注入 80 ml 苏打水并轻搅一次。", "以柠檬片置于杯沿装饰。"]', '["Lemon Sour", "柠檬沙瓦鸡尾酒", "柠檬酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-lemon-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "柠檬沙瓦", "nameEn": "Lemon Sour", "intro": "以伏特加、柠檬汁与苏打水兑制的柠檬沙瓦长饮，柠檬酸感集中、甜度克制，气泡清爽，适合喜欢鲜明柠檬酸味的人。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Gimlet%20cocktail.jpg", "tags": ["伏特加基底", "冷饮", "柑橘", "酸甜", "气泡感", "直调", "低糖", "无乳配方"], "scene": ["日常", "经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "低度≤10%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-lime-sour', 'cocktail', 'COCKTAIL', '青柠沙瓦', 'Lime Sour', 'qingningshawa', 'qnsw', '以白朗姆酒、青柠汁与苏打水兑制的青柠沙瓦长饮，青柠香气明亮，酸甜清爽，气泡充盈，是夏季冰镇长饮的好选择。', '本条目以 40 ml 白朗姆酒替代伏特加，配 20 ml 青柠汁、10 ml 1:1 单糖浆与 80 ml 苏打水直调于高球杯，是黛绮莉的气泡长饮版本。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 93, 219, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["朗姆基底", "冷饮", "柑橘", "酸甜", "气泡感", "直调", "夏季", "无乳配方"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "低度≤10%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 40, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 80, "unit": "ml", "role": "苏打水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "青柠片", "nameEn": "Lime wheel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["在高球杯中加入三块冰块。", "倒入 40 ml 白朗姆酒与 20 ml 青柠汁。", "加入 10 ml 单糖浆，注入 80 ml 苏打水并轻搅一次。", "以青柠片置于杯沿装饰。"]', '["Lime Sour", "青柠沙瓦鸡尾酒", "青柠酸"]', 'B', '2026-08-04', 1, '{"id": "cocktail-lime-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "青柠沙瓦", "nameEn": "Lime Sour", "intro": "以白朗姆酒、青柠汁与苏打水兑制的青柠沙瓦长饮，青柠香气明亮，酸甜清爽，气泡充盈，是夏季冰镇长饮的好选择。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["朗姆基底", "冷饮", "柑橘", "酸甜", "气泡感", "直调", "夏季", "无乳配方"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸基", "flavor": "柑橘、酸甜", "abv": "低度≤10%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-oolong-tea-cocktail', 'cocktail', 'COCKTAIL', '乌龙茶鸡尾酒', 'Oolong Tea Cocktail', 'wulongchajiweijiu', 'wlcjwj', '以波本威士忌、乌龙茶、柠檬与蜂蜜调制的茶香长饮，乌龙茶韵带烘焙感，酸甜平衡，咖啡因适中，适合下午茶或餐后场景。', '本条目以 40 ml 波本威士忌、100 ml 乌龙茶液、15 ml 柠檬汁与 10 g 蜂蜜直调于高球杯。乌龙茶液浸泡约 4 分钟，茶香带烘焙感，蜂蜜提供温润甜味。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Oolong%20tea%20being%20poured,%20Holiday%20Restaurant,%20Semarang,%202014-06-19.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Oolong%20tea%20being%20poured,%20Holiday%20Restaurant,%20Semarang,%202014-06-19.jpg', 93, 220, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["威士忌基底", "冷饮", "草本", "蜂蜜", "酸甜", "直调", "清爽", "含咖啡因"]', '["夏季", "经典"]', '{"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "草本、蜂蜜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "红茶液"], "scene": ["夏季", "经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 40, "unit": "ml", "role": "波本威士忌"}, {"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 100, "unit": "ml", "role": "乌龙茶液，浸泡 4 分钟"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "g", "role": "蜂蜜"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["取 100 ml 乌龙茶液并冷藏备用。", "在高球杯中加入三块冰块。", "倒入 40 ml 波本威士忌、15 ml 柠檬汁与 10 g 蜂蜜，搅拌至蜂蜜溶解。", "加入乌龙茶液，轻搅一次，以柠檬皮提香。"]', '["Oolong Tea Cocktail", "乌龙茶调酒", "乌龙茶高球"]', 'B', '2026-08-04', 1, '{"id": "cocktail-oolong-tea-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "乌龙茶鸡尾酒", "nameEn": "Oolong Tea Cocktail", "intro": "以波本威士忌、乌龙茶、柠檬与蜂蜜调制的茶香长饮，乌龙茶韵带烘焙感，酸甜平衡，咖啡因适中，适合下午茶或餐后场景。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Oolong%20tea%20being%20poured,%20Holiday%20Restaurant,%20Semarang,%202014-06-19.jpg", "tags": ["威士忌基底", "冷饮", "草本", "蜂蜜", "酸甜", "直调", "清爽", "含咖啡因"], "scene": ["夏季", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "草本、蜂蜜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "红茶液"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-green-tea-cocktail', 'cocktail', 'COCKTAIL', '绿茶鸡尾酒', 'Green Tea Cocktail', 'lvchajiweijiu', 'lcjwj', '以金酒与现泡绿茶调成的清爽酸型鸡尾酒，绿茶的鲜爽与草本气息托起金酒的杜松香，青柠与糖浆平衡苦甜，清冽易饮。', 'V6 编辑标准化配方以伦敦干金酒为烈酒基底、配现泡绿茶液并加入青柠汁与单糖浆，采用摇和法；茶液用绿茶粉以 70°C 热水调制，配方与数值为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Green_Tea_Salmon_Cocktail_%283543340424%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Green_Tea_Salmon_Cocktail_%283543340424%29.jpg', 91, 221, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "酸型鸡尾酒", "冷饮", "草本", "清爽", "含咖啡因", "无乳配方"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本", "abv": "较高＞20%～30%", "extra": ["抹茶", "新鲜青柠汁"], "scene": ["经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "抹茶", "nameEn": "Matcha", "amount": 4, "unit": "g", "role": "绿茶研磨粉，70°C 热水调开"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 60, "unit": "ml", "role": "70°C，冲泡绿茶茶底"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 20, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 15, "unit": "ml", "role": "平衡茶涩"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇合用冰块"}]', '["用 60 ml、70°C 热水冲泡 4 g 绿茶粉，静置降温至室温。", "在摇酒壶中加入金酒、青柠汁与单糖浆。", "倒入放凉的绿茶液，加入冰块摇合约 12 秒。", "过滤入预冷的高球杯，补入一块大冰。", "轻搅两圈后立即饮用。"]', '["绿茶金酒调", "Green Tea Gimlet", "绿茶酒饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-green-tea-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "绿茶鸡尾酒", "nameEn": "Green Tea Cocktail", "intro": "以金酒与现泡绿茶调成的清爽酸型鸡尾酒，绿茶的鲜爽与草本气息托起金酒的杜松香，青柠与糖浆平衡苦甜，清冽易饮。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4a/Green_Tea_Salmon_Cocktail_%283543340424%29.jpg", "tags": ["金酒基底", "酸型鸡尾酒", "冷饮", "草本", "清爽", "含咖啡因", "无乳配方"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本", "abv": "较高＞20%～30%", "extra": ["抹茶", "新鲜青柠汁"], "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-jasmine-tea-cocktail', 'cocktail', 'COCKTAIL', '茉莉茶鸡尾酒', 'Jasmine Tea Cocktail', 'molichajiweijiu', 'mlcjwj', '以金酒与冷泡茉莉花茶调成的花香长饮，茉莉香气清雅，杜松与柑橘微苦托底，气泡水带来清爽易饮的口感，适合午后与夏夜。', 'V6 编辑标准化配方以伦敦干金酒为基、配冷泡茉莉花茶与气泡水，采用直调法；茶底以绿茶研磨粉泡制、以干茉莉花提香，配方与数值为编辑估算值。', 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Green_Tea_Salmon_Cocktail_%283543340424%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Green_Tea_Salmon_Cocktail_%283543340424%29.jpg', 93, 222, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "冷饮", "花香", "草本", "气泡感", "下午茶", "含咖啡因", "无乳配方"]', '["下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "花香、草本", "abv": "中度＞10%～20%", "extra": ["抹茶", "气泡水"], "scene": ["下午茶"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 40, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "抹茶", "nameEn": "Matcha", "amount": 3, "unit": "g", "role": "绿茶研磨粉，冷泡茉莉茶底"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 90, "unit": "ml", "role": "冷水冷泡茶底"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 80, "unit": "ml", "role": "冷藏气泡水"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "柔和花香"}, {"nameZh": "可食用花", "nameEn": "Edible flower", "amount": 1, "unit": "g", "role": "干茉莉花装饰"}]', '["用 90 ml 冷水浸泡 3 g 绿茶粉与干茉莉花约 3 分钟，滤出茶液。", "在高球杯中加入冰块并预冷。", "倒入金酒与单糖浆。", "加入茉莉茶液，轻轻搅拌。", "沿杯壁缓慢补入气泡水至八成满，以干茉莉花装饰后饮用。"]', '["茉莉花茶调", "Jasmine Highball", "茉莉茶酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-jasmine-tea-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "茉莉茶鸡尾酒", "nameEn": "Jasmine Tea Cocktail", "intro": "以金酒与冷泡茉莉花茶调成的花香长饮，茉莉香气清雅，杜松与柑橘微苦托底，气泡水带来清爽易饮的口感，适合午后与夏夜。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4a/Green_Tea_Salmon_Cocktail_%283543340424%29.jpg", "tags": ["金酒基底", "冷饮", "花香", "草本", "气泡感", "下午茶", "含咖啡因", "无乳配方"], "scene": ["下午茶"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "高球", "flavor": "花香、草本", "abv": "中度＞10%～20%", "extra": ["抹茶", "气泡水"], "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-osmanthus-tea-cocktail', 'cocktail', 'COCKTAIL', '桂花茶鸡尾酒', 'Osmanthus Tea Cocktail', 'guihuachajiweijiu', 'ghcjwj', '以伏特加与桂花乌龙茶调成的花茶长饮，桂花蜜香温润，茶底烘焙香与伏特加中性的酒体结合，气泡水带来清爽质感，适合下午与夏夜。', 'V6 编辑标准化配方以伏特加为基、配桂花乌龙茶底与气泡水，采用直调法；茶底以红茶液稀释复配并加入桂花糖浆增香，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Osmanthus%20wine%20for%20sale%20in%20Dali.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Osmanthus%20wine%20for%20sale%20in%20Dali.jpg', 93, 223, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["伏特加基底", "冷饮", "花香", "蜂蜜", "气泡感", "下午茶", "含咖啡因", "无乳配方"]', '["下午茶"]', '{"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "花香、蜂蜜", "abv": "中度＞10%～20%", "extra": ["气泡水", "红茶液"], "scene": ["下午茶"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 40, "unit": "ml", "role": "伏特加"}, {"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 90, "unit": "ml", "role": "乌龙茶液，浸泡 4 分钟"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "g", "role": "桂花蜜"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 80, "unit": "ml", "role": "冷藏气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "大冰块"}]', '["用热水浸泡红茶液 4 分钟制成乌龙茶底，加入桂花蜜搅匀后放凉。", "在高球杯中加入大冰块并预冷。", "倒入伏特加 40 ml。", "加入调好的桂花乌龙茶液，轻搅混合。", "缓慢补入气泡水至八成满，轻搅一次后饮用。"]', '["桂花茶酒", "Osmanthus Highball", "桂花乌龙调"]', 'B', '2026-08-04', 1, '{"id": "cocktail-osmanthus-tea-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "桂花茶鸡尾酒", "nameEn": "Osmanthus Tea Cocktail", "intro": "以伏特加与桂花乌龙茶调成的花茶长饮，桂花蜜香温润，茶底烘焙香与伏特加中性的酒体结合，气泡水带来清爽质感，适合下午与夏夜。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Osmanthus%20wine%20for%20sale%20in%20Dali.jpg", "tags": ["伏特加基底", "冷饮", "花香", "蜂蜜", "气泡感", "下午茶", "含咖啡因", "无乳配方"], "scene": ["下午茶"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "花香、蜂蜜", "abv": "中度＞10%～20%", "extra": ["气泡水", "红茶液"], "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-black-tea-cocktail', 'cocktail', 'COCKTAIL', '红茶鸡尾酒', 'Black Tea Cocktail', 'hongchajiweijiu', 'hcjwj', '以威士忌与现泡红茶调成的长饮，红茶的麦芽与单宁托起威士忌的烟熏甜香，柠檬与蜂蜜平衡涩感，清凉爽口，适合午后与餐后。', 'V6 编辑标准化配方以调和苏格兰威士忌为基、配现泡红茶液并加柠檬汁与蜂蜜，采用直调法；红茶以红茶液浸泡 4 分钟制成，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg', 93, 224, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["威士忌基底", "冷饮", "蜂蜜", "柑橘", "清爽", "下午茶", "含咖啡因", "无乳配方"]', '["下午茶"]', '{"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["下午茶"]}', '[{"nameZh": "混合苏格兰威士忌", "nameEn": "Blended Scotch whisky", "amount": 40, "unit": "ml", "role": "调和苏格兰威士忌"}, {"nameZh": "红茶液", "nameEn": "Black tea liquid", "amount": 100, "unit": "ml", "role": "浓红茶液，浸泡 4 分钟"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蜂蜜", "nameEn": "Honey", "amount": 10, "unit": "g", "role": "中和茶涩"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 60, "unit": "ml", "role": "冷藏气泡水"}, {"nameZh": "柠檬片", "nameEn": "Lemon wheel", "amount": 1, "unit": "piece", "role": "装饰用柠檬片"}]', '["用热水浸泡红茶液 4 分钟制成浓红茶，放凉至室温。", "在高球杯中加入冰块并预冷。", "倒入威士忌与新鲜柠檬汁。", "加入放凉的红茶液与蜂蜜，轻搅至蜂蜜溶开。", "补入气泡水至八成满，以柠檬片装饰后饮用。"]', '["红茶威士忌调", "Black Tea Highball", "红茶酒饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-black-tea-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "红茶鸡尾酒", "nameEn": "Black Tea Cocktail", "intro": "以威士忌与现泡红茶调成的长饮，红茶的麦芽与单宁托起威士忌的烟熏甜香，柠檬与蜂蜜平衡涩感，清凉爽口，适合午后与餐后。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/MargaritaReal.jpg", "tags": ["威士忌基底", "冷饮", "蜂蜜", "柑橘", "清爽", "下午茶", "含咖啡因", "无乳配方"], "scene": ["下午茶"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "高球", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "气泡水"], "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cold-brew-cocktail', 'cocktail', 'COCKTAIL', '冷萃鸡尾酒', 'Cold Brew Cocktail', 'lengcuijiweijiu', 'lcjwj', '以伏特加与冷萃浓缩液调成的咖啡鸡尾酒，冷萃的顺滑低酸与坚果甜香托起伏特加的干净酒体，微苦回甘，冰爽而浓度适中。', 'V6 编辑标准化配方以伏特加为基、配冷萃浓缩液并加香草糖浆平衡苦味，采用摇和法；冷萃浓缩液按 NCA 冷萃比例稀释，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg', 91, 225, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["伏特加基底", "咖啡鸡尾酒", "冷饮", "咖啡风味", "含咖啡因", "日常", "无乳配方"]', '["日常"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "较高＞20%～30%", "extra": ["冷萃浓缩液"], "scene": ["日常"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "伏特加"}, {"nameZh": "冷萃浓缩液", "nameEn": "Cold brew concentrate", "amount": 45, "unit": "ml", "role": "冷萃浓缩液"}, {"nameZh": "香草糖浆", "nameEn": "Vanilla syrup", "amount": 10, "unit": "ml", "role": "香草糖浆"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 40, "unit": "ml", "role": "稀释用冷水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 90, "unit": "g", "role": "摇合用冰块"}]', '["在摇酒壶中加入伏特加、冷萃浓缩液与香草糖浆。", "加入冰块，摇合约 12 秒至充分冷却。", "滤入装有冰块的岩石杯。", "补入 40 ml 冷水稀释至合适浓度。", "轻搅一圈后立即饮用。"]', '["冷萃咖啡调", "Cold Brew Mix", "冷萃咖酒"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cold-brew-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冷萃鸡尾酒", "nameEn": "Cold Brew Cocktail", "intro": "以伏特加与冷萃浓缩液调成的咖啡鸡尾酒，冷萃的顺滑低酸与坚果甜香托起伏特加的干净酒体，微苦回甘，冰爽而浓度适中。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg", "tags": ["伏特加基底", "咖啡鸡尾酒", "冷饮", "咖啡风味", "含咖啡因", "日常", "无乳配方"], "scene": ["日常"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "较高＞20%～30%", "extra": ["冷萃浓缩液"], "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cold-brew-tonic', 'cocktail', 'COCKTAIL', '冷萃金汤力', 'Cold Brew Tonic', 'lengcuijintangli', 'lcjtl', '以金酒与冷萃咖啡液配汤力水调成的咖啡长饮，冷萃的顺滑坚果香与汤力的奎宁微苦交织，气泡清亮，清爽易饮，适合夏季与午后。', 'V6 编辑标准化配方以伦敦干金酒为基、配冷萃浓缩液与汤力水，采用直调法；冷萃浓缩液按 NCA 冷萃比例稀释，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg', 93, 226, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["金酒基底", "咖啡鸡尾酒", "冷饮", "咖啡风味", "气泡感", "夏季", "含咖啡因", "无乳配方"]', '["夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "中度＞10%～20%", "extra": ["冷萃浓缩液", "汤力水"], "scene": ["夏季"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 40, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "冷萃浓缩液", "nameEn": "Cold brew concentrate", "amount": 40, "unit": "ml", "role": "冷萃浓缩液"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 130, "unit": "ml", "role": "冷藏汤力水"}, {"nameZh": "1:1 单糖浆", "nameEn": "1:1 simple syrup", "amount": 10, "unit": "ml", "role": "平衡汤力苦味"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "大冰块"}]', '["在高球杯中加入大冰块并预冷。", "倒入金酒与冷萃浓缩液。", "加入单糖浆，轻搅混合。", "沿杯壁缓慢补入汤力水至八成满，保留气泡。", "轻搅一次后立即饮用。"]', '["冷萃汤力", "Cold Brew Tonic", "咖汤力冷萃"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cold-brew-tonic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冷萃金汤力", "nameEn": "Cold Brew Tonic", "intro": "以金酒与冷萃咖啡液配汤力水调成的咖啡长饮，冷萃的顺滑坚果香与汤力的奎宁微苦交织，气泡清亮，清爽易饮，适合夏季与午后。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg", "tags": ["金酒基底", "咖啡鸡尾酒", "冷饮", "咖啡风味", "气泡感", "夏季", "含咖啡因", "无乳配方"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味", "abv": "中度＞10%～20%", "extra": ["冷萃浓缩液", "汤力水"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cold-brew-cola', 'cocktail', 'COCKTAIL', '冷萃可乐', 'Cold Brew Cola', 'lengcuikele', 'lckl', '以朗姆酒、冷萃咖啡液与可乐调成的咖啡长饮，可乐的焦糖甜香与冷萃坚果微苦结合，气泡丰沛，冰爽易饮，适合夏日与休闲场景。', 'V6 编辑标准化配方以白朗姆酒为基、配冷萃浓缩液与可乐，采用直调法；冷萃浓缩液按 NCA 冷萃比例稀释，可乐贡献碳酸与焦糖甜，配方与数值为编辑估算值。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg', 93, 227, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "冷饮", "咖啡风味", "气泡感", "甜感明显", "夏季", "含咖啡因", "无乳配方"]', '["夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "咖啡风味、甜感明显", "abv": "中度＞10%～20%", "extra": ["冷萃浓缩液", "可乐"], "scene": ["夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 40, "unit": "ml", "role": "白朗姆酒"}, {"nameZh": "冷萃浓缩液", "nameEn": "Cold brew concentrate", "amount": 30, "unit": "ml", "role": "冷萃浓缩液"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 160, "unit": "ml", "role": "冷藏可乐"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 1, "unit": "piece", "role": "装饰用青柠角"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "大冰块"}]', '["在高球杯中加入大冰块并预冷。", "倒入白朗姆酒与冷萃浓缩液。", "轻搅混合均匀。", "沿杯壁缓慢倒入可乐至八成满。", "挤入青柠角汁液并放入杯中作装饰后饮用。"]', '["冷萃可乐调", "Cold Brew Rum Cola", "咖味可乐"]', 'B', '2026-08-04', 1, '{"id": "cocktail-cold-brew-cola", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "冷萃可乐", "nameEn": "Cold Brew Cola", "intro": "以朗姆酒、冷萃咖啡液与可乐调成的咖啡长饮，可乐的焦糖甜香与冷萃坚果微苦结合，气泡丰沛，冰爽易饮，适合夏日与休闲场景。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20Coffee.jpg", "tags": ["朗姆基底", "冷饮", "咖啡风味", "气泡感", "甜感明显", "夏季", "含咖啡因", "无乳配方"], "scene": ["夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "咖啡风味、甜感明显", "abv": "中度＞10%～20%", "extra": ["冷萃浓缩液", "可乐"], "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
